input.command:
$h = @{ 'User-Agent' = 'gh-activity-check'; 'Accept' = 'application/vnd.github+json' }
try { $u = Invoke-RestMethod -Uri 'https://api.github.com/users/StoneSSSSSSS' -Headers $h; "USER: $($u.login) | name: $($u.name) | public repos: $($u.public_repos) | profile: $($u.html_url)" } catch { "USER LOOKUP FAILED: $($_.Exception.Message)" }
try {
  $ev = Invoke-RestMethod -Uri 'https://api.github.com/users/StoneSSSSSSS/events/public?per_page=100' -Headers $h
  "TOTAL EVENTS: $($ev.Count)"
  $ev | Select-Object -First 10 | ForEach-Object { "$($_.created_at) | $($_.type) | $($_.repo.name)" }
  $p = $ev | Where-Object { $_.type -eq 'PushEvent' } | Select-Object -First 1
  if ($p) { "---- LATEST PUSH ----"; $p | ConvertTo-Json -Depth 6 }
} catch { "EVENTS FAILED: $($_.Exception.Message)" }

