$h = @{ 'User-Agent' = 'gh-activity-check'; 'Accept' = 'application/vnd.github+json' }
$ev = Invoke-RestMethod -Uri 'https://api.github.com/users/StoneSSSSSSS/events/public?per_page=100' -Headers $h
"== Pushes, newest first =="
$pushes = $ev | Where-Object { $_.type -eq 'PushEvent' } | Sort-Object { [datetime]$_.created_at } -Descending
$pushes | ForEach-Object { "$($_.created_at) | $($_.payload.ref) | $($_.payload.before.Substring(0,7)) -> $($_.payload.head.Substring(0,7))" }
$latest = $pushes | Select-Object -First 1
"== Repos by last push =="
$repos = Invoke-RestMethod -Uri 'https://api.github.com/users/StoneSSSSSSS/repos?sort=pushed&direction=desc&per_page=5' -Headers $h
$repos | ForEach-Object { "$($_.pushed_at) | $($_.full_name) | default: $($_.default_branch) | private: $($_.private)" }
"== Compare for latest push =="
$repo = $latest.repo.name
$cmp = Invoke-RestMethod -Uri "https://api.github.com/repos/$repo/compare/$($latest.payload.before)...$($latest.payload.head)" -Headers $h
"commits: $($cmp.total_commits) | files changed: $($cmp.files.Count)"
$cmp.commits | ForEach-Object { "$($_.sha.Substring(0,7)) | $($_.commit.author.date) | $($_.commit.author.name) | $($_.commit.message -replace "`r?`n", ' / ')" }
"-- files --"
$cmp.files | ForEach-Object { "$($_.status) | $($_.filename) | +$($_.additions) -$($_.deletions)" }

