"OBS:"; foreach ($p in "$env:ProgramFiles\obs-studio\bin\64bit\obs64.exe", "${env:ProgramFiles(x86)}\obs-studio\bin\64bit\obs64.exe") { if (Test-Path $p) { "  found $p  version $((Get-Item $p).VersionInfo.ProductVersion)" } }
"ffmpeg in Program Files:"; Get-ChildItem $env:ProgramFiles -Directory -Filter 'ffmpeg*' -ErrorAction SilentlyContinue | ForEach-Object { "  $($_.FullName)  has ffmpeg.exe: $(Test-Path (Join-Path $_.FullName 'bin\ffmpeg.exe'))/$(Test-Path (Join-Path $_.FullName 'ffmpeg.exe'))" }
"ffmpeg on PATH: $((Get-Command ffmpeg -ErrorAction SilentlyContinue).Source)"
"libmpv in repo: $(Test-Path 'C:\Users\stone\Desktop\Recording\third_party\libmpv-2.dll')"
"libmpv elsewhere:"; Get-ChildItem "$env:USERPROFILE\Downloads", "$env:USERPROFILE\Desktop" -Recurse -Filter 'libmpv-2.dll' -ErrorAction SilentlyContinue -Depth 3 | ForEach-Object { "  $($_.FullName)" }
"ClipVault installed: $(Test-Path "$env:LOCALAPPDATA\Programs\ClipVault")"
if (Test-Path "$env:LOCALAPPDATA\Programs\ClipVault") { Get-ChildItem "$env:LOCALAPPDATA\Programs\ClipVault" -Name }
"ClipVault data folder: $(Test-Path "$env:LOCALAPPDATA\ClipVault")"
"Startup folder:"; Get-ChildItem "$env:APPDATA\Microsoft\Windows\Start Menu\Programs\Startup" -Name -ErrorAction SilentlyContinue
"Running:"; Get-Process obs64, clipvault, clipvault-service, python, pythonw -ErrorAction SilentlyContinue | Select-Object Name, Id, Path | Format-Table -AutoSize | Out-String -Width 250

