3	//! mpv can only play one audio track at a time, unless the tracks are combined
4	//! in `lavfi-complex`. Filters inside lavfi-complex can't be changed at runtime,
5	//! so we `join` all tracks into one multichannel stream there (each track's
6	//! left/right on its own named speaker pair), and do the per-track volume in
7	//! the regular `af` chain, where `af-command` can change gains live.
8	//!
9	//! Verified against libmpv with real OBS recordings (6 stereo tracks):
10	//! * the joined layout must list speakers in FFmpeg's canonical order, or mpv
11	//!   rejects the frames ("could not use filter output");
12	//! * remapping with `pan` into 2-channel side/top layouts fails in swresample,
13	//!   which is why `join` is used instead;
14	//! * volume changes via af-command are instant and survive seeks as long as
15	//!   the `af` option string is also kept current.
16	
17	/// Speaker pairs used to carry each track through the joined stream. None of
18	/// them is LFE (which may be low-pass filtered or dropped on conversion).
19	pub const CHANNEL_PAIRS: [(&str, &str); 6] =
20	    [("FL", "FR"), ("FC", "BC"), ("BL", "BR"), ("FLC", "FRC"), ("SL", "SR"), ("TFL", "TFR")];
21	
22	/// FFmpeg's canonical speaker order (AV_CH_* bit order) for the names above.
23	const CANONICAL: [&str; 14] = ["FL", "FR", "FC", "LFE", "BL", "BR", "FLC", "FRC", "BC", "SL", "SR", "TC", "TFL", "TFR"];
24	
25	fn joined_layout(n: usize) -> String {
26	    let used: Vec<&str> = CHANNEL_PAIRS[..n].iter().flat_map(|(a, b)| [*a, *b]).collect();
27	    CANONICAL.iter().filter(|c| used.contains(c)).copied().collect::<Vec<_>>().join("+")
28	}
29	
30	pub const MAX_MIX_TRACKS: usize = CHANNEL_PAIRS.len();
31	pub const MIX_FILTER_LABEL: &str = "cvmix";
32	
33	/// lavfi-complex graph merging `n` audio tracks (mpv aid 1..=n) into [ao].
34	/// Returns `None` when there is nothing to merge (0 or 1 track).
35	pub fn mpv_lavfi_complex(n: usize) -> Option<String> {
36	    let n = n.min(MAX_MIX_TRACKS);
37	    if n < 2 {
38	        return None;
39	    }
40	    let mut g = String::new();
41	    for i in 0..n {
42	        g.push_str(&format!("[aid{}]aformat=sample_rates=48000:channel_layouts=stereo[cvt{i}];", i + 1));
43	    }
44	    for i in 0..n {
45	        g.push_str(&format!("[cvt{i}]"));
46	    }
47	    let map: Vec<String> = (0..n)
48	        .map(|i| {
49	            let (a, b) = CHANNEL_PAIRS[i];
50	            format!("{i}.0-{a}|{i}.1-{b}")
51	        })
52	        .collect();
53	    g.push_str(&format!("join=inputs={n}:channel_layout={}:map={}[ao]", joined_layout(n), map.join("|")));
54	    Some(g)
55	}
56	
57	/// Per-track gain expression: the base gain times a factor for every edit on
58	/// that track (`if(between(t,a,b),g,1)`), evaluated per audio frame. `offset`
59	/// shifts edit times (e.g. an export that starts `offset` seconds into the
60	/// clip, where ffmpeg's `t` restarts at 0).
61	pub fn track_expr(base: f32, edits: &[crate::model::AudioEdit], track: usize, offset: f64) -> String {
62	    let mut s = fmt_gain(base);
63	    let mut n = 0;
64	    for e in edits.iter().filter(|e| e.track == track) {
65	        if n >= 400 {
66	            break; // keep expressions bounded
67	        }
68	        let (a, b) = (e.start - offset, e.end - offset);
69	        if b <= 0.0 {
70	            continue;
71	        }
72	        s.push_str(&format!("*if(between(t,{:.3},{:.3}),{},1)", a.max(0.0), b, fmt_gain(e.gain)));
73	        n += 1;
74	    }
75	    s
76	}
77	
78	/// Expressions for every track from plain gains (no edits).
79	pub fn gains_to_exprs(gains: &[f32]) -> Vec<String> {
80	    gains.iter().map(|g| fmt_gain(*g)).collect()
81	}
