21	/// Parse `ffmpeg version X ...` and decide whether it's recent enough.
22	/// Accepts release builds >= 5 and git builds `N-xxxxx` from 2022 onwards.
23	pub fn version_ok(first_line: &str) -> bool {
24	    let v = first_line
25	        .split_whitespace()
26	        .skip_while(|w| *w != "version")
27	        .nth(1)
28	        .unwrap_or("");
29	    if let Some(n) = v.strip_prefix("N-") {
30	        return n.split('-').next().and_then(|n| n.parse::<u64>().ok()).map(|n| n >= 105_000).unwrap_or(false);
31	    }
32	    let v = v.trim_start_matches('n');
33	    v.split(['.', '-']).next().and_then(|m| m.parse::<u32>().ok()).map(|m| m >= 5).unwrap_or(false)
34	}
