36	fn probe_version(exe: &Path) -> Option<String> {
37	    let mut cmd = Command::new(exe);
38	    cmd.arg("-hide_banner").arg("-version").stdout(Stdio::piped()).stderr(Stdio::null()).stdin(Stdio::null());
39	    hide_console(&mut cmd);
40	    let out = run_with_timeout(cmd, Duration::from_secs(10)).ok()?;
41	    let text = String::from_utf8_lossy(&out.stdout).to_string();
42	    let first = text.lines().next()?.to_string();
43	    version_ok(&first).then_some(first)
44	}
