46	fn candidate_dirs() -> Vec<PathBuf> {
47	    let mut dirs = vec![crate::paths::exe_dir(), crate::paths::exe_dir().join("bin")];
48	    for root in [r"C:\Program Files", r"C:\Program Files (x86)", r"C:\ffmpeg"] {
49	        if let Ok(rd) = std::fs::read_dir(root) {
50	            let mut found: Vec<PathBuf> = rd
51	                .flatten()
52	                .map(|e| e.path())
53	                .filter(|p| {
54	                    p.file_name()
55	                        .map(|n| n.to_string_lossy().to_lowercase().starts_with("ffmpeg"))
56	                        .unwrap_or(false)
57	                })
58	                .collect();
59	            found.sort();
60	            found.reverse(); // newest version folder first
61	            for f in found {
62	                dirs.push(f.join("bin"));
63	                dirs.push(f);
64	            }
65	        }
66	        dirs.push(PathBuf::from(root).join("bin"));
67	    }
68	    if let Some(path) = std::env::var_os("PATH") {
69	        dirs.extend(std::env::split_paths(&path));
70	    }
71	    dirs
72	}
