278	    /// Run ffmpeg with `-progress`, reporting 0..1 and honouring `cancel`.
279	    pub fn run_progress(
280	        &self,
281	        args: &[String],
282	        total_s: f64,
283	        progress: &mut dyn FnMut(f32),
284	        cancel: &AtomicBool,
285	    ) -> Result<()> {
286	        let mut cmd = Command::new(&self.ffmpeg);
287	        cmd.args(["-hide_banner", "-nostdin", "-y", "-loglevel", "error", "-progress", "pipe:1", "-nostats"])
288	            .args(args)
289	            .stdin(Stdio::null())
290	            .stdout(Stdio::piped())
291	            .stderr(Stdio::piped());
292	        hide_console(&mut cmd);
293	        tracing::debug!("ffmpeg {}", args.join(" "));
294	        let mut child = cmd.spawn().context("starting ffmpeg")?;
295	        let stderr = child.stderr.take();
296	        let err_t = std::thread::spawn(move || {
297	            let mut s = String::new();
298	            if let Some(mut e) = stderr {
299	                let _ = std::io::Read::read_to_string(&mut e, &mut s);
300	            }
301	            s
302	        });
303	        let stdout = child.stdout.take().context("ffmpeg stdout")?;
304	        let (line_tx, line_rx) = crossbeam_channel::unbounded::<String>();
305	        std::thread::spawn(move || {
306	            for line in BufReader::new(stdout).lines().map_while(Result::ok) {
307	                if line_tx.send(line).is_err() {
308	                    break;
309	                }
310	            }
311	        });
312	        loop {
313	            if cancel.load(Ordering::SeqCst) {
314	                let _ = child.kill();
315	                let _ = child.wait();
316	                bail!("cancelled");
317	            }
318	            match line_rx.recv_timeout(Duration::from_millis(100)) {
319	                Ok(line) => {
320	                    if let Some(us) = line.strip_prefix("out_time_us=").or_else(|| line.strip_prefix("out_time_ms=")) {
321	                        if let Ok(us) = us.trim().parse::<i64>() {
322	                            if total_s > 0.0 {
323	                                progress(((us as f64 / 1e6) / total_s).clamp(0.0, 1.0) as f32);
324	                            }
325	                        }
326	                    }
327	                }
328	                Err(crossbeam_channel::RecvTimeoutError::Timeout) => {
329	                    if child.try_wait()?.is_some() {
330	                        break;
331	                    }
332	                }
333	                Err(crossbeam_channel::RecvTimeoutError::Disconnected) => break,
334	            }
335	        }
336	        let status = child.wait()?;
337	        let err = err_t.join().unwrap_or_default();
338	        if !status.success() {
339	            bail!("ffmpeg failed: {}", last_lines(&err, 4));
340	        }
341	        progress(1.0);
342	        Ok(())
343	    }
344	}
