375	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
376	pub struct EncodeOptions {
377	    /// "h264_nvenc", "hevc_nvenc", "libx264".
378	    pub video_encoder: String,
379	    /// CQ/CRF.
380	    pub quality: u32,
381	    pub audio_bitrate_kbps: u32,
382	}
383	
384	impl Default for EncodeOptions {
385	    fn default() -> Self {
386	        Self { video_encoder: "h264_nvenc".into(), quality: 23, audio_bitrate_kbps: 192 }
387	    }
388	}
389	
390	fn video_quality_args(o: &EncodeOptions) -> Vec<String> {
391	    let mut a: Vec<String> = vec!["-c:v".into(), o.video_encoder.clone()];
392	    if o.video_encoder.contains("nvenc") {
393	        a.extend(["-preset", "p5", "-rc", "vbr", "-cq"].iter().map(|s| s.to_string()));
394	        a.push(o.quality.to_string());
395	        a.extend(["-b:v", "0"].iter().map(|s| s.to_string()));
396	    } else {
397	        a.extend(["-preset", "veryfast", "-crf"].iter().map(|s| s.to_string()));
398	        a.push(o.quality.to_string());
399	    }
400	    a.extend(["-pix_fmt", "yuv420p"].iter().map(|s| s.to_string()));
401	    a
402	}
