404	/// Build ffmpeg args for cutting `parts` into `out`.
405	///
406	/// * fast (`precise == false`): stream copy, starts at the keyframe before the
407	///   in-point (an MP4 edit list hides the extra frames in most players).
408	/// * precise: re-encodes video, frame exact. Audio tracks are re-encoded too.
409	pub fn cut_args(parts: &[CutPart], out: &Path, list_file: &Path, precise: bool, audio_tracks: usize, enc: &EncodeOptions) -> Result<Vec<String>> {
410	    if parts.is_empty() {
411	        bail!("nothing to cut");
412	    }
413	    let mut a: Vec<String> = Vec::new();
414	    if parts.len() == 1 || !precise {
415	        if parts.len() == 1 {
416	            let p = &parts[0];
417	            a.push("-ss".into());
418	            a.push(secs(p.in_s));
419	            if let Some(o) = p.out_s {
420	                a.push("-t".into());
421	                a.push(secs(o - p.in_s));
422	            }
423	            a.push("-i".into());
424	            a.push(p.path.to_string_lossy().to_string());
425	        } else {
426	            a.extend(["-f", "concat", "-safe", "0", "-i"].iter().map(|s| s.to_string()));
427	            a.push(list_file.to_string_lossy().to_string());
428	        }
429	        a.extend(["-map", "0:v:0", "-map", "0:a?"].iter().map(|s| s.to_string()));
430	        if precise {
431	            a.extend(video_quality_args(enc));
432	            a.extend(["-c:a", "aac", "-b:a"].iter().map(|s| s.to_string()));
433	            a.push(format!("{}k", enc.audio_bitrate_kbps));
434	        } else {
435	            a.extend(["-c", "copy"].iter().map(|s| s.to_string()));
436	        }
437	    } else {
438	        // Precise multi-file: trim the first/last inputs and join with the
439	        // concat filter, carrying every audio track through.
440	        let n = parts.len();
441	        for p in parts {
442	            if p.in_s > 0.0 {
443	                a.push("-ss".into());
444	                a.push(secs(p.in_s));
445	            }
446	            if let Some(o) = p.out_s {
447	                a.push("-t".into());
448	                a.push(secs(o - p.in_s));
449	            }
450	            a.push("-i".into());
451	            a.push(p.path.to_string_lossy().to_string());
452	        }
453	        let mut f = String::new();
454	        for i in 0..n {
455	            f.push_str(&format!("[{i}:v:0]"));
456	            for t in 0..audio_tracks {
457	                f.push_str(&format!("[{i}:a:{t}]"));
458	            }
459	        }
460	        f.push_str(&format!("concat=n={n}:v=1:a={audio_tracks}[v]"));
461	        for t in 0..audio_tracks {
462	            f.push_str(&format!("[a{t}]"));
463	        }
464	        a.push("-filter_complex".into());
465	        a.push(f);
466	        a.push("-map".into());
467	        a.push("[v]".into());
468	        for t in 0..audio_tracks {
469	            a.push("-map".into());
470	            a.push(format!("[a{t}]"));
471	        }
472	        a.extend(video_quality_args(enc));
473	        if audio_tracks > 0 {
474	            a.extend(["-c:a", "aac", "-b:a"].iter().map(|s| s.to_string()));
475	            a.push(format!("{}k", enc.audio_bitrate_kbps));
476	        }
477	    }
478	    a.extend(["-movflags", "+faststart", "-f", "mp4"].iter().map(|s| s.to_string()));
479	    a.push(out.to_string_lossy().to_string());
480	    Ok(a)
481	}
482	
483	/// Settings for exporting a shareable file.
484	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default)]
485	pub struct ExportSpec {
486	    /// (audio track index, gain expression). Empty = keep all tracks untouched.
487	    pub gains: Vec<(usize, String)>,
488	    /// Optional (start, end) seconds within the input.
489	    pub range: Option<(f64, f64)>,
490	    /// Re-encode to fit this many MB (None = keep video as is).
491	    pub target_size_mb: Option<u32>,
492	    pub max_height: u32,
493	    /// Re-encode video even without a size target (frame-exact range).
494	    pub reencode_video: bool,
495	}
496	
497	/// Video bitrate (kbps) that fits `target_mb` for `duration_s`, or None if impossible.
498	pub fn bitrate_for_size(target_mb: u32, duration_s: f64, audio_kbps: u32) -> Option<u32> {
499	    if duration_s <= 0.0 {
500	        return None;
501	    }
502	    let total_kbits = target_mb as f64 * 8.0 * 1024.0 * 0.94; // container overhead margin
503	    let video = total_kbits / duration_s - audio_kbps as f64;
504	    (video >= 150.0).then(|| video.floor() as u32)
505	}
506	
507	/// Height to scale to for a given bitrate so quality stays reasonable.
508	pub fn height_for_bitrate(kbps: u32, source_h: u32, max_h: u32) -> u32 {
509	    let cap = if kbps < 1200 {
510	        480
511	    } else if kbps < 2500 {
512	        720
513	    } else if kbps < 6000 {
514	        1080
515	    } else {
516	        source_h
517	    };
518	    let mut h = source_h.min(cap);
519	    if max_h > 0 {
520	        h = h.min(max_h);
521	    }
522	    h - h % 2
523	}
524	
525	pub fn export_args(input: &Path, out: &Path, spec: &ExportSpec, enc: &EncodeOptions, info: &ProbeInfo, video_kbps: Option<u32>) -> Vec<String> {
526	    let mut a: Vec<String> = Vec::new();
527	    let reencode = video_kbps.is_some() || spec.reencode_video;
528	    if let Some((s, e)) = spec.range {
529	        a.push("-ss".into());
530	        a.push(secs(s));
531	        a.push("-t".into());
532	        a.push(secs(e - s));
533	    }
534	    a.push("-i".into());
535	    a.push(input.to_string_lossy().to_string());
536	    let mix = if spec.gains.is_empty() { None } else { crate::mixer::ffmpeg_mix_filter(&spec.gains) };
537	    let mut filters: Vec<String> = Vec::new();
538	    let target_h = video_kbps.map(|k| height_for_bitrate(k, info.height, spec.max_height)).unwrap_or(info.height);
539	    let scale = reencode && target_h > 0 && target_h < info.height;
540	    if scale {
541	        filters.push(format!("[0:v:0]scale=-2:{target_h}:flags=lanczos[vout]"));
542	    }
543	    if let Some(m) = &mix {
544	        filters.push(m.clone());
545	    }
546	    if !filters.is_empty() {
547	        a.push("-filter_complex".into());
548	        a.push(filters.join(";"));
549	    }
550	    a.push("-map".into());
551	    a.push(if scale { "[vout]".into() } else { "0:v:0".into() });
552	    match (&mix, spec.gains.is_empty()) {
553	        (Some(_), _) => {
554	            a.push("-map".into());
555	            a.push("[aout]".into());
556	        }
557	        (None, true) => {
558	            a.push("-map".into());
559	            a.push("0:a?".into());
560	        }
561	        (None, false) => {} // everything muted -> no audio
562	    }
563	    if let Some(k) = video_kbps {
564	        a.extend(["-c:v".to_string(), enc.video_encoder.clone()]);
565	        if enc.video_encoder.contains("nvenc") {
566	            a.extend(["-preset", "p6", "-rc", "vbr", "-multipass", "fullres"].iter().map(|s| s.to_string()));
567	        } else {
568	            a.extend(["-preset", "medium"].iter().map(|s| s.to_string()));
569	        }
570	        a.extend([
571	            "-b:v".to_string(),
572	            format!("{k}k"),
573	            "-maxrate".to_string(),
574	            format!("{}k", (k as f64 * 1.15) as u32),
575	            "-bufsize".to_string(),
576	            format!("{}k", k * 2),
577	            "-pix_fmt".to_string(),
578	            "yuv420p".to_string(),
579	        ]);
580	    } else if spec.reencode_video {
581	        a.extend(video_quality_args(enc));
582	    } else {
583	        a.extend(["-c:v", "copy"].iter().map(|s| s.to_string()));
584	    }
585	    if mix.is_some() {
586	        a.extend(["-c:a".to_string(), "aac".to_string(), "-b:a".to_string(), format!("{}k", enc.audio_bitrate_kbps)]);
587	    } else if spec.gains.is_empty() {
588	        a.extend(["-c:a", "copy"].iter().map(|s| s.to_string()));
589	    }
590	    a.extend(["-movflags", "+faststart", "-f", "mp4"].iter().map(|s| s.to_string()));
591	    a.push(out.to_string_lossy().to_string());
592	    a
593	}
