            format: "fragmented_mp4".into(),
            encoder: "jim_nvenc".into(),
            rate_control: "CQP".into(),
            cqp: 25,
            bitrate_kbps: 20_000,
            max_bitrate_kbps: 30_000,
            preset: "p2".into(),
            keyframe_interval_secs: 2,
            fps: 60,
            output_resolution: String::new(),
            audio_bitrate_kbps: 160,
            auto_restart: true,
            stall_timeout_secs: 90,
        }
    }
}

