30	    pub name: String,
31	    pub color: String,
32	    pub sort: i64,
33	    pub clip_count: i64,
34	}
35	
36	/// A non-destructive volume change on one audio track over a time range.
37	/// `gain` 0 = muted, 1 = unchanged, 2 = twice as loud. Times are seconds on
38	/// the media's own timeline (clip time), except in `Request::CutRange` where
39	/// they are wall-clock seconds (Unix time) on the 24/7 timeline.
40	#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
41	pub struct AudioEdit {
42	    pub track: usize,
43	    pub start: f64,
44	    pub end: f64,
45	    pub gain: f32,
46	}
47	
48	impl AudioEdit {
49	    pub fn overlaps(&self, a: f64, b: f64) -> bool {
50	        self.start < b && self.end > a
51	    }
52	}
53	
54	/// Apply a gain to `[a, b)` on `track`, replacing whatever edits covered that
55	/// range on that track. `gain == 1.0` simply clears the range.
56	pub fn apply_edit(edits: &mut Vec<AudioEdit>, track: usize, a: f64, b: f64, gain: f32) {
57	    let (a, b) = (a.min(b), a.max(b));
58	    if b - a < 0.01 {
59	        return;
60	    }
61	    let mut out = Vec::with_capacity(edits.len() + 2);
62	    for e in edits.drain(..) {
63	        if e.track != track || !e.overlaps(a, b) {
64	            out.push(e);
65	            continue;
66	        }
67	        // Keep the parts of the old edit outside [a, b).
68	        if e.start < a {
69	            out.push(AudioEdit { end: a, ..e });
70	        }
71	        if e.end > b {
72	            out.push(AudioEdit { start: b, ..e });
73	        }
74	    }
75	    if (gain - 1.0).abs() > 0.001 {
76	        out.push(AudioEdit { track, start: a, end: b, gain });
77	    }
78	    out.sort_by(|x, y| x.track.cmp(&y.track).then(x.start.total_cmp(&y.start)));
79	    *edits = out;
80	}
81	
82	/// Edits re-based onto a sub-range `[from, to)` of the timeline (e.g. when a
83	/// clip is cut from the 24/7 recording or trimmed): clipped to the range and
84	/// shifted so `from` becomes 0.
85	pub fn rebase_edits(edits: &[AudioEdit], from: f64, to: f64) -> Vec<AudioEdit> {
86	    edits
87	        .iter()
88	        .filter(|e| e.overlaps(from, to))
89	        .map(|e| AudioEdit { track: e.track, start: e.start.max(from) - from, end: e.end.min(to) - from, gain: e.gain })
90	        .collect()
91	}
92	
