100	    /// When the clip was saved (Unix ms).
101	    pub created_at: i64,
102	    /// Wall-clock time the clip's content starts, if known.
103	    pub source_start_ms: Option<i64>,
104	    pub duration: f64,
105	    pub size: i64,
