1	//! Audio-track mixing filter graphs for mpv (live playback) and ffmpeg (export).
2	//!
3	//! mpv can only play one audio track at a time, unless the tracks are combined
4	//! in `lavfi-complex`. Filters inside lavfi-complex can't be changed at runtime,
5	//! so we `join` all tracks into one multichannel stream there (each track's
6	//! left/right on its own named speaker pair), and do the per-track volume in
7	//! the regular `af` chain, where `af-command` can change gains live.
8	//!
9	//! Verified against libmpv with real OBS recordings (6 stereo tracks):
10	//! * the joined layout must list speakers in FFmpeg's canonical order, or mpv
11	//!   rejects the frames ("could not use filter output");
12	//! * remapping with `pan` into 2-channel side/top layouts fails in swresample,
13	//!   which is why `join` is used instead;
14	//! * volume changes via af-command are instant and survive seeks as long as
15	//!   the `af` option string is also kept current.
16	
17	/// Speaker pairs used to carry each track through the joined stream. None of
18	/// them is LFE (which may be low-pass filtered or dropped on conversion).
19	pub const CHANNEL_PAIRS: [(&str, &str); 6] =
20	    [("FL", "FR"), ("FC", "BC"), ("BL", "BR"), ("FLC", "FRC"), ("SL", "SR"), ("TFL", "TFR")];
21	
22	/// FFmpeg's canonical speaker order (AV_CH_* bit order) for the names above.
23	const CANONICAL: [&str; 14] = ["FL", "FR", "FC", "LFE", "BL", "BR", "FLC", "FRC", "BC", "SL", "SR", "TC", "TFL", "TFR"];
24	
25	fn joined_layout(n: usize) -> String {
26	    let used: Vec<&str> = CHANNEL_PAIRS[..n].iter().flat_map(|(a, b)| [*a, *b]).collect();
27	    CANONICAL.iter().filter(|c| used.contains(c)).copied().collect::<Vec<_>>().join("+")
28	}
29	
30	pub const MAX_MIX_TRACKS: usize = CHANNEL_PAIRS.len();
31	pub const MIX_FILTER_LABEL: &str = "cvmix";
32	
33	/// lavfi-complex graph merging `n` audio tracks (mpv aid 1..=n) into [ao].
34	/// Returns `None` when there is nothing to merge (0 or 1 track).
35	pub fn mpv_lavfi_complex(n: usize) -> Option<String> {
36	    let n = n.min(MAX_MIX_TRACKS);
37	    if n < 2 {
38	        return None;
39	    }
40	    let mut g = String::new();
41	    for i in 0..n {
42	        g.push_str(&format!("[aid{}]aformat=sample_rates=48000:channel_layouts=stereo[cvt{i}];", i + 1));
43	    }
44	    for i in 0..n {
45	        g.push_str(&format!("[cvt{i}]"));
46	    }
47	    let map: Vec<String> = (0..n)
48	        .map(|i| {
49	            let (a, b) = CHANNEL_PAIRS[i];
50	            format!("{i}.0-{a}|{i}.1-{b}")
51	        })
52	        .collect();
53	    g.push_str(&format!("join=inputs={n}:channel_layout={}:map={}[ao]", joined_layout(n), map.join("|")));
54	    Some(g)
55	}
56	
57	/// Per-track gain expression: the base gain times a factor for every edit on
58	/// that track (`if(between(t,a,b),g,1)`), evaluated per audio frame. `offset`
59	/// shifts edit times (e.g. an export that starts `offset` seconds into the
60	/// clip, where ffmpeg's `t` restarts at 0).
61	pub fn track_expr(base: f32, edits: &[crate::model::AudioEdit], track: usize, offset: f64) -> String {
62	    let mut s = fmt_gain(base);
63	    let mut n = 0;
64	    for e in edits.iter().filter(|e| e.track == track) {
65	        if n >= 400 {
66	            break; // keep expressions bounded
67	        }
68	        let (a, b) = (e.start - offset, e.end - offset);
69	        if b <= 0.0 {
70	            continue;
71	        }
72	        s.push_str(&format!("*if(between(t,{:.3},{:.3}),{},1)", a.max(0.0), b, fmt_gain(e.gain)));
73	        n += 1;
74	    }
75	    s
76	}
77	
78	/// Expressions for every track from plain gains (no edits).
79	pub fn gains_to_exprs(gains: &[f32]) -> Vec<String> {
80	    gains.iter().map(|g| fmt_gain(*g)).collect()
81	}
82	
83	/// Expressions for every track from gains + edits.
84	pub fn exprs_for(gains: &[f32], edits: &[crate::model::AudioEdit], offset: f64) -> Vec<String> {
85	    gains.iter().enumerate().map(|(i, g)| track_expr(*g, edits, i, offset)).collect()
86	}
87	
88	fn volume_filter(i: usize, expr: &str) -> String {
89	    format!("volume@g{i}=eval=frame:volume='{expr}'")
90	}
91	
92	/// The `af` chain that splits the joined stream back into tracks, applies a
93	/// gain expression per track (`volume@gN`), and mixes them, with a limiter so
94	/// boosting tracks can't clip.
95	pub fn mpv_af(exprs: &[String]) -> String {
96	    let n = exprs.len().min(MAX_MIX_TRACKS);
97	    if n < 2 {
98	        let e = exprs.first().cloned().unwrap_or_else(|| "1.000".into());
99	        return format!("@{MIX_FILTER_LABEL}:lavfi=[{}]", volume_filter(0, &e));
100	    }
101	    let splits: String = (0..n).map(|i| format!("[s{i}]")).collect();
102	    let mut graph = format!("asplit={n}{splits}");
103	    for (i, e) in exprs.iter().enumerate().take(n) {
104	        let (a, b) = CHANNEL_PAIRS[i];
105	        graph.push_str(&format!(";[s{i}]pan=stereo|c0={a}|c1={b},{}[m{i}]", volume_filter(i, e)));
106	    }
107	    let ms: String = (0..n).map(|i| format!("[m{i}]")).collect();
108	    graph.push_str(&format!(";{ms}amix=inputs={n}:normalize=0,alimiter=limit=0.98:level=disabled"));
109	    format!("@{MIX_FILTER_LABEL}:lavfi=[{graph}]")
110	}
111	
112	/// Arguments for mpv's `af-command` to change one track's gain live.
113	pub fn mpv_gain_command(track_index: usize, expr: &str) -> [String; 5] {
114	    [
115	        "af-command".into(),
116	        MIX_FILTER_LABEL.into(),
117	        "volume".into(),
118	        expr.to_string(),
119	        format!("volume@g{track_index}"),
120	    ]
121	}
122	
123	fn fmt_gain(g: f32) -> String {
124	    let g = if g.is_finite() { g.clamp(0.0, 4.0) } else { 1.0 };
125	    format!("{g:.3}")
126	}
127	
128	/// An expression whose base gain is zero is silent whatever the edits say.
129	pub fn is_silent(expr: &str) -> bool {
130	    expr.split('*').next().and_then(|b| b.parse::<f32>().ok()).map(|b| b <= 0.0005).unwrap_or(false)
131	}
132	
133	/// ffmpeg `-filter_complex` that mixes the given (track index, gain
134	/// expression) pairs of input 0 into `[aout]`. Silent tracks are skipped.
135	/// Returns `None` when every track is silent.
136	pub fn ffmpeg_mix_filter(tracks: &[(usize, String)]) -> Option<String> {
137	    let active: Vec<&(usize, String)> = tracks.iter().filter(|(_, e)| !is_silent(e)).collect();
138	    if active.is_empty() {
139	        return None;
140	    }
141	    let mut parts = Vec::new();
142	    for (k, (idx, e)) in active.iter().enumerate() {
143	        parts.push(format!(
144	            "[0:a:{idx}]aformat=sample_rates=48000:channel_layouts=stereo,volume=eval=frame:volume='{e}'[x{k}]"
145	        ));
146	    }
147	    let n = active.len();
148	    let ins: String = (0..n).map(|k| format!("[x{k}]")).collect();
149	    if n == 1 {
150	        parts.push(format!("{ins}alimiter=limit=0.98:level=disabled[aout]"));
151	    } else {
152	        parts.push(format!(
153	            "{ins}amix=inputs={n}:normalize=0:duration=longest,alimiter=limit=0.98:level=disabled[aout]"
154	        ));
155	    }
156	    Some(parts.join(";"))
157	}
158	
159	/// Default gains for a file with `n` tracks.
160	///
161	/// "full" mode plays only track 1 (the full mix). "separate" plays every
162	/// isolated stem except "Desktop" (track 6, which already contains game, voice
163	/// and music and would double them up).
164	pub fn default_gains(n: usize, mode: &str, multitrack_layout: bool) -> Vec<f32> {
165	    let mut g = vec![0.0; n];
166	    if n == 0 {
167	        return g;
168	    }
169	    if n == 1 || mode != "separate" || !multitrack_layout {
170	        g[0] = 1.0;
171	        return g;
172	    }
173	    for (i, v) in g.iter_mut().enumerate().skip(1) {
174	        *v = if i == crate::config::TRACK_DESKTOP - 1 { 0.0 } else { 1.0 };
175	    }
176	    g
177	}
178	
