1	//! ffmpeg/ffprobe: locating binaries, probing, thumbnails, cutting, exporting.
2	
3	use crate::timeline::CutPart;
4	use crate::util::hide_console;
5	use anyhow::{bail, Context, Result};
6	use serde::{Deserialize, Serialize};
7	use serde_json::Value;
8	use std::io::{BufRead, BufReader};
9	use std::path::{Path, PathBuf};
10	use std::process::{Command, Stdio};
11	use std::sync::atomic::{AtomicBool, Ordering};
12	use std::time::{Duration, Instant};
13	
14	#[derive(Debug, Clone, PartialEq)]
15	pub struct Tools {
16	    pub ffmpeg: PathBuf,
17	    pub ffprobe: PathBuf,
18	    pub version: String,
19	}
20	
21	/// Parse `ffmpeg version X ...` and decide whether it's recent enough.
22	/// Accepts release builds >= 5 and git builds `N-xxxxx` from 2022 onwards.
23	pub fn version_ok(first_line: &str) -> bool {
24	    let v = first_line
25	        .split_whitespace()
26	        .skip_while(|w| *w != "version")
27	        .nth(1)
28	        .unwrap_or("");
29	    if let Some(n) = v.strip_prefix("N-") {
30	        return n.split('-').next().and_then(|n| n.parse::<u64>().ok()).map(|n| n >= 105_000).unwrap_or(false);
31	    }
32	    let v = v.trim_start_matches('n');
33	    v.split(['.', '-']).next().and_then(|m| m.parse::<u32>().ok()).map(|m| m >= 5).unwrap_or(false)
34	}
35	
36	fn probe_version(exe: &Path) -> Option<String> {
37	    let mut cmd = Command::new(exe);
38	    cmd.arg("-hide_banner").arg("-version").stdout(Stdio::piped()).stderr(Stdio::null()).stdin(Stdio::null());
39	    hide_console(&mut cmd);
40	    let out = run_with_timeout(cmd, Duration::from_secs(10)).ok()?;
41	    let text = String::from_utf8_lossy(&out.stdout).to_string();
42	    let first = text.lines().next()?.to_string();
43	    version_ok(&first).then_some(first)
44	}
45	
46	fn candidate_dirs() -> Vec<PathBuf> {
47	    let mut dirs = vec![crate::paths::exe_dir(), crate::paths::exe_dir().join("bin")];
48	    for root in [r"C:\Program Files", r"C:\Program Files (x86)", r"C:\ffmpeg"] {
49	        if let Ok(rd) = std::fs::read_dir(root) {
50	            let mut found: Vec<PathBuf> = rd
51	                .flatten()
52	                .map(|e| e.path())
53	                .filter(|p| {
54	                    p.file_name()
55	                        .map(|n| n.to_string_lossy().to_lowercase().starts_with("ffmpeg"))
56	                        .unwrap_or(false)
57	                })
58	                .collect();
59	            found.sort();
60	            found.reverse(); // newest version folder first
61	            for f in found {
62	                dirs.push(f.join("bin"));
63	                dirs.push(f);
64	            }
65	        }
66	        dirs.push(PathBuf::from(root).join("bin"));
67	    }
68	    if let Some(path) = std::env::var_os("PATH") {
69	        dirs.extend(std::env::split_paths(&path));
70	    }
71	    dirs
72	}
