74	/// Find a working ffmpeg + ffprobe pair. Explicit paths win if they work.
75	pub fn locate(ffmpeg_cfg: &str, ffprobe_cfg: &str) -> Result<Tools> {
76	    let mut tried = Vec::new();
77	    let mut pairs: Vec<(PathBuf, PathBuf)> = Vec::new();
78	    if !ffmpeg_cfg.trim().is_empty() {
79	        let f = PathBuf::from(ffmpeg_cfg.trim());
80	        let p = if ffprobe_cfg.trim().is_empty() {
81	            f.with_file_name("ffprobe.exe")
82	        } else {
83	            PathBuf::from(ffprobe_cfg.trim())
84	        };
85	        pairs.push((f, p));
86	    }
87	    for d in candidate_dirs() {
88	        pairs.push((d.join("ffmpeg.exe"), d.join("ffprobe.exe")));
89	    }
90	    for (f, p) in pairs {
91	        if !f.is_file() || !p.is_file() {
92	            continue;
93	        }
94	        tried.push(f.display().to_string());
95	        if let Some(version) = probe_version(&f) {
96	            if probe_version(&p).is_some() {
97	                return Ok(Tools { ffmpeg: f, ffprobe: p, version });
98	            }
99	        }
100	    }
101	    bail!(
102	        "no usable ffmpeg 5+ with ffprobe found (checked {}). Set the path in Settings > Advanced.",
103	        if tried.is_empty() { "nothing".to_string() } else { tried.join(", ") }
104	    )
105	}
