107	/// Run a command, killing it if it exceeds `timeout`.
108	pub fn run_with_timeout(mut cmd: Command, timeout: Duration) -> Result<std::process::Output> {
109	    let mut child = cmd.spawn().context("starting process")?;
110	    let start = Instant::now();
111	    // Drain pipes on threads so a chatty process can't deadlock on a full pipe.
112	    let stdout = child.stdout.take();
113	    let stderr = child.stderr.take();
114	    let out_t = std::thread::spawn(move || {
115	        let mut v = Vec::new();
116	        if let Some(mut s) = stdout {
117	            let _ = std::io::Read::read_to_end(&mut s, &mut v);
118	        }
119	        v
120	    });
121	    let err_t = std::thread::spawn(move || {
122	        let mut v = Vec::new();
123	        if let Some(mut s) = stderr {
124	            let _ = std::io::Read::read_to_end(&mut s, &mut v);
125	        }
126	        v
127	    });
128	    let status = loop {
129	        if let Some(st) = child.try_wait()? {
130	            break st;
131	        }
132	        if start.elapsed() > timeout {
133	            let _ = child.kill();
134	            let _ = child.wait();
135	            bail!("process timed out after {:?}", timeout);
136	        }
137	        std::thread::sleep(Duration::from_millis(20));
138	    };
139	    Ok(std::process::Output { status, stdout: out_t.join().unwrap_or_default(), stderr: err_t.join().unwrap_or_default() })
140	}
