161	fn parse_rate(s: &str) -> f64 {
162	    match s.split_once('/') {
163	        Some((n, d)) => {
164	            let n: f64 = n.parse().unwrap_or(0.0);
165	            let d: f64 = d.parse().unwrap_or(0.0);
166	            if d > 0.0 {
167	                n / d
168	            } else {
169	                0.0
170	            }
171	        }
172	        None => s.parse().unwrap_or(0.0),
173	    }
174	}
