176	/// Parse ffprobe `-show_format -show_streams` JSON.
177	pub fn parse_probe_json(v: &Value) -> ProbeInfo {
178	    let mut info = ProbeInfo::default();
179	    let f = &v["format"];
180	    info.duration = f["duration"].as_str().and_then(|s| s.parse().ok()).unwrap_or(0.0);
181	    info.size = f["size"].as_str().and_then(|s| s.parse().ok()).unwrap_or(0);
182	    let mut audio_idx = 0;
183	    if let Some(streams) = v["streams"].as_array() {
184	        for s in streams {
185	            match s["codec_type"].as_str() {
186	                Some("video") if info.width == 0 => {
187	                    // Skip attached cover art.
188	                    if s["disposition"]["attached_pic"].as_i64() == Some(1) {
189	                        continue;
190	                    }
191	                    info.width = s["width"].as_u64().unwrap_or(0) as u32;
192	                    info.height = s["height"].as_u64().unwrap_or(0) as u32;
193	                    info.video_codec = s["codec_name"].as_str().unwrap_or("").to_string();
194	                    let avg = parse_rate(s["avg_frame_rate"].as_str().unwrap_or("0/0"));
195	                    let r = parse_rate(s["r_frame_rate"].as_str().unwrap_or("0/0"));
196	                    info.fps = if avg > 0.0 && avg < 1000.0 { avg } else { r };
197	                    if info.duration <= 0.0 {
198	                        info.duration = s["duration"].as_str().and_then(|d| d.parse().ok()).unwrap_or(0.0);
199	                    }
200	                }
201	                Some("audio") => {
202	                    let tags = &s["tags"];
203	                    let mut title = tags["title"].as_str().unwrap_or("").to_string();
204	                    if title.is_empty() {
205	                        let h = tags["handler_name"].as_str().unwrap_or("");
206	                        if !h.is_empty() && !h.eq_ignore_ascii_case("SoundHandler") && !h.contains("Handler") {
207	                            title = h.to_string();
208	                        }
209	                    }
210	                    info.audio.push(AudioTrack {
211	                        index: audio_idx,
212	                        title,
213	                        channels: s["channels"].as_u64().unwrap_or(0) as u32,
214	                        sample_rate: s["sample_rate"].as_str().and_then(|r| r.parse().ok()).unwrap_or(0),
215	                    });
216	                    audio_idx += 1;
217	                }
218	                _ => {}
219	            }
220	        }
221	    }
222	    info
223	}
