226	    pub fn probe(&self, path: &Path) -> Result<ProbeInfo> {
227	        let mut cmd = Command::new(&self.ffprobe);
228	        cmd.args(["-v", "error", "-print_format", "json", "-show_format", "-show_streams"])
229	            .arg(path)
230	            .stdin(Stdio::null())
231	            .stdout(Stdio::piped())
232	            .stderr(Stdio::piped());
233	        hide_console(&mut cmd);
234	        let out = run_with_timeout(cmd, Duration::from_secs(60))?;
235	        if !out.status.success() {
236	            bail!("ffprobe failed on {}: {}", path.display(), String::from_utf8_lossy(&out.stderr).trim());
237	        }
238	        let v: Value = serde_json::from_slice(&out.stdout).context("ffprobe output")?;
239	        let mut info = parse_probe_json(&v);
240	        if info.size == 0 {
241	            info.size = std::fs::metadata(path).map(|m| m.len()).unwrap_or(0);
242	        }
243	        Ok(info)
244	    }
