246	    /// Grab one frame at `at_s` as a JPEG `width` pixels wide.
247	    pub fn thumbnail(&self, input: &Path, at_s: f64, out: &Path, width: u32) -> Result<()> {
248	        if let Some(p) = out.parent() {
249	            std::fs::create_dir_all(p)?;
250	        }
251	        let tmp = out.with_extension("tmp.jpg");
252	        let attempt = |t: f64| -> Result<bool> {
253	            let mut cmd = Command::new(&self.ffmpeg);
254	            cmd.args(["-hide_banner", "-loglevel", "error", "-nostdin", "-y", "-ss"])
255	                .arg(format!("{t:.3}"))
256	                .arg("-i")
257	                .arg(input)
258	                .args(["-frames:v", "1", "-an", "-vf"])
259	                .arg(format!("scale={width}:-2:flags=bicubic"))
260	                .args(["-q:v", "4", "-f", "image2"])
261	                .arg(&tmp)
262	                .stdin(Stdio::null())
263	                .stdout(Stdio::null())
264	                .stderr(Stdio::piped());
265	            hide_console(&mut cmd);
266	            let out = run_with_timeout(cmd, Duration::from_secs(60))?;
267	            Ok(out.status.success() && tmp.metadata().map(|m| m.len() > 0).unwrap_or(false))
268	        };
269	        if attempt(at_s.max(0.0))? || attempt(0.0)? {
270	            std::fs::rename(&tmp, out)?;
271	            Ok(())
272	        } else {
273	            let _ = std::fs::remove_file(&tmp);
274	            bail!("could not extract a frame from {}", input.display())
275	        }
276	    }
