404	/// Build ffmpeg args for cutting `parts` into `out`.
405	///
406	/// * fast (`precise == false`): stream copy, starts at the keyframe before the
407	///   in-point (an MP4 edit list hides the extra frames in most players).
408	/// * precise: re-encodes video, frame exact. Audio tracks are re-encoded too.
409	pub fn cut_args(parts: &[CutPart], out: &Path, list_file: &Path, precise: bool, audio_tracks: usize, enc: &EncodeOptions) -> Result<Vec<String>> {
410	    if parts.is_empty() {
411	        bail!("nothing to cut");
412	    }
413	    let mut a: Vec<String> = Vec::new();
414	    if parts.len() == 1 || !precise {
415	        if parts.len() == 1 {
416	            let p = &parts[0];
417	            a.push("-ss".into());
418	            a.push(secs(p.in_s));
419	            if let Some(o) = p.out_s {
420	                a.push("-t".into());
421	                a.push(secs(o - p.in_s));
422	            }
423	            a.push("-i".into());
424	            a.push(p.path.to_string_lossy().to_string());
425	        } else {
426	            a.extend(["-f", "concat", "-safe", "0", "-i"].iter().map(|s| s.to_string()));
427	            a.push(list_file.to_string_lossy().to_string());
428	        }
429	        a.extend(["-map", "0:v:0", "-map", "0:a?"].iter().map(|s| s.to_string()));
430	        if precise {
431	            a.extend(video_quality_args(enc));
432	            a.extend(["-c:a", "aac", "-b:a"].iter().map(|s| s.to_string()));
433	            a.push(format!("{}k", enc.audio_bitrate_kbps));
434	        } else {
435	            a.extend(["-c", "copy"].iter().map(|s| s.to_string()));
436	        }
437	    } else {
438	        // Precise multi-file: trim the first/last inputs and join with the
439	        // concat filter, carrying every audio track through.
440	        let n = parts.len();
441	        for p in parts {
442	            if p.in_s > 0.0 {
443	                a.push("-ss".into());
444	                a.push(secs(p.in_s));
445	            }
446	            if let Some(o) = p.out_s {
447	                a.push("-t".into());
448	                a.push(secs(o - p.in_s));
449	            }
450	            a.push("-i".into());
451	            a.push(p.path.to_string_lossy().to_string());
452	        }
453	        let mut f = String::new();
454	        for i in 0..n {
455	            f.push_str(&format!("[{i}:v:0]"));
456	            for t in 0..audio_tracks {
457	                f.push_str(&format!("[{i}:a:{t}]"));
458	            }
459	        }
460	        f.push_str(&format!("concat=n={n}:v=1:a={audio_tracks}[v]"));
461	        for t in 0..audio_tracks {
462	            f.push_str(&format!("[a{t}]"));
463	        }
464	        a.push("-filter_complex".into());
465	        a.push(f);
466	        a.push("-map".into());
467	        a.push("[v]".into());
468	        for t in 0..audio_tracks {
469	            a.push("-map".into());
470	            a.push(format!("[a{t}]"));
471	        }
472	        a.extend(video_quality_args(enc));
473	        if audio_tracks > 0 {
474	            a.extend(["-c:a", "aac", "-b:a"].iter().map(|s| s.to_string()));
475	            a.push(format!("{}k", enc.audio_bitrate_kbps));
476	        }
477	    }
478	    a.extend(["-movflags", "+faststart", "-f", "mp4"].iter().map(|s| s.to_string()));
479	    a.push(out.to_string_lossy().to_string());
480	    Ok(a)
481	}
