497	/// Video bitrate (kbps) that fits `target_mb` for `duration_s`, or None if impossible.
498	pub fn bitrate_for_size(target_mb: u32, duration_s: f64, audio_kbps: u32) -> Option<u32> {
499	    if duration_s <= 0.0 {
500	        return None;
501	    }
502	    let total_kbits = target_mb as f64 * 8.0 * 1024.0 * 0.94; // container overhead margin
503	    let video = total_kbits / duration_s - audio_kbps as f64;
504	    (video >= 150.0).then(|| video.floor() as u32)
505	}
