507	/// Height to scale to for a given bitrate so quality stays reasonable.
508	pub fn height_for_bitrate(kbps: u32, source_h: u32, max_h: u32) -> u32 {
509	    let cap = if kbps < 1200 {
510	        480
511	    } else if kbps < 2500 {
512	        720
513	    } else if kbps < 6000 {
514	        1080
515	    } else {
516	        source_h
517	    };
518	    let mut h = source_h.min(cap);
519	    if max_h > 0 {
520	        h = h.min(max_h);
521	    }
522	    h - h % 2
523	}
