525	pub fn export_args(input: &Path, out: &Path, spec: &ExportSpec, enc: &EncodeOptions, info: &ProbeInfo, video_kbps: Option<u32>) -> Vec<String> {
526	    let mut a: Vec<String> = Vec::new();
527	    let reencode = video_kbps.is_some() || spec.reencode_video;
528	    if let Some((s, e)) = spec.range {
529	        a.push("-ss".into());
530	        a.push(secs(s));
531	        a.push("-t".into());
532	        a.push(secs(e - s));
533	    }
534	    a.push("-i".into());
535	    a.push(input.to_string_lossy().to_string());
536	    let mix = if spec.gains.is_empty() { None } else { crate::mixer::ffmpeg_mix_filter(&spec.gains) };
537	    let mut filters: Vec<String> = Vec::new();
538	    let target_h = video_kbps.map(|k| height_for_bitrate(k, info.height, spec.max_height)).unwrap_or(info.height);
539	    let scale = reencode && target_h > 0 && target_h < info.height;
540	    if scale {
541	        filters.push(format!("[0:v:0]scale=-2:{target_h}:flags=lanczos[vout]"));
542	    }
543	    if let Some(m) = &mix {
544	        filters.push(m.clone());
545	    }
546	    if !filters.is_empty() {
547	        a.push("-filter_complex".into());
548	        a.push(filters.join(";"));
549	    }
550	    a.push("-map".into());
551	    a.push(if scale { "[vout]".into() } else { "0:v:0".into() });
552	    match (&mix, spec.gains.is_empty()) {
553	        (Some(_), _) => {
554	            a.push("-map".into());
555	            a.push("[aout]".into());
556	        }
557	        (None, true) => {
558	            a.push("-map".into());
559	            a.push("0:a?".into());
560	        }
561	        (None, false) => {} // everything muted -> no audio
562	    }
563	    if let Some(k) = video_kbps {
564	        a.extend(["-c:v".to_string(), enc.video_encoder.clone()]);
565	        if enc.video_encoder.contains("nvenc") {
566	            a.extend(["-preset", "p6", "-rc", "vbr", "-multipass", "fullres"].iter().map(|s| s.to_string()));
567	        } else {
568	            a.extend(["-preset", "medium"].iter().map(|s| s.to_string()));
569	        }
570	        a.extend([
571	            "-b:v".to_string(),
572	            format!("{k}k"),
573	            "-maxrate".to_string(),
574	            format!("{}k", (k as f64 * 1.15) as u32),
575	            "-bufsize".to_string(),
576	            format!("{}k", k * 2),
577	            "-pix_fmt".to_string(),
578	            "yuv420p".to_string(),
579	        ]);
580	    } else if spec.reencode_video {
581	        a.extend(video_quality_args(enc));
582	    } else {
583	        a.extend(["-c:v", "copy"].iter().map(|s| s.to_string()));
584	    }
585	    if mix.is_some() {
586	        a.extend(["-c:a".to_string(), "aac".to_string(), "-b:a".to_string(), format!("{}k", enc.audio_bitrate_kbps)]);
587	    } else if spec.gains.is_empty() {
588	        a.extend(["-c:a", "copy"].iter().map(|s| s.to_string()));
589	    }
590	    a.extend(["-movflags", "+faststart", "-f", "mp4"].iter().map(|s| s.to_string()));
591	    a.push(out.to_string_lossy().to_string());
592	    a
593	}
