698	    fn real_ffmpeg_cut_probe_thumb_export() {
699	        let Ok(tools) = locate("", "") else {
700	            eprintln!("ffmpeg not found; skipping");
701	            return;
702	        };
703	        let dir = tempfile::tempdir().unwrap();
704	        let src = dir.path().join("src.mp4");
705	        // 12s test video, 2 audio tracks, keyframe every 1s, fragmented like OBS.
706	        let mut cmd = Command::new(&tools.ffmpeg);
707	        cmd.args(["-hide_banner", "-loglevel", "error", "-y", "-f", "lavfi", "-i", "testsrc2=size=320x240:rate=30",
708	                  "-f", "lavfi", "-i", "sine=frequency=440:sample_rate=48000",
709	                  "-f", "lavfi", "-i", "sine=frequency=880:sample_rate=48000",
710	                  "-t", "12", "-map", "0:v", "-map", "1:a", "-map", "2:a",
711	                  "-c:v", "libx264", "-preset", "ultrafast", "-g", "30",
712	                  "-c:a", "aac", "-metadata:s:a:1", "handler_name=Game",
713	                  "-movflags", "frag_keyframe+empty_moov+delay_moov"])
714	            .arg(&src);
715	        hide_console(&mut cmd);
716	        let st = cmd.status().unwrap();
717	        assert!(st.success());
718	        let info = tools.probe(&src).unwrap();
719	        assert!((info.duration - 12.0).abs() < 0.2, "{}", info.duration);
720	        assert_eq!(info.audio.len(), 2);
721	        assert_eq!(info.audio[1].title, "Game");
722	
723	        let thumb = dir.path().join("t.jpg");
724	        tools.thumbnail(&src, 3.0, &thumb, 160).unwrap();
725	        assert!(thumb.metadata().unwrap().len() > 100);
726	
727	        // Fast cut, precise cut, multi-part concat.
728	        let cancel = AtomicBool::new(false);
729	        for (precise, parts, expect) in [
730	            (false, vec![CutPart { path: src.clone(), in_s: 2.0, out_s: Some(6.0) }], 4.0),
731	            (true, vec![CutPart { path: src.clone(), in_s: 2.5, out_s: Some(6.5) }], 4.0),
732	            (false, vec![CutPart { path: src.clone(), in_s: 8.0, out_s: None }, CutPart { path: src.clone(), in_s: 0.0, out_s: Some(2.0) }], 6.0),
733	            (true, vec![CutPart { path: src.clone(), in_s: 8.0, out_s: None }, CutPart { path: src.clone(), in_s: 0.0, out_s: Some(2.0) }], 6.0),
734	        ] {
735	            let out = dir.path().join(format!("cut_{precise}_{}.mp4", parts.len()));
736	            let list = dir.path().join("list.ffconcat");
737	            std::fs::write(&list, concat_list(&parts)).unwrap();
738	            let enc = EncodeOptions { video_encoder: "libx264".into(), quality: 30, audio_bitrate_kbps: 96 };
739	            let args = cut_args(&parts, &out, &list, precise, 2, &enc).unwrap();
740	            let mut last = 0.0f32;
741	            tools.run_progress(&args, 4.0, &mut |p| last = p, &cancel).unwrap();
742	            assert_eq!(last, 1.0);
743	            let ci = tools.probe(&out).unwrap();
744	            assert_eq!(ci.audio.len(), 2, "all audio tracks kept ({precise})");
745	            // Precise cuts are frame exact; fast cuts may start up to one keyframe early.
746	            let tol = if precise { 0.15 } else { 1.1 };
747	            assert!((ci.duration - expect).abs() < tol, "duration {} expected {expect} precise={precise}", ci.duration);
748	        }
749	
750	        // Export with a custom mix to a size target.
751	        let out = dir.path().join("share.mp4");
752	        let spec = ExportSpec { gains: vec![(0, "1.000".into()), (1, "0.300*if(between(t,2.000,4.000),0.000,1)".into())], range: None, target_size_mb: Some(1), max_height: 0, reencode_video: false };
753	        let enc = EncodeOptions { video_encoder: "libx264".into(), quality: 30, audio_bitrate_kbps: 96 };
754	        let k = bitrate_for_size(1, info.duration, 96).unwrap();
755	        let args = export_args(&src, &out, &spec, &enc, &info, Some(k));
756	        tools.run_progress(&args, info.duration, &mut |_| {}, &cancel).unwrap();
757	        let ei = tools.probe(&out).unwrap();
758	        assert_eq!(ei.audio.len(), 1, "mixed down to one track");
759	        assert!(ei.size <= 1024 * 1024 + 64 * 1024, "size {}", ei.size);
760	
761	        // Cancellation stops promptly.
762	        let cancel = AtomicBool::new(true);
763	        let r = tools.run_progress(&args, info.duration, &mut |_| {}, &cancel);
764	        assert!(r.is_err());
765	    }
