1	//! ClipVault background service.
2	//!
3	//! Started at login (Startup folder). Launches and supervises OBS, keeps the
4	//! 24/7 recording and replay buffer running, owns the clip hotkeys, keeps the
5	//! microphone pointed at the right device, files clips by game and enforces
6	//! recording retention. Shows only a tray icon; the GUI (clipvault.exe) talks
7	//! to it over a local socket.
8	
9	#![windows_subsystem = "windows"]
10	
11	mod activity;
12	mod audio_guard;
13	mod clips;
14	mod ipc_server;
15	mod jobs;
16	mod library;
17	mod obs_setup;
18	mod shared;
19	mod startup;
20	mod status;
21	mod supervisor;
22	mod waves;
23	mod win;
24	
25	use crate::shared::{LibCmd, Shared, SupCmd};
26	use crate::win::ui::{self, Action, ToastLevel, UiCmd};
27	use anyhow::Result;
28	use cv_core::config::Config;
29	use cv_core::ipc::Event;
30	use parking_lot::{Mutex, RwLock};
31	use std::sync::atomic::Ordering;
32	use std::sync::Arc;
33	use std::time::Duration;
34	
35	fn main() {
36	    let args: Vec<String> = std::env::args().collect();
37	    if args.len() > 1 {
38	        attach_console();
39	        let code = match cli(&args[1..]) {
40	            Ok(()) => 0,
41	            Err(e) => {
42	                eprintln!("error: {e:#}");
43	                1
44	            }
45	        };
46	        std::process::exit(code);
47	    }
48	    if let Err(e) = run_service() {
49	        tracing::error!("service failed: {e:#}");
50	        std::process::exit(1);
51	    }
52	}
53	
54	fn attach_console() {
55	    unsafe {
56	        let _ = windows::Win32::System::Console::AttachConsole(windows::Win32::System::Console::ATTACH_PARENT_PROCESS);
57	    }
58	}
59	
60	/// Command-line maintenance commands (used by the installer and for diagnostics).
61	fn cli(args: &[String]) -> Result<()> {
62	    cv_core::paths::ensure_dirs()?;
63	    match args[0].as_str() {
64	        "--version" => println!("ClipVault service {}", cv_core::VERSION),
65	        "--migrate" => {
66	            let dir = args.get(1).map(std::path::PathBuf::from).ok_or_else(|| anyhow::anyhow!("--migrate <old program folder>"))?;
67	            let cfg = startup::migrate_legacy(&dir)?;
68	            println!("config written to {}", cv_core::paths::config_path().display());
69	            println!("recordings: {}  clips: {}  retention: {}h  replay: {}s  mic: {:?}", cfg.recording.folder, cfg.clips.folder, cfg.recording.retention_hours, cfg.clips.clip_length_secs, cfg.audio.mic_priority);
70	        }
71	        "--install-shortcuts" => {
72	            let cfg = startup::load_or_first_run();
73	            startup::sync_startup_shortcut(&cfg)?;
74	            startup::create_app_shortcuts(args.iter().any(|a| a == "--desktop"))?;
75	            println!("shortcuts created");
76	        }
77	        "--remove-startup" => {
78	            let mut cfg = Config::load_or_default();
79	            cfg.general.start_with_windows = false;
80	            startup::sync_startup_shortcut(&cfg)?;
81	        }
82	        "--diagnose" => diagnose()?,
83	        "--stop" => {
84	            let (client, _) = cv_core::ipc::IpcClient::connect(Duration::from_secs(3))?;
85	            client.call(cv_core::ipc::Request::Shutdown, Duration::from_secs(5))?;
86	            println!("service stopping");
87	        }
88	        other => anyhow::bail!("unknown option {other}"),
89	    }
90	    Ok(())
91	}
92	
93	fn diagnose() -> Result<()> {
94	    let cfg = startup::load_or_first_run();
95	    let devices = std::thread::spawn(|| {
96	        win::coreaudio::com_init_mta();
97	        let sys = win::coreaudio::AudioSystem::new(None).ok()?;
98	        Some((sys.inputs(), sys.outputs(), sys.default_endpoint(true), sys.default_endpoint(false), sys.sessions_by_output()))
99	    })
100	    .join()
101	    .ok()
102	    .flatten();
103	    let files = cv_core::obs::files::ObsConfigFiles::from_config(&cfg);
104	    let ws = files.read_websocket();
105	    let procs = win::process::list_processes();
106	    let names: std::collections::HashMap<u32, String> = procs.iter().map(|p| (p.pid, p.exe_name.clone())).collect();
107	    let out = serde_json::json!({
108	        "config": cv_core::paths::config_path(),
109	        "obs_running": win::process::find_by_exe(std::path::Path::new(&cfg.obs.exe_path)),
110	        "websocket": {"enabled": ws.enabled, "port": ws.port, "has_password": !ws.password.is_empty()},
111	        "profile": format!("{:?}", files.read_profile_summary().ok()),
112	        "settings_pending": files.apply_settings(&cfg, true).ok(),
113	        "ffmpeg": cv_core::ffmpeg::locate(&cfg.advanced.ffmpeg_path, &cfg.advanced.ffprobe_path).map(|t| t.ffmpeg.display().to_string()).unwrap_or_else(|e| e.to_string()),
114	        "mic_priority": cfg.audio.mic_priority,
115	        "inputs": devices.as_ref().map(|d| &d.0),
116	        "outputs": devices.as_ref().map(|d| &d.1),
117	        "default_input": devices.as_ref().and_then(|d| d.2.clone()),
118	        "default_output": devices.as_ref().and_then(|d| d.3.clone()),
119	        "sessions": devices.as_ref().map(|d| d.4.iter().map(|(k, v)| (k.clone(), v.iter().map(|p| names.get(p).cloned().unwrap_or_default()).collect::<Vec<_>>())).collect::<std::collections::HashMap<_, _>>()),
120	    });
121	    println!("{}", serde_json::to_string_pretty(&out)?);
122	    Ok(())
123	}
124	
125	fn run_service() -> Result<()> {
126	    cv_core::paths::ensure_dirs()?;
127	    let cfg = startup::load_or_first_run();
128	    let _log = cv_core::logging::init("service", &cfg.advanced.log_level, cfg.advanced.log_retention_days);
129	    let Some(_instance) = win::process::SingleInstance::acquire("Local\\ClipVaultService") else {
130	        tracing::info!("another ClipVault service is already running; exiting");
131	        return Ok(());
132	    };
133	    unsafe {
134	        let _ = windows::Win32::UI::HiDpi::SetProcessDpiAwarenessContext(
135	            windows::Win32::UI::HiDpi::DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2,
136	        );
137	    }
138	    tracing::info!("ClipVault service {} starting", cv_core::VERSION);
139	    if let Err(e) = startup::sync_startup_shortcut(&cfg) {
140	        tracing::warn!("startup shortcut: {e:#}");
141	    }
142	
143	    let cfg = Arc::new(RwLock::new(cfg));
144	    let (ui_handle, ui_rx) = ui::channel();
145	    let (sup_tx, sup_rx) = crossbeam_channel::unbounded();
146	    let (clip_tx, clip_rx) = crossbeam_channel::unbounded();
147	    let (job_tx, job_rx) = crossbeam_channel::unbounded();
148	    let (lib_tx, lib_rx) = crossbeam_channel::unbounded();
149	    let (audio_tx, audio_rx) = crossbeam_channel::bounded(4);
150	    let (action_tx, action_rx) = crossbeam_channel::unbounded();
151	    let hotkey_errors = Arc::new(Mutex::new(Vec::new()));
152	    let sh = Arc::new(Shared {
153	        cfg: cfg.clone(),
154	        status: Mutex::new(cv_core::ipc::Status { service_started_ms: cv_core::util::now_ms(), ..Default::default() }),
155	        ui: ui_handle.clone(),
156	        sup_tx,
157	        clip_tx,
158	        job_tx,
159	        lib_tx,
160	        audio_tx,
161	        clients: Mutex::new(Vec::new()),
162	        tools: RwLock::new(None),
163	        hotkey_errors: hotkey_errors.clone(),
164	        devices: Mutex::new(Default::default()),
165	        jobs: Mutex::new(Vec::new()),
166	        event_db: Mutex::new(None),
167	        library_lock: Mutex::new(()),
168	        shutdown: std::sync::atomic::AtomicBool::new(false),
169	    });
170	    sh.log_event("info", format!("ClipVault service {} started", cv_core::VERSION));
171	
172	    spawn("supervisor", { let sh = sh.clone(); move || supervisor::Supervisor::new(sh, sup_rx).run() });
173	    spawn("activity", { let sh = sh.clone(); move || activity::run(sh) });
174	    spawn("audio-guard", { let sh = sh.clone(); move || audio_guard::run(sh, audio_rx) });
175	    spawn("library", { let sh = sh.clone(); move || library::run(sh, lib_rx) });
176	    spawn("clips", { let sh = sh.clone(); move || clips::run(sh, clip_rx) });
177	    spawn("jobs", { let sh = sh.clone(); move || jobs::run(sh, job_rx) });
178	    spawn("status", { let sh = sh.clone(); move || status::run(sh) });
179	    spawn("actions", { let sh = sh.clone(); move || actions(sh, action_rx) });
180	    spawn("tools", { let sh = sh.clone(); move || { let _ = sh.tools(); } });
181	    spawn("waves", { let sh = sh.clone(); move || waves::run(sh) });
182	    if let Err(e) = ipc_server::start(sh.clone()) {
183	        tracing::error!("GUI connection unavailable: {e:#}");
184	    }
185	
186	    // The UI message loop runs on the main thread until shutdown.
187	    ui::run(ui_handle, ui_rx, action_tx, cfg, hotkey_errors)?;
188	    request_shutdown(&sh);
189	    std::thread::sleep(Duration::from_millis(500));
190	    let _ = std::fs::remove_file(cv_core::paths::ipc_info_path());
191	    tracing::info!("ClipVault service stopped");
192	    Ok(())
193	}
194	
195	fn spawn(name: &str, f: impl FnOnce() + Send + 'static) {
196	    let n = name.to_string();
197	    std::thread::Builder::new()
198	        .name(name.into())
199	        .spawn(move || {
200	            let r = std::panic::catch_unwind(std::panic::AssertUnwindSafe(f));
201	            if r.is_err() {
202	                tracing::error!("thread {n} panicked");
203	            }
204	        })
205	        .expect("spawn thread");
206	}
207	
208	pub fn request_shutdown(sh: &Shared) {
209	    if sh.shutdown.swap(true, Ordering::SeqCst) {
210	        return;
211	    }
212	    let _ = sh.sup_tx.send(SupCmd::Shutdown);
213	    sh.ui.send(UiCmd::Quit);
214	}
215	
216	/// Handle hotkeys and tray menu actions.
217	fn actions(sh: Arc<Shared>, rx: crossbeam_channel::Receiver<Action>) {
218	    for a in rx {
219	        match a {
220	            Action::SaveClip => {
221	                let _ = sh.sup_tx.send(SupCmd::SaveClip { short: false, reply: None });
222	            }
223	            Action::SaveShortClip => {
224	                let _ = sh.sup_tx.send(SupCmd::SaveClip { short: true, reply: None });
225	            }
226	            Action::AddMarker => match add_marker(&sh, "") {
227	                Ok(_) => sh.toast(ToastLevel::Info, "Marker added to the 24/7 timeline"),
228	                Err(e) => sh.toast(ToastLevel::Error, format!("Marker failed: {e}")),
229	            },
230	            Action::ToggleRecording => {
231	                let paused = sh.status.lock().recording.paused_by_user;
232	                let _ = sh.sup_tx.send(SupCmd::SetRecording { enabled: paused, reply: None });
233	            }
234	            Action::OpenGui => open_gui(&sh),
235	            Action::RestartObs => {
236	                let _ = sh.sup_tx.send(SupCmd::RestartObs { reply: None });
237	            }
238	            Action::OpenClipsFolder => win::shell::open_in_explorer(std::path::Path::new(&sh.cfg.read().clips.folder)),
239	            Action::OpenRecordingsFolder => win::shell::open_in_explorer(std::path::Path::new(&sh.cfg.read().recording.folder)),
240	            Action::QuitService | Action::SessionEnding => {
