27	}
28	
29	pub struct Supervisor {
30	    sh: Arc<Shared>,
31	    rx: Receiver<SupCmd>,
32	    obs: Option<Arc<ObsClient>>,
33	    events: Option<Receiver<ObsEvent>>,
34	    pid: Option<u32>,
35	    started: Instant,
36	    launches: VecDeque<Instant>,
37	    closed_by_user: bool,
38	    expecting_exit: bool,
39	    exit_started: bool,
40	    recording_wanted: bool,
41	    last_connect_try: Option<Instant>,
42	    connect_failures: u32,
43	    settings_restart_done: bool,
44	    // outputs
45	    rec_active: bool,
46	    rec_path: String,
47	    rec_started_ms: i64,
48	    rec_bytes: i64,
49	    rec_bytes_changed: Instant,
50	    stall_restarts: VecDeque<Instant>,
51	    last_start_attempt: Option<Instant>,
52	    start_failures: u32,
53	    replay_active: bool,
54	    last_replay_attempt: Option<Instant>,
55	    // audio
56	    managed: Option<Managed>,
57	    inputs_dirty: bool,
58	    mic: Option<MicDecision>,
59	    mic_applied: Option<String>,
60	    desktop_device: Option<String>,
61	    desktop_applied: Option<String>,
62	    routing: HashMap<String, bool>,
63	    game: Option<GameTarget>,
64	    game_applied: Option<String>,
65	    pending_save: Option<PendingSave>,
66	    last_save_request: Option<Instant>,
67	    meters_emitted: Instant,
68	    mic_last_sound: Instant,
69	    mic_silence_warned: bool,
70	    tick_count: u64,
71	    last_error: String,
72	}
73	
74	impl Supervisor {
75	    pub fn new(sh: Arc<Shared>, rx: Receiver<SupCmd>) -> Self {
76	        let wanted = cv_core::db::Db::open_default()
77	            .ok()
78	            .and_then(|db| db.meta_get(META_RECORDING_WANTED).ok().flatten())
79	            .map(|v| v != "0")
80	            .unwrap_or(true);
81	        Self {
82	            sh,
83	            rx,
84	            obs: None,
85	            events: None,
86	            pid: None,
87	            started: Instant::now(),
88	            launches: VecDeque::new(),
89	            closed_by_user: false,
90	            expecting_exit: false,
91	            exit_started: false,
92	            recording_wanted: wanted,
93	            last_connect_try: None,
94	            connect_failures: 0,
95	            settings_restart_done: false,
96	            rec_active: false,
97	            rec_path: String::new(),
98	            rec_started_ms: 0,
99	            rec_bytes: 0,
100	            rec_bytes_changed: Instant::now(),
101	            stall_restarts: VecDeque::new(),
102	            last_start_attempt: None,
103	            start_failures: 0,
104	            replay_active: false,
105	            last_replay_attempt: None,
106	            managed: None,
107	            inputs_dirty: true,
108	            mic: None,
109	            mic_applied: None,
110	            desktop_device: None,
111	            desktop_applied: None,
112	            routing: HashMap::new(),
113	            game: None,
114	            game_applied: None,
115	            pending_save: None,
116	            last_save_request: None,
117	            meters_emitted: Instant::now(),
118	            mic_last_sound: Instant::now(),
119	            mic_silence_warned: false,
120	            tick_count: 0,
121	            last_error: String::new(),
122	        }
123	    }
124	
125	    pub fn run(mut self) {
126	        tracing::info!("supervisor started (24/7 recording {})", if self.recording_wanted { "on" } else { "paused" });
127	        let mut next_tick = Instant::now();
128	        loop {
129	            if self.sh.is_shutting_down() {
130	                break;
131	            }
132	            let ev_rx = self.events.clone().unwrap_or_else(never);
133	            let timeout = next_tick.saturating_duration_since(Instant::now());
134	            select! {
135	                recv(self.rx) -> cmd => match cmd {
136	                    Ok(SupCmd::Shutdown) | Err(_) => break,
137	                    Ok(cmd) => self.command(cmd),
138	                },
139	                recv(ev_rx) -> ev => match ev {
140	                    Ok(ev) => self.obs_event(ev),
141	                    Err(_) => self.disconnected("event channel closed".into()),
142	                },
143	                default(timeout) => {}
144	            }
145	            if Instant::now() >= next_tick {
146	                self.tick();
147	                let secs = self.sh.cfg.read().advanced.health_check_secs.max(1) as u64;
148	                next_tick = Instant::now() + Duration::from_secs(secs);
149	            }
150	        }
151	        if let Some(obs) = &self.obs {
152	            obs.close();
153	        }
154	        tracing::info!("supervisor stopped");
155	    }
156	
157	    fn obs_exe(&self) -> PathBuf {
158	        PathBuf::from(self.sh.cfg.read().obs.exe_path.trim())
159	    }
160	
161	    fn files(&self) -> ObsConfigFiles {
162	        ObsConfigFiles::from_config(&self.sh.cfg.read())
163	    }
164	
165	    fn connected(&self) -> Option<Arc<ObsClient>> {
166	        self.obs.as_ref().filter(|o| o.is_alive()).cloned()
167	    }
168	
169	    // ------------------------------------------------------------ tick
170	
171	    fn tick(&mut self) {
172	        self.tick_count += 1;
173	        let cfg = self.sh.cfg();
174	
175	        // Process state.
176	        if let Some(pid) = self.pid {
177	            if !process::is_running(pid) {
178	                self.obs_process_exited();
179	            }
180	        }
181	        if self.pid.is_none() {
182	            let exe = self.obs_exe();
183	            if let Some(pid) = process::find_by_exe(&exe).into_iter().next() {
184	                tracing::info!("found running OBS (pid {pid})");
185	                self.pid = Some(pid);
186	            }
187	        }
188	        if self.pid.is_none() {
189	            if self.should_launch(&cfg) {
190	                self.launch();
191	            }
192	            self.publish_status();
193	            return;
194	        }
195	
196	        // Connection.
197	        if self.connected().is_none() {
198	            let due = self.last_connect_try.map(|t| t.elapsed() >= Duration::from_secs(2)).unwrap_or(true);
199	            if due {
200	                self.try_connect();
201	            }
202	            // An OBS we didn't start, with the websocket switched off: restart it
203	            // once so the websocket (and our settings) take effect.
204	            if self.connected().is_none()
205	                && self.connect_failures >= 8
206	                && !self.settings_restart_done
207	                && !self.files().read_websocket().enabled
208	            {
209	                self.settings_restart_done = true;
210	                self.sh.log_event("warn", "OBS websocket is off; restarting OBS to enable it");
211	                self.restart_obs("enabling the OBS websocket");
212	            }
213	        } else {
214	            self.health_check(&cfg);
215	        }
216	        self.publish_status();
217	    }
218	
219	    fn should_launch(&mut self, cfg: &cv_core::config::Config) -> bool {
220	        if !cfg.obs.launch_on_start || self.sh.is_shutting_down() {
221	            return false;
222	        }
223	        if self.closed_by_user && !cfg.obs.restart_if_closed {
224	            return false;
225	        }
226	        if self.launches.is_empty() && self.started.elapsed() < Duration::from_secs(cfg.obs.launch_delay_secs as u64) {
227	            return false;
228	        }
229	        while self.launches.front().map(|t| t.elapsed() > Duration::from_secs(3600)).unwrap_or(false) {
230	            self.launches.pop_front();
231	        }
232	        if self.launches.len() as u32 >= cfg.obs.max_restarts_per_hour {
233	            if self.last_error != "restart limit" {
234	                self.last_error = "restart limit".into();
235	                self.sh.log_event("error", "OBS keeps crashing; auto-restart paused for now");
236	                self.sh.ui.send(UiCmd::Balloon {
237	                    level: ToastLevel::Error,
238	                    title: "OBS keeps crashing".into(),
239	                    text: "ClipVault stopped restarting it. Open ClipVault to restart OBS.".into(),
240	                });
241	            }
242	            return false;
243	        }
244	        // Back off a little after a crash.
245	        if let Some(last) = self.launches.back() {
246	            if last.elapsed() < Duration::from_secs(5) {
247	                return false;
248	            }
249	        }
250	        true
251	    }
252	
253	    fn launch(&mut self) {
254	        let cfg = self.sh.cfg();
255	        let exe = self.obs_exe();
256	        if !exe.is_file() {
257	            self.set_error(format!("OBS not found at {}", exe.display()));
258	            return;
259	        }
260	        let files = self.files();
261	        if cfg.obs.manage_settings {
262	            match files.apply_settings(&cfg, false) {
263	                Ok(true) => tracing::info!("updated OBS settings before launch"),
264	                Ok(false) => {}
265	                Err(e) => tracing::warn!("could not write OBS settings: {e:#}"),
266	            }
267	        }
268	        if let Err(e) = files.ensure_websocket(cfg.obs.websocket_port, &cfg.obs.websocket_password) {
269	            tracing::warn!("could not configure OBS websocket: {e:#}");
270	        }
271	        let start_rec = cfg.recording.enabled && self.recording_wanted;
272	        match process::launch_obs(&exe, cfg.obs.minimize_to_tray, start_rec, true) {
273	            Ok(pid) => {
274	                self.pid = Some(pid);
275	                self.launches.push_back(Instant::now());
276	                self.exit_started = false;
277	                self.expecting_exit = false;
278	                self.connect_failures = 0;
279	                self.last_connect_try = Some(Instant::now());
280	                self.inputs_dirty = true;
281	                self.mic_applied = None;
282	                self.desktop_applied = None;
283	                self.game_applied = None;
284	                self.last_error.clear();
285	                self.sh.log_event("info", format!("Started OBS (pid {pid})"));
286	                self.sh.update_status(|s| s.obs.restarts = self.launches.len() as u32);
287	            }
288	            Err(e) => self.set_error(format!("{e:#}")),
289	        }
290	    }
291	
292	    fn obs_process_exited(&mut self) {
293	        let expected = self.expecting_exit;
294	        let clean = self.exit_started;
295	        tracing::info!("OBS exited (expected={expected}, clean={clean})");
296	        self.pid = None;
297	        self.drop_connection();
298	        self.rec_active = false;
299	        self.replay_active = false;
300	        if expected {
301	            self.expecting_exit = false;
302	            return;
303	        }
304	        let cfg = self.sh.cfg();
305	        if clean {
306	            self.closed_by_user = !cfg.obs.restart_if_closed;
307	            self.sh.log_event("warn", "OBS was closed");
308	            if self.closed_by_user {
309	                self.sh.ui.send(UiCmd::Balloon {
310	                    level: ToastLevel::Warning,
311	                    title: "OBS was closed".into(),
312	                    text: "24/7 recording and clipping are stopped. Open ClipVault to start OBS again.".into(),
313	                });
314	            }
315	        } else {
316	            self.sh.log_event("error", "OBS crashed or was killed; restarting it");
317	            if !cfg.obs.restart_on_crash {
318	                self.closed_by_user = true;
319	            }
320	        }
321	        self.exit_started = false;
322	    }
323	
324	    fn try_connect(&mut self) {
325	        self.last_connect_try = Some(Instant::now());
326	        let cfg = self.sh.cfg();
327	        let password = if cfg.obs.websocket_password.is_empty() {
328	            self.files().read_websocket().password
329	        } else {
330	            cfg.obs.websocket_password.clone()
331	        };
332	        let mask = subs::ALL | subs::INPUT_VOLUME_METERS;
333	        match ObsClient::connect(cfg.obs.websocket_port, &password, mask, Duration::from_secs(3)) {
334	            Ok((client, events)) => {
335	                self.obs = Some(Arc::new(client));
336	                self.events = Some(events);
337	                self.connect_failures = 0;
338	                self.on_connected();
339	            }
340	            Err(ObsError::Auth) => {
341	                self.connect_failures += 1;
342	                self.set_error("OBS websocket password is wrong (Settings > OBS)".into());
343	            }
344	            Err(e) => {
345	                self.connect_failures += 1;
346	                if self.connect_failures % 15 == 0 {
347	                    tracing::warn!("still can't reach OBS websocket: {e}");
348	                }
349	            }
350	        }
351	    }
352	
353	    fn on_connected(&mut self) {
354	        let Some(obs) = self.connected() else { return };
355	        let cfg = self.sh.cfg();
356	        let version = obs.request("GetVersion", None).ok().and_then(|v| v["obsVersion"].as_str().map(str::to_string)).unwrap_or_default();
357	        tracing::info!("connected to OBS {version} (websocket {})", obs.ws_version);
358	        self.last_error.clear();
359	        self.sh.update_status(|s| {
360	            s.obs.connected = true;
361	            s.obs.version = version.clone();
362	            s.obs.last_error.clear();
363	        });
364	
365	        // An OBS we didn't launch may be running with different settings.
366	        if cfg.obs.manage_settings && !self.settings_restart_done {
367	            if let Ok(true) = self.files().apply_settings(&cfg, true) {
368	                self.settings_restart_done = true;
369	                self.sh.log_event("info", "Restarting OBS once to apply ClipVault's recording settings");
370	                self.restart_obs("applying recording settings");
371	                return;
372	            }
373	        }
374	        self.settings_restart_done = true;
375	
376	        self.inputs_dirty = true;
377	        self.mic_applied = None;
378	        self.desktop_applied = None;
379	        self.game_applied = None;
380	        self.ensure_inputs();
381	
382	        // Output state.
383	        if let Ok(v) = obs.request("GetRecordStatus", None) {
384	            self.rec_active = v["outputActive"].as_bool().unwrap_or(false);
385	            self.rec_bytes = v["outputBytes"].as_i64().unwrap_or(0);
386	            self.rec_bytes_changed = Instant::now();
387	            if self.rec_active && self.rec_path.is_empty() {
388	                // Find the file OBS is writing: newest recording in the folder.
389	                self.rec_path = newest_recording(&cfg.recording.folder).unwrap_or_default();
390	                self.rec_started_ms = now_ms() - v["outputDuration"].as_i64().unwrap_or(0);
391	                if !self.rec_path.is_empty() {
392	                    let _ = self.sh.lib_tx.send(LibCmd::RecordingsChanged);
393	                }
394	            }
395	        }
396	        if let Ok(v) = obs.request("GetReplayBufferStatus", None) {
397	            self.replay_active = v["outputActive"].as_bool().unwrap_or(false);
398	        }
399	        self.ensure_outputs(&cfg);
400	        self.apply_audio();
401	    }
402	
403	    fn drop_connection(&mut self) {
404	        if let Some(o) = self.obs.take() {
405	            o.close();
406	        }
407	        self.events = None;
408	        self.managed = None;
409	        self.sh.update_status(|s| s.obs.connected = false);
410	    }
411	
412	    fn disconnected(&mut self, reason: String) {
413	        if self.obs.is_some() {
414	            tracing::warn!("lost OBS websocket: {reason}");
415	        }
416	        self.drop_connection();
417	    }
418	
419	    fn set_error(&mut self, e: String) {
420	        if self.last_error != e {
421	            self.sh.log_event("error", &e);
422	            self.last_error = e.clone();
423	        }
424	        self.sh.update_status(|s| s.obs.last_error = e);
425	    }
426	
427	    // ------------------------------------------------------ outputs
428	
429	    fn ensure_outputs(&mut self, cfg: &cv_core::config::Config) {
430	        let Some(obs) = self.connected() else { return };
431	        if self.exit_started || self.expecting_exit {
432	            return;
433	        }
434	        let want_rec = cfg.recording.enabled && self.recording_wanted;
435	        if want_rec && !self.rec_active && cfg.recording.auto_restart {
436	            let due = self.last_start_attempt.map(|t| t.elapsed() > Duration::from_secs(10)).unwrap_or(true);
437	            if due {
438	                self.last_start_attempt = Some(Instant::now());
439	                match obs.request("StartRecord", None) {
440	                    Ok(_) => {
441	                        tracing::info!("started recording");
442	                        self.start_failures = 0;
443	                    }
444	                    Err(ObsError::Request { code: 500, .. }) => {} // already active
445	                    Err(e) => {
446	                        self.start_failures += 1;
447	                        if self.start_failures == 3 {
448	                            self.sh.log_event("error", format!("OBS refuses to start recording: {e}"));
449	                            self.sh.ui.send(UiCmd::Balloon {
450	                                level: ToastLevel::Error,
451	                                title: "Recording won't start".into(),
452	                                text: format!("{e}"),
453	                            });
454	                        }
455	                    }
456	                }
457	            }
458	        }
459	        if !self.replay_active {
460	            let due = self.last_replay_attempt.map(|t| t.elapsed() > Duration::from_secs(10)).unwrap_or(true);
461	            if due {
462	                self.last_replay_attempt = Some(Instant::now());
463	                match obs.request("StartReplayBuffer", None) {
464	                    Ok(_) => tracing::info!("started replay buffer"),
465	                    Err(ObsError::Request { code: 500, .. }) => self.replay_active = true,
466	                    Err(e) => tracing::warn!("could not start replay buffer: {e}"),
467	                }
468	            }
469	        }
470	    }
471	
472	    fn health_check(&mut self, cfg: &cv_core::config::Config) {
473	        let Some(obs) = self.connected() else { return };
474	        if let Ok(v) = obs.request("GetRecordStatus", None) {
475	            let active = v["outputActive"].as_bool().unwrap_or(false);
476	            let bytes = v["outputBytes"].as_i64().unwrap_or(0);
477	            if active != self.rec_active {
478	                self.rec_active = active;
479	                self.rec_bytes_changed = Instant::now();
480	            }
481	            if active {
482	                if bytes != self.rec_bytes {
483	                    self.rec_bytes = bytes;
484	                    self.rec_bytes_changed = Instant::now();
485	                } else if self.rec_bytes_changed.elapsed() > Duration::from_secs(cfg.recording.stall_timeout_secs as u64) {
486	                    self.recording_stalled();
487	                }
488	            }
489	        }
490	        if let Ok(v) = obs.request("GetReplayBufferStatus", None) {
491	            self.replay_active = v["outputActive"].as_bool().unwrap_or(false);
492	        }
493	        self.ensure_outputs(cfg);
494	        if self.inputs_dirty || self.tick_count % 20 == 0 {
495	            self.ensure_inputs();
496	        }
497	        if self.pending_save.as_ref().map(|p| p.at.elapsed() > Duration::from_secs(60)).unwrap_or(false) {
498	            self.pending_save = None;
499	        }
500	        // Mic silence warning.
501	        let mins = cfg.audio.mic_silence_warning_mins;
502	        if mins > 0 && self.rec_active && !self.mic_silence_warned && self.mic_last_sound.elapsed() > Duration::from_secs(mins as u64 * 60) {
503	            self.mic_silence_warned = true;
504	            self.sh.ui.send(UiCmd::Balloon {
505	                level: ToastLevel::Warning,
506	                title: "Your mic is silent".into(),
507	                text: format!("No sound from the microphone for {mins} minutes."),
508	            });
509	        }
510	    }
511	
512	    fn recording_stalled(&mut self) {
513	        let Some(obs) = self.connected() else { return };
514	        while self.stall_restarts.front().map(|t| t.elapsed() > Duration::from_secs(600)).unwrap_or(false) {
515	            self.stall_restarts.pop_front();
516	        }
517	        self.stall_restarts.push_back(Instant::now());
518	        self.rec_bytes_changed = Instant::now();
519	        if self.stall_restarts.len() >= 3 {
520	            self.sh.log_event("error", "Recording keeps stalling; restarting OBS");
521	            self.stall_restarts.clear();
522	            self.restart_obs("recording stalled repeatedly");
523	            return;
524	        }
525	        self.sh.log_event("warn", "Recording stopped growing; restarting the recording");
526	        let _ = obs.request("StopRecord", None);
527	        std::thread::sleep(Duration::from_secs(2));
528	        let _ = obs.request("StartRecord", None);
529	    }
530	
531	    // ------------------------------------------------------- inputs
532	
533	    fn ensure_inputs(&mut self) {
534	        let Some(obs) = self.connected() else { return };
535	        let cfg = self.sh.cfg();
536	        let db = cv_core::db::Db::open_default().ok();
537	        let mic_meta = db.as_ref().and_then(|d| d.meta_get(META_MIC_INPUT).ok().flatten());
538	        let mut routing = self.routing.clone();
539	        if let Some(g) = &self.game {
540	            if let Some(v) = self.routing.get(&g.exe.to_lowercase()) {
541	                routing.insert(String::new(), *v);
542	            }
543	        }
544	        match obs_setup::ensure_inputs(&obs, &cfg, mic_meta.as_deref(), &routing) {
545	            Ok(m) => {
546	                if let (Some(db), Some(mic)) = (db.as_ref(), m.mic.as_ref()) {
547	                    let _ = db.meta_set(META_MIC_INPUT, mic);
548	                }
549	                let changed = self.managed.as_ref() != Some(&m);
550	                self.managed = Some(m);
551	                self.inputs_dirty = false;
552	                if changed {
553	                    self.mic_applied = None;
554	                    self.desktop_applied = None;
555	                    self.game_applied = None;
556	                    self.apply_audio();
557	                }
558	            }
559	            Err(e) => {
560	                tracing::warn!("could not set up OBS audio inputs: {e}");
561	                self.inputs_dirty = true;
562	            }
563	        }
564	    }
565	
566	    fn apply_audio(&mut self) {
567	        let Some(obs) = self.connected() else { return };
568	        let Some(m) = self.managed.clone() else { return };
569	        let cfg = self.sh.cfg();
570	        // Mic.
571	        if let (Some(mic), Some(dec)) = (m.mic.as_ref(), self.mic.clone()) {
572	            if cfg.audio.mic_guard {
573	                if let Some(id) = dec.obs_device_id() {
574	                    if self.mic_applied.as_deref() != Some(id) {
575	                        match obs_setup::set_device(&obs, mic, id) {
576	                            Ok(changed) => {
577	                                self.mic_applied = Some(id.to_string());
578	                                if changed {
579	                                    let msg = match &dec {
580	                                        MicDecision::Preferred { endpoint, .. } => format!("Mic set to {}", cv_core::audio_names::clean_display_name(&endpoint.name)),
581	                                        MicDecision::WindowsDefault => "Preferred mic not connected; recording the Windows default mic".to_string(),
582	                                        MicDecision::Leave => String::new(),
583	                                    };
584	                                    if !msg.is_empty() {
585	                                        self.sh.log_event("info", &msg);
586	                                        self.sh.toast(ToastLevel::Info, msg);
587	                                    }
588	                                }
589	                            }
590	                            Err(e) => tracing::warn!("could not set mic: {e}"),
591	                        }
592	                    }
593	                }
594	            }
595	        }
596	        // Desktop audio device.
597	        if let (Some(desk), Some(dev)) = (m.desktop.as_ref(), self.desktop_device.clone()) {
598	            if self.desktop_applied.as_deref() != Some(dev.as_str()) {
599	                if obs_setup::set_device(&obs, desk, &dev).is_ok() {
600	                    self.desktop_applied = Some(dev);
601	                }
602	            }
603	        }
604	        // Game audio target.
605	        if cfg.audio.multitrack && cfg.audio.game_audio_capture {
606	            if let Some(g) = self.game.clone() {
607	                if self.game_applied.as_deref() != Some(g.exe.as_str()) {
608	                    match obs_setup::set_game_target(&obs, &g.exe, &g.title, &g.class) {
609	                        Ok(changed) => {
610	                            self.game_applied = Some(g.exe.clone());
611	                            if changed {
612	                                tracing::info!("game audio now follows {} ({})", g.name, g.exe);
613	                            }
614	                        }
615	                        Err(e) => tracing::warn!("could not retarget game audio: {e}"),
616	                    }
617	                }
618	            }
619	        }
620	        // Full-mix routing for apps on other devices.
621	        if cfg.audio.multitrack {
622	            let game_exe = self.game.as_ref().map(|g| g.exe.clone());
623	            if let Err(e) = obs_setup::apply_routing(&obs, &m, &self.routing, game_exe.as_deref()) {
624	                tracing::warn!("routing: {e}");
625	            }
626	        }
627	    }
628	
629	    // ------------------------------------------------------- events
630	
631	    fn obs_event(&mut self, ev: ObsEvent) {
632	        match ev {
633	            ObsEvent::Disconnected(reason) => self.disconnected(reason),
634	            ObsEvent::Event { kind, data } => self.obs_event_kind(&kind, &data),
635	        }
636	    }
637	
638	    fn obs_event_kind(&mut self, kind: &str, data: &Value) {
639	        match kind {
640	            "ReplayBufferSaved" => {
641	                let path = data["savedReplayPath"].as_str().unwrap_or("").to_string();
642	                let pending = self.pending_save.take();
643	                if pending.is_none() {
644	                    // Saved from OBS itself: still give the usual feedback.
645	                    self.sh.ui.send(UiCmd::ShowOverlay);
646	                }
647	                tracing::info!("replay saved: {path}");
648	                if !path.is_empty() {
649	                    let _ = self.sh.clip_tx.send(ClipTask::ReplaySaved {
650	                        path: PathBuf::from(norm_path(&path)),
651	                        at_ms: now_ms(),
652	                        short: pending.map(|p| p.short).unwrap_or(false),
653	                    });
654	                }
655	            }
656	            "RecordStateChanged" => {
657	                let state = data["outputState"].as_str().unwrap_or("");
658	                let path = data["outputPath"].as_str().map(norm_path).unwrap_or_default();
659	                match state {
660	                    "OBS_WEBSOCKET_OUTPUT_STARTED" => {
661	                        self.rec_active = true;
662	                        if !path.is_empty() {
663	                            self.rec_path = path;
664	                        }
665	                        self.rec_started_ms = now_ms();
666	                        self.rec_bytes_changed = Instant::now();
667	                        self.sh.log_event("info", "Recording started");
668	                        let _ = self.sh.lib_tx.send(LibCmd::RecordingsChanged);
669	                    }
670	                    "OBS_WEBSOCKET_OUTPUT_STOPPED" => {
671	                        self.rec_active = false;
672	                        self.rec_path.clear();
673	                        if !self.expecting_exit && !self.exit_started {
674	                            self.sh.log_event("warn", "Recording stopped");
675	                        }
676	                        let _ = self.sh.lib_tx.send(LibCmd::RecordingsChanged);
677	                    }
678	                    _ => {}
679	                }
680	            }
681	            "RecordFileChanged" => {
682	                let path = data["newOutputPath"].as_str().map(norm_path).unwrap_or_default();
683	                tracing::info!("recording split -> {path}");
684	                self.rec_path = path;
685	                self.rec_started_ms = now_ms();
686	                let _ = self.sh.lib_tx.send(LibCmd::RecordingsChanged);
687	            }
688	            "ReplayBufferStateChanged" => {
689	                self.replay_active = data["outputActive"].as_bool().unwrap_or(false);
690	            }
691	            "ExitStarted" => {
692	                self.exit_started = true;
693	                tracing::info!("OBS is exiting");
694	            }
695	            "CurrentProgramSceneChanged" | "InputRemoved" | "InputNameChanged" | "SceneItemRemoved" => {
696	                self.inputs_dirty = true;
697	            }
698	            "InputVolumeMeters" => self.meters(data),
699	            _ => {}
700	        }
701	    }
702	
703	    fn meters(&mut self, data: &Value) {
704	        let mic_name = self.managed.as_ref().and_then(|m| m.mic.clone());
705	        let mut out = Vec::new();
706	        if let Some(inputs) = data["inputs"].as_array() {
707	            for i in inputs {
708	                let name = i["inputName"].as_str().unwrap_or("").to_string();
709	                let peak = i["inputLevelsMul"]
710	                    .as_array()
711	                    .map(|chs| chs.iter().filter_map(|c| c.get(1).and_then(Value::as_f64)).fold(0.0f64, f64::max))
712	                    .unwrap_or(0.0) as f32;
713	                if Some(&name) == mic_name.as_ref() && peak > 0.003 {
714	                    self.mic_last_sound = Instant::now();
715	                    self.mic_silence_warned = false;
716	                }
717	                out.push(Meter { name, peak });
718	            }
719	        }
720	        if self.sh.has_clients() && self.meters_emitted.elapsed() >= Duration::from_millis(100) {
721	            self.meters_emitted = Instant::now();
722	            self.sh.emit(Event::Meters { meters: out });
723	        }
724	    }
725	
726	    // ----------------------------------------------------- commands
727	
728	    fn command(&mut self, cmd: SupCmd) {
729	        match cmd {
730	            SupCmd::SaveClip { short, reply } => {
731	                let r = self.save_clip(short);
732	                if let Err(e) = &r {
733	                    self.sh.toast(ToastLevel::Error, format!("Clip not saved: {e}"));
734	                }
735	                if let Some(reply) = reply {
736	                    let _ = reply.send(r);
737	                }
738	            }
739	            SupCmd::SetRecording { enabled, reply } => {
740	                let r = self.set_recording(enabled);
741	                if let Some(reply) = reply {
742	                    let _ = reply.send(r);
743	                }
744	            }
745	            SupCmd::RestartObs { reply } => {
746	                self.closed_by_user = false;
747	                self.launches.clear();
748	                if self.pid.is_some() {
749	                    self.restart_obs("requested");
750	                }
751	                self.tick();
752	                if let Some(reply) = reply {
753	                    let _ = reply.send(Ok(()));
754	                }
755	            }
756	            SupCmd::ConfigChanged { restart_obs } => {
757	                self.inputs_dirty = true;
758	                *self.sh.tools.write() = None;
759	                if restart_obs && self.pid.is_some() {
760	                    self.restart_obs("settings changed");
761	                } else {
762	                    self.ensure_inputs();
763	                }
764	            }
765	            SupCmd::Mic { decision } => {
766	                if self.mic.as_ref() != Some(&decision) {
767	                    tracing::info!("mic decision: {decision:?}");
768	                    self.mic = Some(decision);
769	                    self.apply_audio();
770	                }
771	            }
772	            SupCmd::DesktopDevice { device_id } => {
773	                if self.desktop_device.as_deref() != Some(&device_id) {
774	                    self.desktop_device = Some(device_id);
775	                    self.apply_audio();
776	                }
777	            }
778	            SupCmd::AppRouting(r) => {
779	                if r != self.routing {
780	                    self.routing = r;
781	                    self.apply_audio();
782	                }
783	            }
784	            SupCmd::GameTarget(g) => {
785	                if self.game.as_ref() != Some(&g) {
786	                    self.game = Some(g);
787	                    self.apply_audio();
788	                }
789	            }
790	            SupCmd::Shutdown => {}
791	        }
792	    }
793	
794	    fn save_clip(&mut self, short: bool) -> Result<(), String> {
795	        let cfg = self.sh.cfg();
796	        if let Some(t) = self.last_save_request {
797	            if t.elapsed() < Duration::from_millis(cfg.clips.save_cooldown_ms as u64) {
798	                return Ok(()); // double press: ignore silently
799	            }
800	        }
801	        let Some(obs) = self.connected() else {
802	            return Err(if self.pid.is_none() { "OBS is not running".into() } else { "not connected to OBS yet".into() });
803	        };
804	        if !self.replay_active {
805	            let _ = obs.request("StartReplayBuffer", None);
806	            return Err("the replay buffer was off; it's starting now, try again in a moment".into());
807	        }
808	        obs.request("SaveReplayBuffer", None).map_err(|e| e.to_string())?;
809	        self.last_save_request = Some(Instant::now());
810	        self.pending_save = Some(PendingSave { short, at: Instant::now() });
811	        self.sh.ui.send(UiCmd::ShowOverlay);
812	        Ok(())
813	    }
814	
815	    fn set_recording(&mut self, enabled: bool) -> Result<(), String> {
816	        self.recording_wanted = enabled;
817	        if let Ok(db) = cv_core::db::Db::open_default() {
818	            let _ = db.meta_set(META_RECORDING_WANTED, if enabled { "1" } else { "0" });
819	        }
820	        let msg = if enabled { "24/7 recording resumed" } else { "24/7 recording paused" };
821	        self.sh.log_event("info", msg);
822	        self.sh.toast(ToastLevel::Info, msg);
823	        if let Some(obs) = self.connected() {
824	            if enabled {
825	                self.last_start_attempt = None;
826	                let cfg = self.sh.cfg();
827	                self.ensure_outputs(&cfg);
828	            } else if self.rec_active {
829	                obs.request("StopRecord", None).map_err(|e| e.to_string())?;
830	            }
831	        }
832	        self.publish_status();
833	        Ok(())
834	    }
835	
836	    /// Stop outputs, close OBS gracefully (or end it), and let the next tick relaunch.
837	    fn restart_obs(&mut self, why: &str) {
838	        let Some(pid) = self.pid else { return };
839	        tracing::info!("restarting OBS ({why})");
840	        self.expecting_exit = true;
841	        if let Some(obs) = self.connected() {
842	            let _ = obs.request("StopReplayBuffer", None);
843	            if self.rec_active {
844	                let _ = obs.request("StopRecord", None);
845	                for _ in 0..50 {
846	                    std::thread::sleep(Duration::from_millis(200));
847	                    match obs.request("GetRecordStatus", None) {
848	                        Ok(v) if v["outputActive"].as_bool() == Some(false) => break,
849	                        Err(_) => break,
850	                        _ => {}
851	                    }
852	                }
853	            }
854	        }
855	        self.drop_connection();
856	        process::request_close_obs(pid);
857	        let timeout = Duration::from_secs(self.sh.cfg.read().obs.shutdown_timeout_secs as u64);
858	        let t = Instant::now();
859	        while process::is_running(pid) && t.elapsed() < timeout {
860	            std::thread::sleep(Duration::from_millis(250));
861	        }
862	        if process::is_running(pid) {
863	            tracing::warn!("OBS did not close in time; ending it");
864	            process::terminate(pid);
865	            std::thread::sleep(Duration::from_millis(1500));
866	        }
867	        self.pid = None;
868	        self.expecting_exit = false;
869	        self.exit_started = false;
870	        self.rec_active = false;
871	        self.replay_active = false;
872	        self.closed_by_user = false;
873	        // Relaunch right away (settings are written in launch()).
874	        if self.should_launch(&self.sh.cfg()) || self.launches.is_empty() {
875	            self.launch();
876	        }
877	    }
878	
879	    // ------------------------------------------------------- status
880	
881	    fn publish_status(&mut self) {
882	        let cfg = self.sh.cfg();
883	        let running = self.pid.is_some();
884	        let connected = self.connected().is_some();
885	        let mic_state;
886	        let mic_device;
887	        match (&self.mic, cfg.audio.mic_guard) {
888	            (_, false) => {
889	                mic_state = "disabled";
890	                mic_device = String::new();
891	            }
892	            (Some(MicDecision::Preferred { rank, endpoint }), _) => {
893	                mic_state = if *rank == 0 { "ok" } else { "fallback" };
894	                mic_device = cv_core::audio_names::clean_display_name(&endpoint.name);
895	            }
896	            (Some(MicDecision::WindowsDefault), _) => {
897	                mic_state = if cfg.audio.mic_priority.is_empty() { "ok" } else { "fallback" };
898	                mic_device = "Windows default".into();
899	            }
900	            (Some(MicDecision::Leave), _) => {
901	                mic_state = "missing";
902	                mic_device = String::new();
903	            }
904	            (None, _) => {
905	                mic_state = "unknown";
906	                mic_device = String::new();
907	            }
908	        }
909	        let tracks = if cfg.audio.multitrack { 6 } else { 1 };
910	        let healthy = self.rec_active && self.rec_bytes_changed.elapsed() < Duration::from_secs(cfg.recording.stall_timeout_secs as u64);
911	        self.sh.update_status(|s| {
912	            s.obs.running = running;
913	            s.obs.connected = connected;
914	            s.obs.closed_by_user = self.closed_by_user;
915	            if self.last_error.is_empty() {
916	                s.obs.last_error.clear();
917	            }
918	            s.recording.active = self.rec_active;
919	            s.recording.paused_by_user = !self.recording_wanted || !cfg.recording.enabled;
920	            s.recording.path = self.rec_path.clone();
921	            s.recording.started_ms = self.rec_started_ms;
922	            s.recording.bytes = self.rec_bytes;
923	            s.recording.healthy = healthy;
924	            s.recording.tracks = tracks;
925	            s.replay.active = self.replay_active;
926	            s.replay.seconds = cfg.clips.clip_length_secs;
927	            s.mic.state = mic_state.into();
928	            s.mic.device = mic_device;
929	            s.mic.preferred = cfg.audio.mic_priority.first().cloned().unwrap_or_default();
930	            s.game.audio_target = self.game.as_ref().map(|g| g.name.clone());
931	        });
932	    }
933	}
934	
935	/// Newest non-replay video in the recordings folder.
936	fn newest_recording(folder: &str) -> Option<String> {
937	    let rd = std::fs::read_dir(folder).ok()?;
938	    rd.flatten()
939	        .map(|e| e.path())
940	        .filter(|p| cv_core::obs::filename::is_video_file(p) && !cv_core::obs::filename::is_replay_file(p))
941	        .max_by_key(|p| p.metadata().and_then(|m| m.modified()).ok())
942	        .map(|p| p.to_string_lossy().to_string())
943	}
944	
945	pub fn send_and_wait(tx: &Sender<SupCmd>, make: impl FnOnce(Sender<Result<(), String>>) -> SupCmd, timeout: Duration) -> Result<(), String> {
946	    let (rtx, rrx) = crossbeam_channel::bounded(1);
947	    tx.send(make(rtx)).map_err(|_| "service is shutting down".to_string())?;
948	    rrx.recv_timeout(timeout).map_err(|_| "timed out".to_string())?
949	}
950	
951	#[allow(dead_code)]
952	fn _unused(_: Value) -> Value {
953	    json!(null)
954	}
