1	//! State shared between the service's threads.
2	
3	use crate::win::ui::{ToastLevel, UiHandle};
4	use crossbeam_channel::Sender;
5	use cv_core::audio_names::MicDecision;
6	use cv_core::config::Config;
7	use cv_core::db::Db;
8	use cv_core::ffmpeg::Tools;
9	use cv_core::ipc::{AudioDevices, Event, JobInfo, ServerMsg, Status};
10	use parking_lot::{Mutex, RwLock};
11	use std::collections::HashMap;
12	use std::path::PathBuf;
13	use std::sync::atomic::{AtomicBool, Ordering};
14	use std::sync::Arc;
15	
16	/// What game audio should follow.
17	#[derive(Debug, Clone, PartialEq, Eq)]
18	pub struct GameTarget {
19	    pub exe: String,
20	    pub title: String,
21	    pub class: String,
22	    pub name: String,
23	}
24	
25	/// Commands for the OBS supervisor thread.
26	pub enum SupCmd {
27	    SaveClip { short: bool, reply: Option<Sender<Result<(), String>>> },
28	    SetRecording { enabled: bool, reply: Option<Sender<Result<(), String>>> },
29	    RestartObs { reply: Option<Sender<Result<(), String>>> },
30	    ConfigChanged { restart_obs: bool },
31	    Mic { decision: MicDecision },
32	    DesktopDevice { device_id: String },
33	    /// exe (lower case) -> include that app's capture in the full mix.
34	    AppRouting(HashMap<String, bool>),
35	    GameTarget(GameTarget),
36	    Shutdown,
37	}
38	
39	/// Work for the clip-saving thread.
40	pub enum ClipTask {
41	    ReplaySaved { path: PathBuf, at_ms: i64, short: bool },
42	    ImportStray { path: PathBuf },
43	}
44	
45	/// Work for the library thread.
46	pub enum LibCmd {
47	    Rescan,
48	    RecordingsChanged,
49	}
50	
51	pub struct Shared {
52	    pub cfg: Arc<RwLock<Config>>,
53	    pub status: Mutex<Status>,
54	    pub ui: UiHandle,
55	    pub sup_tx: Sender<SupCmd>,
56	    pub clip_tx: Sender<ClipTask>,
