71	
72	impl Shared {
73	    pub fn cfg(&self) -> Config {
74	        self.cfg.read().clone()
75	    }
76	
77	    pub fn is_shutting_down(&self) -> bool {
78	        self.shutdown.load(Ordering::SeqCst)
79	    }
80	
81	    /// Send an event to every connected GUI.
82	    pub fn emit(&self, event: Event) {
83	        let Ok(line) = serde_json::to_string(&ServerMsg::Event { event }) else { return };
84	        let mut clients = self.clients.lock();
85	        clients.retain(|c| c.send(line.clone()).is_ok());
