92	    /// Show a toast on screen and in the GUI.
93	    pub fn toast(&self, level: ToastLevel, message: impl Into<String>) {
94	        let message = message.into();
95	        self.ui.toast(level, message.clone());
96	        self.emit(Event::Toast {
97	            level: match level {
98	                ToastLevel::Info => "info",
99	                ToastLevel::Success => "success",
100	                ToastLevel::Warning => "warning",
101	                ToastLevel::Error => "error",
102	            }
103	            .into(),
104	            message,
105	        });
106	    }
107	
108	    /// Record something in the activity log shown on the GUI's home page.
109	    pub fn log_event(&self, level: &str, message: impl AsRef<str>) {
110	        let message = message.as_ref();
111	        match level {
112	            "error" => tracing::error!("{message}"),
113	            "warn" => tracing::warn!("{message}"),
114	            _ => tracing::info!("{message}"),
115	        }
116	        let mut db = self.event_db.lock();
117	        if db.is_none() {
118	            *db = Db::open_default().ok();
119	        }
120	        if let Some(db) = db.as_ref() {
121	            let _ = db.log_event(level, message);
122	            let _ = db.prune_events(500);
123	        }
124	    }
125	
126	    pub fn tools(&self) -> Option<Tools> {
127	        if let Some(t) = self.tools.read().clone() {
128	            return Some(t);
129	        }
130	        let cfg = self.cfg();
131	        match cv_core::ffmpeg::locate(&cfg.advanced.ffmpeg_path, &cfg.advanced.ffprobe_path) {
132	            Ok(t) => {
133	                tracing::info!("using {} ({})", t.ffmpeg.display(), t.version);
134	                *self.tools.write() = Some(t.clone());
135	                Some(t)
136	            }
137	            Err(e) => {
138	                tracing::warn!("{e:#}");
139	                None
140	            }
141	        }
142	    }
143	
144	    pub fn update_status(&self, f: impl FnOnce(&mut Status)) {
145	        f(&mut self.status.lock());
146	    }
147	}
