149	/// Normalise a path reported by OBS (forward slashes) to Windows form.
150	pub fn norm_path(p: &str) -> String {
151	    p.replace('/', "\\")
152	}
153	
154	pub fn same_path(a: &str, b: &str) -> bool {
155	    norm_path(a).eq_ignore_ascii_case(&norm_path(b))
156	}
