124	
125	    pub fn run(mut self) {
126	        tracing::info!("supervisor started (24/7 recording {})", if self.recording_wanted { "on" } else { "paused" });
127	        let mut next_tick = Instant::now();
128	        loop {
129	            if self.sh.is_shutting_down() {
130	                break;
131	            }
132	            let ev_rx = self.events.clone().unwrap_or_else(never);
133	            let timeout = next_tick.saturating_duration_since(Instant::now());
134	            select! {
135	                recv(self.rx) -> cmd => match cmd {
136	                    Ok(SupCmd::Shutdown) | Err(_) => break,
137	                    Ok(cmd) => self.command(cmd),
138	                },
139	                recv(ev_rx) -> ev => match ev {
140	                    Ok(ev) => self.obs_event(ev),
141	                    Err(_) => self.disconnected("event channel closed".into()),
142	                },
143	                default(timeout) => {}
144	            }
145	            if Instant::now() >= next_tick {
146	                self.tick();
147	                let secs = self.sh.cfg.read().advanced.health_check_secs.max(1) as u64;
148	                next_tick = Instant::now() + Duration::from_secs(secs);
149	            }
150	        }
151	        if let Some(obs) = &self.obs {
152	            obs.close();
153	        }
154	        tracing::info!("supervisor stopped");
155	    }
156	
157	    fn obs_exe(&self) -> PathBuf {
158	        PathBuf::from(self.sh.cfg.read().obs.exe_path.trim())
159	    }
160	
161	    fn files(&self) -> ObsConfigFiles {
162	        ObsConfigFiles::from_config(&self.sh.cfg.read())
163	    }
164	
165	    fn connected(&self) -> Option<Arc<ObsClient>> {
166	        self.obs.as_ref().filter(|o| o.is_alive()).cloned()
167	    }
168	
169	    // ------------------------------------------------------------ tick
170	
171	    fn tick(&mut self) {
172	        self.tick_count += 1;
173	        let cfg = self.sh.cfg();
174	
175	        // Process state.
176	        if let Some(pid) = self.pid {
177	            if !process::is_running(pid) {
178	                self.obs_process_exited();
179	            }
180	        }
181	        if self.pid.is_none() {
182	            let exe = self.obs_exe();
183	            if let Some(pid) = process::find_by_exe(&exe).into_iter().next() {
184	                tracing::info!("found running OBS (pid {pid})");
185	                self.pid = Some(pid);
186	            }
187	        }
188	        if self.pid.is_none() {
189	            if self.should_launch(&cfg) {
190	                self.launch();
191	            }
192	            self.publish_status();
193	            return;
194	        }
195	
196	        // Connection.
197	        if self.connected().is_none() {
198	            let due = self.last_connect_try.map(|t| t.elapsed() >= Duration::from_secs(2)).unwrap_or(true);
199	            if due {
200	                self.try_connect();
201	            }
202	            // An OBS we didn't start, with the websocket switched off: restart it
203	            // once so the websocket (and our settings) take effect.
204	            if self.connected().is_none()
205	                && self.connect_failures >= 8
206	                && !self.settings_restart_done
207	                && !self.files().read_websocket().enabled
208	            {
209	                self.settings_restart_done = true;
210	                self.sh.log_event("warn", "OBS websocket is off; restarting OBS to enable it");
211	                self.restart_obs("enabling the OBS websocket");
212	            }
213	        } else {
214	            self.health_check(&cfg);
215	        }
216	        self.publish_status();
217	    }
218	
219	    fn should_launch(&mut self, cfg: &cv_core::config::Config) -> bool {
220	        if !cfg.obs.launch_on_start || self.sh.is_shutting_down() {
221	            return false;
222	        }
223	        if self.closed_by_user && !cfg.obs.restart_if_closed {
224	            return false;
225	        }
226	        if self.launches.is_empty() && self.started.elapsed() < Duration::from_secs(cfg.obs.launch_delay_secs as u64) {
227	            return false;
228	        }
229	        while self.launches.front().map(|t| t.elapsed() > Duration::from_secs(3600)).unwrap_or(false) {
230	            self.launches.pop_front();
231	        }
232	        if self.launches.len() as u32 >= cfg.obs.max_restarts_per_hour {
233	            if self.last_error != "restart limit" {
234	                self.last_error = "restart limit".into();
235	                self.sh.log_event("error", "OBS keeps crashing; auto-restart paused for now");
236	                self.sh.ui.send(UiCmd::Balloon {
237	                    level: ToastLevel::Error,
238	                    title: "OBS keeps crashing".into(),
239	                    text: "ClipVault stopped restarting it. Open ClipVault to restart OBS.".into(),
240	                });
241	            }
242	            return false;
243	        }
244	        // Back off a little after a crash.
245	        if let Some(last) = self.launches.back() {
246	            if last.elapsed() < Duration::from_secs(5) {
247	                return false;
248	            }
249	        }
250	        true
251	    }
252	
253	    fn launch(&mut self) {
254	        let cfg = self.sh.cfg();
255	        let exe = self.obs_exe();
256	        if !exe.is_file() {
257	            self.set_error(format!("OBS not found at {}", exe.display()));
258	            return;
259	        }
260	        let files = self.files();
261	        if cfg.obs.manage_settings {
262	            match files.apply_settings(&cfg, false) {
263	                Ok(true) => tracing::info!("updated OBS settings before launch"),
264	                Ok(false) => {}
265	                Err(e) => tracing::warn!("could not write OBS settings: {e:#}"),
266	            }
267	        }
268	        if let Err(e) = files.ensure_websocket(cfg.obs.websocket_port, &cfg.obs.websocket_password) {
269	            tracing::warn!("could not configure OBS websocket: {e:#}");
270	        }
271	        let start_rec = cfg.recording.enabled && self.recording_wanted;
272	        match process::launch_obs(&exe, cfg.obs.minimize_to_tray, start_rec, true) {
273	            Ok(pid) => {
274	                self.pid = Some(pid);
275	                self.launches.push_back(Instant::now());
276	                self.exit_started = false;
277	                self.expecting_exit = false;
278	                self.connect_failures = 0;
279	                self.last_connect_try = Some(Instant::now());
280	                self.inputs_dirty = true;
281	                self.mic_applied = None;
282	                self.desktop_applied = None;
283	                self.game_applied = None;
284	                self.last_error.clear();
285	                self.sh.log_event("info", format!("Started OBS (pid {pid})"));
286	                self.sh.update_status(|s| s.obs.restarts = self.launches.len() as u32);
287	            }
288	            Err(e) => self.set_error(format!("{e:#}")),
289	        }
290	    }
291	
292	    fn obs_process_exited(&mut self) {
293	        let expected = self.expecting_exit;
294	        let clean = self.exit_started;
295	        tracing::info!("OBS exited (expected={expected}, clean={clean})");
296	        self.pid = None;
297	        self.drop_connection();
298	        self.rec_active = false;
299	        self.replay_active = false;
300	        if expected {
301	            self.expecting_exit = false;
302	            return;
303	        }
304	        let cfg = self.sh.cfg();
305	        if clean {
306	            self.closed_by_user = !cfg.obs.restart_if_closed;
307	            self.sh.log_event("warn", "OBS was closed");
308	            if self.closed_by_user {
309	                self.sh.ui.send(UiCmd::Balloon {
310	                    level: ToastLevel::Warning,
311	                    title: "OBS was closed".into(),
312	                    text: "24/7 recording and clipping are stopped. Open ClipVault to start OBS again.".into(),
313	                });
314	            }
315	        } else {
316	            self.sh.log_event("error", "OBS crashed or was killed; restarting it");
317	            if !cfg.obs.restart_on_crash {
318	                self.closed_by_user = true;
319	            }
320	        }
321	        self.exit_started = false;
322	    }
323	
324	    fn try_connect(&mut self) {
325	        self.last_connect_try = Some(Instant::now());
326	        let cfg = self.sh.cfg();
327	        let password = if cfg.obs.websocket_password.is_empty() {
328	            self.files().read_websocket().password
329	        } else {
330	            cfg.obs.websocket_password.clone()
331	        };
332	        let mask = subs::ALL | subs::INPUT_VOLUME_METERS;
333	        match ObsClient::connect(cfg.obs.websocket_port, &password, mask, Duration::from_secs(3)) {
334	            Ok((client, events)) => {
335	                self.obs = Some(Arc::new(client));
336	                self.events = Some(events);
337	                self.connect_failures = 0;
338	                self.on_connected();
339	            }
340	            Err(ObsError::Auth) => {
341	                self.connect_failures += 1;
342	                self.set_error("OBS websocket password is wrong (Settings > OBS)".into());
343	            }
344	            Err(e) => {
345	                self.connect_failures += 1;
346	                if self.connect_failures % 15 == 0 {
347	                    tracing::warn!("still can't reach OBS websocket: {e}");
348	                }
349	            }
350	        }
351	    }
352	
353	    fn on_connected(&mut self) {
354	        let Some(obs) = self.connected() else { return };
355	        let cfg = self.sh.cfg();
356	        let version = obs.request("GetVersion", None).ok().and_then(|v| v["obsVersion"].as_str().map(str::to_string)).unwrap_or_default();
357	        tracing::info!("connected to OBS {version} (websocket {})", obs.ws_version);
358	        self.last_error.clear();
359	        self.sh.update_status(|s| {
360	            s.obs.connected = true;
361	            s.obs.version = version.clone();
362	            s.obs.last_error.clear();
363	        });
364	
365	        // An OBS we didn't launch may be running with different settings.
366	        if cfg.obs.manage_settings && !self.settings_restart_done {
367	            if let Ok(true) = self.files().apply_settings(&cfg, true) {
368	                self.settings_restart_done = true;
369	                self.sh.log_event("info", "Restarting OBS once to apply ClipVault's recording settings");
370	                self.restart_obs("applying recording settings");
371	                return;
372	            }
373	        }
374	        self.settings_restart_done = true;
375	
376	        self.inputs_dirty = true;
377	        self.mic_applied = None;
378	        self.desktop_applied = None;
379	        self.game_applied = None;
380	        self.ensure_inputs();
381	
382	        // Output state.
383	        if let Ok(v) = obs.request("GetRecordStatus", None) {
384	            self.rec_active = v["outputActive"].as_bool().unwrap_or(false);
385	            self.rec_bytes = v["outputBytes"].as_i64().unwrap_or(0);
386	            self.rec_bytes_changed = Instant::now();
387	            if self.rec_active && self.rec_path.is_empty() {
388	                // Find the file OBS is writing: newest recording in the folder.
389	                self.rec_path = newest_recording(&cfg.recording.folder).unwrap_or_default();
390	                self.rec_started_ms = now_ms() - v["outputDuration"].as_i64().unwrap_or(0);
391	                if !self.rec_path.is_empty() {
392	                    let _ = self.sh.lib_tx.send(LibCmd::RecordingsChanged);
393	                }
394	            }
395	        }
396	        if let Ok(v) = obs.request("GetReplayBufferStatus", None) {
397	            self.replay_active = v["outputActive"].as_bool().unwrap_or(false);
398	        }
399	        self.ensure_outputs(&cfg);
400	        self.apply_audio();
401	    }
402	
403	    fn drop_connection(&mut self) {
404	        if let Some(o) = self.obs.take() {
405	            o.close();
406	        }
407	        self.events = None;
408	        self.managed = None;
409	        self.sh.update_status(|s| s.obs.connected = false);
410	    }
411	
412	    fn disconnected(&mut self, reason: String) {
413	        if self.obs.is_some() {
414	            tracing::warn!("lost OBS websocket: {reason}");
415	        }
416	        self.drop_connection();
417	    }
418	
419	    fn set_error(&mut self, e: String) {
420	        if self.last_error != e {
421	            self.sh.log_event("error", &e);
422	            self.last_error = e.clone();
423	        }
424	        self.sh.update_status(|s| s.obs.last_error = e);
425	    }
426	
427	    // ------------------------------------------------------ outputs
428	
429	    fn ensure_outputs(&mut self, cfg: &cv_core::config::Config) {
430	        let Some(obs) = self.connected() else { return };
431	        if self.exit_started || self.expecting_exit {
432	            return;
433	        }
434	        let want_rec = cfg.recording.enabled && self.recording_wanted;
435	        if want_rec && !self.rec_active && cfg.recording.auto_restart {
436	            let due = self.last_start_attempt.map(|t| t.elapsed() > Duration::from_secs(10)).unwrap_or(true);
437	            if due {
438	                self.last_start_attempt = Some(Instant::now());
439	                match obs.request("StartRecord", None) {
440	                    Ok(_) => {
441	                        tracing::info!("started recording");
442	                        self.start_failures = 0;
443	                    }
444	                    Err(ObsError::Request { code: 500, .. }) => {} // already active
445	                    Err(e) => {
446	                        self.start_failures += 1;
447	                        if self.start_failures == 3 {
448	                            self.sh.log_event("error", format!("OBS refuses to start recording: {e}"));
449	                            self.sh.ui.send(UiCmd::Balloon {
450	                                level: ToastLevel::Error,
451	                                title: "Recording won't start".into(),
452	                                text: format!("{e}"),
453	                            });
454	                        }
455	                    }
456	                }
457	            }
458	        }
459	        if !self.replay_active {
460	            let due = self.last_replay_attempt.map(|t| t.elapsed() > Duration::from_secs(10)).unwrap_or(true);
461	            if due {
462	                self.last_replay_attempt = Some(Instant::now());
463	                match obs.request("StartReplayBuffer", None) {
464	                    Ok(_) => tracing::info!("started replay buffer"),
465	                    Err(ObsError::Request { code: 500, .. }) => self.replay_active = true,
466	                    Err(e) => tracing::warn!("could not start replay buffer: {e}"),
467	                }
468	            }
469	        }
470	    }
471	
472	    fn health_check(&mut self, cfg: &cv_core::config::Config) {
473	        let Some(obs) = self.connected() else { return };
474	        if let Ok(v) = obs.request("GetRecordStatus", None) {
475	            let active = v["outputActive"].as_bool().unwrap_or(false);
476	            let bytes = v["outputBytes"].as_i64().unwrap_or(0);
477	            if active != self.rec_active {
478	                self.rec_active = active;
479	                self.rec_bytes_changed = Instant::now();
480	            }
481	            if active {
482	                if bytes != self.rec_bytes {
483	                    self.rec_bytes = bytes;
484	                    self.rec_bytes_changed = Instant::now();
485	                } else if self.rec_bytes_changed.elapsed() > Duration::from_secs(cfg.recording.stall_timeout_secs as u64) {
486	                    self.recording_stalled();
487	                }
488	            }
489	        }
490	        if let Ok(v) = obs.request("GetReplayBufferStatus", None) {
491	            self.replay_active = v["outputActive"].as_bool().unwrap_or(false);
492	        }
493	        self.ensure_outputs(cfg);
494	        if self.inputs_dirty || self.tick_count % 20 == 0 {
495	            self.ensure_inputs();
496	        }
497	        if self.pending_save.as_ref().map(|p| p.at.elapsed() > Duration::from_secs(60)).unwrap_or(false) {
498	            self.pending_save = None;
499	        }
500	        // Mic silence warning.
501	        let mins = cfg.audio.mic_silence_warning_mins;
502	        if mins > 0 && self.rec_active && !self.mic_silence_warned && self.mic_last_sound.elapsed() > Duration::from_secs(mins as u64 * 60) {
503	            self.mic_silence_warned = true;
504	            self.sh.ui.send(UiCmd::Balloon {
505	                level: ToastLevel::Warning,
506	                title: "Your mic is silent".into(),
507	                text: format!("No sound from the microphone for {mins} minutes."),
508	            });
509	        }
510	    }
511	
512	    fn recording_stalled(&mut self) {
513	        let Some(obs) = self.connected() else { return };
514	        while self.stall_restarts.front().map(|t| t.elapsed() > Duration::from_secs(600)).unwrap_or(false) {
515	            self.stall_restarts.pop_front();
516	        }
517	        self.stall_restarts.push_back(Instant::now());
518	        self.rec_bytes_changed = Instant::now();
519	        if self.stall_restarts.len() >= 3 {
520	            self.sh.log_event("error", "Recording keeps stalling; restarting OBS");
521	            self.stall_restarts.clear();
522	            self.restart_obs("recording stalled repeatedly");
523	            return;
524	        }
525	        self.sh.log_event("warn", "Recording stopped growing; restarting the recording");
526	        let _ = obs.request("StopRecord", None);
527	        std::thread::sleep(Duration::from_secs(2));
528	        let _ = obs.request("StartRecord", None);
529	    }
