531	    // ------------------------------------------------------- inputs
532	
533	    fn ensure_inputs(&mut self) {
534	        let Some(obs) = self.connected() else { return };
535	        let cfg = self.sh.cfg();
536	        let db = cv_core::db::Db::open_default().ok();
537	        let mic_meta = db.as_ref().and_then(|d| d.meta_get(META_MIC_INPUT).ok().flatten());
538	        let mut routing = self.routing.clone();
539	        if let Some(g) = &self.game {
540	            if let Some(v) = self.routing.get(&g.exe.to_lowercase()) {
541	                routing.insert(String::new(), *v);
542	            }
543	        }
544	        match obs_setup::ensure_inputs(&obs, &cfg, mic_meta.as_deref(), &routing) {
545	            Ok(m) => {
546	                if let (Some(db), Some(mic)) = (db.as_ref(), m.mic.as_ref()) {
547	                    let _ = db.meta_set(META_MIC_INPUT, mic);
548	                }
549	                let changed = self.managed.as_ref() != Some(&m);
550	                self.managed = Some(m);
551	                self.inputs_dirty = false;
552	                if changed {
553	                    self.mic_applied = None;
554	                    self.desktop_applied = None;
555	                    self.game_applied = None;
556	                    self.apply_audio();
557	                }
558	            }
559	            Err(e) => {
560	                tracing::warn!("could not set up OBS audio inputs: {e}");
561	                self.inputs_dirty = true;
562	            }
563	        }
564	    }
565	
566	    fn apply_audio(&mut self) {
567	        let Some(obs) = self.connected() else { return };
568	        let Some(m) = self.managed.clone() else { return };
569	        let cfg = self.sh.cfg();
570	        // Mic.
571	        if let (Some(mic), Some(dec)) = (m.mic.as_ref(), self.mic.clone()) {
572	            if cfg.audio.mic_guard {
573	                if let Some(id) = dec.obs_device_id() {
574	                    if self.mic_applied.as_deref() != Some(id) {
575	                        match obs_setup::set_device(&obs, mic, id) {
576	                            Ok(changed) => {
577	                                self.mic_applied = Some(id.to_string());
578	                                if changed {
579	                                    let msg = match &dec {
580	                                        MicDecision::Preferred { endpoint, .. } => format!("Mic set to {}", cv_core::audio_names::clean_display_name(&endpoint.name)),
581	                                        MicDecision::WindowsDefault => "Preferred mic not connected; recording the Windows default mic".to_string(),
582	                                        MicDecision::Leave => String::new(),
583	                                    };
584	                                    if !msg.is_empty() {
585	                                        self.sh.log_event("info", &msg);
586	                                        self.sh.toast(ToastLevel::Info, msg);
587	                                    }
588	                                }
589	                            }
590	                            Err(e) => tracing::warn!("could not set mic: {e}"),
591	                        }
592	                    }
593	                }
594	            }
595	        }
596	        // Desktop audio device.
597	        if let (Some(desk), Some(dev)) = (m.desktop.as_ref(), self.desktop_device.clone()) {
598	            if self.desktop_applied.as_deref() != Some(dev.as_str()) {
599	                if obs_setup::set_device(&obs, desk, &dev).is_ok() {
600	                    self.desktop_applied = Some(dev);
601	                }
602	            }
603	        }
604	        // Game audio target.
605	        if cfg.audio.multitrack && cfg.audio.game_audio_capture {
606	            if let Some(g) = self.game.clone() {
607	                if self.game_applied.as_deref() != Some(g.exe.as_str()) {
608	                    match obs_setup::set_game_target(&obs, &g.exe, &g.title, &g.class) {
609	                        Ok(changed) => {
610	                            self.game_applied = Some(g.exe.clone());
611	                            if changed {
612	                                tracing::info!("game audio now follows {} ({})", g.name, g.exe);
613	                            }
614	                        }
615	                        Err(e) => tracing::warn!("could not retarget game audio: {e}"),
616	                    }
617	                }
618	            }
619	        }
620	        // Full-mix routing for apps on other devices.
621	        if cfg.audio.multitrack {
622	            let game_exe = self.game.as_ref().map(|g| g.exe.clone());
623	            if let Err(e) = obs_setup::apply_routing(&obs, &m, &self.routing, game_exe.as_deref()) {
624	                tracing::warn!("routing: {e}");
625	            }
626	        }
627	    }
