629	    // ------------------------------------------------------- events
630	
631	    fn obs_event(&mut self, ev: ObsEvent) {
632	        match ev {
633	            ObsEvent::Disconnected(reason) => self.disconnected(reason),
634	            ObsEvent::Event { kind, data } => self.obs_event_kind(&kind, &data),
635	        }
