638	    fn obs_event_kind(&mut self, kind: &str, data: &Value) {
639	        match kind {
640	            "ReplayBufferSaved" => {
641	                let path = data["savedReplayPath"].as_str().unwrap_or("").to_string();
642	                let pending = self.pending_save.take();
643	                if pending.is_none() {
644	                    // Saved from OBS itself: still give the usual feedback.
645	                    self.sh.ui.send(UiCmd::ShowOverlay);
646	                }
647	                tracing::info!("replay saved: {path}");
648	                if !path.is_empty() {
649	                    let _ = self.sh.clip_tx.send(ClipTask::ReplaySaved {
650	                        path: PathBuf::from(norm_path(&path)),
651	                        at_ms: now_ms(),
652	                        short: pending.map(|p| p.short).unwrap_or(false),
653	                    });
654	                }
655	            }
656	            "RecordStateChanged" => {
657	                let state = data["outputState"].as_str().unwrap_or("");
658	                let path = data["outputPath"].as_str().map(norm_path).unwrap_or_default();
659	                match state {
660	                    "OBS_WEBSOCKET_OUTPUT_STARTED" => {
661	                        self.rec_active = true;
662	                        if !path.is_empty() {
663	                            self.rec_path = path;
664	                        }
665	                        self.rec_started_ms = now_ms();
666	                        self.rec_bytes_changed = Instant::now();
667	                        self.sh.log_event("info", "Recording started");
668	                        let _ = self.sh.lib_tx.send(LibCmd::RecordingsChanged);
669	                    }
670	                    "OBS_WEBSOCKET_OUTPUT_STOPPED" => {
671	                        self.rec_active = false;
672	                        self.rec_path.clear();
673	                        if !self.expecting_exit && !self.exit_started {
674	                            self.sh.log_event("warn", "Recording stopped");
675	                        }
676	                        let _ = self.sh.lib_tx.send(LibCmd::RecordingsChanged);
677	                    }
678	                    _ => {}
679	                }
680	            }
681	            "RecordFileChanged" => {
682	                let path = data["newOutputPath"].as_str().map(norm_path).unwrap_or_default();
683	                tracing::info!("recording split -> {path}");
684	                self.rec_path = path;
685	                self.rec_started_ms = now_ms();
686	                let _ = self.sh.lib_tx.send(LibCmd::RecordingsChanged);
687	            }
688	            "ReplayBufferStateChanged" => {
689	                self.replay_active = data["outputActive"].as_bool().unwrap_or(false);
690	            }
691	            "ExitStarted" => {
692	                self.exit_started = true;
693	                tracing::info!("OBS is exiting");
694	            }
695	            "CurrentProgramSceneChanged" | "InputRemoved" | "InputNameChanged" | "SceneItemRemoved" => {
696	                self.inputs_dirty = true;
697	            }
698	            "InputVolumeMeters" => self.meters(data),
699	            _ => {}
700	        }
701	    }
702	
703	    fn meters(&mut self, data: &Value) {
704	        let mic_name = self.managed.as_ref().and_then(|m| m.mic.clone());
705	        let mut out = Vec::new();
706	        if let Some(inputs) = data["inputs"].as_array() {
707	            for i in inputs {
708	                let name = i["inputName"].as_str().unwrap_or("").to_string();
709	                let peak = i["inputLevelsMul"]
710	                    .as_array()
711	                    .map(|chs| chs.iter().filter_map(|c| c.get(1).and_then(Value::as_f64)).fold(0.0f64, f64::max))
712	                    .unwrap_or(0.0) as f32;
713	                if Some(&name) == mic_name.as_ref() && peak > 0.003 {
714	                    self.mic_last_sound = Instant::now();
715	                    self.mic_silence_warned = false;
716	                }
717	                out.push(Meter { name, peak });
718	            }
719	        }
720	        if self.sh.has_clients() && self.meters_emitted.elapsed() >= Duration::from_millis(100) {
721	            self.meters_emitted = Instant::now();
722	            self.sh.emit(Event::Meters { meters: out });
723	        }
724	    }
