728	    fn command(&mut self, cmd: SupCmd) {
729	        match cmd {
730	            SupCmd::SaveClip { short, reply } => {
731	                let r = self.save_clip(short);
732	                if let Err(e) = &r {
733	                    self.sh.toast(ToastLevel::Error, format!("Clip not saved: {e}"));
734	                }
735	                if let Some(reply) = reply {
736	                    let _ = reply.send(r);
737	                }
738	            }
739	            SupCmd::SetRecording { enabled, reply } => {
740	                let r = self.set_recording(enabled);
741	                if let Some(reply) = reply {
742	                    let _ = reply.send(r);
743	                }
744	            }
745	            SupCmd::RestartObs { reply } => {
746	                self.closed_by_user = false;
747	                self.launches.clear();
748	                if self.pid.is_some() {
749	                    self.restart_obs("requested");
750	                }
751	                self.tick();
752	                if let Some(reply) = reply {
753	                    let _ = reply.send(Ok(()));
754	                }
755	            }
756	            SupCmd::ConfigChanged { restart_obs } => {
757	                self.inputs_dirty = true;
758	                *self.sh.tools.write() = None;
759	                if restart_obs && self.pid.is_some() {
760	                    self.restart_obs("settings changed");
761	                } else {
762	                    self.ensure_inputs();
763	                }
764	            }
765	            SupCmd::Mic { decision } => {
766	                if self.mic.as_ref() != Some(&decision) {
767	                    tracing::info!("mic decision: {decision:?}");
768	                    self.mic = Some(decision);
769	                    self.apply_audio();
770	                }
771	            }
772	            SupCmd::DesktopDevice { device_id } => {
773	                if self.desktop_device.as_deref() != Some(&device_id) {
774	                    self.desktop_device = Some(device_id);
775	                    self.apply_audio();
776	                }
777	            }
778	            SupCmd::AppRouting(r) => {
779	                if r != self.routing {
780	                    self.routing = r;
781	                    self.apply_audio();
782	                }
783	            }
784	            SupCmd::GameTarget(g) => {
785	                if self.game.as_ref() != Some(&g) {
786	                    self.game = Some(g);
787	                    self.apply_audio();
788	                }
789	            }
790	            SupCmd::Shutdown => {}
791	        }
792	    }
