794	    fn save_clip(&mut self, short: bool) -> Result<(), String> {
795	        let cfg = self.sh.cfg();
796	        if let Some(t) = self.last_save_request {
797	            if t.elapsed() < Duration::from_millis(cfg.clips.save_cooldown_ms as u64) {
798	                return Ok(()); // double press: ignore silently
799	            }
800	        }
801	        let Some(obs) = self.connected() else {
802	            return Err(if self.pid.is_none() { "OBS is not running".into() } else { "not connected to OBS yet".into() });
803	        };
804	        if !self.replay_active {
805	            let _ = obs.request("StartReplayBuffer", None);
806	            return Err("the replay buffer was off; it's starting now, try again in a moment".into());
807	        }
808	        obs.request("SaveReplayBuffer", None).map_err(|e| e.to_string())?;
809	        self.last_save_request = Some(Instant::now());
810	        self.pending_save = Some(PendingSave { short, at: Instant::now() });
811	        self.sh.ui.send(UiCmd::ShowOverlay);
812	        Ok(())
813	    }
814	
815	    fn set_recording(&mut self, enabled: bool) -> Result<(), String> {
816	        self.recording_wanted = enabled;
817	        if let Ok(db) = cv_core::db::Db::open_default() {
818	            let _ = db.meta_set(META_RECORDING_WANTED, if enabled { "1" } else { "0" });
819	        }
820	        let msg = if enabled { "24/7 recording resumed" } else { "24/7 recording paused" };
821	        self.sh.log_event("info", msg);
822	        self.sh.toast(ToastLevel::Info, msg);
823	        if let Some(obs) = self.connected() {
824	            if enabled {
825	                self.last_start_attempt = None;
826	                let cfg = self.sh.cfg();
827	                self.ensure_outputs(&cfg);
828	            } else if self.rec_active {
829	                obs.request("StopRecord", None).map_err(|e| e.to_string())?;
830	            }
831	        }
832	        self.publish_status();
833	        Ok(())
834	    }
835	
836	    /// Stop outputs, close OBS gracefully (or end it), and let the next tick relaunch.
837	    fn restart_obs(&mut self, why: &str) {
838	        let Some(pid) = self.pid else { return };
839	        tracing::info!("restarting OBS ({why})");
840	        self.expecting_exit = true;
841	        if let Some(obs) = self.connected() {
842	            let _ = obs.request("StopReplayBuffer", None);
843	            if self.rec_active {
844	                let _ = obs.request("StopRecord", None);
845	                for _ in 0..50 {
846	                    std::thread::sleep(Duration::from_millis(200));
847	                    match obs.request("GetRecordStatus", None) {
848	                        Ok(v) if v["outputActive"].as_bool() == Some(false) => break,
849	                        Err(_) => break,
850	                        _ => {}
851	                    }
852	                }
853	            }
854	        }
855	        self.drop_connection();
856	        process::request_close_obs(pid);
857	        let timeout = Duration::from_secs(self.sh.cfg.read().obs.shutdown_timeout_secs as u64);
858	        let t = Instant::now();
859	        while process::is_running(pid) && t.elapsed() < timeout {
860	            std::thread::sleep(Duration::from_millis(250));
861	        }
862	        if process::is_running(pid) {
863	            tracing::warn!("OBS did not close in time; ending it");
864	            process::terminate(pid);
865	            std::thread::sleep(Duration::from_millis(1500));
866	        }
867	        self.pid = None;
868	        self.expecting_exit = false;
869	        self.exit_started = false;
870	        self.rec_active = false;
871	        self.replay_active = false;
872	        self.closed_by_user = false;
873	        // Relaunch right away (settings are written in launch()).
874	        if self.should_launch(&self.sh.cfg()) || self.launches.is_empty() {
875	            self.launch();
876	        }
877	    }
878	
879	    // ------------------------------------------------------- status
880	
881	    fn publish_status(&mut self) {
882	        let cfg = self.sh.cfg();
883	        let running = self.pid.is_some();
884	        let connected = self.connected().is_some();
885	        let mic_state;
886	        let mic_device;
887	        match (&self.mic, cfg.audio.mic_guard) {
888	            (_, false) => {
889	                mic_state = "disabled";
890	                mic_device = String::new();
891	            }
892	            (Some(MicDecision::Preferred { rank, endpoint }), _) => {
893	                mic_state = if *rank == 0 { "ok" } else { "fallback" };
894	                mic_device = cv_core::audio_names::clean_display_name(&endpoint.name);
895	            }
896	            (Some(MicDecision::WindowsDefault), _) => {
897	                mic_state = if cfg.audio.mic_priority.is_empty() { "ok" } else { "fallback" };
898	                mic_device = "Windows default".into();
899	            }
900	            (Some(MicDecision::Leave), _) => {
901	                mic_state = "missing";
902	                mic_device = String::new();
903	            }
904	            (None, _) => {
905	                mic_state = "unknown";
906	                mic_device = String::new();
907	            }
908	        }
909	        let tracks = if cfg.audio.multitrack { 6 } else { 1 };
910	        let healthy = self.rec_active && self.rec_bytes_changed.elapsed() < Duration::from_secs(cfg.recording.stall_timeout_secs as u64);
911	        self.sh.update_status(|s| {
912	            s.obs.running = running;
913	            s.obs.connected = connected;
914	            s.obs.closed_by_user = self.closed_by_user;
915	            if self.last_error.is_empty() {
916	                s.obs.last_error.clear();
917	            }
918	            s.recording.active = self.rec_active;
919	            s.recording.paused_by_user = !self.recording_wanted || !cfg.recording.enabled;
920	            s.recording.path = self.rec_path.clone();
921	            s.recording.started_ms = self.rec_started_ms;
922	            s.recording.bytes = self.rec_bytes;
923	            s.recording.healthy = healthy;
924	            s.recording.tracks = tracks;
925	            s.replay.active = self.replay_active;
926	            s.replay.seconds = cfg.clips.clip_length_secs;
927	            s.mic.state = mic_state.into();
928	            s.mic.device = mic_device;
929	            s.mic.preferred = cfg.audio.mic_priority.first().cloned().unwrap_or_default();
930	            s.game.audio_target = self.game.as_ref().map(|g| g.name.clone());
931	        });
932	    }
933	}
