935	/// Newest non-replay video in the recordings folder.
936	fn newest_recording(folder: &str) -> Option<String> {
937	    let rd = std::fs::read_dir(folder).ok()?;
938	    rd.flatten()
939	        .map(|e| e.path())
940	        .filter(|p| cv_core::obs::filename::is_video_file(p) && !cv_core::obs::filename::is_replay_file(p))
941	        .max_by_key(|p| p.metadata().and_then(|m| m.modified()).ok())
942	        .map(|p| p.to_string_lossy().to_string())
943	}
