945	pub fn send_and_wait(tx: &Sender<SupCmd>, make: impl FnOnce(Sender<Result<(), String>>) -> SupCmd, timeout: Duration) -> Result<(), String> {
946	    let (rtx, rrx) = crossbeam_channel::bounded(1);
947	    tx.send(make(rtx)).map_err(|_| "service is shutting down".to_string())?;
948	    rrx.recv_timeout(timeout).map_err(|_| "timed out".to_string())?
949	}
