106	    /// Gain expressions (mode gains x edits) for every track.
107	    pub fn exprs(&self) -> Vec<String> {
108	        cv_core::mixer::exprs_for(&self.effective_gains(), &self.edits, 0.0)
109	    }
110	
111	    /// Push the current gains/edits to mpv (`changed` = only that track).
112	    pub fn apply_audio(&self, changed: Option<usize>) {
113	        if let Some(m) = &self.mpv {
114	            m.set_exprs(&self.exprs(), changed);
115	        }
116	    }
117	
118	    /// Replace the edits (file time) and apply them.
119	    pub fn set_edits(&mut self, edits: Vec<AudioEdit>) {
120	        if edits != self.edits {
121	            self.edits = edits;
122	            self.apply_audio(None);
123	        }
124	    }
125	
126	    pub fn set_track_gain(&mut self, track: usize, gain: f32) {
127	        if self.stem_gains.len() <= track {
128	            self.stem_gains.resize(track + 1, 1.0);
129	        }
130	        self.stem_gains[track] = gain;
131	        if track > 0 && self.mode == MixMode::Full {
132	            self.set_mode(MixMode::Separate);
133	        } else {
134	            self.apply_audio(Some(track));
135	        }
136	    }
137	
138	    /// Open a file. `tracks` = known audio track count (0 = unknown).
139	    #[allow(clippy::too_many_arguments)]
140	    pub fn open(&mut self, path: &str, start: f64, tracks: usize, stored_names: &[String], saved_mix: Option<&[f32]>, live: bool, autoplay: bool, cfg: &PlayerConfig) {
141	        let Some(mpv) = self.mpv.clone() else { return };
142	        self.track_count = tracks;
143	        self.track_names = Self::names_for(tracks, stored_names);
144	        let multitrack = tracks == TRACK_NAMES.len();
145	        self.stem_gains = match saved_mix {
146	            Some(g) if g.len() == tracks && tracks > 1 => {
147	                self.mode = if g.first().copied().unwrap_or(0.0) > 0.0 && g.iter().skip(1).all(|v| *v == 0.0) { MixMode::Full } else { MixMode::Separate };
148	                g.to_vec()
149	            }
150	            _ => {
151	                self.mode = if cfg.default_mix_mode == "separate" && tracks > 1 { MixMode::Separate } else { MixMode::Full };
152	                cv_core::mixer::default_gains(tracks, "separate", multitrack)
153	            }
154	        };
155	        if tracks > 1 && self.stem_gains.iter().all(|g| *g == 0.0) {
156	            self.stem_gains = cv_core::mixer::default_gains(tracks, "separate", multitrack);
157	        }
158	        let exprs = self.exprs();
159	        let same_file = self.path.as_deref() == Some(path) && self.live == live;
160	        if same_file && mpv.state().loaded {
161	            mpv.seek_abs(start, true);
162	            if autoplay {
163	                mpv.set_pause(false);
164	            }
165	            return;
166	        }
167	        self.path = Some(path.to_string());
168	        self.live = live;
169	        if let Err(e) = mpv.load(path, start, tracks, &exprs, live, !autoplay) {
170	            tracing::warn!("load {path}: {e:#}");
171	        }
172	        let _ = mpv.set("speed", &format!("{}", cfg.default_speed));
173	        self.apply_volume();
174	    }
175	
176	    /// After a file with unknown track count loads, configure mixing.
177	    pub fn after_load_check(&mut self) {
178	        let Some(mpv) = self.mpv.clone() else { return };
179	        if self.track_count == 0 && mpv.state().loaded {
180	            let n = mpv.audio_track_count();
181	            if n > 0 {
182	                self.track_count = n;
183	                self.track_names = Self::names_for(n, &[]);
184	                self.stem_gains = cv_core::mixer::default_gains(n, "separate", n == TRACK_NAMES.len());
185	                if n > 1 {
186	                    let lc = cv_core::mixer::mpv_lavfi_complex(n).unwrap_or_default();
187	                    let _ = mpv.set("lavfi-complex", &lc);
188	                    let _ = mpv.set("af", &cv_core::mixer::mpv_af(&self.exprs()));
189	                }
190	            }
191	        }
192	    }
193	
194	    pub fn close(&mut self) {
195	        if let Some(m) = &self.mpv {
196	            m.stop();
197	        }
198	        self.path = None;
199	        self.live = false;
200	    }
201	
202	    pub fn apply_volume(&self) {
203	        if let Some(m) = &self.mpv {
204	            let _ = m.set("volume", &format!("{:.0}", self.volume * 100.0));
205	            let _ = m.set("mute", if self.muted { "yes" } else { "no" });
206	        }
207	    }
208	
209	    pub fn toggle_pause(&self) {
210	        if let Some(m) = &self.mpv {
211	            let st = m.state();
212	            if st.eof && st.paused {
213	                m.seek_abs(0.0, true);
214	            }
215	            m.set_pause(!st.paused);
216	        }
217	    }
218	
219	    pub fn seek(&mut self, t: f64, exact: bool) {
220	        if let Some(m) = &self.mpv {
221	            m.seek_abs(t, exact);
222	            self.last_seek = std::time::Instant::now();
223	        }
224	    }
225	
226	    pub fn seek_relative(&mut self, delta: f64) {
227	        let st = self.state();
228	        let target = (st.time_pos + delta).max(0.0);
229	        let target = if st.duration > 0.0 && !self.live { target.min(st.duration) } else { target };
230	        self.seek(target, true);
231	    }
232	
233	    pub fn frame_step(&self, forward: bool) {
234	        if let Some(m) = &self.mpv {
235	            let _ = m.command(&[if forward { "frame-step" } else { "frame-back-step" }]);
236	        }
237	    }
238	
239	    pub fn set_mode(&mut self, mode: MixMode) {
240	        self.mode = mode;
241	        if let Some(m) = &self.mpv {
242	            m.set_exprs(&self.exprs(), None);
243	            let _ = m.set("af", &cv_core::mixer::mpv_af(&self.exprs()));
244	        }
245	    }
246	
247	    // ------------------------------------------------------------ UI
248	
249	    /// Draw the video. Click toggles pause, double-click toggles fullscreen.
250	    pub fn video(&mut self, ui: &mut Ui, size: Vec2) -> egui::Response {
251	        let (rect, resp) = ui.allocate_exact_size(size, Sense::click());
252	        ui.painter().rect_filled(rect, CornerRadius::same(if self.fullscreen { 0 } else { 12 }), Color32::BLACK);
253	        match (&self.mpv, &self.path) {
254	            (None, _) => {
255	                let msg = self.init_error.clone().unwrap_or_else(|| "Video engine unavailable".into());
256	                ui.painter().text(rect.center(), Align2::CENTER_CENTER, format!("Player unavailable: {msg}"), FontId::proportional(14.0), theme::TEXT_DIM);
257	            }
258	            (Some(_), None) => {
259	                ui.painter().text(rect.center() - egui::vec2(0.0, 14.0), Align2::CENTER_CENTER, icon::PLAY, FontId::new(34.0, theme::icons_family()), theme::TEXT_FAINT);
260	                ui.painter().text(rect.center() + egui::vec2(0.0, 22.0), Align2::CENTER_CENTER, "Nothing playing", FontId::proportional(14.0), theme::TEXT_FAINT);
261	            }
262	            (Some(m), Some(_)) => {
263	                let st = m.state();
264	                if let Some(err) = &st.last_error {
265	                    ui.painter().text(rect.center(), Align2::CENTER_CENTER, format!("Can't play this file: {err}"), FontId::proportional(14.0), theme::DANGER);
266	                } else {
267	                    // Inset by 1px so rounded corners stay clean.
268	                    let inner = rect.shrink(if self.fullscreen { 0.0 } else { 1.0 });
269	                    ui.painter().add(m.paint_callback(inner));
270	                    if !st.loaded {
271	                        ui.painter().text(rect.center(), Align2::CENTER_CENTER, "Loading…", FontId::proportional(14.0), theme::TEXT_DIM);
272	                    } else if st.paused && !self.scrubbing {
273	                        // Subtle play glyph when paused.
274	                        let c = rect.center();
275	                        ui.painter().circle_filled(c, 30.0, Color32::from_black_alpha(120));
276	                        ui.painter().text(c + egui::vec2(2.0, 0.0), Align2::CENTER_CENTER, icon::PLAY, FontId::new(24.0, theme::icons_family()), Color32::WHITE);
277	                    }
278	                }
279	            }
280	        }
281	        if resp.clicked() {
282	            self.toggle_pause();
283	        }
284	        if resp.double_clicked() {
285	            self.toggle_pause(); // undo the single-click toggle
286	            self.fullscreen = !self.fullscreen;
287	            ui.ctx().send_viewport_cmd(egui::ViewportCommand::Fullscreen(self.fullscreen));
288	        }
289	        resp
290	    }
291	
292	    /// Keyboard shortcuts (only when no text field has focus).
293	    pub fn shortcuts(&mut self, ui: &Ui, cfg: &PlayerConfig) -> ShortcutHits {
294	        let mut hits = ShortcutHits::default();
295	        if ui.ctx().egui_wants_keyboard_input() || self.path.is_none() {
296	            return hits;
297	        }
298	        let (small, large) = (cfg.seek_small_secs as f64, cfg.seek_large_secs as f64);
299	        ui.input(|i| {
300	            let shift = i.modifiers.shift;
301	            if i.key_pressed(Key::Space) || i.key_pressed(Key::K) {
302	                hits.toggle = true;
303	            }
304	            if i.key_pressed(Key::ArrowLeft) || i.key_pressed(Key::J) {
305	                hits.seek = Some(-(if shift { large } else { small }));
306	            }
307	            if i.key_pressed(Key::ArrowRight) || i.key_pressed(Key::L) {
308	                hits.seek = Some(if shift { large } else { small });
309	            }
310	            if i.key_pressed(Key::Comma) {
311	                hits.frame = Some(false);
312	            }
313	            if i.key_pressed(Key::Period) {
314	                hits.frame = Some(true);
315	            }
316	            if i.key_pressed(Key::I) {
317	                hits.mark_in = true;
318	            }
319	            if i.key_pressed(Key::O) {
320	                hits.mark_out = true;
321	            }
322	            if i.key_pressed(Key::M) {
323	                hits.mute = true;
324	            }
325	            if i.key_pressed(Key::F) {
326	                hits.fullscreen = true;
327	            }
328	            if i.key_pressed(Key::Escape) {
329	                hits.escape = true;
330	            }
331	            if i.key_pressed(Key::ArrowUp) {
332	                hits.volume = Some(0.05);
333	            }
334	            if i.key_pressed(Key::ArrowDown) {
335	                hits.volume = Some(-0.05);
336	            }
337	        });
338	        if hits.toggle {
339	            self.toggle_pause();
340	        }
341	        if let Some(d) = hits.seek {
342	            self.seek_relative(d);
343	        }
344	        if let Some(f) = hits.frame {
345	            self.frame_step(f);
346	        }
347	        if hits.mute {
348	            self.muted = !self.muted;
349	            self.apply_volume();
350	        }
351	        if let Some(v) = hits.volume {
352	            self.volume = (self.volume + v).clamp(0.0, 1.5);
353	            self.apply_volume();
354	        }
355	        if hits.fullscreen || (hits.escape && self.fullscreen) {
356	            self.fullscreen = !self.fullscreen;
357	            ui.ctx().send_viewport_cmd(egui::ViewportCommand::Fullscreen(self.fullscreen));
358	        }
359	        hits
360	    }
361	
362	    /// Play/pause, skip buttons, time, speed, volume, mixer toggle.
363	    pub fn transport(&mut self, ui: &mut Ui, time_label: &str, cfg: &PlayerConfig) {
364	        let st = self.state();
365	        ui.horizontal(|ui| {
366	            ui.spacing_mut().item_spacing.x = 4.0;
367	            if theme::icon_button(ui, icon::REWIND, 16.0, &format!("Back {}s (Shift+←)", cfg.seek_large_secs)).clicked() {
368	                self.seek_relative(-(cfg.seek_large_secs as f64));
369	            }
370	            if theme::icon_button(ui, icon::SKIP_BACK, 16.0, &format!("Back {}s (←)", cfg.seek_small_secs)).clicked() {
371	                self.seek_relative(-(cfg.seek_small_secs as f64));
372	            }
373	            let play_glyph = if st.paused || !st.loaded { icon::PLAY } else { icon::PAUSE };
374	            if theme::icon_button(ui, play_glyph, 20.0, "Play/pause (Space)").clicked() {
375	                self.toggle_pause();
376	            }
377	            if theme::icon_button(ui, icon::SKIP_FWD, 16.0, &format!("Forward {}s (→)", cfg.seek_small_secs)).clicked() {
378	                self.seek_relative(cfg.seek_small_secs as f64);
379	            }
380	            if theme::icon_button(ui, icon::FAST_FWD, 16.0, &format!("Forward {}s (Shift+→)", cfg.seek_large_secs)).clicked() {
381	                self.seek_relative(cfg.seek_large_secs as f64);
382	            }
383	            ui.add_space(8.0);
384	            ui.label(RichText::new(time_label).monospace().color(theme::TEXT_DIM));
385	
386	            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
387	                ui.spacing_mut().item_spacing.x = 6.0;
388	                let fs_glyph = if self.fullscreen { icon::EXIT_FULLSCREEN } else { icon::FULLSCREEN };
389	                if theme::icon_button(ui, fs_glyph, 15.0, "Fullscreen (F)").clicked() {
390	                    self.fullscreen = !self.fullscreen;
391	                    ui.ctx().send_viewport_cmd(egui::ViewportCommand::Fullscreen(self.fullscreen));
392	                }
393	                let mixer_tip = if self.show_mixer { "Hide audio tracks".to_string() } else { format!("Show audio tracks ({})", self.track_count.max(1)) };
394	                let mresp = theme::icon_button(ui, icon::MIXER, 15.0, &mixer_tip);
395	                if self.show_mixer {
396	                    ui.painter().rect_stroke(mresp.rect, CornerRadius::same(20), Stroke::new(1.0, theme::TEXT_DIM), egui::StrokeKind::Inside);
397	                }
398	                if mresp.clicked() {
399	                    self.show_mixer = !self.show_mixer;
400	                }
401	                // Speed
402	                let speed = st.speed.max(0.01);
403	                egui::ComboBox::from_id_salt("speed")
404	                    .width(64.0)
405	                    .selected_text(format!("{}x", trim_float(speed)))
406	                    .show_ui(ui, |ui| {
407	                        for s in self.speeds {
408	                            if ui.selectable_label((speed - s).abs() < 0.01, format!("{}x", trim_float(s))).clicked() {
409	                                if let Some(m) = &self.mpv {
410	                                    let _ = m.set("speed", &s.to_string());
411	                                }
412	                            }
413	                        }
414	                    });
415	                // Volume
416	                let mut vol = self.volume;
417	                let r = ui.add(egui::Slider::new(&mut vol, 0.0..=1.5).show_value(false).trailing_fill(true));
418	                if r.changed() {
419	                    self.volume = vol;
420	                    self.muted = false;
421	                    self.apply_volume();
422	                }
423	                let vglyph = if self.muted || self.volume == 0.0 { icon::MUTE } else { icon::VOLUME };
424	                if theme::icon_button(ui, vglyph, 15.0, "Mute (M)").clicked() {
425	                    self.muted = !self.muted;
426	                    self.apply_volume();
427	                }
428	            });
429	        });
430	    }
431	}
432	
433	#[derive(Default, Debug, Clone, Copy)]
434	pub struct ShortcutHits {
435	    pub toggle: bool,
436	    pub seek: Option<f64>,
437	    pub frame: Option<bool>,
438	    pub mark_in: bool,
439	    pub mark_out: bool,
440	    pub mute: bool,
441	    pub fullscreen: bool,
442	    pub escape: bool,
443	    pub volume: Option<f32>,
444	}
445	
446	fn trim_float(v: f64) -> String {
447	    let s = format!("{v:.2}");
448	    s.trim_end_matches('0').trim_end_matches('.').to_string()
449	}
450	
451	/// Seek bar for a single file with optional in/out (trim) markers.
452	/// Returns Some(seconds) when the user seeks.
453	pub fn seek_bar(ui: &mut Ui, player: &mut Player, in_pt: &mut Option<f64>, out_pt: &mut Option<f64>, accent: Color32) -> Option<f64> {
454	    let st = player.state();
455	    let dur = st.duration.max(0.001);
456	    let width = ui.available_width();
457	    let (rect, resp) = ui.allocate_exact_size(Vec2::new(width, 34.0), Sense::click_and_drag());
458	    let track = Rect::from_center_size(rect.center(), Vec2::new(rect.width() - 16.0, 6.0));
459	    let x_of = |t: f64| track.left() + (t / dur).clamp(0.0, 1.0) as f32 * track.width();
460	    let t_of = |x: f32| (((x - track.left()) / track.width()).clamp(0.0, 1.0) as f64) * dur;
461	    let p = ui.painter();
462	    p.rect_filled(track, CornerRadius::same(3), theme::SURFACE3);
463	    // Selection
464	    if let (Some(a), Some(b)) = (*in_pt, *out_pt) {
465	        let r = Rect::from_x_y_ranges(x_of(a)..=x_of(b), track.top() - 4.0..=track.bottom() + 4.0);
466	        p.rect_filled(r, CornerRadius::same(3), accent.gamma_multiply(0.35));
467	    }
468	    let played = Rect::from_x_y_ranges(track.left()..=x_of(st.time_pos), track.y_range());
469	    p.rect_filled(played, CornerRadius::same(3), theme::TEXT_DIM);
470	    for (pt, label) in [(*in_pt, "IN"), (*out_pt, "OUT")] {
471	        if let Some(t) = pt {
472	            let x = x_of(t);
473	            p.line_segment([egui::pos2(x, rect.top() + 2.0), egui::pos2(x, rect.bottom() - 2.0)], Stroke::new(2.0, accent));
474	            p.text(egui::pos2(x, rect.top()), Align2::CENTER_BOTTOM, label, FontId::proportional(9.0), accent);
475	        }
476	    }
477	    let hx = x_of(st.time_pos);
478	    p.circle_filled(egui::pos2(hx, track.center().y), if resp.hovered() || resp.dragged() { 7.0 } else { 5.5 }, Color32::WHITE);
479	    if let Some(pos) = resp.hover_pos() {
480	        let t = t_of(pos.x);
481	        egui::Tooltip::always_open(ui.ctx().clone(), ui.layer_id(), egui::Id::unique("seek_tip"), egui::PopupAnchor::Pointer)
482	            .show(|ui| ui.label(format_duration(t)));
483	    }
484	    let mut seek = None;
485	    if resp.dragged() {
486	        if let Some(pos) = resp.interact_pointer_pos() {
487	            player.scrubbing = true;
488	            let t = t_of(pos.x);
489	            if player.last_seek.elapsed().as_millis() > 60 {
490	                player.seek(t, false);
491	            }
492	            seek = Some(t);
493	        }
494	    }
495	    if resp.drag_stopped() || resp.clicked() {
496	        if let Some(pos) = resp.interact_pointer_pos() {
497	            let t = t_of(pos.x);
498	            player.seek(t, true);
499	            seek = Some(t);
500	        }
501	        player.scrubbing = false;
502	    }
503	    let _ = (seek, 0);
504	    seek
505	}
