155	    pub seeking: bool,
156	    pub loaded: bool,
157	    pub idle: bool,
158	    pub speed: f64,
159	    pub video_w: i64,
160	    pub video_h: i64,
161	    pub cache_end: f64,
162	    pub file_generation: u64,
163	    pub last_error: Option<String>,
164	}
165	
166	struct RenderRes {
167	    ctx: *mut MpvRenderCtx,
168	    fbo: Option<glow::Framebuffer>,
169	    tex: Option<glow::Texture>,
170	    size: (i32, i32),
171	    has_frame: bool,
172	}
173	unsafe impl Send for RenderRes {}
174	
175	pub struct Mpv {
176	    api: Arc<Api>,
177	    h: *mut MpvHandle,
178	    render: Arc<Mutex<RenderRes>>,
179	    state: Mutex<PlayState>,
180	    get_proc: Arc<dyn Fn(&CStr) -> *const c_void + Send + Sync>,
181	    repaint: Box<egui::Context>,
182	    pending_af: Mutex<Option<(String, std::time::Instant)>>,
183	}
184	
185	unsafe impl Send for Mpv {}
186	unsafe impl Sync for Mpv {}
187	
188	unsafe extern "C" fn wakeup(ctx: *mut c_void) {
189	    let ctx = &*(ctx as *const egui::Context);
190	    ctx.request_repaint();
191	}
192	
193	unsafe extern "C" fn get_proc_trampoline(ctx: *mut c_void, name: *const c_char) -> *mut c_void {
194	    let f = &*(ctx as *const Arc<dyn Fn(&CStr) -> *const c_void + Send + Sync>);
195	    f(CStr::from_ptr(name)) as *mut c_void
196	}
197	
198	impl Mpv {
199	    pub fn new(
200	        dll: &Path,
201	        egui_ctx: &egui::Context,
202	        get_proc: Arc<dyn Fn(&CStr) -> *const c_void + Send + Sync>,
203	        cfg: &cv_core::config::PlayerConfig,
204	    ) -> Result<Arc<Mpv>> {
205	        let api = Arc::new(Api::load(dll)?);
206	        unsafe {
207	            let h = (api.create)();
208	            if h.is_null() {
209	                bail!("mpv_create failed");
210	            }
211	            let mut opts: Vec<(&str, String)> = vec![
212	                ("vo", "libmpv".into()),
213	                ("config", "no".into()),
214	                ("terminal", "no".into()),
215	                ("msg-level", "all=error".into()),
216	                ("idle", "yes".into()),
217	                ("keep-open", "yes".into()),
218	                ("osc", "no".into()),
219	                ("osd-level", "0".into()),
220	                ("input-default-bindings", "no".into()),
221	                ("input-vo-keyboard", "no".into()),
222	                ("load-scripts", "no".into()),
223	                ("ytdl", "no".into()),
224	                ("sub-auto", "no".into()),
225	                ("audio-file-auto", "no".into()),
226	                ("hwdec", cfg.hwdec.clone()),
227	                ("hr-seek", "yes".into()),
228	                ("hr-seek-framedrop", "yes".into()),
229	                ("cache", "yes".into()),
230	                ("demuxer-max-bytes", "400MiB".into()),
231	                ("demuxer-max-back-bytes", "200MiB".into()),
232	                ("volume", cfg.volume.to_string()),
233	                ("volume-max", "150".into()),
234	                ("background-color", "#000000".into()),
235	                ("video-sync", "audio".into()),
236	                ("audio-client-name", "ClipVault".into()),
237	                ("pause", "yes".into()),
238	            ];
239	            if let Some(f) = std::env::var_os("CLIPVAULT_MPV_LOG") {
240	                opts.push(("log-file", f.to_string_lossy().to_string()));
241	            }
242	            for (k, v) in opts {
243	                let (k, v) = (CString::new(k)?, CString::new(v)?);
244	                let r = (api.set_option_string)(h, k.as_ptr(), v.as_ptr());
245	                if r < 0 {
246	                    tracing::warn!("mpv option {:?}: {}", k, api.err(r));
247	                }
248	            }
249	            let r = (api.initialize)(h);
250	            if r < 0 {
251	                (api.terminate_destroy)(h);
252	                bail!("mpv_initialize: {}", api.err(r));
253	            }
254	            for (i, (name, fmt)) in [
255	                ("time-pos", FMT_DOUBLE),
256	                ("duration", FMT_DOUBLE),
257	                ("pause", FMT_FLAG),
258	                ("eof-reached", FMT_FLAG),
259	                ("seeking", FMT_FLAG),
260	                ("speed", FMT_DOUBLE),
261	                ("idle-active", FMT_FLAG),
262	                ("width", FMT_INT64),
263	                ("height", FMT_INT64),
264	                ("demuxer-cache-time", FMT_DOUBLE),
265	            ]
266	            .iter()
267	            .enumerate()
268	            {
269	                let n = CString::new(*name)?;
270	                (api.observe_property)(h, i as u64 + 1, n.as_ptr(), *fmt);
271	            }
272	            let repaint = Box::new(egui_ctx.clone());
273	            (api.set_wakeup_callback)(h, Some(wakeup), &*repaint as *const egui::Context as *mut c_void);
274	            Ok(Arc::new(Mpv {
275	                api,
276	                h,
277	                render: Arc::new(Mutex::new(RenderRes { ctx: std::ptr::null_mut(), fbo: None, tex: None, size: (0, 0), has_frame: false })),
278	                state: Mutex::new(PlayState { speed: 1.0, paused: true, idle: true, ..Default::default() }),
279	                get_proc,
280	                repaint,
281	                pending_af: Mutex::new(None),
282	            }))
283	        }
284	    }
285	
286	    pub fn command(&self, args: &[&str]) -> Result<()> {
287	        let cs: Vec<CString> = args.iter().map(|a| CString::new(*a)).collect::<std::result::Result<_, _>>()?;
288	        let mut ptrs: Vec<*const c_char> = cs.iter().map(|c| c.as_ptr()).collect();
289	        ptrs.push(std::ptr::null());
290	        let r = unsafe { (self.api.command)(self.h, ptrs.as_ptr()) };
291	        if r < 0 {
292	            return Err(anyhow!("mpv {}: {}", args.first().unwrap_or(&""), self.api.err(r)));
293	        }
294	        Ok(())
295	    }
296	
297	    /// Fire-and-forget command (doesn't block the UI thread on slow seeks).
298	    pub fn command_async(&self, args: &[&str]) {
299	        let Ok(cs) = args.iter().map(|a| CString::new(*a)).collect::<std::result::Result<Vec<_>, _>>() else { return };
300	        let mut ptrs: Vec<*const c_char> = cs.iter().map(|c| c.as_ptr()).collect();
301	        ptrs.push(std::ptr::null());
302	        unsafe {
303	            (self.api.command_async)(self.h, 0, ptrs.as_ptr());
304	        }
305	    }
306	
307	    pub fn set(&self, name: &str, value: &str) -> Result<()> {
308	        let (n, v) = (CString::new(name)?, CString::new(value)?);
309	        let r = unsafe { (self.api.set_property_string)(self.h, n.as_ptr(), v.as_ptr()) };
310	        if r < 0 {
311	            return Err(anyhow!("mpv set {name}: {}", self.api.err(r)));
312	        }
313	        Ok(())
314	    }
315	
316	    pub fn get_string(&self, name: &str) -> Option<String> {
317	        let n = CString::new(name).ok()?;
318	        unsafe {
319	            let p = (self.api.get_property_string)(self.h, n.as_ptr());
320	            if p.is_null() {
321	                return None;
322	            }
323	            let s = CStr::from_ptr(p).to_string_lossy().to_string();
324	            (self.api.free)(p as *mut c_void);
325	            Some(s)
326	        }
327	    }
328	
329	    pub fn state(&self) -> PlayState {
330	        self.state.lock().clone()
331	    }
332	
333	    /// Drain pending mpv events into `state`. Call once per frame.
334	    pub fn pump(&self) {
335	        loop {
336	            let ev = unsafe { &*(self.api.wait_event)(self.h, 0.0) };
337	            if ev.event_id == 0 {
338	                break;
339	            }
340	            let mut st = self.state.lock();
341	            match ev.event_id {
342	                EV_PROPERTY_CHANGE => unsafe {
343	                    let p = &*(ev.data as *const MpvEventProperty);
344	                    let name = CStr::from_ptr(p.name).to_string_lossy();
345	                    let has = !p.data.is_null();
346	                    let f = || if has { *(p.data as *const f64) } else { 0.0 };
347	                    let b = || has && *(p.data as *const c_int) != 0;
348	                    let i = || if has { *(p.data as *const i64) } else { 0 };
349	                    match name.as_ref() {
350	                        "time-pos" if p.format == FMT_DOUBLE => st.time_pos = f(),
351	                        "duration" if p.format == FMT_DOUBLE => st.duration = f(),
352	                        "pause" => st.paused = b(),
353	                        "eof-reached" => st.eof = b(),
354	                        "seeking" => st.seeking = b(),
355	                        "speed" if p.format == FMT_DOUBLE => st.speed = f(),
356	                        "idle-active" => st.idle = b(),
357	                        "width" => st.video_w = i(),
358	                        "height" => st.video_h = i(),
359	                        "demuxer-cache-time" if p.format == FMT_DOUBLE => st.cache_end = f(),
360	                        _ => {}
361	                    }
362	                },
363	                EV_FILE_LOADED => {
364	                    tracing::info!("mpv: file loaded");
365	                    st.loaded = true;
366	                    st.eof = false;
367	                    st.last_error = None;
368	                    st.file_generation += 1;
369	                }
370	                EV_END_FILE => {
371	                    // data: mpv_event_end_file { int reason; int error; ... }
372	                    unsafe {
373	                        if !ev.data.is_null() {
374	                            let reason = *(ev.data as *const c_int);
375	                            let err = *(ev.data as *const c_int).add(1);
376	                            tracing::info!("mpv: end file (reason {reason}, error {})", self.api.err(err));
377	                            if reason == 4 {
378	                                st.last_error = Some(self.api.err(err));
379	                                st.loaded = false;
380	                            }
381	                        }
382	                    }
383	                }
384	                EV_PLAYBACK_RESTART => st.seeking = false,
385	                EV_SHUTDOWN => break,
386	                _ => {}
387	            }
388	        }
389	        // Apply a debounced filter-string update (see `set_gains`).
390	        let due = {
391	            let p = self.pending_af.lock();
392	            p.as_ref().map(|(_, t)| t.elapsed() > std::time::Duration::from_millis(350)).unwrap_or(false)
393	        };
394	        if due {
395	            if let Some((af, _)) = self.pending_af.lock().take() {
396	                let _ = self.set("af", &af);
397	            }
398	        }
399	    }
400	
401	    /// Load a file. `tracks` is the known audio track count (0 = unknown).
402	    /// `exprs` = per-track gain expressions (see `cv_core::mixer::track_expr`).
403	    pub fn load(&self, path: &str, start: f64, tracks: usize, exprs: &[String], live: bool, pause: bool) -> Result<()> {
404	        {
405	            let mut st = self.state.lock();
406	            st.loaded = false;
407	            st.eof = false;
408	            st.time_pos = start;
409	            st.duration = 0.0;
410	            st.last_error = None;
411	        }
412	        *self.pending_af.lock() = None;
413	        let lc = cv_core::mixer::mpv_lavfi_complex(tracks).unwrap_or_default();
414	        self.set("lavfi-complex", &lc)?;
415	        self.set("af", &cv_core::mixer::mpv_af(exprs))?;
416	        self.set("pause", if pause { "yes" } else { "no" })?;
417	        let target = if live { format!("appending://{path}") } else { path.to_string() };
418	        let opts = format!("start={start:.3}");
419	        tracing::info!("mpv: loadfile {target} start={start:.1} tracks={tracks} live={live}");
420	        self.command(&["loadfile", &target, "replace", "-1", &opts])
421	    }
422	
423	    /// Change per-track gain expressions live: the changed track (or all, if
424	    /// `changed` is None) is updated instantly via af-command, and the full
425	    /// filter string is re-applied shortly after so seeks keep the new values.
426	    pub fn set_exprs(&self, exprs: &[String], changed: Option<usize>) {
427	        let targets: Vec<usize> = match changed {
428	            Some(i) => vec![i],
429	            None => (0..exprs.len()).collect(),
430	        };
431	        for i in targets {
432	            if let Some(e) = exprs.get(i) {
433	                let cmd = cv_core::mixer::mpv_gain_command(i, e);
434	                let refs: Vec<&str> = cmd.iter().map(String::as_str).collect();
435	                let _ = self.command(&refs);
436	            }
437	        }
438	        *self.pending_af.lock() = Some((cv_core::mixer::mpv_af(exprs), std::time::Instant::now()));
439	    }
440	
441	    pub fn seek_abs(&self, t: f64, exact: bool) {
442	        let t = format!("{:.3}", t.max(0.0));
443	        self.command_async(&["seek", &t, if exact { "absolute+exact" } else { "absolute+keyframes" }]);
444	    }
445	
446	    pub fn set_pause(&self, p: bool) {
447	        let _ = self.set("pause", if p { "yes" } else { "no" });
448	    }
449	
450	    pub fn stop(&self) {
451	        let _ = self.command(&["stop"]);
452	        let mut st = self.state.lock();
453	        st.loaded = false;
454	        st.time_pos = 0.0;
455	        st.duration = 0.0;
456	        self.render.lock().has_frame = false;
457	    }
458	
459	    /// Paint callback that renders the current frame into `rect`.
460	    pub fn paint_callback(self: &Arc<Self>, rect: egui::Rect) -> egui::PaintCallback {
461	        let me = self.clone();
462	        egui::PaintCallback {
463	            rect,
464	            callback: Arc::new(egui_glow::CallbackFn::new(move |info, painter| {
465	                me.render_into(info, painter.gl());
466	            })),
467	        }
468	    }
469	
470	    fn render_into(&self, info: egui::PaintCallbackInfo, gl: &Arc<glow::Context>) {
471	        use glow::HasContext;
472	        let vp = info.viewport_in_pixels();
473	        let (w, h) = (vp.width_px.max(1), vp.height_px.max(1));
474	        let mut rr = self.render.lock();
475	        unsafe {
476	            if rr.ctx.is_null() {
477	                let api_type = CString::new("opengl").unwrap();
478	                let gp: *const Arc<dyn Fn(&CStr) -> *const c_void + Send + Sync> = &self.get_proc;
479	                let mut init = MpvOpenglInitParams { get_proc_address: Some(get_proc_trampoline), get_proc_address_ctx: gp as *mut c_void };
480	                let mut block = 0 as c_int;
481	                let mut params = [
482	                    MpvRenderParam { kind: RP_API_TYPE, data: api_type.as_ptr() as *mut c_void },
483	                    MpvRenderParam { kind: RP_OPENGL_INIT, data: &mut init as *mut _ as *mut c_void },
484	                    MpvRenderParam { kind: RP_BLOCK_FOR_TARGET, data: &mut block as *mut _ as *mut c_void },
485	                    MpvRenderParam { kind: 0, data: std::ptr::null_mut() },
486	                ];
487	                let mut ctx: *mut MpvRenderCtx = std::ptr::null_mut();
488	                let r = (self.api.rc_create)(&mut ctx, self.h, params.as_mut_ptr());
489	                if r < 0 {
490	                    tracing::error!("mpv render context: {}", self.api.err(r));
491	                    return;
492	                }
493	                (self.api.rc_set_update_callback)(ctx, Some(wakeup), &*self.repaint as *const egui::Context as *mut c_void);
494	                tracing::info!("mpv: render context created");
495	                rr.ctx = ctx;
496	            }
497	            // (Re)create our framebuffer when the size changes.
498	            if rr.size != (w, h) || rr.fbo.is_none() {
499	                if let Some(f) = rr.fbo.take() {
500	                    gl.delete_framebuffer(f);
501	                }
502	                if let Some(t) = rr.tex.take() {
503	                    gl.delete_texture(t);
504	                }
505	                let tex = gl.create_texture().ok();
506	                gl.bind_texture(glow::TEXTURE_2D, tex);
507	                gl.tex_image_2d(glow::TEXTURE_2D, 0, glow::RGBA8 as i32, w, h, 0, glow::RGBA, glow::UNSIGNED_BYTE, glow::PixelUnpackData::Slice(None));
508	                gl.tex_parameter_i32(glow::TEXTURE_2D, glow::TEXTURE_MIN_FILTER, glow::LINEAR as i32);
509	                gl.tex_parameter_i32(glow::TEXTURE_2D, glow::TEXTURE_MAG_FILTER, glow::LINEAR as i32);
510	                let fbo = gl.create_framebuffer().ok();
511	                gl.bind_framebuffer(glow::FRAMEBUFFER, fbo);
512	                gl.framebuffer_texture_2d(glow::FRAMEBUFFER, glow::COLOR_ATTACHMENT0, glow::TEXTURE_2D, tex, 0);
513	                gl.bind_framebuffer(glow::FRAMEBUFFER, None);
514	                rr.fbo = fbo;
515	                rr.tex = tex;
516	                rr.size = (w, h);
517	                rr.has_frame = false;
518	            }
519	            let prev_draw = gl.get_parameter_i32(glow::DRAW_FRAMEBUFFER_BINDING);
520	            let flags = (self.api.rc_update)(rr.ctx);
521	            if flags & RENDER_UPDATE_FRAME != 0 || !rr.has_frame {
522	                let fbo_id = rr.fbo.map(|f| f.0.get() as c_int).unwrap_or(0);
523	                let mut fbo = MpvOpenglFbo { fbo: fbo_id, w, h, internal_format: 0 };
524	                let mut flip: c_int = 1;
525	                let mut block: c_int = 0;
526	                let mut params = [
527	                    MpvRenderParam { kind: RP_OPENGL_FBO, data: &mut fbo as *mut _ as *mut c_void },
528	                    MpvRenderParam { kind: RP_FLIP_Y, data: &mut flip as *mut _ as *mut c_void },
529	                    MpvRenderParam { kind: RP_BLOCK_FOR_TARGET, data: &mut block as *mut _ as *mut c_void },
530	                    MpvRenderParam { kind: 0, data: std::ptr::null_mut() },
531	                ];
532	                gl.disable(glow::SCISSOR_TEST);
533	                (self.api.rc_render)(rr.ctx, params.as_mut_ptr());
534	                rr.has_frame = true;
535	            }
536	            // Blit our frame into egui's framebuffer at the widget rect.
537	            gl.bind_framebuffer(glow::READ_FRAMEBUFFER, rr.fbo);
538	            let draw = std::num::NonZeroU32::new(prev_draw as u32).map(glow::NativeFramebuffer);
539	            gl.bind_framebuffer(glow::DRAW_FRAMEBUFFER, draw);
540	            gl.enable(glow::SCISSOR_TEST);
541	            let clip = info.clip_rect_in_pixels();
542	            gl.scissor(clip.left_px, clip.from_bottom_px, clip.width_px, clip.height_px);
543	            gl.blit_framebuffer(
544	                0,
545	                0,
546	                w,
547	                h,
548	                vp.left_px,
549	                vp.from_bottom_px,
550	                vp.left_px + w,
551	                vp.from_bottom_px + h,
552	                glow::COLOR_BUFFER_BIT,
553	                glow::NEAREST,
554	            );
555	            gl.bind_framebuffer(glow::READ_FRAMEBUFFER, None);
556	            gl.bind_framebuffer(glow::FRAMEBUFFER, draw);
557	        }
558	    }
559	
560	    /// Must be called with the GL context current (on exit).
561	    pub fn destroy_gl(&self, gl: &glow::Context) {
562	        use glow::HasContext;
563	        let mut rr = self.render.lock();
564	        unsafe {
565	            if !rr.ctx.is_null() {
566	                (self.api.rc_free)(rr.ctx);
567	                rr.ctx = std::ptr::null_mut();
568	            }
569	            if let Some(f) = rr.fbo.take() {
570	                gl.delete_framebuffer(f);
571	            }
572	            if let Some(t) = rr.tex.take() {
573	                gl.delete_texture(t);
574	            }
575	        }
576	    }
577	
578	    /// Number of audio tracks in the loaded file.
579	    pub fn audio_track_count(&self) -> usize {
580	        let n: usize = self.get_string("track-list/count").and_then(|s| s.parse().ok()).unwrap_or(0);
581	        (0..n).filter(|i| self.get_string(&format!("track-list/{i}/type")).as_deref() == Some("audio")).count()
582	    }
583	}
584	
585	impl Drop for Mpv {
586	    fn drop(&mut self) {
587	        unsafe {
588	            (self.api.set_wakeup_callback)(self.h, None, std::ptr::null_mut());
589	            let rr = self.render.lock();
590	            if !rr.ctx.is_null() {
591	                (self.api.rc_set_update_callback)(rr.ctx, None, std::ptr::null_mut());
592	            }
593	            drop(rr);
594	            (self.api.terminate_destroy)(self.h);
595	        }
596	    }
597	}
