75	pub struct App {
76	    pub c: Ctx,
77	    page: Page,
78	    home: HomeView,
79	    clips: ClipsView,
80	    recordings: RecordingsView,
81	    settings: SettingsView,
82	    titlebar_done: u32,
83	    gl: Option<std::sync::Arc<glow::Context>>,
84	    selftest: Option<SelfTest>,
85	}
