87	/// `CLIPVAULT_SELFTEST=<dir>`: visit each page, save a screenshot of the app
88	/// window to <dir>, then exit. Used to check the UI without screen capture.
89	struct SelfTest {
90	    dir: std::path::PathBuf,
91	    step: usize,
92	    at: Instant,
93	    entered: bool,
