97	const SELFTEST_STEPS: [&str; 8] = ["home", "live", "clips", "clip_detail", "settings_general", "settings_recording", "settings_audio", "settings_games"];
98	
99	impl App {
100	    pub fn new(cc: &eframe::CreationContext<'_>, cfg: Config) -> App {
101	        let ctx = &cc.egui_ctx;
102	        theme::install_fonts(ctx);
103	        let accent = theme::accent(cfg.general.accent);
104	        theme::apply(ctx, accent, cfg.general.ui_scale);
105	        let mpv = match (crate::mpv::find_libmpv(&cfg.advanced.mpv_dll_path), cc.get_proc_address.clone()) {
106	            (Some(dll), Some(gp)) => Mpv::new(&dll, ctx, gp, &cfg.player).map_err(|e| format!("{e:#}")),
107	            (None, _) => Err("libmpv-2.dll not found next to clipvault.exe".to_string()),
108	            (_, None) => Err("OpenGL is unavailable".to_string()),
109	        };
110	        if let Err(e) = &mpv {
111	            tracing::error!("player: {e}");
112	        }
113	        let player = Player::new(mpv, &cfg.player);
114	        crate::views::clips::set_repaint_ctx(ctx);
115	        let page = match cfg.general.start_page.as_str() {
116	            "recordings" => Page::Recordings,
117	            "clips" => Page::Clips,
118	            _ => Page::Home,
119	        };
120	        let c = Ctx {
121	            service: Service::start(ctx.clone()),
122	            thumbs: Thumbs::new(ctx.clone()),
123	            player,
124	            waves: Default::default(),
125	            db: Db::open_default().ok(),
126	            accent,
127	            toasts: Vec::new(),
