144	    fn poll(&mut self, ctx: &egui::Context) {
145	        self.c.thumbs.poll(ctx);
146	        if let Some(m) = &self.c.player.mpv {
147	            m.pump();
148	        }
149	        self.c.player.after_load_check();
150	        while let Ok(ev) = self.c.service.events.try_recv() {
151	            match ev {
152	                UiEvent::LibraryChanged => {
153	                    self.clips.mark_dirty();
154	                    self.home.mark_dirty();
155	                }
156	                UiEvent::ClipAdded(id) => {
157	                    self.clips.mark_dirty();
158	                    self.clips.highlight = Some(id);
159	                    self.home.mark_dirty();
160	                }
161	                UiEvent::RecordingsChanged => self.recordings.mark_dirty(),
162	                UiEvent::Toast { level, message } => self.c.toast(&level, message),
163	                UiEvent::JobDone(job) => {
164	                    if job.state == "done" {
165	                        self.clips.mark_dirty();
166	                        if let Some(id) = job.clip_id {
167	                            self.clips.highlight = Some(id);
168	                        }
169	                    }
170	                }
171	            }
172	        }
173	        // Keep animating while playing (time display/seek bar).
174	        let st = self.c.player.state();
175	        if self.c.player.path.is_some() && !st.paused {
176	            ctx.request_repaint_after(Duration::from_millis(100));
177	        } else {
178	            ctx.request_repaint_after(Duration::from_millis(1000));
179	        }
180	    }
181	
182	    fn navigate(&mut self, page: Page) {
183	        if page == self.page {
184	            return;
185	        }
186	        if self.page == Page::Settings {
187	            self.settings.leave(&mut self.c);
188	        }
189	        // Leaving a page with a player: pause playback.
190	        if matches!(self.page, Page::Recordings | Page::Clips) {
191	            if let Some(m) = &self.c.player.mpv {
192	                m.set_pause(true);
193	            }
194	        }
195	        self.page = page;
196	    }
197	
198	    fn sidebar(&mut self, ui: &mut Ui) {
199	        ui.add_space(18.0);
200	        ui.horizontal(|ui| {
201	            ui.add_space(18.0);
202	            let (r, _) = ui.allocate_exact_size(Vec2::splat(28.0), Sense::hover());
203	            ui.painter().rect_filled(r, CornerRadius::same(8), theme::SURFACE3);
204	            ui.painter().circle_stroke(r.center(), 8.0, Stroke::new(2.4, theme::TEXT));
205	            ui.painter().circle_filled(r.center(), 3.6, self.c.accent);
206	            ui.add_space(4.0);
207	            ui.label(RichText::new("ClipVault").font(FontId::new(18.0, theme::bold())).color(theme::TEXT));
208	        });
209	        ui.add_space(24.0);
210	        let items = [
211	            (Page::Home, icon::HOME, "Home"),
212	            (Page::Recordings, icon::HISTORY, "24/7 Recordings"),
213	            (Page::Clips, icon::LIBRARY, "Clips"),
214	            (Page::Settings, icon::SETTINGS, "Settings"),
215	        ];
216	        for (page, glyph, label) in items {
217	            let selected = self.page == page;
218	            let (rect, resp) = ui.allocate_exact_size(Vec2::new(ui.available_width(), 40.0), Sense::click());
219	            let rect = rect.shrink2(Vec2::new(10.0, 2.0));
220	            let bg = if selected {
221	                theme::SURFACE3
222	            } else if resp.hovered() {
223	                theme::SURFACE2
224	            } else {
225	                Color32::TRANSPARENT
226	            };
227	            ui.painter().rect_filled(rect, CornerRadius::same(9), bg);
228	            if selected {
229	                let bar = egui::Rect::from_min_size(rect.left_top() + egui::vec2(0.0, 10.0), egui::vec2(3.0, rect.height() - 20.0));
230	                ui.painter().rect_filled(bar, CornerRadius::same(2), self.c.accent);
231	            }
232	            let fg = if selected { theme::TEXT } else { theme::TEXT_DIM };
233	            ui.painter().text(rect.left_center() + egui::vec2(20.0, 0.0), Align2::CENTER_CENTER, glyph, FontId::new(15.0, theme::icons_family()), fg);
234	            ui.painter().text(
235	                rect.left_center() + egui::vec2(40.0, 0.0),
236	                Align2::LEFT_CENTER,
237	                label,
238	                FontId::new(14.0, if selected { theme::semibold() } else { egui::FontFamily::Proportional }),
239	                fg,
240	            );
241	            if resp.on_hover_cursor(egui::CursorIcon::PointingHand).clicked() {
242	                self.navigate(page);
243	            }
244	        }
245	
246	        // Bottom: status + save clip.
247	        ui.with_layout(egui::Layout::bottom_up(egui::Align::Center), |ui| {
248	            ui.add_space(16.0);
249	            let status = self.c.service.status();
250	            let connected = self.c.service.connected();
251	            let w = ui.available_width() - 28.0;
252	            ui.allocate_ui(Vec2::new(w, 40.0), |ui| {
253	                ui.set_width(w);
254	                let enabled = connected && status.as_ref().map(|s| s.replay.active).unwrap_or(false);
255	                ui.add_enabled_ui(enabled, |ui| {
256	                    if theme::accent_button(ui, Some(icon::RECORD), "Save clip", self.c.accent)
257	                        .on_hover_text(format!("Saves the last {} ({})", cv_core::util::format_duration(self.c.cfg.clips.clip_length_secs as f64), self.c.cfg.hotkeys.save_clip))
258	                        .clicked()
259	                    {
260	                        self.c.service.fire(Request::SaveClip { short: false });
261	                    }
262	                });
263	            });
264	            ui.add_space(10.0);
265	            theme::card().inner_margin(Margin::same(12)).show(ui, |ui| {
266	                ui.set_width(w - 24.0);
267	                status_block(ui, connected, status.as_ref());
268	            });
269	        });
270	    }
271	
272	    fn toasts(&mut self, ctx: &egui::Context) {
273	        self.c.toasts.retain(|t| t.at.elapsed() < Duration::from_secs(5));
274	        if self.c.toasts.is_empty() {
275	            return;
276	        }
277	        ctx.request_repaint_after(Duration::from_millis(250));
278	        egui::Area::new(egui::Id::unique("toasts"))
279	            .anchor(Align2::RIGHT_BOTTOM, egui::vec2(-20.0, -20.0))
280	            .order(egui::Order::Foreground)
281	            .show(ctx, |ui| {
282	                for t in self.c.toasts.iter().rev() {
283	                    let color = match t.level.as_str() {
284	                        "error" => theme::DANGER,
285	                        "warning" => theme::WARNING,
286	                        "success" => theme::SUCCESS,
287	                        _ => self.c.accent,
288	                    };
289	                    egui::Frame::NONE
290	                        .fill(theme::SURFACE2)
291	                        .stroke(Stroke::new(1.0, theme::BORDER_STRONG))
292	                        .corner_radius(CornerRadius::same(10))
293	                        .inner_margin(Margin::symmetric(14, 10))
294	                        .shadow(egui::Shadow { offset: [0, 6], blur: 16, spread: 0, color: Color32::from_black_alpha(110) })
295	                        .show(ui, |ui| {
296	                            ui.set_max_width(380.0);
297	                            ui.horizontal(|ui| {
298	                                let (r, _) = ui.allocate_exact_size(Vec2::new(3.0, 18.0), Sense::hover());
299	                                ui.painter().rect_filled(r, CornerRadius::same(2), color);
300	                                ui.label(RichText::new(&t.text).color(theme::TEXT));
301	                            });
302	                        });
303	                    ui.add_space(8.0);
304	                }
305	            });
306	    }
307	}
308	
309	impl App {
310	    fn selftest_step(&mut self, ctx: &egui::Context) {
311	        let Some(t) = &mut self.selftest else { return };
312	        ctx.request_repaint_after(Duration::from_millis(200));
313	        let name = SELFTEST_STEPS.get(t.step).copied();
314	        if !t.entered {
315	            // Enter the step (navigate), then wait for it to settle.
316	            t.entered = true;
317	            t.shot = false;
318	            t.at = Instant::now();
319	            match name {
320	                Some("home") => self.page = Page::Home,
321	                Some("live") => {
322	                    self.navigate(Page::Recordings);
323	                    crate::views::recordings::request_go_live();
324	                }
325	                Some("clips") => self.navigate(Page::Clips),
326	                Some("clip_detail") => {
327	                    let clips = self.c.db().and_then(|d| d.list_clips(&Default::default()).ok()).unwrap_or_default();
328	                    if let Some(c) = clips.iter().find(|c| c.audio_tracks > 1).or(clips.first()) {
329	                        crate::views::clips::request_open(c.id);
330	                    }
331	                }
332	                Some(s) if s.starts_with("settings_") => {
333	                    self.navigate(Page::Settings);
334	                    self.settings.select_tab(&s["settings_".len()..]);
335	                }
336	                Some(_) => {}
337	                None => {
338	                    std::thread::spawn(|| {
339	                        std::thread::sleep(Duration::from_secs(2));
340	                        std::process::exit(0);
341	                    });
342	                    self.selftest = None;
343	                }
344	            }
345	            return;
346	        }
347	        let wait = match name {
348	            Some("home") => 5,
349	            Some("live") | Some("clip_detail") => 6,
350	            _ => 3,
351	        };
352	        if !t.shot && t.at.elapsed() >= Duration::from_secs(wait) {
353	            t.shot = true;
354	            t.at = Instant::now();
355	            let path = t.dir.join(format!("{:02}_{}.png", t.step + 1, name.unwrap_or("x")));
356	            ctx.send_viewport_cmd(egui::ViewportCommand::Screenshot(egui::ScreenshotCallback::new(move |img: std::sync::Arc<egui::ColorImage>| {
357	                let [w, h] = img.size;
358	                let mut buf = Vec::with_capacity(w * h * 4);
359	                for p in &img.pixels {
360	                    buf.extend_from_slice(&p.to_array());
361	                }
362	                if let Some(im) = image::RgbaImage::from_raw(w as u32, h as u32, buf) {
363	                    let _ = im.save(&path);
364	                }
365	            })));
366	        } else if t.shot && t.at.elapsed() >= Duration::from_millis(800) {
367	            t.step += 1;
368	            t.entered = false;
369	        }
370	    }
371	}
372	
373	pub fn status_block(ui: &mut Ui, connected: bool, status: Option<&cv_core::ipc::Status>) {
374	    let row = |ui: &mut Ui, color: Color32, text: &str| {
375	        ui.horizontal(|ui| {
376	            let (r, _) = ui.allocate_exact_size(Vec2::splat(10.0), Sense::hover());
377	            ui.painter().circle_filled(r.center(), 4.0, color);
378	            ui.label(RichText::new(text).size(12.5).color(theme::TEXT_DIM));
379	        });
380	    };
381	    let Some(s) = status.filter(|_| connected) else {
382	        row(ui, theme::WARNING, "Starting service…");
383	        return;
384	    };
385	    if !s.obs.running {
386	        row(ui, theme::DANGER, "OBS not running");
387	    } else if !s.obs.connected {
388	        row(ui, theme::WARNING, "Connecting to OBS…");
389	    } else if s.recording.active {
390	        let secs = (cv_core::util::now_ms() - s.recording.started_ms).max(0) / 1000;
391	        row(ui, theme::LIVE, &format!("Recording · {}", cv_core::util::format_span_short(secs)));
392	    } else if s.recording.paused_by_user {
393	        row(ui, theme::TEXT_FAINT, "24/7 paused");
394	    } else {
395	        row(ui, theme::WARNING, "Not recording");
396	    }
397	    let replay = if s.replay.active { theme::SUCCESS } else { theme::DANGER };
398	    row(ui, replay, if s.replay.active { "Replay buffer on" } else { "Replay buffer off" });
399	    let (mc, mt) = match s.mic.state.as_str() {
400	        "ok" => (theme::SUCCESS, "Mic OK"),
401	        "fallback" => (theme::WARNING, "Mic fallback"),
402	        "missing" => (theme::DANGER, "No mic"),
403	        "disabled" => (theme::TEXT_FAINT, "Mic guard off"),
404	        _ => (theme::TEXT_FAINT, "Mic…"),
405	    };
406	    row(ui, mc, mt);
407	}
408	
409	impl eframe::App for App {
410	    fn ui(&mut self, ui: &mut Ui, _frame: &mut eframe::Frame) {
411	        let ctx = ui.ctx().clone();
412	        if self.titlebar_done < 3 {
413	            self.titlebar_done += 1;
414	            crate::dark_title_bar();
415	        }
416	        self.poll(&ctx);
417	        self.selftest_step(&ctx);
418	        if let Some(p) = self.c.goto.take() {
419	            self.navigate(p);
420	        }
421	
422	        let fullscreen = self.c.player.fullscreen && matches!(self.page, Page::Recordings | Page::Clips);
423	        if !fullscreen {
424	            egui::Panel::left("nav")
425	                .exact_size(232.0)
426	                .resizable(false)
427	                .frame(egui::Frame::NONE.fill(theme::SIDEBAR).stroke(Stroke::new(1.0, theme::BORDER)))
428	                .show(ui, |ui| self.sidebar(ui));
429	        }
430	        let margin = if fullscreen { Margin::ZERO } else { Margin::symmetric(28, 22) };
431	        egui::CentralPanel::default()
432	            .frame(egui::Frame::NONE.fill(theme::BG).inner_margin(margin))
433	            .show(ui, |ui| match self.page {
434	                Page::Home => self.home.ui(ui, &mut self.c),
435	                Page::Recordings => self.recordings.ui(ui, &mut self.c),
436	                Page::Clips => self.clips.ui(ui, &mut self.c),
437	                Page::Settings => self.settings.ui(ui, &mut self.c),
438	            });
439	        self.toasts(&ctx);
440	    }
441	
442	    fn on_exit(&mut self, gl: Option<&glow::Context>) {
443	        self.clips.save_position(&mut self.c);
444	        if let (Some(m), Some(gl)) = (&self.c.player.mpv, gl.or(self.gl.as_deref())) {
445	            m.stop();
446	            m.destroy_gl(gl);
447	        }
448	    }
449	
450	    fn clear_color(&self, _visuals: &egui::Visuals) -> [f32; 4] {
451	        theme::BG.to_normalized_gamma_f32()
452	    }
453	}
