//! Top-level app: navigation, shared resources, toasts.

use crate::mpv::Mpv;
use crate::player::Player;
use crate::service::{Service, UiEvent};
use crate::theme::{self, icon};
use crate::thumbs::Thumbs;
use crate::views::{clips::ClipsView, home::HomeView, recordings::RecordingsView, settings::SettingsView};
use cv_core::config::Config;
use cv_core::db::Db;
use cv_core::ipc::Request;
use eframe::egui::{self, Align2, Color32, CornerRadius, FontId, Margin, RichText, Sense, Stroke, Ui, Vec2};
use std::time::{Duration, Instant};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Page {
    Home,
    Recordings,
    Clips,
    Settings,
}

pub struct Toast {
    pub level: String,
    pub text: String,
    pub at: Instant,
}

/// Things views share.
pub struct Ctx {
    pub cfg: Config,
    pub service: Service,
    pub thumbs: Thumbs,
    pub player: Player,
    pub waves: crate::lanes::Waves,
    pub db: Option<Db>,
    pub accent: Color32,
    pub toasts: Vec<Toast>,
    /// Requested navigation (views set this).
    pub goto: Option<Page>,
}

impl Ctx {
    pub fn toast(&mut self, level: &str, text: impl Into<String>) {
        self.toasts.push(Toast { level: level.into(), text: text.into(), at: Instant::now() });
        if self.toasts.len() > 5 {
            self.toasts.remove(0);
        }
    }

    /// Fire a request; show any error as a toast.
    pub fn request(&mut self, req: Request) -> Option<serde_json::Value> {
        match self.service.call(req) {
            Ok(v) => Some(v),
            Err(e) => {
                self.toast("error", e);
                None
            }
        }
    }

    pub fn db(&mut self) -> Option<&Db> {
        if self.db.is_none() {
            self.db = Db::open_default().ok();
        }
        self.db.as_ref()
    }

    pub fn reload_config(&mut self) {
        self.cfg = Config::load_or_default();
        self.accent = theme::accent(self.cfg.general.accent);
    }
}

pub struct App {
    pub c: Ctx,
    page: Page,
    home: HomeView,
    clips: ClipsView,
    recordings: RecordingsView,
    settings: SettingsView,
    titlebar_done: u32,
    gl: Option<std::sync::Arc<glow::Context>>,
    selftest: Option<SelfTest>,
}

/// `CLIPVAULT_SELFTEST=<dir>`: visit each page, save a screenshot of the app
/// window to <dir>, then exit. Used to check the UI without screen capture.
struct SelfTest {
    dir: std::path::PathBuf,
    step: usize,
    at: Instant,
    entered: bool,
    shot: bool,
}

const SELFTEST_STEPS: [&str; 8] = ["home", "live", "clips", "clip_detail", "settings_general", "settings_recording", "settings_audio", "settings_games"];

impl App {
    pub fn new(cc: &eframe::CreationContext<'_>, cfg: Config) -> App {
        let ctx = &cc.egui_ctx;
        theme::install_fonts(ctx);
        let accent = theme::accent(cfg.general.accent);
        theme::apply(ctx, accent, cfg.general.ui_scale);
        let mpv = match (crate::mpv::find_libmpv(&cfg.advanced.mpv_dll_path), cc.get_proc_address.clone()) {
            (Some(dll), Some(gp)) => Mpv::new(&dll, ctx, gp, &cfg.player).map_err(|e| format!("{e:#}")),
            (None, _) => Err("libmpv-2.dll not found next to clipvault.exe".to_string()),
            (_, None) => Err("OpenGL is unavailable".to_string()),
        };
        if let Err(e) = &mpv {
            tracing::error!("player: {e}");
        }
        let player = Player::new(mpv, &cfg.player);
        crate::views::clips::set_repaint_ctx(ctx);
        let page = match cfg.general.start_page.as_str() {
            "recordings" => Page::Recordings,
            "clips" => Page::Clips,
            _ => Page::Home,
        };
        let c = Ctx {
            service: Service::start(ctx.clone()),
            thumbs: Thumbs::new(ctx.clone()),
            player,
            waves: Default::default(),
            db: Db::open_default().ok(),
            accent,
            toasts: Vec::new(),
            goto: None,
            cfg,
        };
        App {
            c,
            page,
            home: HomeView::default(),
            clips: ClipsView::default(),
            recordings: RecordingsView::default(),
            settings: SettingsView::default(),
            titlebar_done: 0,
            gl: cc.gl.clone(),
            selftest: std::env::var_os("CLIPVAULT_SELFTEST").map(|d| SelfTest { dir: d.into(), step: 0, at: Instant::now(), entered: false, shot: false }),
        }
    }

    fn poll(&mut self, ctx: &egui::Context) {
        self.c.thumbs.poll(ctx);
        if let Some(m) = &self.c.player.mpv {
            m.pump();
        }
        self.c.player.after_load_check();
        while let Ok(ev) = self.c.service.events.try_recv() {
            match ev {
                UiEvent::LibraryChanged => {
                    self.clips.mark_dirty();
                    self.home.mark_dirty();
                }
                UiEvent::ClipAdded(id) => {
                    self.clips.mark_dirty();
                    self.clips.highlight = Some(id);
                    self.home.mark_dirty();
                }
                UiEvent::RecordingsChanged => self.recordings.mark_dirty(),
                UiEvent::Toast { level, message } => self.c.toast(&level, message),
                UiEvent::JobDone(job) => {
                    if job.state == "done" {
                        self.clips.mark_dirty();
                        if let Some(id) = job.clip_id {
                            self.clips.highlight = Some(id);
                        }
                    }
                }
            }
        }
        // Keep animating while playing (time display/seek bar).
        let st = self.c.player.state();
        if self.c.player.path.is_some() && !st.paused {
            ctx.request_repaint_after(Duration::from_millis(100));
        } else {
            ctx.request_repaint_after(Duration::from_millis(1000));
        }
    }

    fn navigate(&mut self, page: Page) {
        if page == self.page {
            return;
        }
        if self.page == Page::Settings {
            self.settings.leave(&mut self.c);
        }
        // Leaving a page with a player: pause playback.
        if matches!(self.page, Page::Recordings | Page::Clips) {
            if let Some(m) = &self.c.player.mpv {
                m.set_pause(true);
            }
        }
        self.page = page;
    }

    fn sidebar(&mut self, ui: &mut Ui) {
        ui.add_space(18.0);
        ui.horizontal(|ui| {
            ui.add_space(18.0);
            let (r, _) = ui.allocate_exact_size(Vec2::splat(28.0), Sense::hover());
            ui.painter().rect_filled(r, CornerRadius::same(8), theme::SURFACE3);
            ui.painter().circle_stroke(r.center(), 8.0, Stroke::new(2.4, theme::TEXT));
            ui.painter().circle_filled(r.center(), 3.6, self.c.accent);
            ui.add_space(4.0);
            ui.label(RichText::new("ClipVault").font(FontId::new(18.0, theme::bold())).color(theme::TEXT));
        });
        ui.add_space(24.0);
        let items = [
            (Page::Home, icon::HOME, "Home"),
            (Page::Recordings, icon::HISTORY, "24/7 Recordings"),
            (Page::Clips, icon::LIBRARY, "Clips"),
            (Page::Settings, icon::SETTINGS, "Settings"),
        ];
        for (page, glyph, label) in items {
            let selected = self.page == page;
            let (rect, resp) = ui.allocate_exact_size(Vec2::new(ui.available_width(), 40.0), Sense::click());
            let rect = rect.shrink2(Vec2::new(10.0, 2.0));
            let bg = if selected {
                theme::SURFACE3
            } else if resp.hovered() {
                theme::SURFACE2
            } else {
                Color32::TRANSPARENT
            };
            ui.painter().rect_filled(rect, CornerRadius::same(9), bg);
            if selected {
                let bar = egui::Rect::from_min_size(rect.left_top() + egui::vec2(0.0, 10.0), egui::vec2(3.0, rect.height() - 20.0));
                ui.painter().rect_filled(bar, CornerRadius::same(2), self.c.accent);
            }
            let fg = if selected { theme::TEXT } else { theme::TEXT_DIM };
            ui.painter().text(rect.left_center() + egui::vec2(20.0, 0.0), Align2::CENTER_CENTER, glyph, FontId::new(15.0, theme::icons_family()), fg);
            ui.painter().text(
                rect.left_center() + egui::vec2(40.0, 0.0),
                Align2::LEFT_CENTER,
                label,
                FontId::new(14.0, if selected { theme::semibold() } else { egui::FontFamily::Proportional }),
                fg,
            );
            if resp.on_hover_cursor(egui::CursorIcon::PointingHand).clicked() {
                self.navigate(page);
            }
        }

        // Bottom: status + save clip.
        ui.with_layout(egui::Layout::bottom_up(egui::Align::Center), |ui| {
            ui.add_space(16.0);
            let status = self.c.service.status();
            let connected = self.c.service.connected();
            let w = ui.available_width() - 28.0;
            ui.allocate_ui(Vec2::new(w, 40.0), |ui| {
                ui.set_width(w);
                let enabled = connected && status.as_ref().map(|s| s.replay.active).unwrap_or(false);
                ui.add_enabled_ui(enabled, |ui| {
                    if theme::accent_button(ui, Some(icon::RECORD), "Save clip", self.c.accent)
                        .on_hover_text(format!("Saves the last {} ({})", cv_core::util::format_duration(self.c.cfg.clips.clip_length_secs as f64), self.c.cfg.hotkeys.save_clip))
                        .clicked()
                    {
                        self.c.service.fire(Request::SaveClip { short: false });
                    }
                });
            });
            ui.add_space(10.0);
            theme::card().inner_margin(Margin::same(12)).show(ui, |ui| {
                ui.set_width(w - 24.0);
                status_block(ui, connected, status.as_ref());
            });
        });
    }

    fn toasts(&mut self, ctx: &egui::Context) {
        self.c.toasts.retain(|t| t.at.elapsed() < Duration::from_secs(5));
        if self.c.toasts.is_empty() {
            return;
        }
        ctx.request_repaint_after(Duration::from_millis(250));
        egui::Area::new(egui::Id::unique("toasts"))
            .anchor(Align2::RIGHT_BOTTOM, egui::vec2(-20.0, -20.0))
            .order(egui::Order::Foreground)
            .show(ctx, |ui| {
                for t in self.c.toasts.iter().rev() {
                    let color = match t.level.as_str() {
                        "error" => theme::DANGER,
                        "warning" => theme::WARNING,
                        "success" => theme::SUCCESS,
                        _ => self.c.accent,
                    };
                    egui::Frame::NONE
                        .fill(theme::SURFACE2)
                        .stroke(Stroke::new(1.0, theme::BORDER_STRONG))
                        .corner_radius(CornerRadius::same(10))
                        .inner_margin(Margin::symmetric(14, 10))
                        .shadow(egui::Shadow { offset: [0, 6], blur: 16, spread: 0, color: Color32::from_black_alpha(110) })
                        .show(ui, |ui| {
                            ui.set_max_width(380.0);
                            ui.horizontal(|ui| {
                                let (r, _) = ui.allocate_exact_size(Vec2::new(3.0, 18.0), Sense::hover());
                                ui.painter().rect_filled(r, CornerRadius::same(2), color);
                                ui.label(RichText::new(&t.text).color(theme::TEXT));
                            });
                        });
                    ui.add_space(8.0);
                }
            });
    }
}

impl App {
    fn selftest_step(&mut self, ctx: &egui::Context) {
        let Some(t) = &mut self.selftest else { return };
        ctx.request_repaint_after(Duration::from_millis(200));
        let name = SELFTEST_STEPS.get(t.step).copied();
        if !t.entered {
            // Enter the step (navigate), then wait for it to settle.
            t.entered = true;
            t.shot = false;
            t.at = Instant::now();
            match name {
                Some("home") => self.page = Page::Home,
                Some("live") => {
                    self.navigate(Page::Recordings);
                    crate::views::recordings::request_go_live();
                }
                Some("clips") => self.navigate(Page::Clips),
                Some("clip_detail") => {
                    let clips = self.c.db().and_then(|d| d.list_clips(&Default::default()).ok()).unwrap_or_default();
                    if let Some(c) = clips.iter().find(|c| c.audio_tracks > 1).or(clips.first()) {
                        crate::views::clips::request_open(c.id);
                    }
                }
                Some(s) if s.starts_with("settings_") => {
                    self.navigate(Page::Settings);
                    self.settings.select_tab(&s["settings_".len()..]);
                }
                Some(_) => {}
                None => {
                    std::thread::spawn(|| {
                        std::thread::sleep(Duration::from_secs(2));
                        std::process::exit(0);
                    });
                    self.selftest = None;
                }
            }
            return;
        }
        let wait = match name {
            Some("home") => 5,
            Some("live") | Some("clip_detail") => 6,
            _ => 3,
        };
        if !t.shot && t.at.elapsed() >= Duration::from_secs(wait) {
            t.shot = true;
            t.at = Instant::now();
            let path = t.dir.join(format!("{:02}_{}.png", t.step + 1, name.unwrap_or("x")));
            ctx.send_viewport_cmd(egui::ViewportCommand::Screenshot(egui::ScreenshotCallback::new(move |img: std::sync::Arc<egui::ColorImage>| {
                let [w, h] = img.size;
                let mut buf = Vec::with_capacity(w * h * 4);
                for p in &img.pixels {
                    buf.extend_from_slice(&p.to_array());
                }
                if let Some(im) = image::RgbaImage::from_raw(w as u32, h as u32, buf) {
                    let _ = im.save(&path);
                }
            })));
        } else if t.shot && t.at.elapsed() >= Duration::from_millis(800) {
            t.step += 1;
            t.entered = false;
        }
    }
}

pub fn status_block(ui: &mut Ui, connected: bool, status: Option<&cv_core::ipc::Status>) {
    let row = |ui: &mut Ui, color: Color32, text: &str| {
        ui.horizontal(|ui| {
            let (r, _) = ui.allocate_exact_size(Vec2::splat(10.0), Sense::hover());
            ui.painter().circle_filled(r.center(), 4.0, color);
            ui.label(RichText::new(text).size(12.5).color(theme::TEXT_DIM));
        });
    };
    let Some(s) = status.filter(|_| connected) else {
        row(ui, theme::WARNING, "Starting service…");
        return;
    };
    if !s.obs.running {
        row(ui, theme::DANGER, "OBS not running");
    } else if !s.obs.connected {
        row(ui, theme::WARNING, "Connecting to OBS…");
    } else if s.recording.active {
        let secs = (cv_core::util::now_ms() - s.recording.started_ms).max(0) / 1000;
        row(ui, theme::LIVE, &format!("Recording · {}", cv_core::util::format_span_short(secs)));
    } else if s.recording.paused_by_user {
        row(ui, theme::TEXT_FAINT, "24/7 paused");
    } else {
        row(ui, theme::WARNING, "Not recording");
    }
    let replay = if s.replay.active { theme::SUCCESS } else { theme::DANGER };
    row(ui, replay, if s.replay.active { "Replay buffer on" } else { "Replay buffer off" });
    let (mc, mt) = match s.mic.state.as_str() {
        "ok" => (theme::SUCCESS, "Mic OK"),
        "fallback" => (theme::WARNING, "Mic fallback"),
        "missing" => (theme::DANGER, "No mic"),
        "disabled" => (theme::TEXT_FAINT, "Mic guard off"),
        _ => (theme::TEXT_FAINT, "Mic…"),
    };
    row(ui, mc, mt);
}

impl eframe::App for App {
    fn ui(&mut self, ui: &mut Ui, _frame: &mut eframe::Frame) {
        let ctx = ui.ctx().clone();
        if self.titlebar_done < 3 {
            self.titlebar_done += 1;
            crate::dark_title_bar();
        }
        self.poll(&ctx);
        self.selftest_step(&ctx);
        if let Some(p) = self.c.goto.take() {
            self.navigate(p);
        }

        let fullscreen = self.c.player.fullscreen && matches!(self.page, Page::Recordings | Page::Clips);
        if !fullscreen {
            egui::Panel::left("nav")
                .exact_size(232.0)
                .resizable(false)
                .frame(egui::Frame::NONE.fill(theme::SIDEBAR).stroke(Stroke::new(1.0, theme::BORDER)))
                .show(ui, |ui| self.sidebar(ui));
        }
        let margin = if fullscreen { Margin::ZERO } else { Margin::symmetric(28, 22) };
        egui::CentralPanel::default()
            .frame(egui::Frame::NONE.fill(theme::BG).inner_margin(margin))
            .show(ui, |ui| match self.page {
                Page::Home => self.home.ui(ui, &mut self.c),
                Page::Recordings => self.recordings.ui(ui, &mut self.c),
                Page::Clips => self.clips.ui(ui, &mut self.c),
                Page::Settings => self.settings.ui(ui, &mut self.c),
            });
        self.toasts(&ctx);
    }

    fn on_exit(&mut self, gl: Option<&glow::Context>) {
        self.clips.save_position(&mut self.c);
        if let (Some(m), Some(gl)) = (&self.c.player.mpv, gl.or(self.gl.as_deref())) {
            m.stop();
            m.destroy_gl(gl);
        }
    }

    fn clear_color(&self, _visuals: &egui::Visuals) -> [f32; 4] {
        theme::BG.to_normalized_gamma_f32()
    }
}

content.content:
1	//! The player: video surface, transport controls and the per-track mixer.
2	//! Shared by the clip view and the 24/7 recordings view.
3	
4	use crate::mpv::Mpv;
5	use crate::theme::{self, icon};
6	use cv_core::config::{PlayerConfig, TRACK_NAMES};
7	use cv_core::model::AudioEdit;
8	use cv_core::util::format_duration;
9	use eframe::egui::{self, Align2, Color32, CornerRadius, FontId, Key, Rect, RichText, Sense, Stroke, Ui, Vec2};
10	use std::sync::Arc;
11	
12	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
13	pub enum MixMode {
14	    Full,
15	    Separate,
16	}
17	
18	pub struct Player {
19	    pub mpv: Option<Arc<Mpv>>,
20	    pub init_error: Option<String>,
21	    /// Path currently loaded.
22	    pub path: Option<String>,
23	    pub live: bool,
24	    pub track_count: usize,
25	    pub track_names: Vec<String>,
26	    pub mode: MixMode,
27	    /// Per-track gains used in "separate" mode.
28	    pub stem_gains: Vec<f32>,
29	    /// Non-destructive per-track edits in the loaded file's time.
30	    pub edits: Vec<AudioEdit>,
31	    pub volume: f32,
32	    pub muted: bool,
33	    pub show_mixer: bool,
34	    pub fullscreen: bool,
35	    pub scrubbing: bool,
36	    pub speeds: [f64; 7],
37	    last_seek: std::time::Instant,
38	}
39	
40	impl Player {
41	    pub fn new(mpv: Result<Arc<Mpv>, String>, cfg: &PlayerConfig) -> Player {
42	        let (mpv, init_error) = match mpv {
43	            Ok(m) => (Some(m), None),
44	            Err(e) => (None, Some(e)),
45	        };
46	        Player {
47	            mpv,
48	            init_error,
49	            path: None,
50	            live: false,
51	            track_count: 0,
52	            track_names: Vec::new(),
53	            mode: if cfg.default_mix_mode == "separate" { MixMode::Separate } else { MixMode::Full },
54	            stem_gains: Vec::new(),
55	            edits: Vec::new(),
56	            volume: cfg.volume as f32 / 100.0,
57	            muted: false,
58	            show_mixer: true,
59	            fullscreen: false,
60	            scrubbing: false,
61	            speeds: [0.25, 0.5, 0.75, 1.0, 1.25, 1.5, 2.0],
62	            last_seek: std::time::Instant::now(),
63	        }
64	    }
65	
66	    pub fn state(&self) -> crate::mpv::PlayState {
67	        self.mpv.as_ref().map(|m| m.state()).unwrap_or_default()
68	    }
69	
70	    pub fn names_for(tracks: usize, stored: &[String]) -> Vec<String> {
71	        (0..tracks)
72	            .map(|i| {
73	                if let Some(n) = stored.get(i).filter(|n| !n.is_empty()) {
74	                    n.clone()
75	                } else if tracks == TRACK_NAMES.len() {
76	                    TRACK_NAMES[i].to_string()
77	                } else if tracks == 1 {
78	                    "Audio".to_string()
79	                } else {
80	                    format!("Track {}", i + 1)
81	                }
82	            })
83	            .collect()
84	    }
85	
86	    /// Gains actually sent to mpv for the current mode.
87	    pub fn effective_gains(&self) -> Vec<f32> {
88	        let n = self.track_count.max(1);
89	        if n == 1 {
90	            return vec![1.0];
91	        }
92	        match self.mode {
93	            MixMode::Full => {
94	                let mut g = vec![0.0; n];
95	                g[0] = 1.0;
96	                g
97	            }
98	            MixMode::Separate => {
99	                let mut g = self.stem_gains.clone();
100	                g.resize(n, 1.0);
101	                g
102	            }
103	        }
104	    }
105	
106	    /// Gain expressions (mode gains x edits) for every track.
107	    pub fn exprs(&self) -> Vec<String> {
108	        cv_core::mixer::exprs_for(&self.effective_gains(), &self.edits, 0.0)
109	    }
110	
111	    /// Push the current gains/edits to mpv (`changed` = only that track).
112	    pub fn apply_audio(&self, changed: Option<usize>) {
113	        if let Some(m) = &self.mpv {
114	            m.set_exprs(&self.exprs(), changed);
115	        }
116	    }
117	
118	    /// Replace the edits (file time) and apply them.
119	    pub fn set_edits(&mut self, edits: Vec<AudioEdit>) {
120	        if edits != self.edits {
121	            self.edits = edits;
122	            self.apply_audio(None);
123	        }
124	    }
125	
126	    pub fn set_track_gain(&mut self, track: usize, gain: f32) {
127	        if self.stem_gains.len() <= track {
128	            self.stem_gains.resize(track + 1, 1.0);
129	        }
130	        self.stem_gains[track] = gain;
131	        if track > 0 && self.mode == MixMode::Full {
132	            self.set_mode(MixMode::Separate);
133	        } else {
134	            self.apply_audio(Some(track));
135	        }
136	    }
137	
138	    /// Open a file. `tracks` = known audio track count (0 = unknown).
139	    #[allow(clippy::too_many_arguments)]
140	    pub fn open(&mut self, path: &str, start: f64, tracks: usize, stored_names: &[String], saved_mix: Option<&[f32]>, live: bool, autoplay: bool, cfg: &PlayerConfig) {
141	        let Some(mpv) = self.mpv.clone() else { return };
142	        self.track_count = tracks;
143	        self.track_names = Self::names_for(tracks, stored_names);
144	        let multitrack = tracks == TRACK_NAMES.len();
145	        self.stem_gains = match saved_mix {
146	            Some(g) if g.len() == tracks && tracks > 1 => {
147	                self.mode = if g.first().copied().unwrap_or(0.0) > 0.0 && g.iter().skip(1).all(|v| *v == 0.0) { MixMode::Full } else { MixMode::Separate };
148	                g.to_vec()
149	            }
150	            _ => {
151	                self.mode = if cfg.default_mix_mode == "separate" && tracks > 1 { MixMode::Separate } else { MixMode::Full };
152	                cv_core::mixer::default_gains(tracks, "separate", multitrack)
153	            }
154	        };
155	        if tracks > 1 && self.stem_gains.iter().all(|g| *g == 0.0) {
156	            self.stem_gains = cv_core::mixer::default_gains(tracks, "separate", multitrack);
157	        }
158	        let exprs = self.exprs();
159	        let same_file = self.path.as_deref() == Some(path) && self.live == live;
160	        if same_file && mpv.state().loaded {
161	            mpv.seek_abs(start, true);
162	            if autoplay {
163	                mpv.set_pause(false);
164	            }
165	            return;
166	        }
167	        self.path = Some(path.to_string());
168	        self.live = live;
169	        if let Err(e) = mpv.load(path, start, tracks, &exprs, live, !autoplay) {
170	            tracing::warn!("load {path}: {e:#}");
171	        }
172	        let _ = mpv.set("speed", &format!("{}", cfg.default_speed));
173	        self.apply_volume();
174	    }
175	
176	    /// After a file with unknown track count loads, configure mixing.
177	    pub fn after_load_check(&mut self) {
178	        let Some(mpv) = self.mpv.clone() else { return };
179	        if self.track_count == 0 && mpv.state().loaded {
180	            let n = mpv.audio_track_count();
181	            if n > 0 {
182	                self.track_count = n;
183	                self.track_names = Self::names_for(n, &[]);
184	                self.stem_gains = cv_core::mixer::default_gains(n, "separate", n == TRACK_NAMES.len());
185	                if n > 1 {
186	                    let lc = cv_core::mixer::mpv_lavfi_complex(n).unwrap_or_default();
187	                    let _ = mpv.set("lavfi-complex", &lc);
188	                    let _ = mpv.set("af", &cv_core::mixer::mpv_af(&self.exprs()));
189	                }
190	            }
191	        }
192	    }
193	
194	    pub fn close(&mut self) {
195	        if let Some(m) = &self.mpv {
196	            m.stop();
197	        }
198	        self.path = None;
199	        self.live = false;
200	    }
201	
202	    pub fn apply_volume(&self) {
203	        if let Some(m) = &self.mpv {
204	            let _ = m.set("volume", &format!("{:.0}", self.volume * 100.0));
205	            let _ = m.set("mute", if self.muted { "yes" } else { "no" });
206	        }
207	    }
208	
209	    pub fn toggle_pause(&self) {
210	        if let Some(m) = &self.mpv {
211	            let st = m.state();
212	            if st.eof && st.paused {
213	                m.seek_abs(0.0, true);
214	            }
215	            m.set_pause(!st.paused);
216	        }
217	    }
218	
219	    pub fn seek(&mut self, t: f64, exact: bool) {
220	        if let Some(m) = &self.mpv {
221	            m.seek_abs(t, exact);
222	            self.last_seek = std::time::Instant::now();
223	        }
224	    }
225	
226	    pub fn seek_relative(&mut self, delta: f64) {
227	        let st = self.state();
228	        let target = (st.time_pos + delta).max(0.0);
229	        let target = if st.duration > 0.0 && !self.live { target.min(st.duration) } else { target };
230	        self.seek(target, true);
231	    }
232	
233	    pub fn frame_step(&self, forward: bool) {
234	        if let Some(m) = &self.mpv {
235	            let _ = m.command(&[if forward { "frame-step" } else { "frame-back-step" }]);
236	        }
237	    }
238	
239	    pub fn set_mode(&mut self, mode: MixMode) {
240	        self.mode = mode;
241	        if let Some(m) = &self.mpv {
242	            m.set_exprs(&self.exprs(), None);
243	            let _ = m.set("af", &cv_core::mixer::mpv_af(&self.exprs()));
244	        }
245	    }
246	
247	    // ------------------------------------------------------------ UI
248	
249	    /// Draw the video. Click toggles pause, double-click toggles fullscreen.
250	    pub fn video(&mut self, ui: &mut Ui, size: Vec2) -> egui::Response {
251	        let (rect, resp) = ui.allocate_exact_size(size, Sense::click());
252	        ui.painter().rect_filled(rect, CornerRadius::same(if self.fullscreen { 0 } else { 12 }), Color32::BLACK);
253	        match (&self.mpv, &self.path) {
254	            (None, _) => {
255	                let msg = self.init_error.clone().unwrap_or_else(|| "Video engine unavailable".into());
256	                ui.painter().text(rect.center(), Align2::CENTER_CENTER, format!("Player unavailable: {msg}"), FontId::proportional(14.0), theme::TEXT_DIM);
257	            }
258	            (Some(_), None) => {
259	                ui.painter().text(rect.center() - egui::vec2(0.0, 14.0), Align2::CENTER_CENTER, icon::PLAY, FontId::new(34.0, theme::icons_family()), theme::TEXT_FAINT);
260	                ui.painter().text(rect.center() + egui::vec2(0.0, 22.0), Align2::CENTER_CENTER, "Nothing playing", FontId::proportional(14.0), theme::TEXT_FAINT);
261	            }
262	            (Some(m), Some(_)) => {
263	                let st = m.state();
264	                if let Some(err) = &st.last_error {
265	                    ui.painter().text(rect.center(), Align2::CENTER_CENTER, format!("Can't play this file: {err}"), FontId::proportional(14.0), theme::DANGER);
266	                } else {
267	                    // Inset by 1px so rounded corners stay clean.
268	                    let inner = rect.shrink(if self.fullscreen { 0.0 } else { 1.0 });
269	                    ui.painter().add(m.paint_callback(inner));
270	                    if !st.loaded {
271	                        ui.painter().text(rect.center(), Align2::CENTER_CENTER, "Loading…", FontId::proportional(14.0), theme::TEXT_DIM);
272	                    } else if st.paused && !self.scrubbing {
273	                        // Subtle play glyph when paused.
274	                        let c = rect.center();
275	                        ui.painter().circle_filled(c, 30.0, Color32::from_black_alpha(120));
276	                        ui.painter().text(c + egui::vec2(2.0, 0.0), Align2::CENTER_CENTER, icon::PLAY, FontId::new(24.0, theme::icons_family()), Color32::WHITE);
277	                    }
278	                }
279	            }
280	        }
281	        if resp.clicked() {
282	            self.toggle_pause();
283	        }
284	        if resp.double_clicked() {
285	            self.toggle_pause(); // undo the single-click toggle
286	            self.fullscreen = !self.fullscreen;
287	            ui.ctx().send_viewport_cmd(egui::ViewportCommand::Fullscreen(self.fullscreen));
288	        }
289	        resp
290	    }
