292	    /// Keyboard shortcuts (only when no text field has focus).
293	    pub fn shortcuts(&mut self, ui: &Ui, cfg: &PlayerConfig) -> ShortcutHits {
294	        let mut hits = ShortcutHits::default();
295	        if ui.ctx().egui_wants_keyboard_input() || self.path.is_none() {
296	            return hits;
297	        }
298	        let (small, large) = (cfg.seek_small_secs as f64, cfg.seek_large_secs as f64);
299	        ui.input(|i| {
300	            let shift = i.modifiers.shift;
301	            if i.key_pressed(Key::Space) || i.key_pressed(Key::K) {
302	                hits.toggle = true;
303	            }
304	            if i.key_pressed(Key::ArrowLeft) || i.key_pressed(Key::J) {
305	                hits.seek = Some(-(if shift { large } else { small }));
306	            }
307	            if i.key_pressed(Key::ArrowRight) || i.key_pressed(Key::L) {
308	                hits.seek = Some(if shift { large } else { small });
309	            }
310	            if i.key_pressed(Key::Comma) {
311	                hits.frame = Some(false);
312	            }
313	            if i.key_pressed(Key::Period) {
314	                hits.frame = Some(true);
315	            }
316	            if i.key_pressed(Key::I) {
317	                hits.mark_in = true;
318	            }
319	            if i.key_pressed(Key::O) {
320	                hits.mark_out = true;
321	            }
322	            if i.key_pressed(Key::M) {
323	                hits.mute = true;
324	            }
325	            if i.key_pressed(Key::F) {
326	                hits.fullscreen = true;
327	            }
328	            if i.key_pressed(Key::Escape) {
329	                hits.escape = true;
330	            }
331	            if i.key_pressed(Key::ArrowUp) {
332	                hits.volume = Some(0.05);
333	            }
334	            if i.key_pressed(Key::ArrowDown) {
335	                hits.volume = Some(-0.05);
336	            }
337	        });
338	        if hits.toggle {
339	            self.toggle_pause();
340	        }
341	        if let Some(d) = hits.seek {
342	            self.seek_relative(d);
343	        }
344	        if let Some(f) = hits.frame {
345	            self.frame_step(f);
346	        }
347	        if hits.mute {
348	            self.muted = !self.muted;
349	            self.apply_volume();
350	        }
351	        if let Some(v) = hits.volume {
352	            self.volume = (self.volume + v).clamp(0.0, 1.5);
353	            self.apply_volume();
354	        }
355	        if hits.fullscreen || (hits.escape && self.fullscreen) {
356	            self.fullscreen = !self.fullscreen;
357	            ui.ctx().send_viewport_cmd(egui::ViewportCommand::Fullscreen(self.fullscreen));
358	        }
359	        hits
360	    }
