362	    /// Play/pause, skip buttons, time, speed, volume, mixer toggle.
363	    pub fn transport(&mut self, ui: &mut Ui, time_label: &str, cfg: &PlayerConfig) {
364	        let st = self.state();
365	        ui.horizontal(|ui| {
366	            ui.spacing_mut().item_spacing.x = 4.0;
367	            if theme::icon_button(ui, icon::REWIND, 16.0, &format!("Back {}s (Shift+←)", cfg.seek_large_secs)).clicked() {
368	                self.seek_relative(-(cfg.seek_large_secs as f64));
369	            }
370	            if theme::icon_button(ui, icon::SKIP_BACK, 16.0, &format!("Back {}s (←)", cfg.seek_small_secs)).clicked() {
371	                self.seek_relative(-(cfg.seek_small_secs as f64));
372	            }
373	            let play_glyph = if st.paused || !st.loaded { icon::PLAY } else { icon::PAUSE };
374	            if theme::icon_button(ui, play_glyph, 20.0, "Play/pause (Space)").clicked() {
375	                self.toggle_pause();
376	            }
377	            if theme::icon_button(ui, icon::SKIP_FWD, 16.0, &format!("Forward {}s (→)", cfg.seek_small_secs)).clicked() {
378	                self.seek_relative(cfg.seek_small_secs as f64);
379	            }
380	            if theme::icon_button(ui, icon::FAST_FWD, 16.0, &format!("Forward {}s (Shift+→)", cfg.seek_large_secs)).clicked() {
381	                self.seek_relative(cfg.seek_large_secs as f64);
382	            }
383	            ui.add_space(8.0);
384	            ui.label(RichText::new(time_label).monospace().color(theme::TEXT_DIM));
385	
386	            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
387	                ui.spacing_mut().item_spacing.x = 6.0;
388	                let fs_glyph = if self.fullscreen { icon::EXIT_FULLSCREEN } else { icon::FULLSCREEN };
389	                if theme::icon_button(ui, fs_glyph, 15.0, "Fullscreen (F)").clicked() {
390	                    self.fullscreen = !self.fullscreen;
391	                    ui.ctx().send_viewport_cmd(egui::ViewportCommand::Fullscreen(self.fullscreen));
392	                }
393	                let mixer_tip = if self.show_mixer { "Hide audio tracks".to_string() } else { format!("Show audio tracks ({})", self.track_count.max(1)) };
394	                let mresp = theme::icon_button(ui, icon::MIXER, 15.0, &mixer_tip);
395	                if self.show_mixer {
396	                    ui.painter().rect_stroke(mresp.rect, CornerRadius::same(20), Stroke::new(1.0, theme::TEXT_DIM), egui::StrokeKind::Inside);
397	                }
398	                if mresp.clicked() {
399	                    self.show_mixer = !self.show_mixer;
400	                }
401	                // Speed
402	                let speed = st.speed.max(0.01);
403	                egui::ComboBox::from_id_salt("speed")
404	                    .width(64.0)
405	                    .selected_text(format!("{}x", trim_float(speed)))
406	                    .show_ui(ui, |ui| {
407	                        for s in self.speeds {
408	                            if ui.selectable_label((speed - s).abs() < 0.01, format!("{}x", trim_float(s))).clicked() {
409	                                if let Some(m) = &self.mpv {
410	                                    let _ = m.set("speed", &s.to_string());
411	                                }
412	                            }
413	                        }
414	                    });
415	                // Volume
416	                let mut vol = self.volume;
417	                let r = ui.add(egui::Slider::new(&mut vol, 0.0..=1.5).show_value(false).trailing_fill(true));
418	                if r.changed() {
419	                    self.volume = vol;
420	                    self.muted = false;
421	                    self.apply_volume();
422	                }
423	                let vglyph = if self.muted || self.volume == 0.0 { icon::MUTE } else { icon::VOLUME };
424	                if theme::icon_button(ui, vglyph, 15.0, "Mute (M)").clicked() {
425	                    self.muted = !self.muted;
426	                    self.apply_volume();
427	                }
428	            });
