333	    /// Drain pending mpv events into `state`. Call once per frame.
334	    pub fn pump(&self) {
335	        loop {
336	            let ev = unsafe { &*(self.api.wait_event)(self.h, 0.0) };
337	            if ev.event_id == 0 {
338	                break;
339	            }
340	            let mut st = self.state.lock();
341	            match ev.event_id {
342	                EV_PROPERTY_CHANGE => unsafe {
343	                    let p = &*(ev.data as *const MpvEventProperty);
344	                    let name = CStr::from_ptr(p.name).to_string_lossy();
345	                    let has = !p.data.is_null();
346	                    let f = || if has { *(p.data as *const f64) } else { 0.0 };
347	                    let b = || has && *(p.data as *const c_int) != 0;
348	                    let i = || if has { *(p.data as *const i64) } else { 0 };
349	                    match name.as_ref() {
350	                        "time-pos" if p.format == FMT_DOUBLE => st.time_pos = f(),
351	                        "duration" if p.format == FMT_DOUBLE => st.duration = f(),
352	                        "pause" => st.paused = b(),
353	                        "eof-reached" => st.eof = b(),
354	                        "seeking" => st.seeking = b(),
355	                        "speed" if p.format == FMT_DOUBLE => st.speed = f(),
356	                        "idle-active" => st.idle = b(),
357	                        "width" => st.video_w = i(),
358	                        "height" => st.video_h = i(),
359	                        "demuxer-cache-time" if p.format == FMT_DOUBLE => st.cache_end = f(),
360	                        _ => {}
361	                    }
362	                },
363	                EV_FILE_LOADED => {
364	                    tracing::info!("mpv: file loaded");
365	                    st.loaded = true;
366	                    st.eof = false;
367	                    st.last_error = None;
368	                    st.file_generation += 1;
369	                }
370	                EV_END_FILE => {
371	                    // data: mpv_event_end_file { int reason; int error; ... }
372	                    unsafe {
373	                        if !ev.data.is_null() {
374	                            let reason = *(ev.data as *const c_int);
375	                            let err = *(ev.data as *const c_int).add(1);
376	                            tracing::info!("mpv: end file (reason {reason}, error {})", self.api.err(err));
377	                            if reason == 4 {
378	                                st.last_error = Some(self.api.err(err));
379	                                st.loaded = false;
380	                            }
381	                        }
382	                    }
383	                }
384	                EV_PLAYBACK_RESTART => st.seeking = false,
385	                EV_SHUTDOWN => break,
386	                _ => {}
387	            }
388	        }
389	        // Apply a debounced filter-string update (see `set_gains`).
390	        let due = {
391	            let p = self.pending_af.lock();
392	            p.as_ref().map(|(_, t)| t.elapsed() > std::time::Duration::from_millis(350)).unwrap_or(false)
393	        };
394	        if due {
395	            if let Some((af, _)) = self.pending_af.lock().take() {
396	                let _ = self.set("af", &af);
397	            }
398	        }
399	    }
400	
401	    /// Load a file. `tracks` is the known audio track count (0 = unknown).
402	    /// `exprs` = per-track gain expressions (see `cv_core::mixer::track_expr`).
403	    pub fn load(&self, path: &str, start: f64, tracks: usize, exprs: &[String], live: bool, pause: bool) -> Result<()> {
404	        {
405	            let mut st = self.state.lock();
406	            st.loaded = false;
407	            st.eof = false;
408	            st.time_pos = start;
409	            st.duration = 0.0;
410	            st.last_error = None;
411	        }
412	        *self.pending_af.lock() = None;
413	        let lc = cv_core::mixer::mpv_lavfi_complex(tracks).unwrap_or_default();
414	        self.set("lavfi-complex", &lc)?;
415	        self.set("af", &cv_core::mixer::mpv_af(exprs))?;
416	        self.set("pause", if pause { "yes" } else { "no" })?;
417	        let target = if live { format!("appending://{path}") } else { path.to_string() };
418	        let opts = format!("start={start:.3}");
419	        tracing::info!("mpv: loadfile {target} start={start:.1} tracks={tracks} live={live}");
420	        self.command(&["loadfile", &target, "replace", "-1", &opts])
421	    }
