585	impl Drop for Mpv {
586	    fn drop(&mut self) {
587	        unsafe {
588	            (self.api.set_wakeup_callback)(self.h, None, std::ptr::null_mut());
589	            let rr = self.render.lock();
590	            if !rr.ctx.is_null() {
591	                (self.api.rc_set_update_callback)(rr.ctx, None, std::ptr::null_mut());
592	            }
593	            drop(rr);
594	            (self.api.terminate_destroy)(self.h);
595	        }
596	    }
597	}
