373	pub fn status_block(ui: &mut Ui, connected: bool, status: Option<&cv_core::ipc::Status>) {
374	    let row = |ui: &mut Ui, color: Color32, text: &str| {
375	        ui.horizontal(|ui| {
376	            let (r, _) = ui.allocate_exact_size(Vec2::splat(10.0), Sense::hover());
377	            ui.painter().circle_filled(r.center(), 4.0, color);
378	            ui.label(RichText::new(text).size(12.5).color(theme::TEXT_DIM));
379	        });
380	    };
381	    let Some(s) = status.filter(|_| connected) else {
382	        row(ui, theme::WARNING, "Starting service…");
383	        return;
384	    };
385	    if !s.obs.running {
386	        row(ui, theme::DANGER, "OBS not running");
387	    } else if !s.obs.connected {
388	        row(ui, theme::WARNING, "Connecting to OBS…");
389	    } else if s.recording.active {
390	        let secs = (cv_core::util::now_ms() - s.recording.started_ms).max(0) / 1000;
391	        row(ui, theme::LIVE, &format!("Recording · {}", cv_core::util::format_span_short(secs)));
392	    } else if s.recording.paused_by_user {
393	        row(ui, theme::TEXT_FAINT, "24/7 paused");
394	    } else {
395	        row(ui, theme::WARNING, "Not recording");
396	    }
397	    let replay = if s.replay.active { theme::SUCCESS } else { theme::DANGER };
398	    row(ui, replay, if s.replay.active { "Replay buffer on" } else { "Replay buffer off" });
399	    let (mc, mt) = match s.mic.state.as_str() {
400	        "ok" => (theme::SUCCESS, "Mic OK"),
401	        "fallback" => (theme::WARNING, "Mic fallback"),
402	        "missing" => (theme::DANGER, "No mic"),
403	        "disabled" => (theme::TEXT_FAINT, "Mic guard off"),
404	        _ => (theme::TEXT_FAINT, "Mic…"),
405	    };
406	    row(ui, mc, mt);
407	}
