30	/// A stretch of playing one game (activity spans merged across short breaks).
31	#[derive(Debug, Clone, PartialEq)]
32	pub struct Session {
33	    pub name: String,
34	    pub game_id: Option<i64>,
35	    pub start_ms: i64,
36	    pub end_ms: i64,
37	}
38	
39	/// Group game activity into sessions: same game, breaks shorter than 10 min.
40	pub fn game_sessions(spans: &[ActivitySpan]) -> Vec<Session> {
41	    let mut out: Vec<Session> = Vec::new();
42	    let mut games: Vec<&ActivitySpan> = spans.iter().filter(|s| s.is_game).collect();
43	    games.sort_by_key(|s| s.start_ms);
44	    for s in games {
45	        if let Some(last) = out.iter_mut().rev().find(|x| x.game_id == s.game_id && x.name == s.name) {
46	            if s.start_ms - last.end_ms < 10 * MIN {
47	                last.end_ms = last.end_ms.max(s.end_ms);
48	                continue;
49	            }
50	        }
51	        out.push(Session { name: s.name.clone(), game_id: s.game_id, start_ms: s.start_ms, end_ms: s.end_ms });
52	    }
53	    out.retain(|x| x.end_ms - x.start_ms >= MIN);
54	    out.sort_by_key(|x| std::cmp::Reverse(x.start_ms));
55	    out
56	}
