228	    fn go_live(&mut self, c: &mut Ctx) {
229	        self.refresh(c);
230	        let t = now_ms() - c.cfg.player.live_offset_secs as i64 * 1000;
231	        self.follow_live = true;
232	        self.view_end = now_ms() + self.view_span / 20;
233	        self.play_at(c, t, true);
234	    }
