242	    fn save_edits_if_due(&mut self) {
243	        if let Some(t) = self.edits_dirty {
244	            if t.elapsed() > Duration::from_millis(800) {
245	                // Forget edits for footage that no longer exists.
246	                if let Some(oldest) = self.recs.iter().map(|r| r.start_ms).min() {
247	                    let cutoff = oldest as f64 / 1000.0;
248	                    self.edits.retain(|e| e.end > cutoff);
249	                }
250	                if let Ok(s) = serde_json::to_string(&self.edits) {
251	                    let _ = cv_core::util::write_atomic(&edits_file(), s.as_bytes());
252	                }
253	                self.edits_dirty = None;
254	            }
255	        }
256	    }
