373	    fn header(&mut self, ui: &mut Ui, c: &mut Ctx) {
374	        ui.horizontal(|ui| {
375	            ui.label(theme::heading("24/7 Recordings"));
376	            let total: f64 = self.recs.iter().filter(|r| !r.kept).map(|r| (Self::seg_end(r) - r.start_ms) as f64 / 1000.0).sum();
377	            ui.label(theme::label_dim(format!("{:.1} h stored · keeps {} h", total / 3600.0, c.cfg.recording.retention_hours)));
378	            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
379	                if theme::accent_button(ui, Some(icon::LIVE), "Go live", theme::LIVE).on_hover_text("Jump to what's being recorded right now").clicked() {
380	                    self.go_live(c);
381	                }
382	                ui.add_space(6.0);
383	                for (label, span) in [("All", 0i64), ("3d", 72 * HOUR), ("24h", 24 * HOUR), ("6h", 6 * HOUR), ("1h", HOUR), ("10m", 10 * MIN)] {
384	                    let span = if span == 0 {
385	                        let (a, b) = self.extent();
386	                        (b - a).max(HOUR) + HOUR / 2
387	                    } else {
388	                        span
389	                    };
390	                    let sel = (self.view_span - span).abs() < MIN;
391	                    if ui.add(egui::Button::selectable(sel, label)).clicked() {
392	                        let center = self.playhead(c).unwrap_or(self.view_end - self.view_span / 2);
393	                        self.view_span = span;
394	                        if label == "All" {
395	                            self.view_end = self.extent().1 + span / 40;
396	                            self.follow_live = false;
397	                        } else if self.follow_live {
398	                            self.view_end = now_ms() + span / 20;
399	                        } else {
400	                            self.view_end = center + span / 2;
401	                        }
402	                    }
403	                }
404	            });
405	        });
406	    }
