424	    fn timeline(&mut self, ui: &mut Ui, c: &mut Ctx) {
425	        let w = ui.available_width();
426	        let (row, _) = ui.allocate_exact_size(Vec2::new(w, 96.0), Sense::hover());
427	        let rect = lanes::axis_rect(row);
428	        let span = self.view_span.max(MIN);
429	        let start = self.view_end - span;
430	        let px_per_ms = rect.width() as f64 / span as f64;
431	        let x_of = |t: i64| rect.left() + ((t - start) as f64 * px_per_ms) as f32;
432	        let t_of = |x: f32| start + ((x - rect.left()) as f64 / px_per_ms) as i64;
433	
434	        // Gutter labels.
435	        let ruler = Rect::from_x_y_ranges(rect.x_range(), row.top()..=row.top() + 20.0);
436	        let seg_band = Rect::from_x_y_ranges(rect.x_range(), row.top() + 24.0..=row.top() + 54.0);
437	        let act_band = Rect::from_x_y_ranges(rect.x_range(), row.top() + 60.0..=row.top() + 80.0);
438	        let gp = ui.painter();
439	        let gx = row.left() + 10.0;
440	        gp.text(Pos2::new(gx, seg_band.center().y), Align2::LEFT_CENTER, "Recording", FontId::new(12.0, theme::semibold()), theme::TEXT_DIM);
441	        gp.text(Pos2::new(gx, act_band.center().y), Align2::LEFT_CENTER, "Activity", FontId::new(12.0, theme::semibold()), theme::TEXT_DIM);
442	        gp.text(Pos2::new(gx, act_band.bottom() + 9.0), Align2::LEFT_CENTER, "what was on screen", FontId::proportional(10.5), theme::TEXT_FAINT);
443	
444	        let p = ui.painter_at(rect.expand2(Vec2::new(lanes::AXIS_INSET, 0.0)));
445	        p.rect_filled(Rect::from_x_y_ranges(rect.x_range(), row.y_range()), CornerRadius::same(8), theme::SURFACE);
446	
447	        // Ticks.
448	        let steps = [MIN, 2 * MIN, 5 * MIN, 10 * MIN, 15 * MIN, 30 * MIN, HOUR, 2 * HOUR, 3 * HOUR, 6 * HOUR, 12 * HOUR, 24 * HOUR];
449	        let step = *steps.iter().find(|s| **s as f64 * px_per_ms >= 90.0).unwrap_or(&(24 * HOUR));
450	        let tz = Local.timestamp_millis_opt(start).single().map(|d| d.offset().local_minus_utc() as i64 * 1000).unwrap_or(0);
451	        let mut t = ((start + tz) / step) * step - tz;
452	        while t <= self.view_end {
453	            let x = x_of(t);
454	            if x >= rect.left() {
455	                let dt = Local.timestamp_millis_opt(t).single().unwrap_or_default();
456	                let midnight = dt.format("%H:%M").to_string() == "00:00";
457	                let label = if midnight || step >= 24 * HOUR { dt.format("%a %d").to_string() } else { dt.format("%H:%M").to_string() };
458	                p.line_segment([Pos2::new(x, ruler.bottom() - 4.0), Pos2::new(x, act_band.bottom())], Stroke::new(1.0, if midnight { theme::BORDER_STRONG } else { Color32::from_white_alpha(10) }));
459	                p.text(Pos2::new(x + 4.0, ruler.top() + 3.0), Align2::LEFT_TOP, label, FontId::proportional(11.0), if midnight { theme::TEXT_DIM } else { theme::TEXT_FAINT });
460	            }
461	            t += step;
462	        }
463	
464	        // Recording segments.
465	        for r in &self.recs {
466	            let (a, b) = (r.start_ms, Self::seg_end(r));
467	            if b < start || a > self.view_end {
468	                continue;
469	            }
470	            let sr = Rect::from_x_y_ranges(x_of(a).max(rect.left())..=x_of(b).min(rect.right()).max(x_of(a) + 1.0), seg_band.y_range());
471	            let fill = if r.kept { theme::blend(theme::SURFACE3, c.accent, 0.25) } else { theme::SURFACE3 };
472	            p.rect_filled(sr.shrink2(Vec2::new(0.5, 0.0)), CornerRadius::same(4), fill);
473	            if r.is_live() {
474	                p.rect_filled(Rect::from_x_y_ranges(sr.right() - 3.0..=sr.right(), sr.y_range()), CornerRadius::same(1), theme::LIVE);
475	            }
476	        }
477	        // Clips saved in this range (thin accent bars along the bottom of the band).
478	        for cl in &self.clips {
479	            let a = cl.source_start_ms.unwrap_or(cl.created_at - (cl.duration * 1000.0) as i64);
480	            let b = cl.created_at;
481	            if b < start || a > self.view_end {
482	                continue;
483	            }
484	            let cr = Rect::from_x_y_ranges(x_of(a).max(rect.left())..=x_of(b).max(x_of(a) + 2.0), seg_band.bottom() - 6.0..=seg_band.bottom() - 2.0);
485	            p.rect_filled(cr, CornerRadius::same(2), c.accent.gamma_multiply(0.85));
486	        }
487	        // Activity lane: which program was focused.
488	        if c.cfg.player.show_activity_on_timeline {
489	            for s in &self.spans {
490	                if s.end_ms < start || s.start_ms > self.view_end {
491	                    continue;
492	                }
493	                let x0 = x_of(s.start_ms).max(rect.left());
494	                let x1 = x_of(s.end_ms).min(rect.right());
495	                if x1 - x0 < 0.5 {
496	                    continue;
497	                }
498	                let color = if s.is_game { theme::game_color(s.game_id.unwrap_or(0)) } else { Color32::from_white_alpha(30) };
499	                let br = Rect::from_x_y_ranges(x0..=x1, act_band.y_range());
500	                p.rect_filled(br, CornerRadius::same(3), color);
501	                if x1 - x0 > 46.0 {
502	                    let text_color = if s.is_game { Color32::from_black_alpha(220) } else { theme::TEXT_DIM };
503	                    p.text(Pos2::new(x0 + 5.0, br.center().y), Align2::LEFT_CENTER, crate::views::clips::truncate(&s.name, ((x1 - x0) / 7.0) as usize), FontId::new(10.5, theme::semibold()), text_color);
504	                }
505	            }
506	        }
507	        // Selection.
508	        if let (Some(a), Some(b)) = (self.in_ms, self.out_ms) {
509	            let (a, b) = (a.min(b), a.max(b));
510	            let sr = Rect::from_x_y_ranges(x_of(a)..=x_of(b), seg_band.top() - 2.0..=act_band.bottom() + 2.0);
511	            p.rect_filled(sr, CornerRadius::same(4), c.accent.gamma_multiply(0.22));
512	            p.rect_stroke(sr, CornerRadius::same(4), Stroke::new(1.0, c.accent), egui::StrokeKind::Inside);
513	        }
514	        for (pt, label) in [(self.in_ms, "IN"), (self.out_ms, "OUT")] {
515	            if let Some(t) = pt {
516	                let x = x_of(t);
517	                p.line_segment([Pos2::new(x, seg_band.top() - 4.0), Pos2::new(x, act_band.bottom() + 4.0)], Stroke::new(2.0, c.accent));
518	                p.text(Pos2::new(x, row.bottom() - 2.0), Align2::CENTER_BOTTOM, label, FontId::new(9.0, theme::semibold()), c.accent);
519	            }
520	        }
521	        // Markers.
522	        for m in &self.markers {
523	            if m.at_ms < start || m.at_ms > self.view_end {
524	                continue;
525	            }
526	            let x = x_of(m.at_ms);
527	            let tri = vec![Pos2::new(x - 5.0, seg_band.top() - 6.0), Pos2::new(x + 5.0, seg_band.top() - 6.0), Pos2::new(x, seg_band.top() + 2.0)];
528	            p.add(egui::Shape::convex_polygon(tri, theme::WARNING, Stroke::NONE));
529	        }
530	        // Now + playhead (with a big grab handle).
531	        let nx = x_of(now_ms());
532	        if nx <= rect.right() {
533	            p.line_segment([Pos2::new(nx, seg_band.top() - 4.0), Pos2::new(nx, act_band.bottom())], Stroke::new(1.5, theme::LIVE));
534	        }
535	        if let Some(t) = self.playhead(c) {
536	            let x = x_of(t);
537	            p.line_segment([Pos2::new(x, ruler.bottom()), Pos2::new(x, act_band.bottom() + 4.0)], Stroke::new(2.0, Color32::WHITE));
538	            p.circle_filled(Pos2::new(x, ruler.bottom()), 7.0, Color32::WHITE);
539	        }
540	
541	        // Interaction: drag = scrub (drag the ruler or right-drag = pan),
542	        // wheel = zoom, Shift+wheel = pan, Shift+click = select.
543	        let resp = ui.interact(Rect::from_x_y_ranges(rect.x_range(), row.y_range()), ui.scope_id().with("timeline"), Sense::click_and_drag());
544	        if resp.drag_started() {
545	            let on_ruler = resp.interact_pointer_pos().map(|p| p.y <= ruler.bottom()).unwrap_or(false);
546	            let secondary = ui.input(|i| i.pointer.secondary_down() || i.pointer.middle_down());
547	            self.drag_mode = Some(if on_ruler || secondary { DragMode::Pan } else { DragMode::Scrub });
548	            if self.drag_mode == Some(DragMode::Scrub) {
549	                self.scrub_resume = !c.player.state().paused;
550	                if let Some(m) = &c.player.mpv {
551	                    m.set_pause(true);
552	                }
553	                c.player.scrubbing = true;
554	                self.follow_live = false;
555	            }
556	        }
557	        if resp.dragged() {
558	            match self.drag_mode {
559	                Some(DragMode::Pan) => {
560	                    self.view_end -= (resp.drag_delta().x as f64 / px_per_ms) as i64;
561	                    self.follow_live = false;
562	                }
563	                Some(DragMode::Scrub) => {
564	                    if let Some(pos) = resp.interact_pointer_pos() {
565	                        // Auto-pan when scrubbing past the edges.
566	                        if pos.x > rect.right() - 20.0 {
567	                            self.view_end += span / 60;
568	                        } else if pos.x < rect.left() + 20.0 {
569	                            self.view_end -= span / 60;
570	                        }
571	                        let t = t_of(pos.x.clamp(rect.left(), rect.right()));
572	                        self.scrub_to(c, t);
573	                    }
574	                }
575	                None => {}
576	            }
577	        }
578	        if resp.drag_stopped() {
579	            if self.drag_mode == Some(DragMode::Scrub) {
580	                if let Some(pos) = resp.interact_pointer_pos() {
581	                    let t = t_of(pos.x.clamp(rect.left(), rect.right()));
582	                    self.play_at(c, t.min(now_ms() - 2000), self.scrub_resume);
583	                }
584	                c.player.scrubbing = false;
585	            }
586	            self.drag_mode = None;
587	        }
588	        if let Some(pos) = resp.hover_pos() {
589	            let t = t_of(pos.x);
590	            let dt = Local.timestamp_millis_opt(t).single().unwrap_or_default();
591	            let mut tip = dt.format("%a %d %b %H:%M:%S").to_string();
592	            if let Some(s) = self.spans.iter().find(|s| s.start_ms <= t && s.end_ms >= t) {
593	                tip.push_str(&format!("\nOn screen: {}", s.name));
594	            }
595	            if let Some(m) = self.markers.iter().find(|m| (x_of(m.at_ms) - pos.x).abs() < 6.0) {
596	                tip.push_str(&format!("\nMarker{}", if m.label.is_empty() { String::new() } else { format!(": {}", m.label) }));
597	            }
598	            if !self.recs.iter().any(|r| r.start_ms <= t && Self::seg_end(r) >= t) {
599	                tip.push_str("\nNot recorded");
600	            }
601	            if self.drag_mode.is_none() {
602	                egui::Tooltip::always_open(ui.ctx().clone(), ui.layer_id(), egui::Id::unique("tl_tip"), egui::PopupAnchor::Pointer).show(|ui| ui.label(tip));
603	            }
604	            let (dx, dy) = ui.input(|i| (i.smooth_scroll_delta.x, i.smooth_scroll_delta.y));
605	            if dx.abs() > 0.1 {
606	                self.view_end -= (dx as f64 / px_per_ms) as i64;
607	                self.follow_live = false;
608	            } else if dy.abs() > 0.1 {
609	                let factor = (1.0 - dy as f64 * 0.0025).clamp(0.5, 2.0);
610	                let new_span = ((span as f64) * factor).clamp((2 * MIN) as f64, (30 * 24 * HOUR) as f64) as i64;
611	                let frac = (pos.x - rect.left()) as f64 / rect.width() as f64;
612	                let anchor = t_of(pos.x);
613	                self.view_end = anchor + ((1.0 - frac) * new_span as f64) as i64;
614	                self.view_span = new_span;
615	                if self.view_end < now_ms() {
616	                    self.follow_live = false;
617	                }
618	            }
619	        }
620	        if resp.clicked() {
621	            if let Some(pos) = resp.interact_pointer_pos() {
622	                let t = t_of(pos.x);
623	                if ui.input(|i| i.modifiers.shift) {
624	                    match (self.in_ms, self.out_ms) {
625	                        (Some(a), _) if t > a => self.out_ms = Some(t),
626	                        _ => self.in_ms = Some(t),
627	                    }
628	                } else {
629	                    self.play_at(c, t.min(now_ms() - 2000), true);
630	                }
631	            }
632	        }
633	        let resp = resp.on_hover_cursor(egui::CursorIcon::PointingHand);
634	        resp.context_menu(|ui| {
635	            if ui.button("Add marker at playhead").clicked() {
636	                if let (Some(t), Some(db)) = (self.playhead(c), c.db()) {
637	                    let _ = db.add_marker(t, "");
638	                }
639	                self.dirty = true;
640	                ui.close();
641	            }
642	            if ui.button("Clear selection").clicked() {
643	                self.in_ms = None;
644	                self.out_ms = None;
645	                ui.close();
646	            }
647	        });
648	        ui.horizontal(|ui| {
649	            ui.add_space(GUTTER + lanes::AXIS_INSET);
650	            ui.label(theme::small("Drag to scrub · drag the time ruler to pan · scroll to zoom · Shift+scroll to pan · Shift+click or I / O to select"));
651	        });
652	    }
653	
654	    fn audio_lanes(&mut self, ui: &mut Ui, c: &mut Ctx) {
655	        let span = self.view_span.max(MIN);
656	        let t0 = (self.view_end - span) as f64 / 1000.0;
657	        let t1 = self.view_end as f64 / 1000.0;
658	        // Waveforms for every visible recording file.
659	        let visible: Vec<(String, f64, f64)> = self
660	            .recs
661	            .iter()
662	            .filter(|r| Self::seg_end(r) as f64 / 1000.0 > t0 && (r.start_ms as f64 / 1000.0) < t1)
663	            .map(|r| (r.path.clone(), r.start_ms as f64 / 1000.0, Self::seg_end(r) as f64 / 1000.0))
664	            .collect();
665	        let mut owned = Vec::new();
