949	/// Merge consecutive activity spans of the same program separated by short
950	/// gaps (alt-tab blips) so the lane reads cleanly.
951	fn merge_spans(mut spans: Vec<ActivitySpan>) -> Vec<ActivitySpan> {
952	    spans.sort_by_key(|s| s.start_ms);
953	    let mut out: Vec<ActivitySpan> = Vec::with_capacity(spans.len());
954	    for s in spans {
955	        if let Some(last) = out.last_mut() {
956	            if last.key == s.key && s.start_ms - last.end_ms < 15_000 {
957	                last.end_ms = last.end_ms.max(s.end_ms);
958	                continue;
959	            }
960	            // Fill tiny gaps between different programs too.
961	            if s.start_ms - last.end_ms < 3_000 && s.start_ms > last.end_ms {
962	                last.end_ms = s.start_ms;
963	            }
964	        }
965	        out.push(s);
966	    }
967	    out
968	}
