1	//! Audio lanes: one row per audio track under the timeline, showing the
2	//! waveform, a mute button and a volume slider. Drag across a lane to select
3	//! part of it, then mute it or make it louder. Edits are non-destructive: they
4	//! are stored as metadata and applied during playback/export only.
5	
6	use crate::player::{MixMode, Player};
7	use crate::theme::{self, icon};
8	use cv_core::model::AudioEdit;
9	use cv_core::waveform::{wave_path, Waveform};
10	use eframe::egui::{self, Align2, Color32, CornerRadius, FontId, Pos2, Rect, RichText, Sense, Stroke, Ui, Vec2};
11	use std::collections::HashMap;
12	use std::path::Path;
13	use std::time::{Duration, Instant, SystemTime};
14	
15	/// Width of the label column left of lanes (and of the timeline).
16	pub const GUTTER: f32 = 196.0;
17	/// Inset of the time axis inside the area right of the gutter.
18	pub const AXIS_INSET: f32 = 8.0;
19	const LANE_H: f32 = 40.0;
20	
21	/// The time-axis rectangle for a full-width row rect.
22	pub fn axis_rect(row: Rect) -> Rect {
23	    Rect::from_x_y_ranges(row.left() + GUTTER + AXIS_INSET..=row.right() - AXIS_INSET, row.y_range())
24	}
25	
26	/// A waveform placed on the lane time axis (`start`..`end` in axis units).
27	pub struct WaveSource<'a> {
28	    pub start: f64,
29	    pub end: f64,
30	    pub wave: &'a Waveform,
31	}
32	
33	/// Caches waveform files by media path, reloading when the service updates them.
34	#[derive(Default)]
35	pub struct Waves {
36	    map: HashMap<String, (Option<Waveform>, Option<SystemTime>, Instant)>,
37	}
38	
39	impl Waves {
40	    pub fn get(&mut self, media: &str) -> Option<&Waveform> {
41	        let now = Instant::now();
42	        let stale = self.map.get(media).map(|(_, _, t)| now.duration_since(*t) > Duration::from_secs(5)).unwrap_or(true);
43	        if stale {
44	            let wp = wave_path(Path::new(media));
45	            let mtime = std::fs::metadata(&wp).and_then(|m| m.modified()).ok();
46	            let entry = self.map.entry(media.to_string()).or_insert((None, None, now));
47	            if entry.1 != mtime || (entry.0.is_none() && mtime.is_some()) {
48	                entry.0 = mtime.and_then(|_| Waveform::load(&wp).ok());
49	                entry.1 = mtime;
50	            }
51	            entry.2 = now;
52	        }
53	        self.map.get(media).and_then(|(w, _, _)| w.as_ref())
54	    }
55	}
56	
57	#[derive(Default)]
58	pub struct LaneState {
59	    /// Selected range: (track, start, end) in axis units.
60	    pub sel: Option<(usize, f64, f64)>,
61	    drag: Option<(usize, f64)>,
62	    /// Resizing an existing edit: (track, start, end, gain, dragging the left edge?).
63	    resize: Option<(usize, f64, f64, f32, bool)>,
64	    pub all_tracks: bool,
65	    pub custom_pct: f32,
66	}
67	
68	pub enum LaneAction {
69	    Seek(f64),
70	    /// Apply `gain` to `[a, b)` on these tracks (1.0 = remove edits there).
71	    Edit { tracks: Vec<usize>, a: f64, b: f64, gain: f32 },
72	    /// A track volume or the mix mode changed (persist the mix).
73	    MixChanged,
74	}
75	
76	fn gain_label(g: f32) -> String {
77	    if g <= 0.0005 {
78	        "Muted".into()
79	    } else {
80	        let db = 20.0 * g.log10();
81	        if db >= 0.0 {
82	            format!("+{db:.0} dB")
83	        } else {
84	            format!("{db:.0} dB")
85	        }
86	    }
87	}
88	
89	fn fmt_time(t: f64, wall: bool) -> String {
90	    if wall {
91	        chrono::DateTime::from_timestamp_millis((t * 1000.0) as i64)
92	            .map(|d| d.with_timezone(&chrono::Local).format("%H:%M:%S").to_string())
93	            .unwrap_or_default()
94	    } else {
95	        cv_core::util::format_duration_precise(t)
96	    }
97	}
98	
99	/// Draw the lanes. `t0..t1` is the visible range in axis units; `wall` says
100	/// the axis is wall-clock seconds (24/7 view) rather than file seconds.
101	#[allow(clippy::too_many_arguments)]
102	pub fn lanes(
103	    ui: &mut Ui,
104	    player: &mut Player,
105	    t0: f64,
106	    t1: f64,
107	    wall: bool,
108	    sources: &[WaveSource],
109	    edits: &[AudioEdit],
110	    playhead: Option<f64>,
111	    st: &mut LaneState,
112	    accent: Color32,
113	) -> Vec<LaneAction> {
114	    let mut actions = Vec::new();
115	    let n = player.track_count;
116	    if st.custom_pct == 0.0 {
117	        st.custom_pct = 150.0;
118	    }
119	
120	    // Header: mode switch and help.
121	    ui.horizontal(|ui| {
122	        ui.add_space(4.0);
123	        ui.label(RichText::new("Audio tracks").font(FontId::new(14.0, theme::semibold())).color(theme::TEXT));
124	        if n > 1 {
125	            ui.add_space(8.0);
126	            let full = player.mode == MixMode::Full;
127	            if ui.add(egui::Button::selectable(full, "Full mix")).on_hover_text("Play everything you heard plus your mic (track 1)").clicked() && !full {
128	                player.set_mode(MixMode::Full);
129	                actions.push(LaneAction::MixChanged);
130	            }
131	            if ui.add(egui::Button::selectable(!full, "Separate tracks")).on_hover_text("Play game, voice, music and mic separately so you can balance them").clicked() && full {
132	                player.set_mode(MixMode::Separate);
133	                actions.push(LaneAction::MixChanged);
134	            }
135	        }
136	        ui.add_space(10.0);
137	        ui.label(theme::small(if n > 1 {
138	            "Drag across a track to select part of it, then mute it or make it louder. Drag an edit's edge to resize it. The recording itself is never changed."
139	        } else {
140	            "This file has a single audio track. Recordings made since the upgrade have separate tracks."
141	        }));
142	    });
143	
144	    // Selection toolbar.
145	    if let Some((tr, a, b)) = st.sel {
146	        ui.horizontal(|ui| {
147	            ui.add_space(4.0);
148	            let name = if st.all_tracks { "all tracks".to_string() } else { player.track_names.get(tr).cloned().unwrap_or_default() };
149	            ui.label(RichText::new(format!("{}–{} on {}", fmt_time(a, wall), fmt_time(b, wall), name)).color(theme::TEXT));
150	            let tracks: Vec<usize> = if st.all_tracks { (0..n).collect() } else { vec![tr] };
151	            let apply = |gain: f32, actions: &mut Vec<LaneAction>| actions.push(LaneAction::Edit { tracks: tracks.clone(), a, b, gain });
152	            if ui.button("Mute").clicked() {
153	                apply(0.0, &mut actions);
154	            }
155	            if ui.button("Quieter (−6 dB)").clicked() {
156	                apply(0.5, &mut actions);
157	            }
158	            if ui.button("Louder (+6 dB)").clicked() {
159	                apply(2.0, &mut actions);
160	            }
161	            ui.add(egui::DragValue::new(&mut st.custom_pct).range(0.0..=400.0).suffix("%").speed(1.0));
162	            if ui.button("Set").on_hover_text("Set this part to the exact volume").clicked() {
163	                apply(st.custom_pct / 100.0, &mut actions);
164	            }
165	            if ui.button("Reset").on_hover_text("Remove edits in this part").clicked() {
166	                apply(1.0, &mut actions);
167	            }
