297	        // An edit edge under the pointer (for resizing).
298	        let edge_at = |x: f32| -> Option<(f64, f64, f32, bool)> {
299	            edits.iter().filter(|e| e.track == i).find_map(|e| {
300	                if (x - x_of(e.start)).abs() <= 5.0 {
