310	        if resp.drag_started() {
311	            if let Some(pos) = resp.interact_pointer_pos() {
312	                match edge_at(pos.x) {
313	                    Some((a, b, g, left)) => st.resize = Some((i, a, b, g, left)),
314	                    None => st.drag = Some((i, t_of(pos.x))),
315	                }
316	            }
317	        }
318	        if resp.dragged() {
319	            if let Some(pos) = resp.interact_pointer_pos() {
320	                let t = t_of(pos.x.clamp(wave_area.left(), wave_area.right()));
321	                if let Some((tr, a, b, _, left)) = st.resize {
322	                    let (na, nb) = if left { (t.min(b - 0.05), b) } else { (a, t.max(a + 0.05)) };
