1	//! The 24/7 view: a zoomable wall-clock timeline across all recording files
2	//! with an activity lane (what was focused), markers and clips, audio lanes
3	//! with non-destructive region edits, live playback and clip-from-range.
4	
5	use crate::app::Ctx;
6	use crate::lanes::{self, LaneAction, LaneState, WaveSource, GUTTER};
7	use crate::theme::{self, icon};
8	use chrono::{Local, TimeZone};
9	use cv_core::ipc::Request;
10	use cv_core::model::{apply_edit, ActivitySpan, AudioEdit, Category, Clip, Game, Marker, Recording};
11	use cv_core::timeline::{locate, Segment};
12	use cv_core::util::{format_duration, human_bytes, now_ms};
13	use eframe::egui::{self, Align2, Color32, CornerRadius, FontId, Margin, Pos2, Rect, RichText, Sense, Stroke, Ui, Vec2};
14	use std::path::PathBuf;
15	use std::sync::atomic::{AtomicBool, Ordering};
16	use std::time::{Duration, Instant};
17	
18	static GO_LIVE: AtomicBool = AtomicBool::new(false);
19	static PLAY_AT: std::sync::atomic::AtomicI64 = std::sync::atomic::AtomicI64::new(0);
20	
21	pub fn request_go_live() {
22	    GO_LIVE.store(true, Ordering::SeqCst);
23	}
24	
25	/// Ask the 24/7 view to show and play a wall-clock moment (Unix ms).
26	pub fn request_play_at(ms: i64) {
27	    PLAY_AT.store(ms, Ordering::SeqCst);
28	}
29	
30	/// A stretch of playing one game (activity spans merged across short breaks).
31	#[derive(Debug, Clone, PartialEq)]
32	pub struct Session {
33	    pub name: String,
34	    pub game_id: Option<i64>,
35	    pub start_ms: i64,
36	    pub end_ms: i64,
37	}
38	
39	/// Group game activity into sessions: same game, breaks shorter than 10 min.
40	pub fn game_sessions(spans: &[ActivitySpan]) -> Vec<Session> {
41	    let mut out: Vec<Session> = Vec::new();
42	    let mut games: Vec<&ActivitySpan> = spans.iter().filter(|s| s.is_game).collect();
43	    games.sort_by_key(|s| s.start_ms);
44	    for s in games {
45	        if let Some(last) = out.iter_mut().rev().find(|x| x.game_id == s.game_id && x.name == s.name) {
46	            if s.start_ms - last.end_ms < 10 * MIN {
47	                last.end_ms = last.end_ms.max(s.end_ms);
48	                continue;
49	            }
50	        }
51	        out.push(Session { name: s.name.clone(), game_id: s.game_id, start_ms: s.start_ms, end_ms: s.end_ms });
52	    }
53	    out.retain(|x| x.end_ms - x.start_ms >= MIN);
54	    out.sort_by_key(|x| std::cmp::Reverse(x.start_ms));
55	    out
56	}
57	
58	const MIN: i64 = 60_000;
59	const HOUR: i64 = 3_600_000;
60	
61	struct CutDialog {
62	    title: String,
63	    game_id: Option<i64>,
64	    cats: Vec<i64>,
65	    precise: bool,
66	}
67	
68	#[derive(Clone, Copy, PartialEq)]
69	enum DragMode {
70	    Scrub,
71	    Pan,
72	}
73	
74	#[derive(Default)]
75	pub struct RecordingsView {
76	    recs: Vec<Recording>,
77	    spans: Vec<ActivitySpan>,
78	    markers: Vec<Marker>,
79	    clips: Vec<Clip>,
80	    games: Vec<Game>,
81	    cats: Vec<Category>,
82	    dirty: bool,
83	    loaded: Option<Instant>,
84	    view_end: i64,
85	    view_span: i64,
86	    follow_live: bool,
87	    cur: Option<usize>,
88	    cur_path: Option<String>,
89	    in_ms: Option<i64>,
90	    out_ms: Option<i64>,
91	    dialog: Option<CutDialog>,
92	    init: bool,
93	    rename_marker: Option<(i64, String)>,
94	    drag_mode: Option<DragMode>,
95	    scrub_resume: bool,
96	    last_scrub: Option<Instant>,
97	    /// Non-destructive edits on the 24/7 timeline (wall-clock seconds).
98	    edits: Vec<AudioEdit>,
99	    edits_dirty: Option<Instant>,
100	    lane_state: LaneState,
101	    /// Playhead when the player was last showing our file.
102	    resume_ms: Option<i64>,
103	}
104	
105	fn edits_file() -> PathBuf {
106	    cv_core::paths::data_dir().join("timeline_edits.json")
107	}
108	
109	impl RecordingsView {
110	    pub fn mark_dirty(&mut self) {
111	        self.dirty = true;
112	    }
113	
114	    fn refresh(&mut self, c: &mut Ctx) {
115	        let stale = self.loaded.map(|t| t.elapsed() > Duration::from_secs(10)).unwrap_or(true);
116	        if !(self.dirty || stale) {
117	            return;
118	        }
119	        if let Some(db) = c.db() {
120	            self.recs = db.list_recordings().unwrap_or_default();
121	            let (from, to) = self.extent();
122	            self.spans = merge_spans(db.activity_between(from - HOUR, to + HOUR).unwrap_or_default());
123	            self.markers = db.markers_between(from - HOUR, to + HOUR).unwrap_or_default();
124	            self.clips = db.clips_between(from - HOUR, to + HOUR).unwrap_or_default();
125	            self.games = db.list_games().unwrap_or_default();
126	            self.cats = db.list_categories().unwrap_or_default();
127	        }
128	        if let Some(p) = &self.cur_path {
129	            self.cur = self.recs.iter().position(|r| &r.path == p);
130	        }
131	        self.loaded = Some(Instant::now());
132	        self.dirty = false;
133	    }
134	
135	    fn seg_end(r: &Recording) -> i64 {
136	        if r.is_live() {
137	            now_ms()
138	        } else {
139	            r.start_ms + (r.duration.max(0.0) * 1000.0) as i64
140	        }
141	    }
142	
143	    fn extent(&self) -> (i64, i64) {
144	        let start = self.recs.iter().map(|r| r.start_ms).min().unwrap_or(now_ms() - 6 * HOUR);
145	        let end = self.recs.iter().map(Self::seg_end).max().unwrap_or(now_ms()).max(now_ms());
146	        (start, end)
147	    }
148	
149	    fn segments(&self) -> Vec<Segment> {
150	        self.recs
151	            .iter()
152	            .map(|r| Segment { path: PathBuf::from(&r.path), start_ms: r.start_ms, duration_ms: Self::seg_end(r) - r.start_ms, live: r.is_live() })
153	            .collect()
154	    }
155	
156	    fn playhead(&self, c: &Ctx) -> Option<i64> {
157	        let i = self.cur?;
158	        let r = self.recs.get(i)?;
159	        Some(r.start_ms + (c.player.state().time_pos * 1000.0) as i64)
160	    }
161	
162	    fn tracks_for(&self, c: &Ctx, r: &Recording) -> usize {
163	        if r.audio_tracks > 0 {
164	            r.audio_tracks as usize
165	        } else if r.is_live() {
166	            c.service.status().map(|s| s.recording.tracks as usize).unwrap_or(0)
167	        } else {
168	            0
169	        }
170	    }
171	
172	    /// Edits for the loaded segment, in that file's time.
173	    fn segment_edits(&self) -> Vec<AudioEdit> {
174	        let Some(r) = self.cur.and_then(|i| self.recs.get(i)) else { return Vec::new() };
175	        let s0 = r.start_ms as f64 / 1000.0;
176	        let s1 = Self::seg_end(r) as f64 / 1000.0 + 3600.0; // live files keep growing
177	        self.edits
178	            .iter()
179	            .filter(|e| e.overlaps(s0, s1))
180	            .map(|e| AudioEdit { track: e.track, start: e.start - s0, end: e.end - s0, gain: e.gain })
181	            .collect()
182	    }
183	
184	    /// Start playing at wall-clock time `t`.
185	    fn play_at(&mut self, c: &mut Ctx, t: i64, autoplay: bool) {
186	        let segs = self.segments();
187	        let Some(loc) = locate(&segs, t) else {
188	            c.toast("info", "Nothing was recorded at that time");
189	            return;
190	        };
191	        let rec = self.recs[loc.index].clone();
192	        let offset = loc.offset_ms as f64 / 1000.0;
193	        let same = self.cur == Some(loc.index) && c.player.path.as_deref() == Some(rec.path.as_str()) && c.player.state().loaded;
194	        let mpv_dur = c.player.state().duration;
195	        self.cur = Some(loc.index);
196	        self.cur_path = Some(rec.path.clone());
197	        if same && !(rec.is_live() && offset > mpv_dur - 1.0) {
198	            c.player.seek(offset, true);
199	            if autoplay {
200	                if let Some(m) = &c.player.mpv {
201	                    m.set_pause(false);
202	                }
203	            }
204	        } else {
205	            let tracks = self.tracks_for(c, &rec);
206	            c.player.edits = self.segment_edits();
207	            c.player.path = None; // force reload (live files need a fresh duration)
208	            c.player.open(&rec.path, offset, tracks, &[], None, rec.is_live(), autoplay, &c.cfg.player);
209	        }
210	    }
211	
212	    /// Fast seek while dragging the playhead.
213	    fn scrub_to(&mut self, c: &mut Ctx, t: i64) {
214	        let segs = self.segments();
215	        let Some(loc) = locate(&segs, t.min(now_ms() - 2000)) else { return };
216	        let throttle = self.last_scrub.map(|i| i.elapsed() < Duration::from_millis(45)).unwrap_or(false);
217	        if self.cur == Some(loc.index) && c.player.state().loaded {
218	            if !throttle {
219	                c.player.seek(loc.offset_ms as f64 / 1000.0, false);
220	                self.last_scrub = Some(Instant::now());
221	            }
222	        } else if !throttle {
223	            self.play_at(c, t, false);
224	            self.last_scrub = Some(Instant::now());
225	        }
226	    }
227	
228	    fn go_live(&mut self, c: &mut Ctx) {
229	        self.refresh(c);
230	        let t = now_ms() - c.cfg.player.live_offset_secs as i64 * 1000;
231	        self.follow_live = true;
232	        self.view_end = now_ms() + self.view_span / 20;
233	        self.play_at(c, t, true);
234	    }
235	
236	    fn load_edits(&mut self) {
237	        if let Ok(text) = std::fs::read_to_string(edits_file()) {
238	            self.edits = serde_json::from_str(&text).unwrap_or_default();
239	        }
240	    }
241	
242	    fn save_edits_if_due(&mut self) {
243	        if let Some(t) = self.edits_dirty {
244	            if t.elapsed() > Duration::from_millis(800) {
245	                // Forget edits for footage that no longer exists.
246	                if let Some(oldest) = self.recs.iter().map(|r| r.start_ms).min() {
247	                    let cutoff = oldest as f64 / 1000.0;
248	                    self.edits.retain(|e| e.end > cutoff);
249	                }
250	                if let Ok(s) = serde_json::to_string(&self.edits) {
251	                    let _ = cv_core::util::write_atomic(&edits_file(), s.as_bytes());
252	                }
253	                self.edits_dirty = None;
254	            }
255	        }
256	    }
257	
258	    pub fn ui(&mut self, ui: &mut Ui, c: &mut Ctx) {
259	        if !self.init {
260	            self.init = true;
261	            self.view_span = c.cfg.player.timeline_hours as i64 * HOUR;
262	            self.view_end = now_ms() + self.view_span / 20;
263	            self.follow_live = true;
264	            self.dirty = true;
265	            self.load_edits();
266	            if c.player.track_count == 0 {
267	                c.player.show_mixer = true;
268	            }
269	        }
270	        self.refresh(c);
271	        self.save_edits_if_due();
272	        // The player is shared with the clip view: take it back if needed.
273	        if let Some(p) = self.cur_path.clone() {
274	            if c.player.path.as_deref() == Some(p.as_str()) {
275	                self.resume_ms = self.playhead(c);
276	            } else if let Some(t) = self.resume_ms.take() {
277	                self.play_at(c, t, false);
278	            } else {
279	                self.cur = None;
280	                self.cur_path = None;
281	            }
282	        }
283	        if GO_LIVE.swap(false, Ordering::SeqCst) {
284	            self.go_live(c);
285	        }
286	        let jump = PLAY_AT.swap(0, Ordering::SeqCst);
287	        if jump != 0 {
288	            self.refresh(c);
289	            self.follow_live = false;
290	            self.view_end = jump + self.view_span / 2;
291	            self.play_at(c, jump, true);
292	        }
293	        // Auto-advance to the next file at the end of a segment.
294	        let st = c.player.state();
295	        if let Some(i) = self.cur {
296	            if st.eof && st.loaded && i + 1 < self.recs.len() && c.player.path.is_some() && self.drag_mode.is_none() {
297	                let next = self.recs[i + 1].start_ms;
298	                self.play_at(c, next, true);
299	            }
300	        }
301	        // Keep the player's edits in sync with the timeline's.
302	        if self.cur.is_some() {
303	            let e = self.segment_edits();
304	            c.player.set_edits(e);
305	        }
306	        if self.follow_live {
307	            let target = now_ms() + self.view_span / 20;
308	            if (target - self.view_end).abs() > 500 {
309	                self.view_end = target;
310	            }
311	            ui.ctx().request_repaint_after(Duration::from_millis(500));
312	        }
313	
314	        let hits = c.player.shortcuts(ui, &c.cfg.player);
315	        if hits.mark_in {
316	            self.in_ms = self.playhead(c);
317	        }
318	        if hits.mark_out {
319	            self.out_ms = self.playhead(c);
320	        }
321	
322	        let fullscreen = c.player.fullscreen;
323	        if !fullscreen {
324	            self.header(ui, c);
325	            ui.add_space(10.0);
326	            egui::Panel::right("rec_side")
327	                .exact_size(330.0)
328	                .resizable(false)
329	                .frame(egui::Frame::NONE.inner_margin(Margin { left: 18, right: 0, top: 0, bottom: 0 }))
330	                .show(ui, |ui| {
331	                    egui::ScrollArea::vertical().id_salt("rec_side_scroll").auto_shrink(false).show(ui, |ui| {
332	                        ui.set_max_width(ui.available_width());
333	                        self.side(ui, c);
334	                    });
335	                });
336	        }
337	
338	        if self.recs.is_empty() {
339	            ui.add_space(60.0);
340	            ui.vertical_centered(|ui| {
341	                ui.label(theme::icon_text(icon::HISTORY, 40.0).color(theme::TEXT_FAINT));
342	                ui.label(theme::title("No recordings yet"));
343	                ui.label(theme::label_dim("Once OBS is recording, everything shows up here."));
344	            });
345	            return;
346	        }
347	
348	        // Controls live in a bottom panel so they're never pushed off screen;
349	        // the video gets whatever space is left.
350	        let bottom_margin = if fullscreen { Margin::symmetric(16, 8) } else { Margin::ZERO };
351	        egui::Panel::bottom("rec_controls")
352	            .resizable(false)
353	            .frame(egui::Frame::NONE.inner_margin(bottom_margin).fill(if fullscreen { theme::BG } else { Color32::TRANSPARENT }))
354	            .show(ui, |ui| {
355	                ui.add_space(6.0);
356	                self.timeline(ui, c);
357	                if c.player.show_mixer && !fullscreen {
358	                    ui.add_space(4.0);
359	                    self.audio_lanes(ui, c);
360	                }
361	                let label = self.time_label(c);
362	                c.player.transport(ui, &label, &c.cfg.player);
363	                if !fullscreen {
364	                    self.cut_bar(ui, c);
365	                }
366	            });
367	        let avail = ui.available_size();
368	        let h = if fullscreen { avail.y } else { (avail.x * 9.0 / 16.0).min(avail.y).max(120.0) };
369	        c.player.video(ui, Vec2::new(avail.x, h));
370	        self.cut_dialog(ui, c);
371	    }
372	
373	    fn header(&mut self, ui: &mut Ui, c: &mut Ctx) {
374	        ui.horizontal(|ui| {
375	            ui.label(theme::heading("24/7 Recordings"));
376	            let total: f64 = self.recs.iter().filter(|r| !r.kept).map(|r| (Self::seg_end(r) - r.start_ms) as f64 / 1000.0).sum();
377	            ui.label(theme::label_dim(format!("{:.1} h stored · keeps {} h", total / 3600.0, c.cfg.recording.retention_hours)));
378	            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
379	                if theme::accent_button(ui, Some(icon::LIVE), "Go live", theme::LIVE).on_hover_text("Jump to what's being recorded right now").clicked() {
380	                    self.go_live(c);
381	                }
382	                ui.add_space(6.0);
383	                for (label, span) in [("All", 0i64), ("3d", 72 * HOUR), ("24h", 24 * HOUR), ("6h", 6 * HOUR), ("1h", HOUR), ("10m", 10 * MIN)] {
384	                    let span = if span == 0 {
385	                        let (a, b) = self.extent();
386	                        (b - a).max(HOUR) + HOUR / 2
387	                    } else {
388	                        span
389	                    };
390	                    let sel = (self.view_span - span).abs() < MIN;
391	                    if ui.add(egui::Button::selectable(sel, label)).clicked() {
392	                        let center = self.playhead(c).unwrap_or(self.view_end - self.view_span / 2);
393	                        self.view_span = span;
394	                        if label == "All" {
395	                            self.view_end = self.extent().1 + span / 40;
396	                            self.follow_live = false;
397	                        } else if self.follow_live {
398	                            self.view_end = now_ms() + span / 20;
399	                        } else {
400	                            self.view_end = center + span / 2;
401	                        }
402	                    }
403	                }
