408	    fn time_label(&self, c: &Ctx) -> String {
409	        match self.playhead(c) {
410	            Some(t) => {
411	                let dt = Local.timestamp_millis_opt(t).single().unwrap_or_default();
412	                let behind = (now_ms() - t) / 1000;
413	                let live = self.cur.and_then(|i| self.recs.get(i)).map(|r| r.is_live()).unwrap_or(false);
414	                if live && behind < 30 {
415	                    format!("{}  ·  LIVE", dt.format("%a %d %b  %H:%M:%S"))
416	                } else {
417	                    format!("{}  ·  {} ago", dt.format("%a %d %b  %H:%M:%S"), cv_core::util::format_span_short(behind))
418	                }
419	            }
420	            None => "Click the timeline or Go live".into(),
421	        }
422	    }
