654	    fn audio_lanes(&mut self, ui: &mut Ui, c: &mut Ctx) {
655	        let span = self.view_span.max(MIN);
656	        let t0 = (self.view_end - span) as f64 / 1000.0;
657	        let t1 = self.view_end as f64 / 1000.0;
658	        // Waveforms for every visible recording file.
659	        let visible: Vec<(String, f64, f64)> = self
660	            .recs
661	            .iter()
662	            .filter(|r| Self::seg_end(r) as f64 / 1000.0 > t0 && (r.start_ms as f64 / 1000.0) < t1)
663	            .map(|r| (r.path.clone(), r.start_ms as f64 / 1000.0, Self::seg_end(r) as f64 / 1000.0))
664	            .collect();
665	        let mut owned = Vec::new();
666	        for (path, a, b) in &visible {
667	            if let Some(w) = c.waves.get(path) {
668	                owned.push((w.clone(), *a, *b));
669	            }
670	        }
671	        let sources: Vec<WaveSource> = owned.iter().map(|(w, a, b)| WaveSource { start: *a, end: *b, wave: w }).collect();
672	        let playhead = self.playhead(c).map(|t| t as f64 / 1000.0);
673	        let acts = lanes::lanes(ui, &mut c.player, t0, t1, true, &sources, &self.edits, playhead, &mut self.lane_state, c.accent);
674	        for a in acts {
675	            match a {
676	                LaneAction::Seek(t) => self.play_at(c, (t * 1000.0) as i64, !c.player.state().paused),
677	                LaneAction::Edit { tracks, a, b, gain } => {
678	                    for tr in &tracks {
679	                        apply_edit(&mut self.edits, *tr, a, b, gain);
680	                    }
681	                    if tracks.iter().any(|t| *t > 0) && c.player.mode == crate::player::MixMode::Full && gain != 1.0 {
682	                        c.player.set_mode(crate::player::MixMode::Separate);
683	                        c.toast("info", "Switched to separate tracks so the edit is audible");
684	                    }
685	                    self.edits_dirty = Some(Instant::now());
686	                    let e = self.segment_edits();
687	                    c.player.set_edits(e);
688	                }
689	                LaneAction::MixChanged => {}
690	            }
691	        }
692	    }
