738	    fn cut_dialog(&mut self, ui: &mut Ui, c: &mut Ctx) {
739	        let Some(d) = &mut self.dialog else { return };
740	        let (a, b) = match (self.in_ms, self.out_ms) {
741	            (Some(a), Some(b)) => (a.min(b), a.max(b)),
742	            _ => {
743	                self.dialog = None;
744	                return;
745	            }
746	        };
747	        let (a_s, b_s) = (a as f64 / 1000.0, b as f64 / 1000.0);
748	        let edits_in: Vec<AudioEdit> = self.edits.iter().filter(|e| e.overlaps(a_s, b_s)).copied().collect();
749	        let mut close = false;
