755	            ui.label(theme::label_dim(format!("{} · {}", from.format("%a %d %b %H:%M:%S"), format_duration((b - a) as f64 / 1000.0))));
756	            ui.add_space(8.0);
757	            ui.label("Title");
758	            ui.add(egui::TextEdit::singleline(&mut d.title).hint_text("Automatic (game + date)").desired_width(f32::INFINITY));
759	            ui.add_space(4.0);
760	            ui.label("Game");
761	            let name = d.game_id.and_then(|g| self.games.iter().find(|x| x.id == g)).map(|g| g.name.clone()).unwrap_or_else(|| "Detect automatically".into());
762	            egui::ComboBox::from_id_salt("cut_game").selected_text(name).width(300.0).show_ui(ui, |ui| {
763	                ui.selectable_value(&mut d.game_id, None, "Detect automatically");
764	                egui::ScrollArea::vertical().max_height(260.0).show(ui, |ui| {
765	                    for g in &self.games {
766	                        ui.selectable_value(&mut d.game_id, Some(g.id), &g.name);
767	                    }
768	                });
769	            });
770	            if !self.cats.is_empty() {
771	                ui.add_space(4.0);
772	                ui.label("Categories");
773	                ui.horizontal_wrapped(|ui| {
774	                    for cat in &self.cats {
775	                        let on = d.cats.contains(&cat.id);
776	                        if ui.add(egui::Button::selectable(on, &cat.name)).clicked() {
777	                            if on {
778	                                d.cats.retain(|x| *x != cat.id);
779	                            } else {
780	                                d.cats.push(cat.id);
781	                            }
782	                        }
783	                    }
784	                });
785	            }
786	            ui.add_space(4.0);
787	            ui.checkbox(&mut d.precise, "Frame-exact cut (re-encodes; slower)");
788	            ui.label(theme::small("Off: instant lossless cut, may start up to a couple of seconds early."));
789	            ui.add_space(4.0);
790	            let mix_note = if edits_in.is_empty() { "Your current track volumes are saved with the clip." } else { "Your track volumes and the audio edits in this range are saved with the clip." };
791	            ui.label(theme::small(format!("{mix_note} All original audio tracks are kept, so you can change them later.")));
792	            ui.add_space(10.0);
793	            ui.horizontal(|ui| {
794	                if theme::primary_button(ui, Some(icon::SCISSORS), "Create").clicked() {
795	                    create = true;
796	                }
