15	/// Width of the label column left of lanes (and of the timeline).
16	pub const GUTTER: f32 = 196.0;
17	/// Inset of the time axis inside the area right of the gutter.
18	pub const AXIS_INSET: f32 = 8.0;
19	const LANE_H: f32 = 40.0;
20	
21	/// The time-axis rectangle for a full-width row rect.
22	pub fn axis_rect(row: Rect) -> Rect {
23	    Rect::from_x_y_ranges(row.left() + GUTTER + AXIS_INSET..=row.right() - AXIS_INSET, row.y_range())
24	}
