26	/// A waveform placed on the lane time axis (`start`..`end` in axis units).
27	pub struct WaveSource<'a> {
28	    pub start: f64,
29	    pub end: f64,
30	    pub wave: &'a Waveform,
31	}
32	
33	/// Caches waveform files by media path, reloading when the service updates them.
34	#[derive(Default)]
35	pub struct Waves {
36	    map: HashMap<String, (Option<Waveform>, Option<SystemTime>, Instant)>,
37	}
38	
39	impl Waves {
40	    pub fn get(&mut self, media: &str) -> Option<&Waveform> {
41	        let now = Instant::now();
42	        let stale = self.map.get(media).map(|(_, _, t)| now.duration_since(*t) > Duration::from_secs(5)).unwrap_or(true);
43	        if stale {
44	            let wp = wave_path(Path::new(media));
45	            let mtime = std::fs::metadata(&wp).and_then(|m| m.modified()).ok();
46	            let entry = self.map.entry(media.to_string()).or_insert((None, None, now));
47	            if entry.1 != mtime || (entry.0.is_none() && mtime.is_some()) {
48	                entry.0 = mtime.and_then(|_| Waveform::load(&wp).ok());
49	                entry.1 = mtime;
50	            }
51	            entry.2 = now;
52	        }
53	        self.map.get(media).and_then(|(w, _, _)| w.as_ref())
54	    }
55	}
