99	/// Draw the lanes. `t0..t1` is the visible range in axis units; `wall` says
100	/// the axis is wall-clock seconds (24/7 view) rather than file seconds.
101	#[allow(clippy::too_many_arguments)]
102	pub fn lanes(
103	    ui: &mut Ui,
104	    player: &mut Player,
105	    t0: f64,
106	    t1: f64,
107	    wall: bool,
108	    sources: &[WaveSource],
109	    edits: &[AudioEdit],
110	    playhead: Option<f64>,
111	    st: &mut LaneState,
112	    accent: Color32,
113	) -> Vec<LaneAction> {
114	    let mut actions = Vec::new();
115	    let n = player.track_count;
116	    if st.custom_pct == 0.0 {
117	        st.custom_pct = 150.0;
118	    }
119	
120	    // Header: mode switch and help.
121	    ui.horizontal(|ui| {
122	        ui.add_space(4.0);
123	        ui.label(RichText::new("Audio tracks").font(FontId::new(14.0, theme::semibold())).color(theme::TEXT));
124	        if n > 1 {
125	            ui.add_space(8.0);
126	            let full = player.mode == MixMode::Full;
127	            if ui.add(egui::Button::selectable(full, "Full mix")).on_hover_text("Play everything you heard plus your mic (track 1)").clicked() && !full {
128	                player.set_mode(MixMode::Full);
129	                actions.push(LaneAction::MixChanged);
130	            }
131	            if ui.add(egui::Button::selectable(!full, "Separate tracks")).on_hover_text("Play game, voice, music and mic separately so you can balance them").clicked() && full {
132	                player.set_mode(MixMode::Separate);
133	                actions.push(LaneAction::MixChanged);
134	            }
135	        }
136	        ui.add_space(10.0);
137	        ui.label(theme::small(if n > 1 {
138	            "Drag across a track to select part of it, then mute it or make it louder. Drag an edit's edge to resize it. The recording itself is never changed."
139	        } else {
140	            "This file has a single audio track. Recordings made since the upgrade have separate tracks."
141	        }));
142	    });
143	
144	    // Selection toolbar.
145	    if let Some((tr, a, b)) = st.sel {
146	        ui.horizontal(|ui| {
147	            ui.add_space(4.0);
148	            let name = if st.all_tracks { "all tracks".to_string() } else { player.track_names.get(tr).cloned().unwrap_or_default() };
149	            ui.label(RichText::new(format!("{}–{} on {}", fmt_time(a, wall), fmt_time(b, wall), name)).color(theme::TEXT));
150	            let tracks: Vec<usize> = if st.all_tracks { (0..n).collect() } else { vec![tr] };
151	            let apply = |gain: f32, actions: &mut Vec<LaneAction>| actions.push(LaneAction::Edit { tracks: tracks.clone(), a, b, gain });
152	            if ui.button("Mute").clicked() {
153	                apply(0.0, &mut actions);
154	            }
155	            if ui.button("Quieter (−6 dB)").clicked() {
156	                apply(0.5, &mut actions);
157	            }
158	            if ui.button("Louder (+6 dB)").clicked() {
159	                apply(2.0, &mut actions);
160	            }
161	            ui.add(egui::DragValue::new(&mut st.custom_pct).range(0.0..=400.0).suffix("%").speed(1.0));
162	            if ui.button("Set").on_hover_text("Set this part to the exact volume").clicked() {
163	                apply(st.custom_pct / 100.0, &mut actions);
164	            }
165	            if ui.button("Reset").on_hover_text("Remove edits in this part").clicked() {
166	                apply(1.0, &mut actions);
167	            }
168	            ui.checkbox(&mut st.all_tracks, "All tracks");
169	            if theme::icon_button(ui, icon::CLOSE, 11.0, "Clear selection").clicked() {
170	                st.sel = None;
171	            }
172	        });
173	    }
174	    if n == 0 {
175	        return actions;
176	    }
177	
178	    let span = (t1 - t0).max(1e-6);
179	    for i in 0..n {
180	        let (row, _) = ui.allocate_exact_size(Vec2::new(ui.available_width(), LANE_H), Sense::hover());
181	        let axis = axis_rect(row);
182	        let x_of = |t: f64| axis.left() + (((t - t0) / span) as f32 * axis.width());
183	        let t_of = |x: f32| t0 + ((x - axis.left()) / axis.width()) as f64 * span;
184	        let audible_gain = player.effective_gains().get(i).copied().unwrap_or(0.0);
185	
186	        // ---- header (name, mute, volume)
187	        let head = Rect::from_min_size(row.min, Vec2::new(GUTTER - 4.0, LANE_H - 4.0));
188	        ui.painter().rect_filled(head, CornerRadius::same(8), theme::SURFACE);
189	        let name = player.track_names.get(i).cloned().unwrap_or_else(|| format!("Track {}", i + 1));
190	        let dim = audible_gain <= 0.0005;
191	        ui.painter().text(
192	            head.left_top() + egui::vec2(10.0, 6.0),
193	            Align2::LEFT_TOP,
194	            crate::views::clips::truncate(&name, 14),
195	            FontId::new(12.5, theme::semibold()),
196	            if dim { theme::TEXT_FAINT } else { theme::TEXT },
197	        );
198	        let mut g = player.stem_gains.get(i).copied().unwrap_or(1.0);
199	        if player.mode == MixMode::Full {
200	            g = if i == 0 { 1.0 } else { 0.0 };
201	        }
202	        let mute_rect = Rect::from_center_size(Pos2::new(head.right() - 16.0, head.top() + 13.0), Vec2::splat(22.0));
203	        let mresp = ui.interact(mute_rect, ui.scope_id().with(("lane_mute", i)), Sense::click());
204	        let glyph = if g <= 0.0005 { icon::MUTE } else { icon::VOLUME };
205	        if mresp.hovered() {
206	            ui.painter().circle_filled(mute_rect.center(), 11.0, theme::SURFACE3);
207	        }
208	        ui.painter().text(mute_rect.center(), Align2::CENTER_CENTER, glyph, FontId::new(11.0, theme::icons_family()), theme::TEXT_DIM);
209	        if mresp.on_hover_text(if g <= 0.0005 { "Unmute" } else { "Mute" }).clicked() {
210	            let new = if g <= 0.0005 { 1.0 } else { 0.0 };
211	            if player.mode == MixMode::Full && i == 0 && new == 0.0 {
212	                // Muting the full mix in full-mix mode: switch to stems with full mix off.
213	                player.stem_gains.resize(n, 1.0);
214	                player.stem_gains[0] = 0.0;
215	                player.set_mode(MixMode::Separate);
216	            } else {
217	                player.set_track_gain(i, new);
218	            }
219	            actions.push(LaneAction::MixChanged);
220	        }
221	        let slider_rect = Rect::from_min_size(head.left_top() + egui::vec2(8.0, 22.0), Vec2::new(GUTTER - 60.0, 14.0));
222	        let mut gv = g;
223	        let sresp = ui.put(slider_rect, egui::Slider::new(&mut gv, 0.0..=2.0).show_value(false).trailing_fill(true));
224	        if sresp.changed() {
225	            player.set_track_gain(i, gv);
226	            actions.push(LaneAction::MixChanged);
227	        }
228	        ui.painter().text(
229	            Pos2::new(head.right() - 8.0, slider_rect.center().y),
230	            Align2::RIGHT_CENTER,
231	            format!("{:.0}%", gv * 100.0),
232	            FontId::monospace(10.5),
233	            theme::TEXT_FAINT,
234	        );
235	
236	        // ---- waveform area
237	        let wave_area = Rect::from_x_y_ranges(axis.x_range(), row.top()..=row.bottom() - 4.0);
238	        let p = ui.painter_at(wave_area.expand2(Vec2::new(AXIS_INSET, 0.0)));
239	        p.rect_filled(wave_area, CornerRadius::same(6), theme::SURFACE);
240	        let mid = wave_area.center().y;
241	        let half = wave_area.height() / 2.0 - 3.0;
242	        let color = if dim { Color32::from_white_alpha(40) } else { theme::TEXT_DIM.gamma_multiply(0.85) };
243	        let px_step = 2.0;
244	        let mut x = wave_area.left();
245	        while x < wave_area.right() {
246	            let ta = t_of(x);
247	            let tb = t_of(x + px_step);
248	            let mut v = 0u8;
249	            for s in sources {
250	                if s.end <= ta || s.start >= tb {
251	                    continue;
252	                }
253	                v = v.max(s.wave.max_in(i, ta - s.start, tb - s.start, 48));
254	            }
255	            if v > 0 {
256	                let h = (v as f32 / 255.0) * half;
257	                p.line_segment([Pos2::new(x, mid - h), Pos2::new(x, mid + h)], Stroke::new(1.2, color));
258	            }
259	            x += px_step;
260	        }
261	        if sources.is_empty() {
262	            p.text(wave_area.center(), Align2::CENTER_CENTER, "waveform is being generated…", FontId::proportional(11.0), theme::TEXT_FAINT);
263	        }
264	        // Edits on this track.
265	        for e in edits.iter().filter(|e| e.track == i && e.end > t0 && e.start < t1) {
266	            let r = Rect::from_x_y_ranges(x_of(e.start).max(wave_area.left())..=x_of(e.end).min(wave_area.right()), wave_area.y_range());
267	            let tint = if e.gain <= 0.0005 {
268	                theme::DANGER
269	            } else if e.gain > 1.0 {
270	                theme::SUCCESS
271	            } else {
272	                theme::WARNING
273	            };
274	            p.rect_filled(r, CornerRadius::same(4), tint.gamma_multiply(0.22));
275	            p.rect_stroke(r, CornerRadius::same(4), Stroke::new(1.0, tint.gamma_multiply(0.7)), egui::StrokeKind::Inside);
276	            if r.width() > 46.0 {
277	                p.text(r.left_top() + egui::vec2(5.0, 3.0), Align2::LEFT_TOP, gain_label(e.gain), FontId::new(10.5, theme::semibold()), tint);
278	            }
279	        }
280	        // Selection.
281	        if let Some((tr, a, b)) = st.sel {
282	            if tr == i || st.all_tracks {
283	                let r = Rect::from_x_y_ranges(x_of(a).max(wave_area.left())..=x_of(b).min(wave_area.right()), wave_area.y_range());
284	                p.rect_filled(r, CornerRadius::same(4), accent.gamma_multiply(0.20));
285	                p.rect_stroke(r, CornerRadius::same(4), Stroke::new(1.5, accent), egui::StrokeKind::Inside);
286	            }
287	        }
288	        if let Some(ph) = playhead {
289	            let px = x_of(ph);
290	            if px >= wave_area.left() && px <= wave_area.right() {
291	                p.line_segment([Pos2::new(px, wave_area.top()), Pos2::new(px, wave_area.bottom())], Stroke::new(1.5, Color32::WHITE));
292	            }
293	        }
294	
295	        // ---- interaction: drag = select, click = seek (or pick an edit)
296	        let resp = ui.interact(wave_area, ui.scope_id().with(("lane", i)), Sense::click_and_drag());
297	        // An edit edge under the pointer (for resizing).
298	        let edge_at = |x: f32| -> Option<(f64, f64, f32, bool)> {
299	            edits.iter().filter(|e| e.track == i).find_map(|e| {
300	                if (x - x_of(e.start)).abs() <= 5.0 {
301	                    Some((e.start, e.end, e.gain, true))
302	                } else if (x - x_of(e.end)).abs() <= 5.0 {
303	                    Some((e.start, e.end, e.gain, false))
304	                } else {
305	                    None
306	                }
307	            })
308	        };
309	        let hover_edge = resp.hover_pos().and_then(|p| edge_at(p.x)).is_some();
310	        if resp.drag_started() {
311	            if let Some(pos) = resp.interact_pointer_pos() {
312	                match edge_at(pos.x) {
313	                    Some((a, b, g, left)) => st.resize = Some((i, a, b, g, left)),
314	                    None => st.drag = Some((i, t_of(pos.x))),
315	                }
316	            }
317	        }
318	        if resp.dragged() {
319	            if let Some(pos) = resp.interact_pointer_pos() {
320	                let t = t_of(pos.x.clamp(wave_area.left(), wave_area.right()));
321	                if let Some((tr, a, b, _, left)) = st.resize {
322	                    let (na, nb) = if left { (t.min(b - 0.05), b) } else { (a, t.max(a + 0.05)) };
323	                    st.sel = Some((tr, na, nb));
324	                } else if let Some((tr, start)) = st.drag {
325	                    st.sel = Some((tr, start.min(t), start.max(t)));
326	                }
327	            }
328	        }
329	        if resp.drag_stopped() {
330	            st.drag = None;
331	            if let Some((tr, a, b, g, _)) = st.resize.take() {
332	                if let Some((_, na, nb)) = st.sel {
333	                    // Clear the old range, then apply the edit over the new one.
334	                    actions.push(LaneAction::Edit { tracks: vec![tr], a, b, gain: 1.0 });
335	                    actions.push(LaneAction::Edit { tracks: vec![tr], a: na, b: nb, gain: g });
336	                }
337	            } else if let Some((_, a, b)) = st.sel {
338	                if ((b - a) / span) * (axis.width() as f64) < 3.0 {
339	                    st.sel = None;
340	                }
341	            }
342	        }
343	        if resp.clicked() {
344	            if let Some(pos) = resp.interact_pointer_pos() {
345	                let t = t_of(pos.x);
346	                match edits.iter().find(|e| e.track == i && e.start <= t && e.end >= t) {
347	                    Some(e) => {
348	                        st.sel = Some((i, e.start, e.end));
349	                        st.custom_pct = e.gain * 100.0;
350	                    }
351	                    None => {
352	                        st.sel = None;
353	                        actions.push(LaneAction::Seek(t));
354	                    }
355	                }
356	            }
357	        }
358	        if hover_edge || st.resize.is_some() {
359	            resp.on_hover_cursor(egui::CursorIcon::ResizeHorizontal);
360	        } else {
361	            resp.on_hover_cursor(egui::CursorIcon::Text);
362	        }
363	    }
364	    actions
365	}
