80	impl ClipsView {
81	    pub fn mark_dirty(&mut self) {
82	        self.dirty = true;
83	    }
84	
85	    fn refresh(&mut self, c: &mut Ctx) {
86	        if self.loaded && !self.dirty && self.search == self.last_search {
87	            return;
88	        }
89	        let mut f = ClipFilter { search: self.search.clone(), sort: self.sort, ..Default::default() };
90	        match self.filter {
91	            Filter::Favorites => f.favorites_only = true,
92	            Filter::Uncategorized => f.uncategorized = true,
93	            Filter::Game(g) => f.game_id = Some(g),
94	            Filter::Category(k) => f.category_id = Some(k),
95	            _ => {}
96	        }
97	        if let Some(db) = c.db() {
98	            let mut clips = db.list_clips(&f).unwrap_or_default();
99	            if self.filter == Filter::Recent {
100	                let cutoff = now_ms() - 7 * 86_400_000;
101	                clips.retain(|c| c.created_at >= cutoff);
102	            }
103	            self.clips = clips;
104	            self.games = db.list_games().unwrap_or_default().into_iter().filter(|g| g.clip_count > 0).collect();
105	            self.cats = db.list_categories().unwrap_or_default();
106	        }
107	        // Refresh the open clip's metadata too.
108	        if let Some(id) = self.open {
109	            if let Some(db) = c.db() {
110	                if let Ok(Some(clip)) = db.clip(id) {
111	                    if self.detail.clip.as_ref().map(|c| c.path != clip.path || c.title != clip.title).unwrap_or(false) {
112	                        self.detail.title_edit = clip.title.clone();
113	                    }
114	                    self.detail.clip = Some(clip);
115	                }
116	            }
117	        }
118	        self.selected.retain(|id| self.clips.iter().any(|c| c.id == *id));
119	        self.loaded = true;
120	        self.dirty = false;
121	        self.last_search = self.search.clone();
122	    }
123	
124	    pub fn save_position(&mut self, c: &mut Ctx) {
125	        if let Some(clip) = &self.detail.clip {
126	            let pos = c.player.state().time_pos;
127	            if let Some(db) = c.db() {
128	                let _ = db.set_clip_position(clip.id, pos);
129	            }
130	        }
131	    }
132	
133	    pub fn ui(&mut self, ui: &mut Ui, c: &mut Ctx) {
134	        if self.card_w == 0.0 {
135	            self.card_w = 260.0;
136	        }
137	        let req = OPEN_REQUEST.swap(0, Ordering::SeqCst);
138	        if req != 0 {
139	            self.open_clip(c, req);
140	        }
141	        self.refresh(c);
142	        self.reclaim_player(c);
143	        if self.open.is_some() {
144	            self.detail_ui(ui, c);
145	        } else {
146	            self.library_ui(ui, c);
147	        }
148	    }
149	
150	    /// The player is shared with the 24/7 view: if it's showing something
151	    /// else now, reload this clip (paused where it was).
152	    fn reclaim_player(&mut self, c: &mut Ctx) {
153	        let Some(clip) = self.detail.clip.clone() else { return };
154	        if self.open.is_none() {
155	            return;
156	        }
157	        if c.player.path.as_deref() == Some(clip.path.as_str()) {
158	            self.detail.resume_pos = c.player.state().time_pos;
159	            return;
160	        }
161	        c.player.edits = self.detail.edits.clone();
162	        let mix = if c.cfg.player.remember_clip_mix { clip.mixer.clone() } else { None };
163	        c.player.open(&clip.path, self.detail.resume_pos, clip.audio_tracks.max(0) as usize, &clip.track_names, mix.as_deref(), false, false, &c.cfg.player);
164	    }
165	
166	    fn open_clip(&mut self, c: &mut Ctx, id: i64) {
167	        self.save_position(c);
168	        let Some(clip) = c.db().and_then(|db| db.clip(id).ok().flatten()) else { return };
169	        if let Some(db) = c.db() {
170	            let _ = db.bump_clip_views(id);
171	        }
172	        let start = if clip.last_position > 1.0 && clip.last_position < clip.duration - 2.0 { clip.last_position } else { 0.0 };
173	        let mix = if c.cfg.player.remember_clip_mix { clip.mixer.clone() } else { None };
174	        c.player.edits = clip.audio_edits.clone();
175	        c.player.open(&clip.path, start, clip.audio_tracks.max(0) as usize, &clip.track_names, mix.as_deref(), false, c.cfg.player.autoplay, &c.cfg.player);
176	        if c.player.track_count > 1 {
177	            c.player.show_mixer = true;
178	        }
179	        let loop_v = if c.cfg.player.loop_clips { "inf" } else { "no" };
180	        if let Some(m) = &c.player.mpv {
181	            let _ = m.set("loop-file", loop_v);
182	        }
183	        self.detail = Detail {
184	            title_edit: clip.title.clone(),
185	            notes_edit: clip.notes.clone(),
186	            share_mb: c.cfg.export.target_size_mb,
187	            edits: clip.audio_edits.clone(),
188	            clip: Some(clip),
189	            ..Default::default()
190	        };
191	        self.open = Some(id);
192	    }
193	
194	    fn close_clip(&mut self, c: &mut Ctx) {
195	        self.save_position(c);
196	        c.player.close();
197	        if let Some(m) = &c.player.mpv {
198	            let _ = m.set("loop-file", "no");
199	        }
200	        self.open = None;
201	        self.detail = Detail::default();
202	        self.dirty = true;
203	    }
