205	    // ------------------------------------------------------------ library
206	
207	    fn library_ui(&mut self, ui: &mut Ui, c: &mut Ctx) {
208	        egui::Panel::left("clip_filters")
209	            .exact_size(236.0)
210	            .resizable(false)
211	            .frame(egui::Frame::NONE.inner_margin(Margin { left: 0, right: 18, top: 0, bottom: 0 }))
212	            .show(ui, |ui| self.filters_ui(ui, c));
213	
214	        // Header
215	        ui.horizontal(|ui| {
216	            ui.label(theme::heading(self.filter_title()));
217	            ui.label(theme::label_dim(format!("{} clip{}", self.clips.len(), if self.clips.len() == 1 { "" } else { "s" })));
218	            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
219	                ui.add(egui::Slider::new(&mut self.card_w, 180.0..=420.0).show_value(false)).on_hover_text("Card size");
220	                let before = self.sort;
221	                egui::ComboBox::from_id_salt("sort").selected_text(self.sort.label()).show_ui(ui, |ui| {
222	                    for s in ClipSort::ALL {
223	                        ui.selectable_value(&mut self.sort, s, s.label());
224	                    }
225	                });
226	                if self.sort != before {
227	                    self.dirty = true;
228	                }
229	                ui.add(egui::TextEdit::singleline(&mut self.search).hint_text("Search clips, games, categories…").desired_width(260.0));
230	                ui.label(theme::icon_text(icon::SEARCH, 14.0).color(theme::TEXT_FAINT));
231	            });
232	        });
233	        ui.add_space(8.0);
234	
235	        if !self.selected.is_empty() {
236	            self.bulk_bar(ui, c);
237	            ui.add_space(8.0);
238	        }
239	
240	        if self.clips.is_empty() {
241	            ui.add_space(60.0);
242	            ui.vertical_centered(|ui| {
243	                ui.label(theme::icon_text(icon::LIBRARY, 40.0).color(theme::TEXT_FAINT));
244	                ui.label(theme::title(if self.search.is_empty() { "No clips here yet" } else { "No matches" }));
245	                ui.label(theme::label_dim(format!("Save a clip with {} while you play.", c.cfg.hotkeys.save_clip)));
246	            });
247	            return;
248	        }
249	
250	        let gap = 16.0;
251	        let avail = ui.available_width();
252	        let cols = ((avail + gap) / (self.card_w + gap)).floor().max(1.0) as usize;
253	        let cw = (avail - gap * (cols as f32 - 1.0)) / cols as f32;
254	        let ch = cw * 9.0 / 16.0 + 56.0;
255	        let rows = self.clips.len().div_ceil(cols);
256	        let clips = self.clips.clone();
257	        let mut open = None;
258	        egui::ScrollArea::vertical().auto_shrink(false).show_rows(ui, ch + gap, rows, |ui, range| {
259	            for r in range {
260	                ui.horizontal(|ui| {
261	                    ui.spacing_mut().item_spacing.x = gap;
262	                    for clip in clips.iter().skip(r * cols).take(cols) {
263	                        if let Some(a) = self.card(ui, c, clip, cw) {
264	                            match a {
265	                                CardAction::Open => open = Some(clip.id),
266	                                CardAction::Toggle => {
267	                                    if !self.selected.remove(&clip.id) {
268	                                        self.selected.insert(clip.id);
269	                                    }
270	                                }
271	                            }
272	                        }
273	                    }
274	                });
275	                ui.add_space(gap - ui.spacing().item_spacing.y);
276	            }
277	        });
278	        if let Some(id) = open {
279	            self.open_clip(c, id);
280	        }
281	        self.confirm_bulk(ui, c);
282	    }
