284	    fn filter_title(&self) -> String {
285	        match &self.filter {
286	            Filter::All => "All clips".into(),
287	            Filter::Favorites => "Favorites".into(),
288	            Filter::Recent => "Last 7 days".into(),
289	            Filter::Uncategorized => "Uncategorized".into(),
290	            Filter::Game(g) => self.games.iter().find(|x| x.id == *g).map(|x| x.name.clone()).unwrap_or_else(|| "Game".into()),
291	            Filter::Category(k) => self.cats.iter().find(|x| x.id == *k).map(|x| x.name.clone()).unwrap_or_else(|| "Category".into()),
292	        }
293	    }
