295	    fn filters_ui(&mut self, ui: &mut Ui, c: &mut Ctx) {
296	        egui::ScrollArea::vertical().id_salt("filters").auto_shrink(false).show(ui, |ui| {
297	            theme::section(ui, "Library");
298	            for (f, glyph, label) in [
299	                (Filter::All, icon::LIBRARY, "All clips"),
300	                (Filter::Favorites, icon::STAR_FILL, "Favorites"),
301	                (Filter::Recent, icon::CLOCK, "Last 7 days"),
302	                (Filter::Uncategorized, icon::TAG, "Uncategorized"),
303	            ] {
304	                if filter_row(ui, self.filter == f, glyph, label, None, c.accent).clicked() {
305	                    self.filter = f;
306	                    self.dirty = true;
307	                }
308	            }
309	            ui.add_space(10.0);
310	            theme::section(ui, "Games & apps");
311	            for g in self.games.clone() {
312	                let f = Filter::Game(g.id);
313	                if filter_row(ui, self.filter == f, if g.is_game() { icon::GAME } else { icon::DEVICE }, &g.name, Some(g.clip_count), c.accent).clicked() {
314	                    self.filter = f;
315	                    self.dirty = true;
316	                }
317	            }
318	            ui.add_space(10.0);
319	            theme::section(ui, "Categories");
320	            for cat in self.cats.clone() {
321	                if let Some((id, name)) = &mut self.renaming_cat {
322	                    if *id == cat.id {
323	                        let r = ui.add(egui::TextEdit::singleline(name).desired_width(180.0));
324	                        if r.lost_focus() {
325	                            let (id, name) = (*id, name.clone());
326	                            if let Some(db) = c.db() {
327	                                if let Err(e) = db.rename_category(id, &name) {
328	                                    c.toast("error", format!("{e:#}"));
329	                                }
330	                            }
331	                            self.renaming_cat = None;
332	                            self.dirty = true;
333	                        } else {
334	                            r.request_focus();
335	                        }
336	                        continue;
337	                    }
338	                }
339	                let f = Filter::Category(cat.id);
340	                let resp = filter_row(ui, self.filter == f, icon::TAG, &cat.name, Some(cat.clip_count), c.accent);
341	                if resp.clicked() {
342	                    self.filter = f.clone();
343	                    self.dirty = true;
344	                }
345	                resp.context_menu(|ui| {
346	                    if ui.button("Rename").clicked() {
347	                        self.renaming_cat = Some((cat.id, cat.name.clone()));
348	                        ui.close();
349	                    }
350	                    if ui.button("Delete category").clicked() {
351	                        if let Some(db) = c.db() {
352	                            let _ = db.delete_category(cat.id);
353	                        }
354	                        if self.filter == f {
355	                            self.filter = Filter::All;
356	                        }
357	                        self.dirty = true;
358	                        ui.close();
359	                    }
360	                });
361	            }
362	            ui.horizontal(|ui| {
363	                let r = ui.add(egui::TextEdit::singleline(&mut self.new_cat).hint_text("New category").desired_width(150.0));
364	                let enter = r.lost_focus() && ui.input(|i| i.key_pressed(egui::Key::Enter));
365	                if (theme::icon_button(ui, icon::ADD, 13.0, "Add category").clicked() || enter) && !self.new_cat.trim().is_empty() {
366	                    let name = self.new_cat.trim().to_string();
367	                    if let Some(db) = c.db() {
368	                        match db.create_category(&name, "") {
369	                            Ok(_) => self.new_cat.clear(),
370	                            Err(e) => c.toast("error", format!("{e:#}")),
371	                        }
372	                    }
373	                    self.dirty = true;
374	                }
375	            });
376	            ui.label(theme::small("Right-click a category to rename or delete it."));
377	        });
378	    }
