380	    fn bulk_bar(&mut self, ui: &mut Ui, c: &mut Ctx) {
381	        theme::card().inner_margin(Margin::symmetric(14, 8)).show(ui, |ui| {
382	            ui.set_width(ui.available_width());
383	            ui.horizontal(|ui| {
384	                ui.label(theme::title(format!("{} selected", self.selected.len())));
385	                ui.add_space(12.0);
386	                let ids: Vec<i64> = self.selected.iter().copied().collect();
387	                ui.menu_button("Add to category", |ui| {
388	                    for cat in self.cats.clone() {
389	                        if ui.button(&cat.name).clicked() {
390	                            if let Some(db) = c.db() {
391	                                for id in &ids {
392	                                    let _ = db.add_clip_category(*id, cat.id);
393	                                }
394	                            }
395	                            self.dirty = true;
396	                            ui.close();
397	                        }
398	                    }
399	                    if self.cats.is_empty() {
400	                        ui.label("Create a category first (left panel)");
401	                    }
402	                });
