693	    fn clip_lanes(&mut self, ui: &mut Ui, c: &mut Ctx, clip: &Clip) {
694	        let dur = c.player.state().duration.max(clip.duration).max(0.1);
695	        let wave = c.waves.get(&clip.path).cloned();
696	        let sources: Vec<WaveSource> = wave.iter().map(|w| WaveSource { start: 0.0, end: dur, wave: w }).collect();
697	        let ph = Some(c.player.state().time_pos);
698	        let acts = lanes::lanes(ui, &mut c.player, 0.0, dur, false, &sources, &self.detail.edits, ph, &mut self.detail.lanes, c.accent);
699	        for a in acts {
700	            match a {
701	                LaneAction::Seek(t) => c.player.seek(t, true),
702	                LaneAction::Edit { tracks, a, b, gain } => {
703	                    for tr in &tracks {
704	                        apply_edit(&mut self.detail.edits, *tr, a, b, gain);
705	                    }
706	                    if tracks.iter().any(|t| *t > 0) && c.player.mode == crate::player::MixMode::Full && gain != 1.0 {
707	                        c.player.set_mode(crate::player::MixMode::Separate);
708	                        self.detail.mix_dirty = Some(Instant::now());
709	                        c.toast("info", "Switched to separate tracks so the edit is audible");
710	                    }
711	                    c.player.set_edits(self.detail.edits.clone());
712	                    self.detail.edits_dirty = Some(Instant::now());
713	                }
714	                LaneAction::MixChanged => self.detail.mix_dirty = Some(Instant::now()),
715	            }
716	        }
717	    }
