719	    /// Save the clip's mix and audio edits shortly after they change.
720	    fn persist_audio(&mut self, c: &mut Ctx, clip: &Clip) {
721	        if let Some(t) = self.detail.mix_dirty {
722	            if t.elapsed() > Duration::from_millis(800) {
723	                if c.cfg.player.remember_clip_mix {
724	                    let gains = c.player.effective_gains();
725	                    if let Some(db) = c.db() {
726	                        let _ = db.set_clip_mixer(clip.id, Some(&gains));
727	                    }
728	                }
729	                self.detail.mix_dirty = None;
730	            }
731	        }
732	        if let Some(t) = self.detail.edits_dirty {
733	            if t.elapsed() > Duration::from_millis(500) {
734	                let edits = self.detail.edits.clone();
735	                if let Some(db) = c.db() {
736	                    let _ = db.set_clip_audio_edits(clip.id, &edits);
737	                }
738	                self.detail.edits_dirty = None;
739	            }
740	        }
741	        if self.detail.mix_dirty.is_some() || self.detail.edits_dirty.is_some() {
742	            ui_repaint_soon();
743	        }
744	    }
