862	                });
863	            });
864	            ui.add_space(4.0);
865	            ui.label(theme::label_dim("Categories"));
866	            let cats = self.cats.clone();
867	            ui.horizontal_wrapped(|ui| {
868	                for cat in &cats {
869	                    let on = clip.category_ids.contains(&cat.id);
870	                    if ui.add(egui::Button::selectable(on, &cat.name)).clicked() {
871	                        if let Some(db) = c.db() {
