873	                        }
874	                        self.dirty = true;
875	                    }
876	                }
877	            });
878	            ui.horizontal(|ui| {
879	                let r = ui.add(egui::TextEdit::singleline(&mut self.detail.new_cat).hint_text("New category").desired_width(170.0));
880	                let enter = r.lost_focus() && ui.input(|i| i.key_pressed(egui::Key::Enter));
881	                if (theme::icon_button(ui, icon::ADD, 12.0, "Create and add").clicked() || enter) && !self.detail.new_cat.trim().is_empty() {
882	                    let name = self.detail.new_cat.trim().to_string();
