1	//! Background jobs: clipping from the 24/7 recording, trimming, exporting.
2	//! Run one at a time on their own thread with progress reported to the GUI.
3	
4	use crate::clips::{attribute_game, clip_dir, probe_and_thumb};
5	use crate::shared::Shared;
6	use crate::win::ui::{ToastLevel, UiCmd};
7	use anyhow::{bail, Context, Result};
8	use cv_core::db::Db;
9	use cv_core::ffmpeg::{bitrate_for_size, concat_list, cut_args, export_args, EncodeOptions, ExportSpec};
10	use cv_core::ipc::{Event, JobInfo};
11	use cv_core::model::{rebase_edits, AudioEdit, NewClip};
12	use cv_core::naming::{render_template, sanitize_component, unique_path};
13	use cv_core::timeline::{plan_cut, plan_duration_s, CutPart, Segment};
14	use cv_core::util::now_ms;
15	use std::path::{Path, PathBuf};
16	use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
17	use std::sync::Arc;
18	use std::time::{Duration, Instant};
19	
20	#[derive(Debug, Clone)]
21	pub enum JobKind {
22	    CutRange {
23	        from_ms: i64,
24	        to_ms: i64,
25	        title: String,
26	        game_id: Option<i64>,
27	        category_ids: Vec<i64>,
28	        precise: Option<bool>,
29	        gains: Vec<f32>,
30	        audio_edits: Vec<AudioEdit>,
31	    },
32	    Trim { clip_id: i64, start_s: f64, end_s: f64, replace: bool, precise: Option<bool> },
33	    Export { clip_id: i64, range: Option<(f64, f64)>, gains: Vec<f32>, target_size_mb: Option<u32> },
34	}
35	
36	pub struct JobRequest {
37	    pub id: u64,
38	    pub kind: JobKind,
39	    pub cancel: Arc<AtomicBool>,
40	}
41	
42	static NEXT_ID: AtomicU64 = AtomicU64::new(1);
43	static CANCELS: once_cell::sync::Lazy<parking_lot::Mutex<Vec<(u64, Arc<AtomicBool>)>>> =
44	    once_cell::sync::Lazy::new(Default::default);
45	
46	/// Queue a job; returns its id.
47	pub fn submit(sh: &Shared, kind: JobKind) -> u64 {
48	    let id = NEXT_ID.fetch_add(1, Ordering::SeqCst);
49	    let cancel = Arc::new(AtomicBool::new(false));
50	    CANCELS.lock().push((id, cancel.clone()));
51	    let (label, title) = match &kind {
52	        JobKind::CutRange { title, .. } => ("clip", if title.is_empty() { "New clip".to_string() } else { title.clone() }),
53	        JobKind::Trim { .. } => ("trim", "Trimming clip".to_string()),
54	        JobKind::Export { .. } => ("export", "Exporting".to_string()),
55	    };
56	    let info = JobInfo { id, kind: label.into(), title, progress: 0.0, state: "queued".into(), ..Default::default() };
57	    sh.jobs.lock().push(info.clone());
58	    sh.emit(Event::Job { job: info });
59	    let _ = sh.job_tx.send(JobRequest { id, kind, cancel });
60	    id
61	}
62	
63	pub fn cancel(id: u64) -> bool {
64	    let c = CANCELS.lock();
65	    if let Some((_, flag)) = c.iter().find(|(i, _)| *i == id) {
66	        flag.store(true, Ordering::SeqCst);
67	        true
68	    } else {
69	        false
70	    }
71	}
72	
73	fn update(sh: &Shared, id: u64, f: impl FnOnce(&mut JobInfo)) {
74	    let mut jobs = sh.jobs.lock();
75	    if let Some(j) = jobs.iter_mut().find(|j| j.id == id) {
76	        f(j);
77	        let j = j.clone();
78	        drop(jobs);
79	        sh.emit(Event::Job { job: j });
80	    }
81	}
82	
83	pub fn run(sh: Arc<Shared>, rx: crossbeam_channel::Receiver<JobRequest>) {
84	    while let Ok(req) = rx.recv() {
85	        if sh.is_shutting_down() {
86	            break;
87	        }
88	        let id = req.id;
89	        if req.cancel.load(Ordering::SeqCst) {
90	            update(&sh, id, |j| j.state = "cancelled".into());
91	            continue;
92	        }
93	        update(&sh, id, |j| j.state = "running".into());
94	        let mut last_emit = Instant::now();
95	        let mut progress = |p: f32| {
96	            if last_emit.elapsed() > Duration::from_millis(250) || p >= 1.0 {
97	                last_emit = Instant::now();
98	                update(&sh, id, |j| j.progress = p);
99	            }
100	        };
101	        let result = match &req.kind {
102	            JobKind::CutRange { from_ms, to_ms, title, game_id, category_ids, precise, gains, audio_edits } => {
103	                let meta = ClipMeta { category_ids, gains, audio_edits };
104	                cut_range(&sh, *from_ms, *to_ms, title, *game_id, &meta, *precise, &mut progress, &req.cancel)
105	            }
106	            JobKind::Trim { clip_id, start_s, end_s, replace, precise } => {
107	                trim(&sh, *clip_id, *start_s, *end_s, *replace, *precise, &mut progress, &req.cancel)
108	            }
109	            JobKind::Export { clip_id, range, gains, target_size_mb } => {
110	                export(&sh, *clip_id, *range, gains, *target_size_mb, &mut progress, &req.cancel)
111	            }
112	        };
113	        match result {
114	            Ok((output, clip_id)) => {
115	                update(&sh, id, |j| {
116	                    j.state = "done".into();
117	                    j.progress = 1.0;
118	                    j.output = Some(output.to_string_lossy().to_string());
119	                    j.clip_id = clip_id;
120	                });
121	                if let Some(c) = clip_id {
122	                    sh.emit(Event::ClipAdded { clip_id: c });
123	                }
124	                sh.emit(Event::LibraryChanged);
125	            }
126	            Err(e) => {
127	                let cancelled = req.cancel.load(Ordering::SeqCst);
128	                let msg = if cancelled { "Cancelled".to_string() } else { format!("{e:#}") };
129	                if !cancelled {
130	                    sh.log_event("error", format!("Job failed: {msg}"));
131	                    sh.toast(ToastLevel::Error, format!("Failed: {msg}"));
132	                }
133	                update(&sh, id, |j| {
134	                    j.state = if cancelled { "cancelled".into() } else { "failed".into() };
135	                    j.message = msg;
136	                });
137	            }
138	        }
139	        CANCELS.lock().retain(|(i, _)| *i != id);
140	        // Keep the 10 most recent finished jobs for the GUI's job list.
141	        let mut jobs = sh.jobs.lock();
142	        let finished = jobs.iter().filter(|j| j.state != "running" && j.state != "queued").count();
143	        if finished > 10 {
144	            let mut to_drop = finished - 10;
145	            jobs.retain(|j| {
146	                if to_drop > 0 && j.state != "running" && j.state != "queued" {
147	                    to_drop -= 1;
148	                    false
149	                } else {
150	                    true
151	                }
152	            });
153	        }
154	    }
155	}
156	
157	fn encode_opts(cfg: &cv_core::config::Config) -> EncodeOptions {
158	    EncodeOptions {
159	        video_encoder: cfg.export.video_encoder.clone(),
160	        quality: cfg.export.quality,
161	        audio_bitrate_kbps: cfg.export.audio_bitrate_kbps,
162	    }
163	}
164	
165	/// Metadata carried from the 24/7 view onto a new clip.
166	struct ClipMeta<'a> {
167	    category_ids: &'a [i64],
168	    /// Track volumes in use when the clip was made.
169	    gains: &'a [f32],
170	    /// Edits in wall-clock seconds.
171	    audio_edits: &'a [AudioEdit],
172	}
173	
174	#[allow(clippy::too_many_arguments)]
175	fn cut_range(
176	    sh: &Shared,
177	    from_ms: i64,
178	    to_ms: i64,
179	    title: &str,
180	    game_id: Option<i64>,
181	    meta: &ClipMeta,
182	    precise: Option<bool>,
183	    progress: &mut dyn FnMut(f32),
184	    cancel: &AtomicBool,
185	) -> Result<(PathBuf, Option<i64>)> {
186	    let cfg = sh.cfg();
187	    anyhow::ensure!(to_ms > from_ms, "the end is before the start");
188	    anyhow::ensure!(to_ms - from_ms <= 6 * 3600 * 1000, "clips are limited to 6 hours");
189	    let tools = sh.tools().context("ffmpeg is not available")?;
190	    let db = Db::open_default()?;
191	    let now = now_ms();
192	    let recs = db.list_recordings()?;
193	    let segments: Vec<Segment> = recs
194	        .iter()
195	        .map(|r| Segment {
196	            path: PathBuf::from(&r.path),
197	            start_ms: r.start_ms,
198	            duration_ms: if r.is_live() { (now - r.start_ms - 3000).max(0) } else { (r.duration * 1000.0) as i64 },
199	            live: r.is_live(),
200	        })
201	        .collect();
202	    let parts = plan_cut(&segments, from_ms, to_ms);
203	    anyhow::ensure!(!parts.is_empty(), "nothing was recorded in that time range");
204	    // All parts must share one audio layout for a lossless join.
205	    let mut tracks: Option<i64> = None;
206	    for p in &parts {
207	        let r = recs.iter().find(|r| Path::new(&r.path) == p.path).unwrap();
208	        let t = if r.audio_tracks > 0 { r.audio_tracks } else { tools.probe(&p.path).map(|i| i.audio.len() as i64).unwrap_or(0) };
209	        match tracks {
210	            None => tracks = Some(t),
211	            Some(prev) if prev != t => bail!("that range spans recordings with different audio track layouts; clip each part separately"),
212	            _ => {}
213	        }
214	    }
215	    let total_s = plan_duration_s(&parts, &segments);
216	
217	    let (gid, game_name, exe) = match game_id {
218	        Some(g) => {
219	            let game = db.game(g)?.context("game not found")?;
220	            let exe = cv_core::games::exe_name_of(&game.exe_path);
221	            (g, game.name, exe)
222	        }
223	        None => attribute_game(&db, from_ms, to_ms, &cfg.clips.unknown_game_name)?,
224	    };
225	    let local = chrono::DateTime::from_timestamp_millis(from_ms).unwrap_or_default().with_timezone(&chrono::Local);
226	    let title = if title.trim().is_empty() {
227	        render_template(&cfg.clips.name_template, &game_name, &exe, local)
228	    } else {
229	        sanitize_component(title)
230	    };
231	    let dir = clip_dir(&cfg, &game_name);
232	    std::fs::create_dir_all(&dir)?;
233	    let dest = unique_path(&dir, &title, "mp4", None);
234	    let tmp = cv_core::paths::temp_dir().join(format!("cut_{}.mp4", now_ms()));
235	    let list = cv_core::paths::temp_dir().join(format!("cut_{}.ffconcat", now_ms()));
236	    std::fs::create_dir_all(cv_core::paths::temp_dir())?;
237	    std::fs::write(&list, concat_list(&parts))?;
238	    let precise = precise.unwrap_or(cfg.export.precise_cuts);
239	    let args = cut_args(&parts, &tmp, &list, precise, tracks.unwrap_or(0) as usize, &encode_opts(&cfg))?;
240	    let r = tools.run_progress(&args, total_s, progress, cancel);
241	    let _ = std::fs::remove_file(&list);
242	    if let Err(e) = r {
243	        let _ = std::fs::remove_file(&tmp);
244	        return Err(e);
245	    }
246	    {
247	        let _lock = sh.library_lock.lock();
248	        crate::clips::move_file(&tmp, &dest, Duration::from_secs(10))?;
249	        let stem = dest.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or(title);
250	        let id = db.insert_clip(&NewClip {
251	            path: dest.to_string_lossy().to_string(),
252	            title: stem,
253	            game_id: Some(gid),
254	            created_at: to_ms,
255	            source_start_ms: Some(from_ms),
256	            size: dest.metadata().map(|m| m.len() as i64).unwrap_or(0),
257	            source: "recording".into(),
258	            favorite: false,
259	        })?;
260	        drop(_lock);
261	        let mut db2 = Db::open_default()?;
262	        if !meta.category_ids.is_empty() {
263	            db2.set_clip_categories(id, meta.category_ids)?;
264	        }
265	        // Non-destructive: the file keeps every original track; the volumes
266	        // and edits are remembered with the clip and can be changed later.
267	        if meta.gains.len() > 1 && meta.gains.len() as i64 == tracks.unwrap_or(0) {
268	            db.set_clip_mixer(id, Some(meta.gains))?;
269	        }
270	        let edits = rebase_edits(meta.audio_edits, from_ms as f64 / 1000.0, to_ms as f64 / 1000.0);
271	        if !edits.is_empty() {
272	            db.set_clip_audio_edits(id, &edits)?;
273	        }
274	        probe_and_thumb(&db, &tools, id, &dest, cfg.clips.generate_thumbnails);
275	        sh.toast(ToastLevel::Success, format!("Clip created: {}", dest.file_stem().unwrap_or_default().to_string_lossy()));
276	        sh.log_event("info", format!("Clipped {} from the 24/7 recording", cv_core::util::format_duration(total_s)));
277	        Ok((dest, Some(id)))
278	    }
279	}
280	
281	#[allow(clippy::too_many_arguments)]
282	fn trim(
283	    sh: &Shared,
284	    clip_id: i64,
285	    start_s: f64,
286	    end_s: f64,
287	    replace: bool,
288	    precise: Option<bool>,
289	    progress: &mut dyn FnMut(f32),
290	    cancel: &AtomicBool,
291	) -> Result<(PathBuf, Option<i64>)> {
292	    let cfg = sh.cfg();
293	    anyhow::ensure!(end_s > start_s + 0.1, "the trim range is empty");
294	    let tools = sh.tools().context("ffmpeg is not available")?;
295	    let mut db = Db::open_default()?;
296	    let clip = db.clip(clip_id)?.context("clip not found")?;
297	    let src = PathBuf::from(&clip.path);
298	    anyhow::ensure!(src.is_file(), "the clip file is missing");
299	    let dir = src.parent().map(Path::to_path_buf).unwrap_or_default();
300	    let tmp = dir.join(format!(".cv_trim_{}.mp4", now_ms()));
301	    let parts = [CutPart { path: src.clone(), in_s: start_s.max(0.0), out_s: Some(end_s) }];
302	    let precise = precise.unwrap_or(cfg.export.precise_cuts);
303	    let args = cut_args(&parts, &tmp, Path::new("unused"), precise, clip.audio_tracks.max(0) as usize, &encode_opts(&cfg))?;
304	    if let Err(e) = tools.run_progress(&args, end_s - start_s, progress, cancel) {
305	        let _ = std::fs::remove_file(&tmp);
306	        return Err(e);
307	    }
308	    let _lock = sh.library_lock.lock();
309	    if replace {
310	        if cfg.clips.delete_to_recycle_bin {
311	            crate::win::shell::recycle(&[src.as_path()])?;
312	        } else {
313	            std::fs::remove_file(&src)?;
314	        }
315	        std::fs::rename(&tmp, &src)?;
316	        drop(_lock);
317	        probe_and_thumb(&db, &tools, clip_id, &src, cfg.clips.generate_thumbnails);
318	        db.set_clip_audio_edits(clip_id, &rebase_edits(&clip.audio_edits, start_s, end_s))?;
319	        let new_start = clip.source_start_ms.map(|s| s + (start_s * 1000.0) as i64);
320	        let _ = db.set_clip_source_start(clip_id, new_start);
321	        let _ = db.set_clip_position(clip_id, 0.0);
322	        sh.toast(ToastLevel::Success, "Clip trimmed");
323	        Ok((src, Some(clip_id)))
324	    } else {
325	        let dest = unique_path(&dir, &format!("{} (trim)", clip.title), "mp4", None);
326	        std::fs::rename(&tmp, &dest)?;
327	        let stem = dest.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
328	        let id = db.insert_clip(&NewClip {
329	            path: dest.to_string_lossy().to_string(),
330	            title: stem,
331	            game_id: clip.game_id,
332	            created_at: now_ms(),
333	            source_start_ms: clip.source_start_ms.map(|s| s + (start_s * 1000.0) as i64),
334	            size: dest.metadata().map(|m| m.len() as i64).unwrap_or(0),
335	            source: "trim".into(),
336	            favorite: clip.favorite,
337	        })?;
338	        drop(_lock);
339	        db.set_clip_categories(id, &clip.category_ids)?;
340	        db.set_clip_audio_edits(id, &rebase_edits(&clip.audio_edits, start_s, end_s))?;
341	        if let Some(m) = &clip.mixer {
342	            db.set_clip_mixer(id, Some(m))?;
343	        }
344	        probe_and_thumb(&db, &tools, id, &dest, cfg.clips.generate_thumbnails);
345	        sh.toast(ToastLevel::Success, "Trimmed copy saved");
346	        Ok((dest, Some(id)))
347	    }
348	}
349	
350	fn export(
351	    sh: &Shared,
352	    clip_id: i64,
353	    range: Option<(f64, f64)>,
354	    gains: &[f32],
355	    target_size_mb: Option<u32>,
356	    progress: &mut dyn FnMut(f32),
357	    cancel: &AtomicBool,
358	) -> Result<(PathBuf, Option<i64>)> {
359	    let cfg = sh.cfg();
360	    let tools = sh.tools().context("ffmpeg is not available")?;
361	    let db = Db::open_default()?;
362	    let clip = db.clip(clip_id)?.context("clip not found")?;
363	    let src = PathBuf::from(&clip.path);
364	    anyhow::ensure!(src.is_file(), "the clip file is missing");
365	    let info = tools.probe(&src)?;
366	    let n = info.audio.len();
367	    // Mix only if the user changed something or there are several tracks.
368	    let gain_of = |i: usize| gains.get(i).copied().unwrap_or(if i == 0 { 1.0 } else { 0.0 });
369	    let offset = range.map(|r| r.0).unwrap_or(0.0);
370	    let gains_full: Vec<(usize, String)> =
371	        (0..n).map(|i| (i, cv_core::mixer::track_expr(gain_of(i), &clip.audio_edits, i, offset))).collect();
372	    let untouched = n <= 1 && (gain_of(0) - 1.0).abs() < 0.001 && clip.audio_edits.is_empty();
373	    let dur = match range {
374	        Some((a, b)) => (b - a).max(0.1),
375	        None => info.duration,
376	    };
377	    let video_kbps = match target_size_mb {
378	        Some(mb) => Some(
379	            bitrate_for_size(mb, dur, cfg.export.audio_bitrate_kbps)
380	                .with_context(|| format!("{} is too long to fit in {mb} MB; trim it first", cv_core::util::format_duration(dur)))?,
381	        ),
382	        None => None,
383	    };
384	    let spec = ExportSpec {
385	        gains: if untouched { Vec::new() } else { gains_full },
386	        range,
387	        target_size_mb,
388	        max_height: cfg.export.max_height,
389	        reencode_video: range.is_some() && cfg.export.precise_cuts,
390	    };
391	    let out_dir = cfg.exports_dir();
392	    std::fs::create_dir_all(&out_dir)?;
393	    let suffix = if target_size_mb.is_some() { "share" } else { "export" };
394	    let out = unique_path(&out_dir, &format!("{} ({suffix})", clip.title), "mp4", None);
395	    let tmp = out.with_extension("tmp.mp4");
396	    let enc = encode_opts(&cfg);
397	    let mut args = export_args(&src, &tmp, &spec, &enc, &info, video_kbps);
398	    let mut attempt = 0;
399	    loop {
400	        if let Err(e) = tools.run_progress(&args, dur, progress, cancel) {
401	            let _ = std::fs::remove_file(&tmp);
402	            return Err(e);
403	        }
404	        let size = tmp.metadata().map(|m| m.len()).unwrap_or(0);
405	        match (target_size_mb, video_kbps) {
406	            (Some(mb), Some(k)) if size > mb as u64 * 1024 * 1024 && attempt == 0 => {
407	                attempt += 1;
408	                let smaller = (k as f64 * 0.82) as u32;
409	                tracing::info!("export {} MB over target; retrying at {smaller} kbps", size / 1024 / 1024);
410	                args = export_args(&src, &tmp, &spec, &enc, &info, Some(smaller));
411	            }
412	            _ => break,
413	        }
414	    }
415	    std::fs::rename(&tmp, &out)?;
416	    if cfg.export.copy_to_clipboard {
417	        sh.ui.send(UiCmd::CopyFile(out.clone()));
418	    }
419	    if cfg.export.open_folder_after {
420	        crate::win::shell::open_in_explorer(&out_dir);
421	    }
422	    let msg = if cfg.export.copy_to_clipboard { "Exported — copied to clipboard, paste it anywhere" } else { "Export finished" };
423	    sh.toast(ToastLevel::Success, msg);
424	    Ok((out, None))
425	}
