1	//! Clips library (grid with game/category filters) and the clip detail view
2	//! (player, trim, mixer, export, organise).
3	
4	use crate::app::Ctx;
5	use crate::lanes::{self, LaneAction, LaneState, WaveSource, GUTTER};
6	use crate::player::seek_bar;
7	use crate::theme::{self, icon};
8	use cv_core::ipc::Request;
9	use cv_core::model::{apply_edit, AudioEdit, Category, Clip, ClipFilter, ClipSort, Game};
10	use cv_core::util::{format_duration, format_duration_precise, human_bytes, now_ms};
11	use eframe::egui::{self, Align2, Color32, CornerRadius, FontId, Margin, Rect, RichText, Sense, Stroke, Ui, Vec2};
12	use std::collections::HashSet;
13	use std::sync::atomic::{AtomicI64, Ordering};
14	use std::time::{Duration, Instant};
15	
16	static OPEN_REQUEST: AtomicI64 = AtomicI64::new(0);
17	
18	/// Ask the clips page to open a clip (used from Home).
19	pub fn request_open(clip_id: i64) {
20	    OPEN_REQUEST.store(clip_id, Ordering::SeqCst);
21	}
22	
23	#[derive(Debug, Clone, PartialEq)]
24	enum Filter {
25	    All,
26	    Favorites,
27	    Recent,
28	    Uncategorized,
29	    Game(i64),
30	    Category(i64),
31	}
32	
33	impl Default for Filter {
34	    fn default() -> Self {
35	        Filter::All
36	    }
37	}
38	
39	#[derive(Default)]
40	struct Detail {
41	    clip: Option<Clip>,
42	    title_edit: String,
43	    notes_edit: String,
44	    notes_dirty: Option<Instant>,
45	    in_pt: Option<f64>,
46	    out_pt: Option<f64>,
47	    confirm_delete: bool,
48	    new_cat: String,
49	    mix_dirty: Option<Instant>,
50	    share_mb: u32,
51	    /// Non-destructive audio edits (clip time).
52	    edits: Vec<AudioEdit>,
53	    edits_dirty: Option<Instant>,
54	    lanes: LaneState,
55	    /// Where this clip was when the player was last showing it.
56	    resume_pos: f64,
57	}
58	
59	#[derive(Default)]
60	pub struct ClipsView {
61	    filter: Filter,
62	    search: String,
63	    sort: ClipSort,
64	    clips: Vec<Clip>,
65	    games: Vec<Game>,
66	    cats: Vec<Category>,
67	    selected: HashSet<i64>,
68	    dirty: bool,
69	    loaded: bool,
70	    card_w: f32,
71	    open: Option<i64>,
72	    detail: Detail,
73	    new_cat: String,
74	    renaming_cat: Option<(i64, String)>,
75	    confirm_bulk_delete: bool,
76	    pub highlight: Option<i64>,
77	    last_search: String,
78	}
79	
80	impl ClipsView {
81	    pub fn mark_dirty(&mut self) {
82	        self.dirty = true;
83	    }
84	
85	    fn refresh(&mut self, c: &mut Ctx) {
86	        if self.loaded && !self.dirty && self.search == self.last_search {
87	            return;
88	        }
89	        let mut f = ClipFilter { search: self.search.clone(), sort: self.sort, ..Default::default() };
90	        match self.filter {
91	            Filter::Favorites => f.favorites_only = true,
92	            Filter::Uncategorized => f.uncategorized = true,
93	            Filter::Game(g) => f.game_id = Some(g),
94	            Filter::Category(k) => f.category_id = Some(k),
95	            _ => {}
96	        }
97	        if let Some(db) = c.db() {
98	            let mut clips = db.list_clips(&f).unwrap_or_default();
99	            if self.filter == Filter::Recent {
100	                let cutoff = now_ms() - 7 * 86_400_000;
101	                clips.retain(|c| c.created_at >= cutoff);
102	            }
103	            self.clips = clips;
104	            self.games = db.list_games().unwrap_or_default().into_iter().filter(|g| g.clip_count > 0).collect();
105	            self.cats = db.list_categories().unwrap_or_default();
106	        }
107	        // Refresh the open clip's metadata too.
108	        if let Some(id) = self.open {
109	            if let Some(db) = c.db() {
110	                if let Ok(Some(clip)) = db.clip(id) {
111	                    if self.detail.clip.as_ref().map(|c| c.path != clip.path || c.title != clip.title).unwrap_or(false) {
112	                        self.detail.title_edit = clip.title.clone();
113	                    }
114	                    self.detail.clip = Some(clip);
115	                }
116	            }
117	        }
118	        self.selected.retain(|id| self.clips.iter().any(|c| c.id == *id));
119	        self.loaded = true;
120	        self.dirty = false;
121	        self.last_search = self.search.clone();
122	    }
123	
124	    pub fn save_position(&mut self, c: &mut Ctx) {
125	        if let Some(clip) = &self.detail.clip {
126	            let pos = c.player.state().time_pos;
127	            if let Some(db) = c.db() {
128	                let _ = db.set_clip_position(clip.id, pos);
129	            }
130	        }
131	    }
132	
133	    pub fn ui(&mut self, ui: &mut Ui, c: &mut Ctx) {
134	        if self.card_w == 0.0 {
135	            self.card_w = 260.0;
136	        }
137	        let req = OPEN_REQUEST.swap(0, Ordering::SeqCst);
138	        if req != 0 {
139	            self.open_clip(c, req);
140	        }
141	        self.refresh(c);
142	        self.reclaim_player(c);
143	        if self.open.is_some() {
144	            self.detail_ui(ui, c);
145	        } else {
146	            self.library_ui(ui, c);
147	        }
148	    }
149	
150	    /// The player is shared with the 24/7 view: if it's showing something
151	    /// else now, reload this clip (paused where it was).
152	    fn reclaim_player(&mut self, c: &mut Ctx) {
153	        let Some(clip) = self.detail.clip.clone() else { return };
154	        if self.open.is_none() {
155	            return;
156	        }
157	        if c.player.path.as_deref() == Some(clip.path.as_str()) {
158	            self.detail.resume_pos = c.player.state().time_pos;
159	            return;
160	        }
161	        c.player.edits = self.detail.edits.clone();
162	        let mix = if c.cfg.player.remember_clip_mix { clip.mixer.clone() } else { None };
163	        c.player.open(&clip.path, self.detail.resume_pos, clip.audio_tracks.max(0) as usize, &clip.track_names, mix.as_deref(), false, false, &c.cfg.player);
164	    }
165	
166	    fn open_clip(&mut self, c: &mut Ctx, id: i64) {
167	        self.save_position(c);
168	        let Some(clip) = c.db().and_then(|db| db.clip(id).ok().flatten()) else { return };
169	        if let Some(db) = c.db() {
170	            let _ = db.bump_clip_views(id);
171	        }
172	        let start = if clip.last_position > 1.0 && clip.last_position < clip.duration - 2.0 { clip.last_position } else { 0.0 };
173	        let mix = if c.cfg.player.remember_clip_mix { clip.mixer.clone() } else { None };
174	        c.player.edits = clip.audio_edits.clone();
175	        c.player.open(&clip.path, start, clip.audio_tracks.max(0) as usize, &clip.track_names, mix.as_deref(), false, c.cfg.player.autoplay, &c.cfg.player);
176	        if c.player.track_count > 1 {
177	            c.player.show_mixer = true;
178	        }
179	        let loop_v = if c.cfg.player.loop_clips { "inf" } else { "no" };
180	        if let Some(m) = &c.player.mpv {
181	            let _ = m.set("loop-file", loop_v);
182	        }
183	        self.detail = Detail {
184	            title_edit: clip.title.clone(),
185	            notes_edit: clip.notes.clone(),
186	            share_mb: c.cfg.export.target_size_mb,
187	            edits: clip.audio_edits.clone(),
188	            clip: Some(clip),
189	            ..Default::default()
190	        };
191	        self.open = Some(id);
192	    }
193	
194	    fn close_clip(&mut self, c: &mut Ctx) {
195	        self.save_position(c);
196	        c.player.close();
197	        if let Some(m) = &c.player.mpv {
198	            let _ = m.set("loop-file", "no");
199	        }
200	        self.open = None;
201	        self.detail = Detail::default();
202	        self.dirty = true;
203	    }
204	
205	    // ------------------------------------------------------------ library
206	
207	    fn library_ui(&mut self, ui: &mut Ui, c: &mut Ctx) {
208	        egui::Panel::left("clip_filters")
209	            .exact_size(236.0)
210	            .resizable(false)
211	            .frame(egui::Frame::NONE.inner_margin(Margin { left: 0, right: 18, top: 0, bottom: 0 }))
212	            .show(ui, |ui| self.filters_ui(ui, c));
213	
214	        // Header
215	        ui.horizontal(|ui| {
216	            ui.label(theme::heading(self.filter_title()));
217	            ui.label(theme::label_dim(format!("{} clip{}", self.clips.len(), if self.clips.len() == 1 { "" } else { "s" })));
218	            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
219	                ui.add(egui::Slider::new(&mut self.card_w, 180.0..=420.0).show_value(false)).on_hover_text("Card size");
220	                let before = self.sort;
221	                egui::ComboBox::from_id_salt("sort").selected_text(self.sort.label()).show_ui(ui, |ui| {
222	                    for s in ClipSort::ALL {
223	                        ui.selectable_value(&mut self.sort, s, s.label());
224	                    }
225	                });
226	                if self.sort != before {
227	                    self.dirty = true;
228	                }
229	                ui.add(egui::TextEdit::singleline(&mut self.search).hint_text("Search clips, games, categories…").desired_width(260.0));
230	                ui.label(theme::icon_text(icon::SEARCH, 14.0).color(theme::TEXT_FAINT));
231	            });
232	        });
233	        ui.add_space(8.0);
234	
235	        if !self.selected.is_empty() {
236	            self.bulk_bar(ui, c);
237	            ui.add_space(8.0);
238	        }
239	
240	        if self.clips.is_empty() {
241	            ui.add_space(60.0);
242	            ui.vertical_centered(|ui| {
243	                ui.label(theme::icon_text(icon::LIBRARY, 40.0).color(theme::TEXT_FAINT));
244	                ui.label(theme::title(if self.search.is_empty() { "No clips here yet" } else { "No matches" }));
245	                ui.label(theme::label_dim(format!("Save a clip with {} while you play.", c.cfg.hotkeys.save_clip)));
246	            });
247	            return;
248	        }
249	
250	        let gap = 16.0;
251	        let avail = ui.available_width();
252	        let cols = ((avail + gap) / (self.card_w + gap)).floor().max(1.0) as usize;
253	        let cw = (avail - gap * (cols as f32 - 1.0)) / cols as f32;
254	        let ch = cw * 9.0 / 16.0 + 56.0;
255	        let rows = self.clips.len().div_ceil(cols);
256	        let clips = self.clips.clone();
257	        let mut open = None;
258	        egui::ScrollArea::vertical().auto_shrink(false).show_rows(ui, ch + gap, rows, |ui, range| {
259	            for r in range {
260	                ui.horizontal(|ui| {
261	                    ui.spacing_mut().item_spacing.x = gap;
262	                    for clip in clips.iter().skip(r * cols).take(cols) {
263	                        if let Some(a) = self.card(ui, c, clip, cw) {
264	                            match a {
265	                                CardAction::Open => open = Some(clip.id),
266	                                CardAction::Toggle => {
267	                                    if !self.selected.remove(&clip.id) {
268	                                        self.selected.insert(clip.id);
269	                                    }
270	                                }
271	                            }
272	                        }
273	                    }
274	                });
275	                ui.add_space(gap - ui.spacing().item_spacing.y);
276	            }
277	        });
278	        if let Some(id) = open {
279	            self.open_clip(c, id);
280	        }
281	        self.confirm_bulk(ui, c);
282	    }
283	
284	    fn filter_title(&self) -> String {
285	        match &self.filter {
286	            Filter::All => "All clips".into(),
287	            Filter::Favorites => "Favorites".into(),
288	            Filter::Recent => "Last 7 days".into(),
289	            Filter::Uncategorized => "Uncategorized".into(),
290	            Filter::Game(g) => self.games.iter().find(|x| x.id == *g).map(|x| x.name.clone()).unwrap_or_else(|| "Game".into()),
291	            Filter::Category(k) => self.cats.iter().find(|x| x.id == *k).map(|x| x.name.clone()).unwrap_or_else(|| "Category".into()),
292	        }
293	    }
294	
295	    fn filters_ui(&mut self, ui: &mut Ui, c: &mut Ctx) {
296	        egui::ScrollArea::vertical().id_salt("filters").auto_shrink(false).show(ui, |ui| {
297	            theme::section(ui, "Library");
298	            for (f, glyph, label) in [
299	                (Filter::All, icon::LIBRARY, "All clips"),
300	                (Filter::Favorites, icon::STAR_FILL, "Favorites"),
301	                (Filter::Recent, icon::CLOCK, "Last 7 days"),
302	                (Filter::Uncategorized, icon::TAG, "Uncategorized"),
303	            ] {
304	                if filter_row(ui, self.filter == f, glyph, label, None, c.accent).clicked() {
305	                    self.filter = f;
306	                    self.dirty = true;
307	                }
308	            }
309	            ui.add_space(10.0);
310	            theme::section(ui, "Games & apps");
311	            for g in self.games.clone() {
312	                let f = Filter::Game(g.id);
313	                if filter_row(ui, self.filter == f, if g.is_game() { icon::GAME } else { icon::DEVICE }, &g.name, Some(g.clip_count), c.accent).clicked() {
314	                    self.filter = f;
315	                    self.dirty = true;
316	                }
317	            }
318	            ui.add_space(10.0);
319	            theme::section(ui, "Categories");
320	            for cat in self.cats.clone() {
321	                if let Some((id, name)) = &mut self.renaming_cat {
322	                    if *id == cat.id {
323	                        let r = ui.add(egui::TextEdit::singleline(name).desired_width(180.0));
324	                        if r.lost_focus() {
325	                            let (id, name) = (*id, name.clone());
326	                            if let Some(db) = c.db() {
327	                                if let Err(e) = db.rename_category(id, &name) {
328	                                    c.toast("error", format!("{e:#}"));
329	                                }
330	                            }
331	                            self.renaming_cat = None;
332	                            self.dirty = true;
333	                        } else {
334	                            r.request_focus();
335	                        }
336	                        continue;
337	                    }
338	                }
339	                let f = Filter::Category(cat.id);
340	                let resp = filter_row(ui, self.filter == f, icon::TAG, &cat.name, Some(cat.clip_count), c.accent);
341	                if resp.clicked() {
342	                    self.filter = f.clone();
343	                    self.dirty = true;
344	                }
345	                resp.context_menu(|ui| {
346	                    if ui.button("Rename").clicked() {
347	                        self.renaming_cat = Some((cat.id, cat.name.clone()));
348	                        ui.close();
349	                    }
350	                    if ui.button("Delete category").clicked() {
351	                        if let Some(db) = c.db() {
352	                            let _ = db.delete_category(cat.id);
353	                        }
354	                        if self.filter == f {
355	                            self.filter = Filter::All;
356	                        }
357	                        self.dirty = true;
358	                        ui.close();
359	                    }
360	                });
361	            }
362	            ui.horizontal(|ui| {
363	                let r = ui.add(egui::TextEdit::singleline(&mut self.new_cat).hint_text("New category").desired_width(150.0));
364	                let enter = r.lost_focus() && ui.input(|i| i.key_pressed(egui::Key::Enter));
365	                if (theme::icon_button(ui, icon::ADD, 13.0, "Add category").clicked() || enter) && !self.new_cat.trim().is_empty() {
366	                    let name = self.new_cat.trim().to_string();
367	                    if let Some(db) = c.db() {
368	                        match db.create_category(&name, "") {
369	                            Ok(_) => self.new_cat.clear(),
370	                            Err(e) => c.toast("error", format!("{e:#}")),
371	                        }
372	                    }
373	                    self.dirty = true;
374	                }
375	            });
376	            ui.label(theme::small("Right-click a category to rename or delete it."));
377	        });
378	    }
379	
380	    fn bulk_bar(&mut self, ui: &mut Ui, c: &mut Ctx) {
381	        theme::card().inner_margin(Margin::symmetric(14, 8)).show(ui, |ui| {
382	            ui.set_width(ui.available_width());
383	            ui.horizontal(|ui| {
384	                ui.label(theme::title(format!("{} selected", self.selected.len())));
385	                ui.add_space(12.0);
386	                let ids: Vec<i64> = self.selected.iter().copied().collect();
387	                ui.menu_button("Add to category", |ui| {
