404	                    let games = c.db().and_then(|d| d.list_games().ok()).unwrap_or_default();
405	                    egui::ScrollArea::vertical().max_height(320.0).show(ui, |ui| {
406	                        for g in games {
407	                            if ui.button(&g.name).clicked() {
408	                                for id in &ids {
409	                                    c.request(Request::SetClipGame { clip_id: *id, game_id: Some(g.id) });
410	                                }
411	                                self.dirty = true;
412	                                ui.close();
413	                            }
414	                        }
415	                    });
416	                });
417	                if ui.button("Favorite").clicked() {
418	                    if let Some(db) = c.db() {
419	                        for id in &ids {
420	                            let _ = db.set_clip_favorite(*id, true);
421	                        }
422	                    }
423	                    self.dirty = true;
424	                }
425	                if ui.button(RichText::new("Delete").color(theme::DANGER)).clicked() {
426	                    if c.cfg.general.confirm_deletes {
427	                        self.confirm_bulk_delete = true;
428	                    } else {
429	                        self.delete(c, ids.clone());
430	                    }
431	                }
432	                ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
433	                    if ui.button("Clear selection").clicked() {
434	                        self.selected.clear();
435	                    }
436	                    if ui.button("Select all").clicked() {
437	                        self.selected = self.clips.iter().map(|c| c.id).collect();
438	                    }
439	                });
440	            });
441	        });
