507	        }
508	        let highlight = self.highlight == Some(clip.id);
509	        if selected || highlight {
510	            ui.painter().rect_stroke(img, CornerRadius::same(12), Stroke::new(2.5, c.accent), egui::StrokeKind::Inside);
