526	            ui.painter().galley(r.min + egui::vec2(6.0, 3.0), g, Color32::WHITE);
527	        }
528	        // Selection checkbox (hover or selection mode).
529	        let cb = Rect::from_center_size(img.right_top() + egui::vec2(-18.0, 18.0), Vec2::splat(22.0));
530	        let mut action = None;
531	        if hovered || selected || !self.selected.is_empty() {
532	            ui.painter().rect_filled(cb, CornerRadius::same(6), if selected { c.accent } else { Color32::from_black_alpha(150) });
533	            ui.painter().rect_stroke(cb, CornerRadius::same(6), Stroke::new(1.5, Color32::WHITE), egui::StrokeKind::Inside);
534	            if selected {
535	                ui.painter().text(cb.center(), Align2::CENTER_CENTER, icon::CHECK, FontId::new(12.0, theme::icons_family()), Color32::WHITE);
536	            }
537	        }
