1061	pub fn relative_time(ms: i64) -> String {
1062	    let secs = (now_ms() - ms) / 1000;
1063	    let dt = chrono::DateTime::from_timestamp_millis(ms).unwrap_or_default().with_timezone(&chrono::Local);
1064	    if secs < 60 {
1065	        "just now".into()
1066	    } else if secs < 3600 {
1067	        format!("{} min ago", secs / 60)
1068	    } else if secs < 86_400 {
1069	        format!("{} h ago", secs / 3600)
1070	    } else if secs < 7 * 86_400 {
1071	        dt.format("%A %H:%M").to_string()
1072	    } else {
1073	        dt.format("%b %d, %Y").to_string()
1074	    }
1075	}
