22	pub fn run(sh: Arc<Shared>, rx: crossbeam_channel::Receiver<ClipTask>) {
23	    let mut failed: HashSet<PathBuf> = HashSet::new();
24	    while let Ok(task) = rx.recv() {
25	        if sh.is_shutting_down() {
26	            break;
27	        }
28	        let (path, at_ms, short, stray) = match task {
29	            ClipTask::ReplaySaved { path, at_ms, short } => (path, at_ms, short, false),
30	            ClipTask::ImportStray { path } => {
31	                if failed.contains(&path) {
32	                    continue;
33	                }
34	                let at = cv_core::obs::filename::parse_timestamp_ms(&path)
35	                    .or_else(|| path.metadata().and_then(|m| m.modified()).ok().map(cv_core::util::system_time_ms))
36	                    .unwrap_or_else(now_ms);
37	                (path, at, false, true)
38	            }
39	        };
40	        match save_replay(&sh, &path, at_ms, short) {
41	            Ok((id, title, game, dur)) => {
42	                sh.log_event("info", format!("Saved clip \"{title}\" ({game}, {})", format_duration(dur)));
43	                if !stray {
44	                    sh.toast(ToastLevel::Success, format!("Clip saved: {game} · {}", format_duration(dur)));
45	                }
46	                sh.emit(Event::ClipAdded { clip_id: id });
47	                sh.emit(Event::LibraryChanged);
48	            }
49	            Err(e) => {
50	                sh.log_event("error", format!("Could not save clip {}: {e:#}", path.display()));
51	                sh.toast(ToastLevel::Error, format!("Clip could not be filed: {e}"));
52	                failed.insert(path);
53	            }
54	        }
55	    }
56	}
