269	pub fn set_clip_game(sh: &Shared, clip_id: i64, game_id: Option<i64>) -> Result<()> {
270	    let cfg = sh.cfg();
271	    let db = Db::open_default()?;
272	    let clip = db.clip(clip_id)?.context("clip not found")?;
273	    let game_name = match game_id {
274	        Some(g) => db.game(g)?.context("game not found")?.name,
275	        None => cfg.clips.unknown_game_name.clone(),
276	    };
277	    let src = PathBuf::from(&clip.path);
278	    let _lock = sh.library_lock.lock();
279	    if cfg.clips.organize_by_game && src.is_file() {
280	        let dir = clip_dir(&cfg, &game_name);
281	        let stem = src.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
282	        let ext = src.extension().map(|e| e.to_string_lossy().to_string()).unwrap_or_else(|| "mp4".into());
283	        if src.parent() != Some(dir.as_path()) {
284	            let dest = unique_path(&dir, &stem, &ext, None);
285	            move_file(&src, &dest, Duration::from_secs(10))?;
286	            let new_stem = dest.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or(stem);
287	            db.set_clip_path_and_title(clip_id, &dest.to_string_lossy(), &new_stem)?;
288	            remove_dir_if_empty(src.parent());
289	        }
290	    }
291	    db.set_clip_game(clip_id, game_id)?;
292	    Ok(())
293	}
