295	pub fn delete_clips(sh: &Shared, ids: &[i64]) -> Result<usize> {
296	    let cfg = sh.cfg();
297	    let db = Db::open_default()?;
298	    let _lock = sh.library_lock.lock();
299	    let mut n = 0;
300	    for id in ids {
301	        let Some(clip) = db.clip(*id)? else { continue };
302	        let p = PathBuf::from(&clip.path);
303	        if p.exists() {
304	            if cfg.clips.delete_to_recycle_bin {
305	                crate::win::shell::recycle(&[p.as_path()])?;
306	            } else {
307	                std::fs::remove_file(&p)?;
308	            }
309	        }
