1	//! Background waveform generation for the timeline's audio lanes.
2	//!
3	//! Newest recordings first, then clips. The file OBS is writing is extended
4	//! incrementally about once a minute. Everything runs at below-normal
5	//! priority with pauses between files so it never competes with a game.
6	
7	use crate::shared::Shared;
8	use cv_core::db::Db;
9	use cv_core::model::ClipFilter;
10	use cv_core::waveform::{generate, wave_path, Waveform};
11	use std::collections::HashSet;
12	use std::path::{Path, PathBuf};
13	use std::sync::atomic::AtomicBool;
14	use std::sync::Arc;
15	use std::time::{Duration, Instant};
16	
17	/// Don't read the last few seconds of a growing file (partial fragment).
18	const LIVE_SAFETY_S: f64 = 4.0;
19	const LIVE_INTERVAL: Duration = Duration::from_secs(60);
20	/// Backfill reads whole files; cap it at this many x realtime (~190 MB/s for
21	/// a 30 Mbit/s recording) so it never saturates the drive.
22	const BACKFILL_READRATE: f64 = 50.0;
23	
24	/// True while a game is (or was recently) in focus: skip heavy backfill then.
25	fn gaming(sh: &Shared) -> bool {
26	    sh.status.lock().game.current.is_some()
27	}
28	
29	pub fn run(sh: Arc<Shared>) {
30	    let _ = std::fs::create_dir_all(cv_core::paths::data_dir().join("waves"));
31	    // Let startup settle (indexing, OBS launch) first.
32	    sleep_unless_shutdown(&sh, Duration::from_secs(20));
33	    let mut live_done: Option<(String, Instant)> = None;
34	    let mut failed: HashSet<String> = HashSet::new();
35	    let mut last_cleanup = Instant::now() - Duration::from_secs(3600);
36	    let never = AtomicBool::new(false);
37	    while !sh.is_shutting_down() {
38	        let Some(tools) = sh.tools() else {
39	            sleep_unless_shutdown(&sh, Duration::from_secs(60));
40	            continue;
41	        };
42	        let Ok(db) = Db::open_default() else {
43	            sleep_unless_shutdown(&sh, Duration::from_secs(60));
44	            continue;
45	        };
46	        let mut recs = db.list_recordings().unwrap_or_default();
47	        recs.sort_by_key(|r| std::cmp::Reverse(r.start_ms));
48	        let live_tracks = sh.status.lock().recording.tracks as usize;
49	        let mut did_work = false;
50	
51	        for r in &recs {
52	            if sh.is_shutting_down() {
53	                return;
54	            }
55	            if failed.contains(&r.path) {
56	                continue;
57	            }
58	            let src = PathBuf::from(&r.path);
59	            let wp = wave_path(&src);
60	            let existing = Waveform::load(&wp).ok();
61	            if r.is_live() {
62	                let due = live_done.as_ref().map(|(p, t)| p != &r.path || t.elapsed() >= LIVE_INTERVAL).unwrap_or(true);
63	                if !due {
64	                    continue;
65	                }
66	                let tracks = if r.audio_tracks > 0 { r.audio_tracks as usize } else { live_tracks.max(1) };
67	                let recorded = (cv_core::util::now_ms() - r.start_ms) as f64 / 1000.0 - LIVE_SAFETY_S;
68	                extend(&tools.ffmpeg, &src, &wp, existing, tracks, recorded, None, &never, &mut failed, &r.path);
69	                live_done = Some((r.path.clone(), Instant::now()));
70	                did_work = true;
71	                continue;
72	            }
73	            if r.audio_tracks <= 0 || r.duration <= 0.0 {
74	                continue; // not probed yet
75	            }
76	            if gaming(&sh) {
77	                continue; // don't compete with a game for disk/CPU
78	            }
79	            let complete = existing.as_ref().map(|w| w.tracks == r.audio_tracks as usize && w.duration_s() >= r.duration - 2.0).unwrap_or(false);
80	            if complete {
81	                continue;
82	            }
83	            extend(&tools.ffmpeg, &src, &wp, existing, r.audio_tracks as usize, r.duration, Some(BACKFILL_READRATE), &never, &mut failed, &r.path);
84	            did_work = true;
85	            // One full file per pass, then breathe (and re-check the live file).
86	            break;
87	        }
88	
89	        if !did_work && !gaming(&sh) {
90	            // Clips (small files) once the recordings are done.
91	            let clips = db.list_clips(&ClipFilter::default()).unwrap_or_default();
92	            for c in clips.iter().filter(|c| c.audio_tracks > 0 && c.duration > 0.0).take(500) {
93	                if sh.is_shutting_down() {
94	                    return;
95	                }
96	                let src = PathBuf::from(&c.path);
97	                let wp = wave_path(&src);
98	                if wp.exists() || failed.contains(&c.path) || !src.is_file() {
99	                    continue;
100	                }
101	                extend(&tools.ffmpeg, &src, &wp, None, c.audio_tracks as usize, c.duration, Some(BACKFILL_READRATE), &never, &mut failed, &c.path);
102	                did_work = true;
103	                break;
104	            }
105	        }
106	
107	        if last_cleanup.elapsed() > Duration::from_secs(3600) {
108	            last_cleanup = Instant::now();
109	            cleanup(&db);
110	        }
111	        sleep_unless_shutdown(&sh, if did_work { Duration::from_secs(5) } else { Duration::from_secs(30) });
112	    }
113	}
114	
115	#[allow(clippy::too_many_arguments)]
116	fn extend(
117	    ffmpeg: &Path,
118	    src: &Path,
119	    wp: &Path,
