131	        return;
132	    }
133	    match generate(ffmpeg, src, tracks, from, readrate, cancel) {
134	        Ok(w) => {
135	            base.append(&w);
136	            if let Err(e) = base.save(wp) {
137	                tracing::warn!("saving waveform for {}: {e:#}", src.display());
138	            }
139	        }
140	        Err(e) => {
141	            tracing::warn!("waveform for {}: {e:#}", src.display());
142	            failed.insert(key.to_string());
143	        }
144	    }
145	}
