147	/// Remove waveform files whose recording/clip no longer exists.
148	fn cleanup(db: &Db) {
149	    let mut keep: HashSet<PathBuf> = HashSet::new();
150	    for r in db.list_recordings().unwrap_or_default() {
151	        keep.insert(wave_path(Path::new(&r.path)));
152	    }
153	    for c in db.list_clips(&ClipFilter { include_missing: true, ..Default::default() }).unwrap_or_default() {
154	        keep.insert(wave_path(Path::new(&c.path)));
155	    }
156	    let dir = cv_core::paths::data_dir().join("waves");
157	    if let Ok(rd) = std::fs::read_dir(&dir) {
158	        for e in rd.flatten() {
159	            if !keep.contains(&e.path()) {
160	                let _ = std::fs::remove_file(e.path());
161	            }
162	        }
163	    }
