58	/// Wait for a file to exist and stop growing.
59	fn wait_stable(path: &Path, max: Duration) -> Result<u64> {
60	    let start = Instant::now();
61	    let mut last = None;
62	    loop {
63	        if let Ok(m) = path.metadata() {
64	            let len = m.len();
65	            if last == Some(len) && len > 0 {
66	                return Ok(len);
67	            }
68	            last = Some(len);
69	        }
70	        if start.elapsed() > max {
71	            if let Some(l) = last {
72	                return Ok(l);
73	            }
74	            bail!("{} never appeared", path.display());
75	        }
76	        std::thread::sleep(Duration::from_millis(400));
77	    }
78	}
79	
80	/// Move a file, retrying while it's locked; copies across drives.
81	pub fn move_file(src: &Path, dest: &Path, retry_for: Duration) -> Result<()> {
82	    if let Some(p) = dest.parent() {
83	        std::fs::create_dir_all(p).with_context(|| format!("creating {}", p.display()))?;
84	    }
85	    let start = Instant::now();
86	    loop {
87	        match std::fs::rename(src, dest) {
88	            Ok(()) => return Ok(()),
89	            Err(e) if e.raw_os_error() == Some(17) => {
90	                // ERROR_NOT_SAME_DEVICE: copy, verify, delete.
91	                let tmp = dest.with_extension("partial");
92	                std::fs::copy(src, &tmp).with_context(|| format!("copying to {}", tmp.display()))?;
93	                let (a, b) = (src.metadata()?.len(), tmp.metadata()?.len());
94	                if a != b {
95	                    let _ = std::fs::remove_file(&tmp);
96	                    bail!("copy verification failed ({a} vs {b} bytes)");
97	                }
98	                std::fs::rename(&tmp, dest)?;
99	                let mut tries = 0;
100	                while std::fs::remove_file(src).is_err() && tries < 50 {
101	                    tries += 1;
102	                    std::thread::sleep(Duration::from_millis(200));
103	                }
104	                return Ok(());
105	            }
106	            Err(e) => {
107	                // 32 = sharing violation, 5 = access denied (still being written / scanned).
108	                let transient = matches!(e.raw_os_error(), Some(32) | Some(5) | Some(33));
109	                if !transient || start.elapsed() > retry_for {
110	                    return Err(e).with_context(|| format!("moving {} -> {}", src.display(), dest.display()));
111	                }
112	                std::thread::sleep(Duration::from_millis(500));
113	            }
114	        }
115	    }
116	}
