118	/// Resolve the game a clip covering [start, end] belongs to.
119	pub fn attribute_game(db: &Db, start_ms: i64, end_ms: i64, unknown_name: &str) -> Result<(i64, String, String)> {
120	    let spans: Vec<Span> = db
121	        .activity_between(start_ms - 5000, end_ms)?
122	        .into_iter()
123	        .map(|a| Span { key: a.key, is_game: a.is_game, start_ms: a.start_ms, end_ms: a.end_ms.max(a.start_ms + 1000) })
124	        .collect();
125	    if let Some((key, _)) = attribute(&spans, start_ms, end_ms) {
126	        if let Some(g) = db.game_by_key(&key)? {
127	            let exe = cv_core::games::exe_name_of(&g.exe_path);
128	            return Ok((g.id, g.name, exe));
129	        }
130	    }
131	    let id = db.upsert_game(DESKTOP_KEY, unknown_name, "", false, now_ms())?;
132	    Ok((id, db.game(id)?.map(|g| g.name).unwrap_or_else(|| unknown_name.to_string()), String::new()))
133	}
