135	pub fn clip_dir(cfg: &cv_core::config::Config, game_name: &str) -> PathBuf {
136	    let root = PathBuf::from(&cfg.clips.folder);
137	    if cfg.clips.organize_by_game {
138	        root.join(sanitize_component(game_name))
139	    } else {
140	        root
