144	fn save_replay(sh: &Shared, src: &Path, at_ms: i64, short: bool) -> Result<(i64, String, String, f64)> {
145	    let cfg = sh.cfg();
146	    wait_stable(src, Duration::from_secs(15))?;
147	    let tools = sh.tools();
148	    let info = tools.as_ref().and_then(|t| t.probe(src).ok());
149	    let dur = info.as_ref().map(|i| i.duration).filter(|d| *d > 0.0).unwrap_or(cfg.clips.clip_length_secs as f64);
150	    let end_ms = at_ms;
151	    let start_ms = end_ms - (dur * 1000.0) as i64;
152	
153	    let db = Db::open_default()?;
154	    let (game_id, game_name, exe) = attribute_game(&db, start_ms, end_ms, &cfg.clips.unknown_game_name)?;
155	    let local = chrono::DateTime::from_timestamp_millis(end_ms).unwrap_or_default().with_timezone(&chrono::Local);
156	    let title = render_template(&cfg.clips.name_template, &game_name, &exe, local);
157	    let dir = clip_dir(&cfg, &game_name);
158	
159	    let _lock = sh.library_lock.lock();
160	    let dest = unique_path(&dir, &title, "mp4", None);
161	    let final_dur;
162	    if short && dur > cfg.clips.short_clip_secs as f64 + 1.0 {
163	        let tools = tools.as_ref().context("ffmpeg is needed for short clips")?;
164	        std::fs::create_dir_all(&dir)?;
165	        let parts = [CutPart { path: src.to_path_buf(), in_s: dur - cfg.clips.short_clip_secs as f64, out_s: None }];
166	        let tmp = dest.with_extension("tmp.mp4");
167	        let args = cv_core::ffmpeg::cut_args(&parts, &tmp, Path::new("unused"), false, 0, &Default::default())?;
168	        tools.run_progress(&args, cfg.clips.short_clip_secs as f64, &mut |_| {}, &AtomicBool::new(false))?;
169	        std::fs::rename(&tmp, &dest)?;
170	        let _ = std::fs::remove_file(src);
171	        final_dur = cfg.clips.short_clip_secs as f64;
172	    } else {
173	        move_file(src, &dest, MOVE_RETRY)?;
174	        final_dur = dur;
175	    }
176	    let stem = dest.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or(title);
177	    let size = dest.metadata().map(|m| m.len() as i64).unwrap_or(0);
178	    let is_game = db.game(game_id)?.map(|g| g.is_game()).unwrap_or(false);
179	    let id = db.insert_clip(&NewClip {
180	        path: dest.to_string_lossy().to_string(),
181	        title: stem.clone(),
182	        game_id: Some(game_id),
183	        created_at: end_ms,
184	        source_start_ms: Some(end_ms - (final_dur * 1000.0) as i64),
185	        size,
186	        source: "replay".into(),
187	        favorite: cfg.clips.auto_favorite && is_game,
188	    })?;
189	    drop(_lock);
190	    if let Some(t) = &tools {
191	        probe_and_thumb(&db, t, id, &dest, cfg.clips.generate_thumbnails);
192	    }
193	    Ok((id, stem, game_name, final_dur))
194	}
