196	/// Fill in duration/tracks and make a thumbnail.
197	pub fn probe_and_thumb(db: &Db, tools: &cv_core::ffmpeg::Tools, id: i64, path: &Path, thumbs: bool) {
198	    match tools.probe(path) {
199	        Ok(info) => {
200	            let names: Vec<String> = info
201	                .audio
202	                .iter()
203	                .enumerate()
204	                .map(|(i, a)| {
205	                    if !a.title.is_empty() {
206	                        a.title.clone()
207	                    } else if info.audio.len() == cv_core::config::TRACK_NAMES.len() {
208	                        cv_core::config::TRACK_NAMES[i].to_string()
209	                    } else if i == 0 {
210	                        "Audio".to_string()
211	                    } else {
212	                        format!("Track {}", i + 1)
213	                    }
214	                })
215	                .collect();
216	            let _ = db.update_clip_probe(
217	                id,
218	                info.duration,
219	                info.size as i64,
220	                info.width as i64,
221	                info.height as i64,
222	                info.fps,
223	                info.audio.len() as i64,
224	                &names,
225	            );
226	            if thumbs {
227	                let out = cv_core::paths::thumbs_dir().join(format!("clip_{id}.jpg"));
228	                let at = (info.duration * 0.85).max(0.0);
229	                match tools.thumbnail(path, at, &out, 480) {
230	                    Ok(()) => {
231	                        let _ = db.set_clip_thumb(id, &out.to_string_lossy());
232	                    }
233	                    Err(e) => tracing::warn!("thumbnail for clip {id}: {e:#}"),
234	                }
235	            }
236	        }
237	        Err(e) => {
238	            tracing::warn!("probe failed for {}: {e:#}", path.display());
239	            // Mark as probed with what we know so we don't retry forever.
240	            let size = path.metadata().map(|m| m.len() as i64).unwrap_or(0);
241	            let _ = db.update_clip_probe(id, 0.0, size, 0, 0, 0.0, 0, &[]);
242	            let _ = db.set_clip_thumb(id, "-");
243	        }
244	    }
245	}
