252	pub fn rename_clip(sh: &Shared, clip_id: i64, title: &str) -> Result<()> {
253	    let db = Db::open_default()?;
254	    let clip = db.clip(clip_id)?.context("clip not found")?;
255	    let title = sanitize_component(title);
256	    let src = PathBuf::from(&clip.path);
257	    let dir = src.parent().map(Path::to_path_buf).unwrap_or_default();
258	    let ext = src.extension().map(|e| e.to_string_lossy().to_string()).unwrap_or_else(|| "mp4".into());
259	    let _lock = sh.library_lock.lock();
260	    let dest = unique_path(&dir, &title, &ext, Some(&src));
261	    if dest.to_string_lossy() != clip.path {
262	        move_file(&src, &dest, Duration::from_secs(10))?;
263	    }
264	    let stem = dest.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or(title);
265	    db.set_clip_path_and_title(clip_id, &dest.to_string_lossy(), &stem)?;
266	    Ok(())
267	}
