320	pub fn remove_dir_if_empty(dir: Option<&Path>) {
321	    if let Some(d) = dir {
322	        if std::fs::read_dir(d).map(|mut r| r.next().is_none()).unwrap_or(false) {
323	            let _ = std::fs::remove_dir(d);
324	        }
325	    }
326	}
