1	//! Audio waveforms for the timeline lanes.
2	//!
3	//! One low-priority ffmpeg pass per media file turns every audio track into a
4	//! loudness envelope (10 values per second per track, 0-255 on a dB scale),
5	//! stored in `%LOCALAPPDATA%\ClipVault\waves\<hash>.cvw`. The file being
6	//! recorded is extended incrementally.
7	
8	use anyhow::{bail, Context, Result};
9	use std::io::Read;
10	use std::path::{Path, PathBuf};
11	use std::process::{Command, Stdio};
12	use std::sync::atomic::{AtomicBool, Ordering};
13	
14	pub const PEAKS_PER_SEC: u32 = 10;
15	/// Envelope sample rate produced by ffmpeg (decimated mean |x|).
16	const ENVELOPE_HZ: u32 = 200;
17	const MAGIC: &[u8; 4] = b"CVW1";
18	/// dB range mapped onto 0..255.
19	const FLOOR_DB: f32 = -54.0;
20	
21	#[derive(Debug, Clone, PartialEq, Default)]
22	pub struct Waveform {
23	    pub tracks: usize,
24	    pub rate: u32,
25	    /// Interleaved: frame-major, `tracks` values per frame.
26	    pub peaks: Vec<u8>,
27	}
28	
29	impl Waveform {
30	    pub fn frames(&self) -> usize {
31	        if self.tracks == 0 {
32	            0
33	        } else {
34	            self.peaks.len() / self.tracks
35	        }
36	    }
37	
38	    pub fn duration_s(&self) -> f64 {
39	        self.frames() as f64 / self.rate.max(1) as f64
40	    }
41	
42	    pub fn get(&self, frame: usize, track: usize) -> u8 {
43	        self.peaks.get(frame * self.tracks + track).copied().unwrap_or(0)
44	    }
45	
46	    /// Loudest value for `track` within `[from_s, to_s)`, looking at no more
47	    /// than `max_samples` frames (strided) so zoomed-out views stay cheap.
48	    pub fn max_in(&self, track: usize, from_s: f64, to_s: f64, max_samples: usize) -> u8 {
49	        if track >= self.tracks || to_s <= 0.0 {
50	            return 0;
51	        }
52	        let r = self.rate as f64;
53	        let a = (from_s.max(0.0) * r).floor() as usize;
54	        let b = ((to_s * r).ceil() as usize).min(self.frames());
55	        if b <= a {
56	            return if a < self.frames() { self.get(a, track) } else { 0 };
57	        }
58	        let step = ((b - a) / max_samples.max(1)).max(1);
59	        (a..b).step_by(step).map(|f| self.get(f, track)).max().unwrap_or(0)
60	    }
61	
62	    pub fn append(&mut self, other: &Waveform) {
63	        if self.tracks == 0 {
64	            *self = other.clone();
65	        } else if other.tracks == self.tracks {
66	            self.peaks.extend_from_slice(&other.peaks);
67	        }
68	    }
69	
70	    pub fn to_bytes(&self) -> Vec<u8> {
71	        let mut v = Vec::with_capacity(16 + self.peaks.len());
72	        v.extend_from_slice(MAGIC);
73	        v.extend_from_slice(&(self.tracks as u32).to_le_bytes());
74	        v.extend_from_slice(&self.rate.to_le_bytes());
75	        v.extend_from_slice(&(self.frames() as u32).to_le_bytes());
76	        v.extend_from_slice(&self.peaks[..self.frames() * self.tracks]);
77	        v
78	    }
79	
80	    pub fn from_bytes(b: &[u8]) -> Result<Waveform> {
81	        if b.len() < 16 || &b[..4] != MAGIC {
82	            bail!("not a waveform file");
83	        }
84	        let rd = |i: usize| u32::from_le_bytes([b[i], b[i + 1], b[i + 2], b[i + 3]]);
85	        let (tracks, rate, frames) = (rd(4) as usize, rd(8), rd(12) as usize);
86	        let need = 16 + tracks * frames;
87	        if tracks == 0 || tracks > 16 || rate == 0 || b.len() < need {
88	            bail!("corrupt waveform file");
89	        }
90	        Ok(Waveform { tracks, rate, peaks: b[16..need].to_vec() })
91	    }
92	
93	    pub fn save(&self, path: &Path) -> Result<()> {
94	        crate::util::write_atomic(path, &self.to_bytes())?;
95	        Ok(())
96	    }
97	
98	    pub fn load(path: &Path) -> Result<Waveform> {
99	        Self::from_bytes(&std::fs::read(path)?)
100	    }
101	}
102	
103	/// Where the waveform for `media` is cached.
104	pub fn wave_path(media: &Path) -> PathBuf {
105	    // FNV-1a over the lower-cased path: stable across runs and processes.
106	    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
107	    for b in media.to_string_lossy().to_lowercase().bytes() {
108	        h ^= b as u64;
109	        h = h.wrapping_mul(0x0100_0000_01b3);
110	    }
111	    crate::paths::data_dir().join("waves").join(format!("{h:016x}.cvw"))
112	}
113	
114	/// Mean |amplitude| (0..1) -> 0..255 on a dB scale.
115	pub fn level_u8(amp: f32) -> u8 {
116	    if !(amp > 0.0) {
117	        return 0;
118	    }
119	    let db = 20.0 * amp.log10();
120	    (((db - FLOOR_DB) / -FLOOR_DB).clamp(0.0, 1.0) * 255.0).round() as u8
121	}
122	
123	/// ffmpeg arguments producing interleaved s16 envelopes for `tracks` audio
124	/// tracks on stdout, starting `from_s` seconds into the file.
125	/// `readrate` (x realtime) throttles disk reads for background backfill.
126	pub fn ffmpeg_args(input: &Path, tracks: usize, from_s: f64, readrate: Option<f64>) -> Vec<String> {
127	    let mut a: Vec<String> = vec!["-hide_banner".into(), "-nostdin".into(), "-loglevel".into(), "error".into()];
128	    if let Some(r) = readrate {
129	        a.push("-readrate".into());
130	        a.push(format!("{r:.0}"));
131	    }
132	    if from_s > 0.0 {
133	        a.push("-ss".into());
134	        a.push(format!("{from_s:.3}"));
135	    }
136	    a.push("-i".into());
137	    a.push(input.to_string_lossy().to_string());
138	    let n = tracks.max(1);
139	    let abs: Vec<String> = (0..n).map(|i| format!("abs(val({i}))")).collect();
140	    let graph = if n == 1 {
141	        format!("[0:a:0]aformat=sample_fmts=fltp:channel_layouts=mono,aeval={}:c=same,aresample={ENVELOPE_HZ}[w]", abs[0])
142	    } else {
143	        let mut g = String::new();
144	        for i in 0..n {
145	            g.push_str(&format!("[0:a:{i}]aformat=sample_fmts=fltp:channel_layouts=mono[m{i}];"));
146	        }
147	        for i in 0..n {
148	            g.push_str(&format!("[m{i}]"));
149	        }
150	        g.push_str(&format!("amerge=inputs={n},aeval={}:c=same,aresample={ENVELOPE_HZ}[w]", abs.join("|")));
151	        g
152	    };
153	    a.extend(["-vn", "-sn", "-dn", "-filter_complex"].iter().map(|s| s.to_string()));
154	    a.push(graph);
155	    a.extend(["-map", "[w]", "-f", "s16le", "pipe:1"].iter().map(|s| s.to_string()));
156	    a
157	}
158	
159	/// Turn the interleaved s16 envelope into 10/s peaks.
160	pub fn peaks_from_envelope(samples: &[i16], tracks: usize) -> Waveform {
161	    let per = (ENVELOPE_HZ / PEAKS_PER_SEC) as usize;
162	    let frames = samples.len() / tracks.max(1);
163	    let out_frames = frames / per;
164	    let mut peaks = Vec::with_capacity(out_frames * tracks);
165	    for f in 0..out_frames {
166	        for t in 0..tracks {
167	            let mut m = 0i32;
168	            for k in 0..per {
169	                let v = (samples[(f * per + k) * tracks + t] as i32).abs();
170	                m = m.max(v);
171	            }
172	            peaks.push(level_u8(m as f32 / 32768.0));
173	        }
174	    }
175	    Waveform { tracks, rate: PEAKS_PER_SEC, peaks }
176	}
177	
178	/// Run ffmpeg and build the waveform. Runs at below-normal priority so it
179	/// never competes with a game.
180	pub fn generate(ffmpeg: &Path, input: &Path, tracks: usize, from_s: f64, readrate: Option<f64>, cancel: &AtomicBool) -> Result<Waveform> {
181	    let tracks = tracks.max(1);
182	    let mut cmd = Command::new(ffmpeg);
183	    cmd.args(ffmpeg_args(input, tracks, from_s, readrate)).stdin(Stdio::null()).stdout(Stdio::piped()).stderr(Stdio::piped());
184	    #[cfg(windows)]
185	    {
186	        use std::os::windows::process::CommandExt;
187	        const CREATE_NO_WINDOW: u32 = 0x0800_0000;
188	        const BELOW_NORMAL_PRIORITY_CLASS: u32 = 0x0000_4000;
189	        cmd.creation_flags(CREATE_NO_WINDOW | BELOW_NORMAL_PRIORITY_CLASS);
190	    }
191	    let mut child = cmd.spawn().context("starting ffmpeg")?;
192	    let stderr = child.stderr.take();
193	    let err_t = std::thread::spawn(move || {
194	        let mut s = String::new();
195	        if let Some(mut e) = stderr {
196	            let _ = e.read_to_string(&mut s);
197	        }
198	        s
199	    });
200	    let mut out = child.stdout.take().context("ffmpeg stdout")?;
201	    let mut bytes = Vec::new();
202	    let mut buf = vec![0u8; 64 * 1024];
203	    loop {
204	        if cancel.load(Ordering::SeqCst) {
205	            let _ = child.kill();
206	            let _ = child.wait();
207	            bail!("cancelled");
208	        }
209	        let n = out.read(&mut buf)?;
210	        if n == 0 {
211	            break;
212	        }
213	        bytes.extend_from_slice(&buf[..n]);
214	    }
215	    let status = child.wait()?;
216	    let err = err_t.join().unwrap_or_default();
217	    if !status.success() {
218	        bail!("ffmpeg waveform failed: {}", err.lines().last().unwrap_or(""));
219	    }
220	    let samples: Vec<i16> = bytes.chunks_exact(2).map(|c| i16::from_le_bytes([c[0], c[1]])).collect();
221	    Ok(peaks_from_envelope(&samples, tracks))
222	}
