1	//! Mapping wall-clock time onto the continuous-recording segment files.
2	
3	use serde::{Deserialize, Serialize};
4	use std::path::PathBuf;
5	
6	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
7	pub struct Segment {
8	    pub path: PathBuf,
9	    /// Wall-clock start (Unix ms).
10	    pub start_ms: i64,
11	    /// Length of the file in ms (for the live file: recorded so far).
12	    pub duration_ms: i64,
13	    pub live: bool,
14	}
15	
16	impl Segment {
17	    pub fn end_ms(&self) -> i64 {
18	        self.start_ms + self.duration_ms.max(0)
19	    }
20	}
21	
22	/// Position inside a segment.
23	#[derive(Debug, Clone, Copy, PartialEq)]
24	pub struct Located {
25	    pub index: usize,
26	    pub offset_ms: i64,
27	    /// The requested time fell into a gap; this is the start of the next segment.
28	    pub snapped: bool,
29	}
30	
31	/// Find the segment containing wall-clock time `t_ms`. `segments` must be
32	/// sorted by start. Times in gaps snap forward to the next segment; times
33	/// after the end snap to the end of the last segment.
34	pub fn locate(segments: &[Segment], t_ms: i64) -> Option<Located> {
35	    if segments.is_empty() {
36	        return None;
37	    }
38	    // Last segment that starts at or before t.
39	    let idx = segments.partition_point(|s| s.start_ms <= t_ms);
40	    if idx == 0 {
41	        return Some(Located { index: 0, offset_ms: 0, snapped: true });
42	    }
43	    let i = idx - 1;
44	    let s = &segments[i];
45	    if t_ms < s.end_ms() {
46	        return Some(Located { index: i, offset_ms: t_ms - s.start_ms, snapped: false });
47	    }
48	    if i + 1 < segments.len() {
49	        return Some(Located { index: i + 1, offset_ms: 0, snapped: true });
50	    }
51	    Some(Located { index: i, offset_ms: s.duration_ms.max(0), snapped: true })
52	}
53	
54	/// Wall-clock time for an offset in a segment.
55	pub fn to_wall(segments: &[Segment], index: usize, offset_ms: i64) -> Option<i64> {
56	    segments.get(index).map(|s| s.start_ms + offset_ms)
57	}
58	
59	/// One piece of a cut that spans one or more files.
60	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
61	pub struct CutPart {
62	    pub path: PathBuf,
63	    /// Seconds into the file where this piece starts.
64	    pub in_s: f64,
65	    /// Seconds into the file where it ends (None = to the end of the file).
66	    pub out_s: Option<f64>,
67	}
68	
69	/// Plan a cut of wall-clock range `[from_ms, to_ms)` across segments.
70	/// Gaps between segments are skipped.
71	pub fn plan_cut(segments: &[Segment], from_ms: i64, to_ms: i64) -> Vec<CutPart> {
72	    let mut parts = Vec::new();
73	    if to_ms <= from_ms {
74	        return parts;
75	    }
76	    for s in segments {
77	        let a = from_ms.max(s.start_ms);
78	        let b = to_ms.min(s.end_ms());
79	        if b <= a {
80	            continue;
81	        }
82	        let in_s = (a - s.start_ms) as f64 / 1000.0;
83	        let out_s = if b >= s.end_ms() && !s.live { None } else { Some((b - s.start_ms) as f64 / 1000.0) };
84	        parts.push(CutPart { path: s.path.clone(), in_s, out_s });
85	    }
86	    parts
87	}
88	
89	/// Total seconds covered by a cut plan (needs the segment durations for
90	/// open-ended parts).
91	pub fn plan_duration_s(parts: &[CutPart], segments: &[Segment]) -> f64 {
92	    parts
93	        .iter()
94	        .map(|p| {
95	            let end = p.out_s.unwrap_or_else(|| {
96	                segments
97	                    .iter()
98	                    .find(|s| s.path == p.path)
99	                    .map(|s| s.duration_ms as f64 / 1000.0)
100	                    .unwrap_or(p.in_s)
101	            });
102	            (end - p.in_s).max(0.0)
103	        })
104	        .sum()
105	}
