115	    #[test]
116	    fn locating() {
117	        let segs = vec![seg("a", 1000, 1000), seg("b", 2000, 1000), seg("c", 5000, 1000)];
118	        assert_eq!(locate(&segs, 1500), Some(Located { index: 0, offset_ms: 500, snapped: false }));
119	        assert_eq!(locate(&segs, 2000), Some(Located { index: 1, offset_ms: 0, snapped: false }));
120	        assert_eq!(locate(&segs, 3500), Some(Located { index: 2, offset_ms: 0, snapped: true }));
121	        assert_eq!(locate(&segs, 500), Some(Located { index: 0, offset_ms: 0, snapped: true }));
122	        assert_eq!(locate(&segs, 9000), Some(Located { index: 2, offset_ms: 1000, snapped: true }));
123	        assert_eq!(locate(&[], 0), None);
