129	        let segs = vec![seg("a", 0, 60_000), seg("b", 60_000, 60_000)];
130	        let p = plan_cut(&segs, 10_000, 20_000);
131	        assert_eq!(p, vec![CutPart { path: "a".into(), in_s: 10.0, out_s: Some(20.0) }]);
132	        assert!((plan_duration_s(&p, &segs) - 10.0).abs() < 1e-9);
