136	    fn cut_spanning_segments_and_gap() {
137	        let segs = vec![seg("a", 0, 60_000), seg("b", 60_000, 60_000), seg("c", 200_000, 60_000)];
138	        let p = plan_cut(&segs, 50_000, 210_000);
139	        assert_eq!(
140	            p,
141	            vec![
142	                CutPart { path: "a".into(), in_s: 50.0, out_s: None },
143	                CutPart { path: "b".into(), in_s: 0.0, out_s: None },
144	                CutPart { path: "c".into(), in_s: 0.0, out_s: Some(10.0) },
145	            ]
146	        );
147	        assert!((plan_duration_s(&p, &segs) - 80.0).abs() < 1e-9);
148	        assert!(plan_cut(&segs, 10, 10).is_empty());
