211	pub fn write_line<T: Serialize>(w: &mut impl Write, msg: &T) -> std::io::Result<()> {
212	    let mut s = serde_json::to_string(msg).map_err(std::io::Error::other)?;
213	    s.push('\n');
214	    w.write_all(s.as_bytes())?;
215	    w.flush()
216	}
