1	//! Library maintenance: index 24/7 recordings, enforce retention, scan the
2	//! clips folder, probe/thumbnail new files, and (once) tidy the folders the
3	//! old program created.
4	
5	use crate::clips::{move_file, probe_and_thumb, remove_dir_if_empty};
6	use crate::shared::{same_path, ClipTask, LibCmd, Shared};
7	use cv_core::db::Db;
8	use cv_core::ipc::Event;
9	use cv_core::model::NewClip;
10	use cv_core::naming::{legacy_folder_to_game, merge_key, sanitize_component, unique_path};
11	use cv_core::obs::filename::{is_replay_file, is_video_file, parse_timestamp_ms};
12	use cv_core::retention::{select_for_deletion, Policy, Reason, SegmentInfo};
13	use cv_core::util::{human_bytes, now_ms, system_time_ms};
14	use std::collections::{HashMap, HashSet};
15	use std::io::Write;
16	use std::path::{Path, PathBuf};
17	use std::sync::Arc;
18	use std::time::{Duration, Instant};
19	
20	pub const KEPT_DIR: &str = "Kept";
21	pub const EXPORTS_DIR: &str = "_Exports";
22	const META_LEGACY_REORG: &str = "legacy_reorg_v1";
23	
24	pub fn run(sh: Arc<Shared>, rx: crossbeam_channel::Receiver<LibCmd>) {
25	    let db = match Db::open_default() {
26	        Ok(d) => d,
27	        Err(e) => {
28	            tracing::error!("library: cannot open database: {e:#}");
29	            return;
30	        }
31	    };
32	    if let Err(e) = legacy_reorganize(&sh, &db) {
33	        tracing::warn!("folder tidy-up failed: {e:#}");
34	    }
35	    let mut last_clip_scan: Option<Instant> = None;
36	    let mut stray_seen: HashMap<PathBuf, Instant> = HashMap::new();
37	    let mut force_scan = true;
38	    loop {
39	        if sh.is_shutting_down() {
40	            break;
41	        }
42	        let rec_changed = index_recordings(&sh, &db, &mut stray_seen);
43	        if rec_changed {
44	            sh.emit(Event::RecordingsChanged);
45	        }
46	        retention(&sh, &db);
47	        let scan_due = last_clip_scan.map(|t| t.elapsed() > Duration::from_secs(300)).unwrap_or(true);
48	        if force_scan || scan_due {
49	            if scan_clips(&sh, &db) {
50	                sh.emit(Event::LibraryChanged);
51	            }
52	            last_clip_scan = Some(Instant::now());
53	            force_scan = false;
54	        }
55	        probe_pending(&sh, &db);
56	        update_disk_status(&sh, &db);
57	
58	        match rx.recv_timeout(Duration::from_secs(30)) {
59	            Ok(LibCmd::Rescan) => force_scan = true,
60	            Ok(LibCmd::RecordingsChanged) => {
61	                // OBS just split/started a file: give it a moment to appear.
62	                std::thread::sleep(Duration::from_millis(1500));
63	            }
64	            Err(crossbeam_channel::RecvTimeoutError::Timeout) => {}
65	            Err(_) => break,
66	        }
67	        while rx.try_recv().is_ok() {}
68	    }
69	}
70	
71	fn list_videos(dir: &Path) -> Vec<PathBuf> {
72	    std::fs::read_dir(dir)
73	        .map(|rd| rd.flatten().map(|e| e.path()).filter(|p| p.is_file() && is_video_file(p)).collect())
74	        .unwrap_or_default()
75	}
76	
77	/// Sync the recordings table with the folder. Returns true if anything changed.
78	fn index_recordings(sh: &Shared, db: &Db, stray_seen: &mut HashMap<PathBuf, Instant>) -> bool {
79	    let cfg = sh.cfg();
80	    let folder = PathBuf::from(&cfg.recording.folder);
81	    if !folder.is_dir() {
82	        return false;
83	    }
84	    let live = sh.status.lock().recording.path.clone();
85	    let live_active = sh.status.lock().recording.active;
86	    let mut changed = false;
87	    let mut present: HashSet<String> = HashSet::new();
88	    let existing: HashMap<String, cv_core::model::Recording> =
89	        db.list_recordings().unwrap_or_default().into_iter().map(|r| (r.path.to_lowercase(), r)).collect();
90	    let now = now_ms();
91	
92	    let mut files: Vec<(PathBuf, bool)> = list_videos(&folder).into_iter().map(|p| (p, false)).collect();
93	    files.extend(list_videos(&folder.join(KEPT_DIR)).into_iter().map(|p| (p, true)));
94	    for (p, kept) in files {
95	        if is_replay_file(&p) {
96	            // A replay that never got filed (e.g. saved while the service was down).
97	            let seen = stray_seen.entry(p.clone()).or_insert_with(Instant::now);
98	            if seen.elapsed() > Duration::from_secs(90) {
99	                let _ = sh.clip_tx.send(ClipTask::ImportStray { path: p.clone() });
100	                stray_seen.remove(&p);
101	            }
102	            continue;
103	        }
104	        let path = p.to_string_lossy().to_string();
105	        present.insert(path.to_lowercase());
106	        let meta = p.metadata().ok();
107	        let size = meta.as_ref().map(|m| m.len() as i64).unwrap_or(0);
108	        let start = parse_timestamp_ms(&p)
109	            .or_else(|| meta.as_ref().and_then(|m| m.created().ok()).map(system_time_ms))
110	            .unwrap_or(now);
111	        let is_live = live_active && !live.is_empty() && same_path(&live, &path);
112	        let status = if is_live { "recording" } else { "complete" };
113	        let prev = existing.get(&path.to_lowercase());
114	        let needs_upsert = prev.map(|r| r.size != size || r.status != status).unwrap_or(true);
115	        let id = if needs_upsert {
116	            changed = true;
117	            match db.upsert_recording(&path, start, size, status) {
118	                Ok(id) => id,
119	                Err(e) => {
120	                    tracing::warn!("index {path}: {e:#}");
121	                    continue;
122	                }
123	            }
124	        } else {
125	            prev.unwrap().id
126	        };
127	        if kept && !prev.map(|r| r.kept).unwrap_or(false) {
128	            let _ = db.set_recording_kept(id, true, &path);
129	            changed = true;
130	        }
131	        // Marked "keep" while it was still being written: move it now.
132	        if !kept && !is_live && prev.map(|r| r.kept).unwrap_or(false) {
133	            if let Some(name) = p.file_name() {
134	                let dest = folder.join(KEPT_DIR).join(name);
135	                if move_file(&p, &dest, Duration::from_secs(5)).is_ok() {
136	                    let _ = db.set_recording_kept(id, true, &dest.to_string_lossy());
137	                    changed = true;
138	                    continue;
139	                }
140	            }
141	        }
142	        if is_live {
143	            let _ = db.set_recording_duration(id, ((now - start) as f64 / 1000.0).max(0.0));
144	        } else if !prev.map(|r| r.probed).unwrap_or(false) {
145	            // Finished file: get its real duration and track count.
146	            let mut dur = 0.0;
147	            let mut tracks = 0;
148	            if let Some(t) = sh.tools() {
149	                if let Ok(info) = t.probe(&p) {
150	                    dur = info.duration;
151	                    tracks = info.audio.len() as i64;
152	                }
153	            }
154	            if dur <= 0.0 {
155	                // Fall back to the file's timestamps.
156	                let modified = meta.as_ref().and_then(|m| m.modified().ok()).map(system_time_ms).unwrap_or(start);
157	                dur = ((modified - start) as f64 / 1000.0).max(0.0);
158	            }
159	            let _ = db.set_recording_probe(id, dur, tracks, true);
160	            changed = true;
161	        }
162	    }
163	    // Forget files that are gone.
164	    for (k, r) in &existing {
165	        if !present.contains(k) {
166	            let _ = db.delete_recording_by_path(&r.path);
167	            changed = true;
168	        }
169	    }
170	    stray_seen.retain(|p, _| p.exists());
171	    changed
172	}
173	
174	fn retention(sh: &Shared, db: &Db) {
175	    let cfg = sh.cfg();
176	    let folder = PathBuf::from(&cfg.recording.folder);
177	    let Some((free, _)) = crate::win::shell::disk_space(&folder) else { return };
178	    let recs = db.list_recordings().unwrap_or_default();
179	    let segments: Vec<SegmentInfo> = recs
180	        .iter()
181	        .map(|r| SegmentInfo {
182	            path: PathBuf::from(&r.path),
183	            start_ms: r.start_ms,
184	            end_ms: if r.duration > 0.0 { r.end_ms() } else { r.start_ms },
185	            size: r.size.max(0) as u64,
186	            in_progress: r.is_live(),
187	            kept: r.kept,
188	        })
189	        .collect();
190	    let plan = select_for_deletion(&segments, now_ms(), free, Policy::from_config(&cfg.recording));
191	    if plan.is_empty() {
192	        return;
193	    }
194	    let mut deleted = 0u64;
195	    let mut count = 0;
196	    let mut reasons = HashSet::new();
197	    for (p, reason) in plan {
198	        // Re-check: never delete the file OBS is writing right now.
199	        let live = sh.status.lock().recording.path.clone();
200	        if !live.is_empty() && same_path(&live, &p.to_string_lossy()) {
201	            continue;
202	        }
203	        let size = p.metadata().map(|m| m.len()).unwrap_or(0);
204	        match std::fs::remove_file(&p) {
205	            Ok(()) => {
206	                let _ = db.delete_recording_by_path(&p.to_string_lossy());
207	                deleted += size;
208	                count += 1;
209	                reasons.insert(reason);
210	            }
211	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
212	                let _ = db.delete_recording_by_path(&p.to_string_lossy());
213	            }
214	            Err(e) => tracing::warn!("could not delete old recording {}: {e}", p.display()),
215	        }
216	    }
217	    if count > 0 {
218	        let why = if reasons.contains(&Reason::LowDisk) {
219	            "to keep free disk space"
220	        } else if reasons.contains(&Reason::TotalSize) {
221	            "to stay under the storage cap"
222	        } else {
223	            "older than the retention window"
224	        };
225	        sh.log_event("info", format!("Deleted {count} old recording(s), {} ({why})", human_bytes(deleted)));
226	        sh.emit(Event::RecordingsChanged);
227	    }
228	}
229	
230	/// Find clips added/removed outside the app. Returns true if anything changed.
231	fn scan_clips(sh: &Shared, db: &Db) -> bool {
232	    let cfg = sh.cfg();
233	    let root = PathBuf::from(&cfg.clips.folder);
234	    if !root.is_dir() {
235	        let _ = std::fs::create_dir_all(&root);
236	        if !root.is_dir() {
237	            return false; // drive missing: don't mark everything as missing
238	        }
239	    }
240	    let _lock = sh.library_lock.lock();
241	    let mut changed = false;
242	    let known: HashMap<String, (i64, bool)> =
243	        db.clip_paths().unwrap_or_default().into_iter().map(|(id, p, m)| (p.to_lowercase(), (id, m))).collect();
244	    let mut found: HashSet<String> = HashSet::new();
245	    let mut files: Vec<(PathBuf, Option<String>)> = list_videos(&root).into_iter().map(|p| (p, None)).collect();
246	    if let Ok(rd) = std::fs::read_dir(&root) {
247	        for e in rd.flatten() {
248	            let p = e.path();
249	            if !p.is_dir() {
250	                continue;
251	            }
252	            let name = e.file_name().to_string_lossy().to_string();
253	            if name.eq_ignore_ascii_case(EXPORTS_DIR) || name.starts_with('.') {
254	                continue;
255	            }
256	            for f in list_videos(&p) {
257	                files.push((f, Some(name.clone())));
258	            }
259	        }
260	    }
261	    let now = now_ms();
262	    for (p, folder) in files {
263	        let key = p.to_string_lossy().to_lowercase();
264	        found.insert(key.clone());
265	        match known.get(&key) {
266	            Some((id, true)) => {
267	                let _ = db.set_clip_missing(*id, false);
268	                changed = true;
269	            }
270	            Some(_) => {}
271	            None => {
272	                if !cfg.clips.import_untracked_files {
273	                    continue;
274	                }
275	                // Skip files still being written.
276	                let modified = p.metadata().and_then(|m| m.modified()).map(system_time_ms).unwrap_or(0);
277	                if now - modified < 10_000 {
278	                    continue;
279	                }
280	                let game_id = folder.as_ref().and_then(|f| game_for_folder(db, f).ok());
281	                let created = parse_timestamp_ms(&p).unwrap_or(modified);
282	                let title = p.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
283	                let size = p.metadata().map(|m| m.len() as i64).unwrap_or(0);
284	                match db.insert_clip(&NewClip {
285	                    path: p.to_string_lossy().to_string(),
286	                    title,
287	                    game_id,
288	                    created_at: created,
289	                    source_start_ms: None,
290	                    size,
291	                    source: "import".into(),
292	                    favorite: false,
293	                }) {
294	                    Ok(_) => changed = true,
295	                    Err(e) => tracing::warn!("import {}: {e:#}", p.display()),
296	                }
297	            }
298	        }
299	    }
300	    for (path, (id, missing)) in &known {
