196	/// Server -> client message.
197	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
198	#[serde(tag = "type", rename_all = "snake_case")]
199	pub enum ServerMsg {
200	    Response { id: u64, ok: bool, #[serde(default)] data: Value, #[serde(default)] error: Option<String> },
201	    Event { event: Event },
202	}
203	
204	/// Client -> server message.
205	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
206	pub struct ClientMsg {
207	    pub id: u64,
208	    pub req: Request,
209	}
210	
211	pub fn write_line<T: Serialize>(w: &mut impl Write, msg: &T) -> std::io::Result<()> {
212	    let mut s = serde_json::to_string(msg).map_err(std::io::Error::other)?;
213	    s.push('\n');
214	    w.write_all(s.as_bytes())?;
215	    w.flush()
216	}
217	
218	type PendingMap = Arc<Mutex<HashMap<u64, Sender<Result<Value, String>>>>>;
219	
220	/// GUI-side connection to the service.
221	pub struct IpcClient {
222	    writer: Mutex<TcpStream>,
223	    pending: PendingMap,
224	    alive: Arc<AtomicBool>,
225	    next: AtomicU64,
226	}
227	
228	impl IpcClient {
229	    pub fn connect(timeout: Duration) -> Result<(IpcClient, Receiver<Event>)> {
230	        let info = IpcInfo::read()?;
231	        Self::connect_to(info.port, &info.token, timeout)
232	    }
233	
234	    pub fn connect_to(port: u16, token: &str, timeout: Duration) -> Result<(IpcClient, Receiver<Event>)> {
235	        let addr: SocketAddr = ([127, 0, 0, 1], port).into();
236	        let stream = TcpStream::connect_timeout(&addr, timeout).context("service is not running")?;
237	        stream.set_nodelay(true).ok();
238	        let reader = stream.try_clone()?;
239	        let (ev_tx, ev_rx) = unbounded();
240	        let pending: PendingMap = Arc::new(Mutex::new(HashMap::new()));
241	        let alive = Arc::new(AtomicBool::new(true));
242	        {
243	            let pending = pending.clone();
244	            let alive = alive.clone();
245	            std::thread::Builder::new()
246	                .name("ipc-client".into())
247	                .spawn(move || {
248	                    let r = BufReader::new(reader);
249	                    for line in r.lines() {
250	                        let Ok(line) = line else { break };
251	                        match serde_json::from_str::<ServerMsg>(&line) {
252	                            Ok(ServerMsg::Response { id, ok, data, error }) => {
253	                                if let Some(tx) = pending.lock().remove(&id) {
254	                                    let _ = tx.send(if ok { Ok(data) } else { Err(error.unwrap_or_default()) });
255	                                }
256	                            }
257	                            Ok(ServerMsg::Event { event }) => {
258	                                let _ = ev_tx.send(event);
259	                            }
260	                            Err(e) => tracing::warn!("bad ipc message: {e}"),
261	                        }
262	                    }
263	                    alive.store(false, Ordering::SeqCst);
264	                    for (_, tx) in pending.lock().drain() {
265	                        let _ = tx.send(Err("disconnected from service".into()));
266	                    }
267	                })?;
268	        }
269	        let client = IpcClient { writer: Mutex::new(stream), pending, alive, next: AtomicU64::new(1) };
270	        client.call(Request::Auth { token: token.to_string() }, timeout)?;
271	        Ok((client, ev_rx))
272	    }
273	
274	    pub fn is_alive(&self) -> bool {
275	        self.alive.load(Ordering::SeqCst)
276	    }
277	
278	    pub fn call(&self, req: Request, timeout: Duration) -> Result<Value> {
279	        if !self.is_alive() {
280	            bail!("disconnected from service");
281	        }
282	        let id = self.next.fetch_add(1, Ordering::SeqCst);
283	        let (tx, rx) = bounded(1);
284	        self.pending.lock().insert(id, tx);
285	        {
286	            let mut w = self.writer.lock();
287	            if let Err(e) = write_line(&mut *w, &ClientMsg { id, req }) {
288	                self.pending.lock().remove(&id);
289	                self.alive.store(false, Ordering::SeqCst);
290	                bail!("send failed: {e}");
291	            }
292	        }
293	        match rx.recv_timeout(timeout) {
294	            Ok(Ok(v)) => Ok(v),
295	            Ok(Err(e)) => bail!("{e}"),
296	            Err(_) => {
297	                self.pending.lock().remove(&id);
298	                bail!("service did not respond")
299	            }
300	        }
301	    }
302	
303	    /// Fire-and-forget: send and return immediately; errors arrive as toasts.
304	    pub fn send(&self, req: Request) -> Result<()> {
305	        let id = self.next.fetch_add(1, Ordering::SeqCst);
306	        let mut w = self.writer.lock();
307	        write_line(&mut *w, &ClientMsg { id, req })?;
308	        Ok(())
309	    }
310	}
311	
312	#[cfg(test)]
313	mod tests {
314	    use super::*;
315	    use std::net::TcpListener;
316	
317	    #[test]
318	    fn wire_format_is_stable() {
319	        let m = ClientMsg { id: 3, req: Request::SaveClip { short: true } };
320	        assert_eq!(serde_json::to_string(&m).unwrap(), r#"{"id":3,"req":{"cmd":"save_clip","short":true}}"#);
321	        let ev = ServerMsg::Event { event: Event::Toast { level: "info".into(), message: "hi".into() } };
322	        let s = serde_json::to_string(&ev).unwrap();
323	        assert_eq!(s, r#"{"type":"event","event":{"kind":"toast","level":"info","message":"hi"}}"#);
324	        let back: ServerMsg = serde_json::from_str(&s).unwrap();
325	        assert_eq!(back, ev);
326	        let st = ServerMsg::Event { event: Event::Status { status: Box::default() } };
327	        let back: ServerMsg = serde_json::from_str(&serde_json::to_string(&st).unwrap()).unwrap();
328	        assert_eq!(back, st);
329	    }
330	
331	    #[test]
332	    fn client_roundtrip_with_fake_server() {
333	        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
334	        let port = listener.local_addr().unwrap().port();
335	        std::thread::spawn(move || {
336	            let (s, _) = listener.accept().unwrap();
337	            let mut w = s.try_clone().unwrap();
338	            let r = BufReader::new(s);
339	            for line in r.lines() {
340	                let msg: ClientMsg = serde_json::from_str(&line.unwrap()).unwrap();
341	                let reply = match msg.req {
342	                    Request::Auth { token } if token == "tok" => ServerMsg::Response { id: msg.id, ok: true, data: Value::Null, error: None },
343	                    Request::Auth { .. } => ServerMsg::Response { id: msg.id, ok: false, data: Value::Null, error: Some("bad token".into()) },
344	                    Request::Status => {
345	                        write_line(&mut w, &ServerMsg::Event { event: Event::LibraryChanged }).unwrap();
346	                        ServerMsg::Response { id: msg.id, ok: true, data: serde_json::json!({"x": 1}), error: None }
347	                    }
348	                    _ => ServerMsg::Response { id: msg.id, ok: false, data: Value::Null, error: Some("unsupported".into()) },
349	                };
350	                write_line(&mut w, &reply).unwrap();
351	            }
352	        });
353	        let (c, events) = IpcClient::connect_to(port, "tok", Duration::from_secs(2)).unwrap();
354	        let v = c.call(Request::Status, Duration::from_secs(2)).unwrap();
355	        assert_eq!(v["x"], 1);
356	        assert_eq!(events.recv_timeout(Duration::from_secs(2)).unwrap(), Event::LibraryChanged);
357	        let e = c.call(Request::RestartObs, Duration::from_secs(2)).unwrap_err();
358	        assert!(e.to_string().contains("unsupported"));
359	    }
360	
361	    #[test]
362	    fn bad_token_rejected() {
363	        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
364	        let port = listener.local_addr().unwrap().port();
365	        std::thread::spawn(move || {
366	            let (s, _) = listener.accept().unwrap();
367	            let mut w = s.try_clone().unwrap();
368	            let mut line = String::new();
369	            BufReader::new(s).read_line(&mut line).unwrap();
370	            let msg: ClientMsg = serde_json::from_str(&line).unwrap();
371	            write_line(&mut w, &ServerMsg::Response { id: msg.id, ok: false, data: Value::Null, error: Some("bad token".into()) }).unwrap();
372	        });
373	        assert!(IpcClient::connect_to(port, "nope", Duration::from_secs(2)).is_err());
374	    }
375	}
