310	fn game_for_folder(db: &Db, folder: &str) -> anyhow::Result<i64> {
311	    let name = legacy_folder_to_game(folder);
312	    if let Some(g) = db.game_by_name(&name)? {
313	        return Ok(g.id);
314	    }
315	    db.upsert_game(&format!("folder:{}", merge_key(&name)), &name, "", true, now_ms())
