318	fn probe_pending(sh: &Shared, db: &Db) {
319	    let pending = db.unprobed_clips(16).unwrap_or_default();
320	    if pending.is_empty() {
321	        return;
322	    }
323	    let Some(tools) = sh.tools() else { return };
324	    let thumbs = sh.cfg.read().clips.generate_thumbnails;
325	    let mut any = false;
326	    for (id, path) in pending {
327	        if sh.is_shutting_down() {
328	            break;
329	        }
330	        let p = PathBuf::from(&path);
331	        if p.is_file() {
332	            probe_and_thumb(db, &tools, id, &p, thumbs);
333	            any = true;
334	        }
335	    }
336	    if any {
337	        sh.emit(Event::LibraryChanged);
338	    }
