341	fn update_disk_status(sh: &Shared, db: &Db) {
342	    let cfg = sh.cfg();
343	    let recs = db.list_recordings().unwrap_or_default();
344	    let (clips_count, clips_bytes) = db.clip_stats().unwrap_or((0, 0));
345	    let (free, total) = crate::win::shell::disk_space(Path::new(&cfg.recording.folder)).unwrap_or((0, 0));
346	    sh.update_status(|s| {
347	        s.disk.free_bytes = free;
348	        s.disk.total_bytes = total;
349	        s.disk.recordings_bytes = recs.iter().map(|r| r.size.max(0) as u64).sum();
350	        s.disk.recordings_count = recs.len() as u32;
351	        s.disk.oldest_ms = recs.iter().map(|r| r.start_ms).min();
352	        s.disk.clips_count = clips_count as u32;
353	        s.disk.clips_bytes = clips_bytes as u64;
354	    });
355	}
