357	/// One-time: merge folders the old program created from raw window titles
358	/// (e.g. six "ARC Raiders" folders full of invisible characters) into clean
359	/// per-game folders. Every move is logged to `migration.log` in the data dir.
360	fn legacy_reorganize(sh: &Shared, db: &Db) -> anyhow::Result<()> {
361	    if db.meta_get(META_LEGACY_REORG)?.is_some() {
362	        return Ok(());
363	    }
364	    let cfg = sh.cfg();
365	    let root = PathBuf::from(&cfg.clips.folder);
366	    if !root.is_dir() {
367	        return Ok(()); // try again next start
368	    }
369	    let _lock = sh.library_lock.lock();
370	    let log_path = cv_core::paths::data_dir().join("migration.log");
371	    let mut log = std::fs::OpenOptions::new().create(true).append(true).open(&log_path)?;
372	    writeln!(log, "== folder tidy-up {} ==", chrono::Local::now().format("%Y-%m-%d %H:%M:%S"))?;
373	    let mut moved = 0;
374	    let mut dirs: Vec<PathBuf> = std::fs::read_dir(&root)?.flatten().map(|e| e.path()).filter(|p| p.is_dir()).collect();
375	    dirs.sort();
376	    for dir in dirs {
377	        let name = dir.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
378	        if name.eq_ignore_ascii_case(EXPORTS_DIR) {
379	            continue;
380	        }
381	        let clean = sanitize_component(&legacy_folder_to_game(&name));
382	        if clean == name {
383	            continue;
384	        }
385	        let target = root.join(&clean);
386	        for f in std::fs::read_dir(&dir)?.flatten().map(|e| e.path()) {
387	            if !f.is_file() {
388	                continue;
389	            }
390	            let stem = f.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
391	            let ext = f.extension().map(|e| e.to_string_lossy().to_string()).unwrap_or_default();
392	            let dest = unique_path(&target, &stem, &ext, None);
393	            match move_file(&f, &dest, Duration::from_secs(5)) {
394	                Ok(()) => {
395	                    writeln!(log, "{} -> {}", f.display(), dest.display())?;
396	                    if let Some(c) = db.clip_by_path(&f.to_string_lossy())? {
397	                        db.set_clip_path_and_title(c.id, &dest.to_string_lossy(), &c.title)?;
398	                    }
399	                    moved += 1;
400	                }
401	                Err(e) => writeln!(log, "FAILED {}: {e:#}", f.display())?,
402	            }
403	        }
404	        remove_dir_if_empty(Some(&dir));
405	    }
406	    db.meta_set(META_LEGACY_REORG, &now_ms().to_string())?;
407	    if moved > 0 {
408	        sh.log_event("info", format!("Tidied {moved} old clip(s) into per-game folders (see migration.log)"));
409	    }
410	    Ok(())
411	}
412	
413	/// Move a recording into/out of the Kept folder (protected from retention).
414	pub fn set_kept(sh: &Shared, recording_id: i64, keep: bool) -> anyhow::Result<()> {
415	    let db = Db::open_default()?;
416	    let rec = db.recording(recording_id)?.ok_or_else(|| anyhow::anyhow!("recording not found"))?;
417	    anyhow::ensure!(!rec.is_live() || keep, "can't move the recording that's being written");
418	    let src = PathBuf::from(&rec.path);
419	    let folder = PathBuf::from(&sh.cfg.read().recording.folder);
420	    let dest_dir = if keep { folder.join(KEPT_DIR) } else { folder };
421	    if rec.is_live() {
422	        // Can't move a file OBS is writing: flag it, the move happens later.
423	        db.set_recording_kept(recording_id, true, &rec.path)?;
424	        return Ok(());
425	    }
426	    let name = src.file_name().map(|n| n.to_owned()).unwrap_or_default();
427	    let dest = dest_dir.join(name);
428	    move_file(&src, &dest, Duration::from_secs(10))?;
429	    db.set_recording_kept(recording_id, keep, &dest.to_string_lossy())?;
430	    sh.emit(Event::RecordingsChanged);
431	    Ok(())
432	}
