98	            let n = coll.GetCount().unwrap_or(0);
99	            for i in 0..n {
100	                let Ok(dev) = coll.Item(i) else { continue };
101	                let (Some(id), Some(name)) = (device_id(&dev), device_name(&dev)) else { continue };
102	                out.push((Endpoint { id, name }, dev));
103	            }
104	        }
