1	//! Windows Core Audio: endpoint enumeration, change notifications, and which
2	//! processes are playing audio on which output device.
3	
4	use cv_core::audio_names::Endpoint;
5	use crossbeam_channel::Sender;
6	use std::collections::{HashMap, HashSet};
7	use windows::core::{implement, Interface, PCWSTR};
8	use windows::Win32::Devices::FunctionDiscovery::PKEY_Device_FriendlyName;
9	use windows::Win32::Media::Audio::{
10	    eCapture, eConsole, eRender, AudioSessionStateExpired, EDataFlow, ERole, IAudioSessionControl2,
11	    IAudioSessionManager2, IMMDevice, IMMDeviceEnumerator, IMMNotificationClient, IMMNotificationClient_Impl,
12	    MMDeviceEnumerator, DEVICE_STATE, DEVICE_STATE_ACTIVE,
13	};
14	use windows::Win32::System::Com::StructuredStorage::PropVariantToStringAlloc;
15	use windows::Win32::System::Com::{CoCreateInstance, CoInitializeEx, CoTaskMemFree, CLSCTX_ALL, COINIT_MULTITHREADED, STGM_READ};
16	use windows::Win32::UI::Shell::PropertiesSystem::PROPERTYKEY;
17	
18	/// Initialise COM (multithreaded) on the current thread.
19	pub fn com_init_mta() {
20	    unsafe {
21	        let _ = CoInitializeEx(None, COINIT_MULTITHREADED);
22	    }
23	}
24	
25	pub struct AudioSystem {
26	    enumerator: IMMDeviceEnumerator,
27	    _client: Option<IMMNotificationClient>,
28	}
29	
30	#[implement(IMMNotificationClient)]
31	struct DeviceWatcher {
32	    tx: Sender<()>,
33	}
34	
35	impl IMMNotificationClient_Impl for DeviceWatcher_Impl {
36	    fn OnDeviceStateChanged(&self, _id: &PCWSTR, _state: DEVICE_STATE) -> windows::core::Result<()> {
37	        let _ = self.tx.try_send(());
38	        Ok(())
39	    }
40	    fn OnDeviceAdded(&self, _id: &PCWSTR) -> windows::core::Result<()> {
41	        let _ = self.tx.try_send(());
42	        Ok(())
43	    }
44	    fn OnDeviceRemoved(&self, _id: &PCWSTR) -> windows::core::Result<()> {
45	        let _ = self.tx.try_send(());
46	        Ok(())
47	    }
48	    fn OnDefaultDeviceChanged(&self, _flow: EDataFlow, _role: ERole, _id: &PCWSTR) -> windows::core::Result<()> {
49	        let _ = self.tx.try_send(());
50	        Ok(())
51	    }
52	    fn OnPropertyValueChanged(&self, _id: &PCWSTR, _key: &PROPERTYKEY) -> windows::core::Result<()> {
53	        Ok(())
54	    }
55	}
56	
57	fn device_id(dev: &IMMDevice) -> Option<String> {
58	    unsafe {
59	        let p = dev.GetId().ok()?;
60	        let s = p.to_string().ok();
61	        CoTaskMemFree(Some(p.0 as *const _));
62	        s
63	    }
64	}
65	
66	fn device_name(dev: &IMMDevice) -> Option<String> {
67	    unsafe {
68	        let store = dev.OpenPropertyStore(STGM_READ).ok()?;
69	        let pv = store.GetValue(&PKEY_Device_FriendlyName).ok()?;
70	        let p = PropVariantToStringAlloc(&pv).ok()?;
71	        let s = p.to_string().ok();
72	        CoTaskMemFree(Some(p.0 as *const _));
73	        s
74	    }
75	}
76	
77	impl AudioSystem {
78	    /// `change_tx` receives a unit message whenever devices change.
79	    pub fn new(change_tx: Option<Sender<()>>) -> windows::core::Result<AudioSystem> {
80	        unsafe {
81	            let enumerator: IMMDeviceEnumerator = CoCreateInstance(&MMDeviceEnumerator, None, CLSCTX_ALL)?;
82	            let client = match change_tx {
83	                Some(tx) => {
84	                    let c: IMMNotificationClient = DeviceWatcher { tx }.into();
85	                    enumerator.RegisterEndpointNotificationCallback(&c)?;
86	                    Some(c)
87	                }
88	                None => None,
89	            };
90	            Ok(AudioSystem { enumerator, _client: client })
91	        }
92	    }
93	
94	    fn list(&self, flow: EDataFlow) -> Vec<(Endpoint, IMMDevice)> {
95	        let mut out = Vec::new();
96	        unsafe {
97	            let Ok(coll) = self.enumerator.EnumAudioEndpoints(flow, DEVICE_STATE_ACTIVE) else { return out };
98	            let n = coll.GetCount().unwrap_or(0);
99	            for i in 0..n {
100	                let Ok(dev) = coll.Item(i) else { continue };
101	                let (Some(id), Some(name)) = (device_id(&dev), device_name(&dev)) else { continue };
102	                out.push((Endpoint { id, name }, dev));
103	            }
104	        }
105	        out
106	    }
107	
108	    pub fn inputs(&self) -> Vec<Endpoint> {
109	        self.list(eCapture).into_iter().map(|(e, _)| e).collect()
110	    }
111	
112	    pub fn outputs(&self) -> Vec<Endpoint> {
113	        self.list(eRender).into_iter().map(|(e, _)| e).collect()
114	    }
115	
116	    pub fn default_endpoint(&self, capture: bool) -> Option<Endpoint> {
117	        unsafe {
118	            let dev = self
119	                .enumerator
120	                .GetDefaultAudioEndpoint(if capture { eCapture } else { eRender }, eConsole)
121	                .ok()?;
122	            Some(Endpoint { id: device_id(&dev)?, name: device_name(&dev)? })
123	        }
124	    }
125	
126	    /// For every active output device: the set of process ids with a live
127	    /// (non-expired) audio session on it.
128	    pub fn sessions_by_output(&self) -> HashMap<String, HashSet<u32>> {
129	        let mut out = HashMap::new();
130	        for (ep, dev) in self.list(eRender) {
131	            let mut pids = HashSet::new();
132	            unsafe {
133	                let Ok(mgr) = dev.Activate::<IAudioSessionManager2>(CLSCTX_ALL, None) else { continue };
134	                let Ok(en) = mgr.GetSessionEnumerator() else { continue };
135	                let n = en.GetCount().unwrap_or(0);
136	                for i in 0..n {
137	                    let Ok(ctl) = en.GetSession(i) else { continue };
138	                    if ctl.GetState().map(|s| s == AudioSessionStateExpired).unwrap_or(true) {
139	                        continue;
140	                    }
141	                    let Ok(ctl2) = ctl.cast::<IAudioSessionControl2>() else { continue };
142	                    if let Ok(pid) = ctl2.GetProcessId() {
143	                        if pid != 0 {
144	                            pids.insert(pid);
145	                        }
146	                    }
147	                }
148	            }
149	            out.insert(ep.id, pids);
150	        }
151	        out
152	    }
153	}
154

1	//! Mic guard + audio routing.
2	//!
3	//! Watches Windows audio devices. Whenever something changes (headset
4	//! unplugged/replugged, default device switched, new endpoint registered) it
5	//! recomputes which microphone OBS should record and tells the supervisor,
6	//! which re-points OBS within a second or two.
7	
8	use crate::shared::{Shared, SupCmd};
9	use crate::win::coreaudio::{com_init_mta, AudioSystem};
10	use crate::win::process;
11	use cv_core::audio_names::{decide_mic, pick_preferred, MicDecision};
12	use cv_core::ipc::AudioDevices;
13	use std::collections::{HashMap, HashSet};
14	use std::sync::Arc;
15	use std::time::Duration;
16	
17	pub fn run(sh: Arc<Shared>, trigger_rx: crossbeam_channel::Receiver<()>) {
18	    com_init_mta();
19	    let (change_tx, change_rx) = crossbeam_channel::bounded::<()>(64);
20	    let sys = match AudioSystem::new(Some(change_tx)) {
21	        Ok(s) => s,
22	        Err(e) => {
23	            tracing::error!("audio guard: Core Audio unavailable: {e}");
24	            return;
25	        }
26	    };
27	    let mut last_mic: Option<MicDecision> = None;
28	    let mut last_desktop: Option<String> = None;
29	    let mut last_routing: Option<HashMap<String, bool>> = None;
30	    let mut first = true;
31	    while !sh.is_shutting_down() {
32	        if !first {
33	            crossbeam_channel::select! {
34	                recv(change_rx) -> _ => {
35	                    // Devices often change in bursts; let things settle.
36	                    std::thread::sleep(Duration::from_millis(1200));
37	                    while change_rx.try_recv().is_ok() {}
38	                }
39	                recv(trigger_rx) -> _ => { while trigger_rx.try_recv().is_ok() {} }
40	                default(Duration::from_secs(5)) => {}
41	            }
42	        }
43	        first = false;
44	        let cfg = sh.cfg();
45	        let inputs = sys.inputs();
46	        let outputs = sys.outputs();
47	        let def_in = sys.default_endpoint(true);
48	        let def_out = sys.default_endpoint(false);
49	        *sh.devices.lock() = AudioDevices {
50	            inputs: inputs.clone(),
51	            outputs: outputs.clone(),
52	            default_input: def_in.as_ref().map(|e| e.name.clone()),
53	            default_output: def_out.as_ref().map(|e| e.name.clone()),
54	        };
55	
56	        // Microphone.
57	        if cfg.audio.mic_guard {
58	            let d = decide_mic(&cfg.audio.mic_priority, &inputs, &cfg.audio.mic_fallback);
59	            if last_mic.as_ref() != Some(&d) {
60	                if let Some(prev) = &last_mic {
61	                    let was_ok = matches!(prev, MicDecision::Preferred { rank: 0, .. });
62	                    let now_ok = matches!(d, MicDecision::Preferred { rank: 0, .. });
63	                    if was_ok && !now_ok && !cfg.audio.mic_priority.is_empty() {
64	                        sh.log_event("warn", "Preferred microphone disconnected");
65	                    } else if !was_ok && now_ok {
66	                        sh.log_event("info", "Preferred microphone reconnected");
67	                    }
68	                }
69	                last_mic = Some(d.clone());
70	                let _ = sh.sup_tx.send(SupCmd::Mic { decision: d });
71	            }
72	        }
73	
74	        // Desktop audio device.
75	        let desktop_id = if cfg.audio.desktop_device.eq_ignore_ascii_case("default") {
76	            "default".to_string()
77	        } else {
78	            pick_preferred(&[cfg.audio.desktop_device.clone()], &outputs)
79	                .map(|(_, e)| e.id.clone())
80	                .unwrap_or_else(|| "default".to_string())
81	        };
82	        if last_desktop.as_deref() != Some(desktop_id.as_str()) {
83	            last_desktop = Some(desktop_id.clone());
84	            let _ = sh.sup_tx.send(SupCmd::DesktopDevice { device_id: desktop_id.clone() });
85	        }
86	
87	        // Apps playing on a device other than the desktop-audio one must be
88	        // added to the full mix, or they'd be missing from it.
89	        if cfg.audio.multitrack && cfg.audio.auto_mix_other_devices {
90	            let desktop_endpoint = if desktop_id == "default" { def_out.as_ref().map(|e| e.id.clone()) } else { Some(desktop_id.clone()) };
91	            let sessions = sys.sessions_by_output();
92	            let names: HashMap<u32, String> = process::list_processes().into_iter().map(|p| (p.pid, p.exe_name.to_lowercase())).collect();
93	            let mut apps: HashSet<String> = cfg.audio.voice_apps.iter().chain(cfg.audio.music_apps.iter()).map(|s| s.to_lowercase()).collect();
94	            if let Some(exe) = current_game_exe(&sh) {
95	                apps.insert(exe);
96	            }
97	            let mut routing = HashMap::new();
98	            for app in apps {
99	                let mut on_desktop = false;
100	                let mut elsewhere = false;
101	                for (ep, pids) in &sessions {
102	                    let has = pids.iter().any(|p| names.get(p).map(|n| *n == app).unwrap_or(false));
103	                    if !has {
104	                        continue;
105	                    }
106	                    if Some(ep) == desktop_endpoint.as_ref() {
107	                        on_desktop = true;
108	                    } else {
109	                        elsewhere = true;
110	                    }
111	                }
112	                routing.insert(app, elsewhere && !on_desktop);
113	            }
114	            if last_routing.as_ref() != Some(&routing) {
115	                if routing.values().any(|v| *v) {
116	                    tracing::info!("apps on other devices added to full mix: {:?}", routing.iter().filter(|(_, v)| **v).map(|(k, _)| k).collect::<Vec<_>>());
117	                }
118	                last_routing = Some(routing.clone());
119	                let _ = sh.sup_tx.send(SupCmd::AppRouting(routing));
120	            }
121	        }
122	    }
123	}
124	
125	/// Exe of the game the "Game" track currently follows (looked up by name).
126	fn current_game_exe(sh: &Shared) -> Option<String> {
127	    let name = sh.status.lock().game.audio_target.clone()?;
128	    let db = cv_core::db::Db::open_default().ok()?;
129	    let g = db.game_by_name(&name).ok().flatten()?;
130	    let exe = cv_core::games::exe_name_of(&g.exe_path);
131	    (!exe.is_empty()).then_some(exe)
132	}
