1	//! Tracks which app/game is in the foreground, second by second.
2	//!
3	//! This history powers: naming clips after the right game, the game bands on
4	//! the 24/7 timeline, and pointing the "Game" audio track at the game.
5	
6	use crate::shared::{GameTarget, Shared, SupCmd};
7	use crate::win::foreground::{self, ExeCache};
8	use cv_core::db::Db;
9	use cv_core::games::{self, Classifier, WindowInfo};
10	use cv_core::util::now_ms;
11	use std::collections::HashMap;
12	use std::sync::Arc;
13	use std::time::{Duration, Instant};
14	
15	struct OpenSpan {
16	    key: String,
17	    id: i64,
18	    last_seen: i64,
19	    last_flush: i64,
20	    title: String,
21	}
22	
23	struct GameCacheEntry {
24	    id: i64,
25	    name: String,
26	    is_game: bool,
27	    refreshed: Instant,
28	}
29	
30	pub fn run(sh: Arc<Shared>) {
31	    let db = match Db::open_default() {
32	        Ok(d) => d,
33	        Err(e) => {
34	            tracing::error!("activity tracker: cannot open database: {e:#}");
35	            return;
36	        }
37	    };
38	    let mut exe_cache = ExeCache::default();
39	    let mut games_cache: HashMap<String, GameCacheEntry> = HashMap::new();
40	    let mut classifier = make_classifier(&sh, &db);
41	    let mut classifier_built = Instant::now();
42	    let mut span: Option<OpenSpan> = None;
43	    let mut focus: Option<(String, Instant)> = None;
44	    let mut target_key: Option<String> = None;
45	    let mut last_game_name: Option<(String, Instant)> = None;
46	    let mut last_prune = Instant::now() - Duration::from_secs(3600);
47	
48	    while !sh.is_shutting_down() {
49	        let cfg = sh.cfg();
50	        std::thread::sleep(Duration::from_millis(cfg.advanced.activity_sample_ms as u64));
51	        let now = now_ms();
52	        if classifier_built.elapsed() > Duration::from_secs(30) {
53	            classifier = make_classifier(&sh, &db);
54	            classifier_built = Instant::now();
55	            games_cache.retain(|_, g| g.refreshed.elapsed() < Duration::from_secs(600));
56	        }
57	
58	        let fg = foreground::foreground(&mut exe_cache);
59	        let Some((info, _hwnd)) = fg else {
60	            // Nothing focused (desktop/lock screen): close the span after a grace period.
61	            if let Some(s) = &span {
62	                if now - s.last_seen > 3000 {
63	                    let _ = db.extend_activity(s.id, s.last_seen, None);
64	                    span = None;
65	                }
66	            }
67	            continue;
68	        };
69	        if info.exe_path.is_empty() {
70	            continue; // elevated/protected process we can't inspect
71	        }
72	        let key = games::game_key(&info);
73	        let verdict = classifier.classify(&info);
74	        let is_game = verdict.is_game();
75	
76	        // Resolve the game row (cached).
77	        let entry = match games_cache.get(&key) {
78	            Some(e) if e.is_game == is_game => e,
79	            _ => {
80	                let name = resolve_name(&key, &info);
81	                match db.upsert_game(&key, &name, &info.exe_path, is_game, now) {
82	                    Ok(id) => {
83	                        let name = db.game(id).ok().flatten().map(|g| g.name).unwrap_or(name);
84	                        games_cache.insert(key.clone(), GameCacheEntry { id, name, is_game, refreshed: Instant::now() });
85	                    }
86	                    Err(e) => {
87	                        tracing::warn!("activity db: {e:#}");
88	                        continue;
89	                    }
90	                }
91	                games_cache.get(&key).unwrap()
92	            }
93	        };
94	        let (game_id, game_name) = (entry.id, entry.name.clone());
95	
96	        // Extend or start the activity span.
97	        let title = cv_core::naming::strip_invisible(&info.title);
98	        match &mut span {
99	            Some(s) if s.key == key && now - s.last_seen < 5000 => {
100	                s.last_seen = now;
101	                if now - s.last_flush > 10_000 || s.title != title {
102	                    let t = if s.title != title { Some(title.as_str()) } else { None };
103	                    let _ = db.extend_activity(s.id, now, t);
104	                    s.last_flush = now;
105	                    s.title = title.clone();
106	                }
107	            }
108	            _ => {
109	                if let Some(s) = &span {
110	                    let _ = db.extend_activity(s.id, s.last_seen, None);
111	                }
112	                match db.start_activity(&key, Some(game_id), is_game, &title, now) {
113	                    Ok(id) => span = Some(OpenSpan { key: key.clone(), id, last_seen: now, last_flush: now, title }),
114	                    Err(e) => tracing::warn!("activity db: {e:#}"),
115	                }
116	            }
117	        }
118	
119	        // Status: current game (sticky for 5 minutes after leaving it).
120	        if is_game {
121	            last_game_name = Some((game_name.clone(), Instant::now()));
122	        }
123	        let current = last_game_name
124	            .as_ref()
125	            .filter(|(_, t)| t.elapsed() < Duration::from_secs(300))
126	            .map(|(n, _)| n.clone());
127	        sh.update_status(|s| s.game.current = current);
128	
129	        // Game audio follows a game once it's been focused for a moment.
130	        if is_game && cfg.audio.game_audio_capture {
131	            match &focus {
132	                Some((k, since)) if *k == key => {
133	                    if since.elapsed() >= Duration::from_secs(cfg.games.audio_follow_delay_secs as u64)
134	                        && target_key.as_deref() != Some(key.as_str())
135	                    {
136	                        target_key = Some(key.clone());
137	                        let _ = sh.sup_tx.send(SupCmd::GameTarget(GameTarget {
138	                            exe: if info.exe_name.is_empty() { games::exe_name_of(&info.exe_path) } else { info.exe_name.clone() },
139	                            title: info.title.clone(),
140	                            class: info.class.clone(),
141	                            name: game_name.clone(),
142	                        }));
143	                        let _ = sh.audio_tx.try_send(());
144	                    }
145	                }
146	                _ => focus = Some((key.clone(), Instant::now())),
147	            }
148	        } else {
149	            focus = None;
150	        }
151	
152	        if last_prune.elapsed() > Duration::from_secs(3600) {
153	            last_prune = Instant::now();
154	            let keep_days = cfg.advanced.activity_history_days.max(cfg.recording.retention_hours.div_ceil(24) + 1);
155	            let _ = db.prune_activity(now - keep_days as i64 * 86_400_000);
156	            let _ = db.prune_markers(now - keep_days as i64 * 86_400_000);
157	        }
158	    }
159	    if let Some(s) = span {
160	        let _ = db.extend_activity(s.id, s.last_seen, None);
161	    }
162	}
163	
164	fn make_classifier(sh: &Shared, db: &Db) -> Classifier {
165	    let overrides = db.game_overrides().unwrap_or_default();
166	    Classifier::new(&sh.cfg.read().games, overrides)
167	}
168	
169	fn resolve_name(key: &str, info: &WindowInfo) -> String {
170	    let steam = games::steam_name_for_exe(&info.exe_path);
171	    let (product, desc) = foreground::version_strings(&info.exe_path);
172	    games::friendly_name(key, &info.exe_path, steam.as_deref(), product.as_deref(), desc.as_deref())
173	}
