1	//! Well-known file locations.
2	//!
3	//! All mutable app state lives in `%LOCALAPPDATA%\ClipVault` (override with the
4	//! `CLIPVAULT_DATA_DIR` environment variable, used by tests and portable setups).
5	
6	use std::path::{Path, PathBuf};
7	
8	pub fn data_dir() -> PathBuf {
9	    if let Ok(dir) = std::env::var("CLIPVAULT_DATA_DIR") {
10	        if !dir.trim().is_empty() {
11	            return PathBuf::from(dir);
12	        }
13	    }
14	    let base = std::env::var_os("LOCALAPPDATA")
15	        .map(PathBuf::from)
16	        .unwrap_or_else(|| PathBuf::from("."));
17	    base.join(crate::APP_NAME)
18	}
19	
20	pub fn config_path() -> PathBuf {
21	    data_dir().join("config.toml")
22	}
23	
24	pub fn db_path() -> PathBuf {
25	    data_dir().join("library.db")
26	}
27	
28	pub fn logs_dir() -> PathBuf {
29	    data_dir().join("logs")
30	}
31	
32	pub fn thumbs_dir() -> PathBuf {
33	    data_dir().join("thumbs")
34	}
35	
36	pub fn temp_dir() -> PathBuf {
37	    data_dir().join("tmp")
38	}
39	
40	/// Written by the service; tells the GUI which port/token to use.
41	pub fn ipc_info_path() -> PathBuf {
42	    data_dir().join("ipc.json")
43	}
44	
45	pub fn ensure_dirs() -> std::io::Result<()> {
46	    for d in [data_dir(), logs_dir(), thumbs_dir(), temp_dir()] {
47	        std::fs::create_dir_all(d)?;
48	    }
49	    Ok(())
50	}
51	
52	/// Directory containing the running executable.
53	pub fn exe_dir() -> PathBuf {
54	    std::env::current_exe()
55	        .ok()
56	        .and_then(|p| p.parent().map(Path::to_path_buf))
57	        .unwrap_or_else(|| PathBuf::from("."))
58	}
59	
60	/// Look for a resource shipped next to the executable (or in `assets/` beside it,
61	/// or — during development — in the workspace `assets/` folder).
62	pub fn find_resource(name: &str) -> Option<PathBuf> {
63	    let exe = exe_dir();
64	    let mut candidates = vec![exe.join(name), exe.join("assets").join(name)];
65	    // target/{debug,release}/ -> workspace root
66	    if let Some(root) = exe.parent().and_then(Path::parent) {
67	        candidates.push(root.join("assets").join(name));
68	        candidates.push(root.join("third_party").join(name));
69	    }
70	    candidates.into_iter().find(|p| p.is_file())
71	}
72	
73	/// OBS's configuration directory (`%APPDATA%\obs-studio` unless overridden).
74	pub fn obs_config_dir(override_dir: &str) -> PathBuf {
75	    if !override_dir.trim().is_empty() {
76	        return PathBuf::from(override_dir.trim());
77	    }
78	    std::env::var_os("APPDATA")
79	        .map(PathBuf::from)
80	        .unwrap_or_else(|| PathBuf::from("."))
81	        .join("obs-studio")
82	}
83	
84	/// The user's Startup folder (for the "start with Windows" shortcut).
85	pub fn startup_dir() -> Option<PathBuf> {
86	    std::env::var_os("APPDATA").map(|a| {
87	        PathBuf::from(a)
88	            .join("Microsoft")
89	            .join("Windows")
90	            .join("Start Menu")
91	            .join("Programs")
92	            .join("Startup")
93	    })
94	}
95	
96	pub fn start_menu_dir() -> Option<PathBuf> {
97	    std::env::var_os("APPDATA").map(|a| {
98	        PathBuf::from(a)
99	            .join("Microsoft")
100	            .join("Windows")
101	            .join("Start Menu")
102	            .join("Programs")
103	    })
104	}
105	
