        let t = &mut self.tracks[idx];
        t.samples.push(Entry { size: s.data.len() as u32, duration: s.duration, sync: s.sync, cts: s.cts });
        let new_chunk = self.last_track != Some(idx) || t.chunks.last().map(|c| c.1 >= 512).unwrap_or(true);
