        if moov.len() == 0 {
            let probe = build_moov(&self.tracks, self.created, 0, true);
            let base = ftyp_len + probe.len() as u64 + meta_len + mdat_hdr;
            moov = build_moov(&self.tracks, self.created, base, true);
        }
        head.bytes(&moov.0);
        if let Some(m) = meta {
            write_meta_box(&mut head, m);
        }
        if large_mdat {
            head.u32(1);
            head.bytes(b"mdat");
            head.u64(self.data_len + 16);
        } else {
            head.u32((self.data_len + 8) as u32);
            head.bytes(b"mdat");
        }
