        let a = build_avcc(&SPS_1080, &[0x68, 0xEB, 0xE3, 0xCB, 0x22, 0xC0]);
        let (ls, s, p) = parse_avcc(&a).unwrap();
        assert_eq!(ls, 4);
        assert_eq!(s[0], SPS_1080.to_vec());
        assert_eq!(p[0].len(), 6);
        assert_eq!(a[1], 0x64);
    }

