//! ClipVault core library.
//!
//! Everything that both the background service and the GUI need lives here:
//! configuration, the library database, the audio mixing model, and the pure
//! decision logic (game detection, retention,
//! mic selection, timeline math) that is unit tested in isolation.

pub mod audio_names;
pub mod config;
pub mod db;
pub mod filenames;
pub mod games;
pub mod hotkey;
pub mod ipc;
pub mod logging;
pub mod mixer;
pub mod model;
pub mod naming;
pub mod paths;
pub mod retention;
