            b"moov" if !self.have_moov => {
                let body = self.read_vec(pos + hdr, (size - hdr) as usize)?;
                self.parse_moov(&body)?;
                self.have_moov = true;
                changed = true;
            }
            b"moof" if self.have_moov => {
