            let ready_end = if self.gops.len() >= 2 {
                Some(self.gops[1].start)
            } else if (finishing || self.video_ended) && self.gops.len() == 1 {
                let g = &self.gops[0];
                Some(g.packets.last().map(|p| p.time_hns).unwrap_or(g.start) + self.frame_hns())
            } else {
