            width: 0,
            height: 0,
            name,
            enabled,
            default_duration: 1024,
        };
        let mut tracks = vec![
            TrackSpec {
                id: TRACK_VIDEO,
                timescale: 90_000,
                codec: Codec::H264 { avcc: avcc.clone() },
                width: first.width as u16,
                height: first.height as u16,
