1	//! First-run configuration, migration from the old Python program, and the
2	//! "start with Windows" shortcut.
3	
4	use crate::win::coreaudio::{com_init_mta, AudioSystem};
5	use anyhow::Result;
6	use cv_core::audio_names::clean_display_name;
7	use cv_core::config::{parse_legacy_configs, Config};
8	use cv_core::obs::files::ObsConfigFiles;
9	use cv_core::paths;
10	use std::path::{Path, PathBuf};
11	
12	/// Load config.toml, or build one from the current OBS setup on first run.
13	pub fn load_or_first_run() -> Config {
14	    let path = paths::config_path();
15	    if path.exists() {
16	        return Config::load_or_default();
17	    }
18	    let mut cfg = Config::default();
19	    seed_from_obs(&mut cfg);
20	    if let Err(e) = cfg.save() {
21	        tracing::error!("could not save initial config: {e:#}");
22	    }
23	    cfg
24	}
25	
26	/// Copy the user's existing OBS output settings into our config so nothing
27	/// changes unexpectedly (quality, replay length, recordings folder...).
28	pub fn seed_from_obs(cfg: &mut Config) {
29	    let files = ObsConfigFiles::from_config(cfg);
30	    if let Ok(s) = files.read_profile_summary() {
31	        if let Some(p) = s.rec_path.filter(|p| !p.is_empty()) {
32	            cfg.recording.folder = p.clone();
33	            if let Some(parent) = Path::new(&p).parent() {
34	                cfg.clips.folder = parent.join("Clips").to_string_lossy().to_string();
35	            }
36	        }
37	        if let Some(v) = s.replay_secs {
38	            cfg.clips.clip_length_secs = v;
39	        }
40	        if let Some(v) = s.replay_mb {
41	            cfg.clips.replay_max_memory_mb = v;
42	        }
43	        if let Some(v) = s.fps {
44	            cfg.recording.fps = v;
45	        }
46	        if let Some(v) = s.encoder {
47	            cfg.recording.encoder = v;
48	        }
49	        if let Some(v) = s.rate_control {
50	            cfg.recording.rate_control = v.to_uppercase();
51	        }
52	        if let Some(v) = s.cqp {
53	            cfg.recording.cqp = v;
54	        }
55	        if let Some(v) = s.bitrate {
56	            cfg.recording.bitrate_kbps = v;
57	        }
58	        if let Some(v) = s.preset {
59	            cfg.recording.preset = v;
60	        }
61	        if let Some(v) = s.audio_bitrate {
62	            cfg.recording.audio_bitrate_kbps = v;
63	        }
64	        if let Some(f) = s.format {
65	            if cv_core::config::RECORDING_FORMATS.iter().any(|(k, _)| *k == f) {
66	                cfg.recording.format = f;
67	            }
68	        }
69	    }
70	    if let Some(mic) = current_obs_mic_name(&files) {
71	        tracing::info!("preferred mic from OBS: {mic}");
72	        cfg.audio.mic_priority = vec![mic];
73	    }
74	    cfg.sanitize();
75	}
76	
77	/// Name of the microphone OBS currently records (resolved through Core Audio).
78	fn current_obs_mic_name(files: &ObsConfigFiles) -> Option<String> {
79	    let name = files.scene_collection_name().unwrap_or_else(|| "Untitled".into());
80	    let file = files.dir.join("basic").join("scenes").join(format!("{name}.json"));
81	    let v: serde_json::Value = serde_json::from_str(&std::fs::read_to_string(file).ok()?).ok()?;
82	    let mut ids = Vec::new();
83	    for k in ["AuxAudioDevice1", "AuxAudioDevice2"] {
84	        if let Some(id) = v[k]["settings"]["device_id"].as_str() {
85	            ids.push(id.to_string());
86	        }
87	    }
88	    if let Some(sources) = v["sources"].as_array() {
89	        for s in sources {
90	            if s["id"].as_str() == Some("wasapi_input_capture") {
91	                if let Some(id) = s["settings"]["device_id"].as_str() {
92	                    ids.push(id.to_string());
93	                }
94	            }
95	        }
96	    }
97	    let ids: Vec<String> = ids.into_iter().filter(|i| i != "default" && !i.is_empty()).collect();
98	    if ids.is_empty() {
99	        return None;
100	    }
101	    // Core Audio on a throwaway MTA thread.
102	    std::thread::spawn(move || {
103	        com_init_mta();
104	        let sys = AudioSystem::new(None).ok()?;
105	        let inputs = sys.inputs();
106	        ids.iter()
107	            .find_map(|id| inputs.iter().find(|e| e.id.eq_ignore_ascii_case(id)))
108	            .map(|e| clean_display_name(&e.name))
109	    })
110	    .join()
111	    .ok()
112	    .flatten()
113	}
114	
115	/// Import settings from the old Python program's folder (configs.txt).
116	pub fn migrate_legacy(legacy_dir: &Path) -> Result<Config> {
117	    let mut cfg = if paths::config_path().exists() { Config::load()? } else { Config::default() };
118	    seed_from_obs(&mut cfg);
119	    let configs = legacy_dir.join("configs.txt");
120	    if configs.is_file() {
121	        let legacy = parse_legacy_configs(&std::fs::read_to_string(&configs)?);
122	        // The old program used OBS's split length (60 min) to count recordings.
123	        let split = ObsConfigFiles::from_config(&cfg)
124	            .read_profile_summary()
125	            .ok()
126	            .and_then(|s| s.split_minutes)
127	            .unwrap_or(60);
128	        cfg.apply_legacy(&legacy, split);
129	    }
130	    cfg.save()?;
131	    Ok(cfg)
132	}
133	
134	fn service_exe() -> PathBuf {
135	    paths::exe_dir().join(paths::SERVICE_EXE)
136	}
137	
138	/// Create or remove the Startup-folder shortcut for the service.
139	pub fn sync_startup_shortcut(cfg: &Config) -> Result<()> {
140	    let Some(dir) = paths::startup_dir() else { return Ok(()) };
141	    let link = dir.join(paths::STARTUP_LINK_NAME);
142	    // Never register a development build (cargo's target dir) at login.
143	    let exe_dir = paths::exe_dir().to_string_lossy().to_lowercase();
144	    if exe_dir.contains("\\target\\debug") || exe_dir.contains("\\target\\release") {
145	        tracing::debug!("dev build: not touching the startup shortcut");
146	        return Ok(());
147	    }
148	    if cfg.general.start_with_windows {
149	        let exe = service_exe();
150	        if exe.is_file() {
151	            crate::win::shell::create_shortcut(&link, &exe, "", &paths::exe_dir(), "ClipVault background service (keeps OBS recording)")?;
152	        }
153	    } else if link.exists() {
154	        std::fs::remove_file(&link)?;
155	    }
156	    Ok(())
157	}
158	
159	/// Create Start Menu + Desktop shortcuts for the GUI.
160	pub fn create_app_shortcuts(desktop: bool) -> Result<()> {
161	    let gui = paths::exe_dir().join(paths::GUI_EXE);
162	    if let Some(sm) = paths::start_menu_dir() {
163	        crate::win::shell::create_shortcut(&sm.join("ClipVault.lnk"), &gui, "", &paths::exe_dir(), "ClipVault — clips and 24/7 recordings")?;
164	    }
165	    if desktop {
166	        if let Some(home) = std::env::var_os("USERPROFILE") {
167	            let candidates = [PathBuf::from(&home).join("OneDrive").join("Desktop"), PathBuf::from(&home).join("Desktop")];
168	            if let Some(d) = candidates.iter().find(|d| d.is_dir()) {
169	                crate::win::shell::create_shortcut(&d.join("ClipVault.lnk"), &gui, "", &paths::exe_dir(), "ClipVault — clips and 24/7 recordings")?;
170	            }
171	        }
172	    }
173	    Ok(())
174	}
175

1	//! Loopback TCP server the GUI connects to.
2	
3	use crate::jobs::{self, JobKind};
4	use crate::shared::{LibCmd, Shared, SupCmd};
5	use crate::supervisor::send_and_wait;
6	use anyhow::Result;
7	use cv_core::ipc::{ClientMsg, Event, IpcInfo, Request, ServerMsg};
8	use serde_json::{json, Value};
9	use std::io::{BufRead, BufReader};
10	use std::net::{TcpListener, TcpStream};
11	use std::sync::Arc;
12	use std::time::Duration;
13	
14	pub fn start(sh: Arc<Shared>) -> Result<IpcInfo> {
15	    let base = sh.cfg.read().advanced.ipc_port;
16	    let mut listener = None;
17	    for port in base..base.saturating_add(20) {
18	        if let Ok(l) = TcpListener::bind(("127.0.0.1", port)) {
19	            listener = Some((l, port));
20	            break;
21	        }
22	    }
23	    let (listener, port) = listener.ok_or_else(|| anyhow::anyhow!("no free port for the GUI connection"))?;
24	    let info = IpcInfo { port, token: cv_core::util::random_token(24), pid: std::process::id() };
25	    info.write()?;
26	    tracing::info!("GUI connection listening on 127.0.0.1:{port}");
27	    let token = info.token.clone();
28	    std::thread::Builder::new().name("ipc-accept".into()).spawn(move || {
29	        for stream in listener.incoming() {
30	            if sh.is_shutting_down() {
31	                break;
32	            }
33	            let Ok(stream) = stream else { continue };
34	            let sh = sh.clone();
35	            let token = token.clone();
36	            let _ = std::thread::Builder::new().name("ipc-conn".into()).spawn(move || {
37	                if let Err(e) = connection(sh, stream, &token) {
38	                    tracing::debug!("gui connection ended: {e:#}");
39	                }
40	            });
41	        }
42	    })?;
43	    Ok(info)
44	}
45	
46	fn connection(sh: Arc<Shared>, stream: TcpStream, token: &str) -> Result<()> {
47	    stream.set_nodelay(true).ok();
48	    let mut writer = stream.try_clone()?;
49	    let (out_tx, out_rx) = crossbeam_channel::unbounded::<String>();
50	    std::thread::spawn(move || {
51	        use std::io::Write;
52	        for line in out_rx {
53	            if writer.write_all(line.as_bytes()).and_then(|_| writer.write_all(b"\n")).and_then(|_| writer.flush()).is_err() {
54	                break;
55	            }
56	        }
57	    });
58	    let reply = |id: u64, r: Result<Value, String>| {
59	        let msg = match r {
60	            Ok(data) => ServerMsg::Response { id, ok: true, data, error: None },
61	            Err(e) => ServerMsg::Response { id, ok: false, data: Value::Null, error: Some(e) },
62	        };
63	        if let Ok(s) = serde_json::to_string(&msg) {
64	            let _ = out_tx.send(s);
65	        }
66	    };
67	    let mut authed = false;
68	    let reader = BufReader::new(stream.try_clone()?);
69	    for line in reader.lines() {
70	        let line = line?;
71	        let msg: ClientMsg = match serde_json::from_str(&line) {
72	            Ok(m) => m,
73	            Err(e) => {
74	                tracing::warn!("bad request from GUI: {e}");
75	                continue;
76	            }
77	        };
78	        if !authed {
79	            match msg.req {
80	                Request::Auth { token: t } if t == token => {
81	                    authed = true;
82	                    reply(msg.id, Ok(Value::Null));
83	                    sh.clients.lock().push(out_tx.clone());
84	                    let status = Box::new(crate::status::build(&sh));
85	                    if let Ok(s) = serde_json::to_string(&ServerMsg::Event { event: Event::Status { status } }) {
86	                        let _ = out_tx.send(s);
87	                    }
88	                    continue;
89	                }
90	                _ => {
91	                    reply(msg.id, Err("not authorised".into()));
92	                    let _ = stream.shutdown(std::net::Shutdown::Both);
93	                    return Ok(());
94	                }
95	            }
96	        }
97	        let r = handle(&sh, msg.req);
98	        reply(msg.id, r);
99	    }
100	    Ok(())
101	}
102	
103	fn handle(sh: &Arc<Shared>, req: Request) -> Result<Value, String> {
104	    let e2s = |e: anyhow::Error| format!("{e:#}");
105	    match req {
106	        Request::Auth { .. } => Ok(Value::Null),
107	        Request::Status => Ok(serde_json::to_value(crate::status::build(sh)).unwrap_or_default()),
108	        Request::SaveClip { short } => {
109	            send_and_wait(&sh.sup_tx, |r| SupCmd::SaveClip { short, reply: Some(r) }, Duration::from_secs(15)).map(|_| Value::Null)
110	        }
111	        Request::AddMarker { label } => crate::add_marker(sh, &label).map(|id| json!({"id": id})).map_err(e2s),
112	        Request::SetRecording { enabled } => {
113	            send_and_wait(&sh.sup_tx, |r| SupCmd::SetRecording { enabled, reply: Some(r) }, Duration::from_secs(20)).map(|_| Value::Null)
114	        }
115	        Request::RestartObs => {
116	            send_and_wait(&sh.sup_tx, |r| SupCmd::RestartObs { reply: Some(r) }, Duration::from_secs(90)).map(|_| Value::Null)
117	        }
118	        Request::ReloadConfig { restart_obs } => {
119	            crate::reload_config(sh, restart_obs).map_err(e2s)?;
120	            Ok(Value::Null)
121	        }
122	        Request::CutRange { from_ms, to_ms, title, game_id, category_ids, precise, gains, audio_edits } => {
123	            let id = jobs::submit(sh, JobKind::CutRange { from_ms, to_ms, title, game_id, category_ids, precise, gains, audio_edits });
124	            Ok(json!({"job_id": id}))
125	        }
126	        Request::TrimClip { clip_id, start_s, end_s, replace, precise } => {
127	            let id = jobs::submit(sh, JobKind::Trim { clip_id, start_s, end_s, replace, precise });
128	            Ok(json!({"job_id": id}))
129	        }
130	        Request::Export { clip_id, range, gains, target_size_mb } => {
131	            let id = jobs::submit(sh, JobKind::Export { clip_id, range, gains, target_size_mb });
132	            Ok(json!({"job_id": id}))
133	        }
134	        Request::CancelJob { id } => Ok(json!({"cancelled": jobs::cancel(id)})),
135	        Request::AudioDevices => {
136	            let _ = sh.audio_tx.try_send(());
137	            Ok(serde_json::to_value(sh.devices.lock().clone()).unwrap_or_default())
138	        }
139	        Request::RescanLibrary => {
140	            let _ = sh.lib_tx.send(LibCmd::Rescan);
141	            Ok(Value::Null)
142	        }
143	        Request::KeepRecording { recording_id, keep } => {
144	            crate::library::set_kept(sh, recording_id, keep).map(|_| Value::Null).map_err(e2s)
145	        }
146	        Request::DeleteClips { clip_ids } => {
147	            let n = crate::clips::delete_clips(sh, &clip_ids).map_err(e2s)?;
148	            sh.emit(Event::LibraryChanged);
149	            Ok(json!({"deleted": n}))
150	        }
151	        Request::SetClipGame { clip_id, game_id } => {
152	            crate::clips::set_clip_game(sh, clip_id, game_id).map_err(e2s)?;
153	            sh.emit(Event::LibraryChanged);
154	            Ok(Value::Null)
155	        }
156	        Request::RenameClip { clip_id, title } => {
157	            crate::clips::rename_clip(sh, clip_id, &title).map_err(e2s)?;
158	            sh.emit(Event::LibraryChanged);
159	            Ok(Value::Null)
160	        }
161	        Request::CopyFileToClipboard { path } => {
162	            crate::win::shell::copy_file_to_clipboard(std::path::Path::new(&path)).map_err(e2s)?;
163	            Ok(Value::Null)
164	        }
165	        Request::SuspendHotkeys { suspend } => {
166	            sh.ui.send(crate::win::ui::UiCmd::SuspendHotkeys(suspend));
167	            Ok(Value::Null)
168	        }
169	        Request::Touch => {
170	            sh.emit(Event::LibraryChanged);
171	            Ok(Value::Null)
172	        }
173	        Request::Shutdown => {
174	            crate::request_shutdown(sh);
175	            Ok(Value::Null)
176	        }
177	    }
178	}
