1	//! Building the status snapshot (for the GUI and the tray icon).
2	
3	use crate::shared::Shared;
4	use crate::win::ui::{TrayState, UiCmd};
5	use cv_core::ipc::{Event, Status};
6	use cv_core::util::{format_span_short, human_bytes, now_ms};
7	use std::sync::Arc;
8	use std::time::Duration;
9	
10	pub fn build(sh: &Shared) -> Status {
11	    let cfg = sh.cfg();
12	    let mut s = sh.status.lock().clone();
13	    s.version = cv_core::VERSION.to_string();
14	    s.jobs = sh.jobs.lock().clone();
15	    let mut w = Vec::new();
16	    if !s.obs.running {
17	        if s.obs.closed_by_user {
18	            w.push("OBS was closed — recording and clipping are stopped".to_string());
19	        } else {
20	            w.push("OBS is not running".to_string());
21	        }
22	    } else if !s.obs.connected {
23	        w.push("Connecting to OBS…".to_string());
24	    }
25	    if !s.obs.last_error.is_empty() {
26	        w.push(s.obs.last_error.clone());
27	    }
28	    if s.obs.connected {
29	        if !s.recording.active && !s.recording.paused_by_user {
30	            w.push("24/7 recording is not running".to_string());
31	        }
32	        if !s.replay.active {
33	            w.push("Replay buffer is off — clips can't be saved".to_string());
34	        }
35	    }
36	    match s.mic.state.as_str() {
37	        "fallback" => w.push(format!("Preferred mic not connected — using {}", s.mic.device)),
38	        "missing" => w.push("No microphone is being recorded".to_string()),
39	        _ => {}
40	    }
41	    for e in sh.hotkey_errors.lock().iter() {
42	        w.push(e.clone());
43	    }
44	    let min_free = cfg.recording.min_free_space_gb as u64 * 1024 * 1024 * 1024;
45	    if s.disk.total_bytes > 0 && s.disk.free_bytes < min_free {
46	        w.push(format!("Low disk space on the recordings drive ({} free)", human_bytes(s.disk.free_bytes)));
47	    }
48	    if sh.tools.read().is_none() && cfg.advanced.ffmpeg_path.is_empty() && sh.tools().is_none() {
49	        w.push("ffmpeg not found — clipping from recordings and exports won't work".to_string());
50	    }
51	    s.warnings = w;
52	    s
53	}
54	
55	/// Publishes status to GUIs every second and keeps the tray icon current.
56	pub fn run(sh: Arc<Shared>) {
57	    let mut last_tray: Option<(TrayState, String, bool)> = None;
58	    while !sh.is_shutting_down() {
59	        let s = build(&sh);
60	        if sh.has_clients() {
61	            sh.emit(Event::Status { status: Box::new(s.clone()) });
62	        }
63	        let state = if !s.warnings.is_empty() && (!s.obs.connected || !s.replay.active || s.mic.state == "missing" || s.mic.state == "fallback") {
64	            TrayState::Warning
65	        } else if s.recording.active {
66	            TrayState::Recording
67	        } else {
68	            TrayState::Idle
69	        };
70	        let mut tip = String::from("ClipVault — ");
71	        if s.recording.active {
72	            let secs = (now_ms() - s.recording.started_ms).max(0) / 1000;
73	            tip.push_str(&format!("recording ({})", format_span_short(secs)));
74	        } else if s.recording.paused_by_user {
75	            tip.push_str("24/7 recording paused");
76	        } else {
77	            tip.push_str("not recording");
78	        }
79	        if let Some(w) = s.warnings.first() {
80	            tip.push_str("\n");
81	            tip.push_str(w);
82	        }
83	        let tip: String = tip.chars().take(120).collect();
84	        let tray = (state, tip, s.recording.paused_by_user);
85	        if last_tray.as_ref() != Some(&tray) {
86	            sh.ui.send(UiCmd::Tray { state: tray.0, tooltip: tray.1.clone(), recording_paused: tray.2 });
87	            last_tray = Some(tray);
88	        }
89	        std::thread::sleep(Duration::from_secs(1));
90	    }
91	}
