94	/// Lower-case exe file name from a path.
95	pub fn exe_name_of(path: &str) -> String {
96	    Path::new(path)
97	        .file_name()
98	        .map(|f| f.to_string_lossy().to_lowercase())
99	        .unwrap_or_default()
