102	/// Stable key for a game. Java games are keyed by title since they all run as
103	/// `javaw.exe` (Minecraft Java Edition being the common case).
104	pub fn game_key(info: &WindowInfo) -> String {
105	    let exe = if info.exe_name.is_empty() { exe_name_of(&info.exe_path) } else { info.exe_name.to_lowercase() };
106	    if exe == "javaw.exe" || exe == "java.exe" {
107	        let title = crate::naming::strip_invisible(&info.title);
108	        if title.to_lowercase().starts_with("minecraft") {
109	            return "java:minecraft".into();
110	        }
111	    }
112	    exe
113	}
