115	/// Why something was (or wasn't) considered a game; useful for the UI.
116	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
117	pub enum Verdict {
118	    UserGame,
119	    UserNotGame,
120	    KnownGame,
121	    GameFolder,
122	    Fullscreen,
123	    KnownNonGame,
124	    NotGame,
125	}
126	
127	impl Verdict {
128	    pub fn is_game(self) -> bool {
129	        matches!(self, Verdict::UserGame | Verdict::KnownGame | Verdict::GameFolder | Verdict::Fullscreen)
130	    }
131	}
132	
133	pub struct Classifier {
134	    always: Vec<String>,
135	    never: Vec<String>,
136	    library_folders: Vec<String>,
137	    fullscreen_is_game: bool,
138	    /// Per-exe overrides stored in the database (Games page toggles).
139	    db_overrides: HashMap<String, bool>,
140	}
141	
142	impl Classifier {
143	    pub fn new(cfg: &crate::config::GamesConfig, db_overrides: HashMap<String, bool>) -> Self {
144	        let norm = |v: &Vec<String>| v.iter().map(|s| s.trim().to_lowercase()).filter(|s| !s.is_empty()).collect();
145	        Self {
146	            always: norm(&cfg.always_games),
147	            never: norm(&cfg.never_games),
148	            library_folders: cfg
149	                .library_folders
150	                .iter()
151	                .map(|s| {
152	                    let mut p = s.trim().to_lowercase().replace('/', "\\");
153	                    if !p.ends_with('\\') {
154	                        p.push('\\');
155	                    }
156	                    p
157	                })
158	                .filter(|s| s.len() > 1)
159	                .collect(),
160	            fullscreen_is_game: cfg.fullscreen_is_game,
161	            db_overrides,
162	        }
163	    }
164	
165	    pub fn classify(&self, info: &WindowInfo) -> Verdict {
166	        let key = game_key(info);
167	        let exe = if info.exe_name.is_empty() { exe_name_of(&info.exe_path) } else { info.exe_name.to_lowercase() };
168	        if exe.is_empty() {
169	            return Verdict::NotGame;
170	        }
171	        if self.never.contains(&exe) || self.never.contains(&key) {
172	            return Verdict::UserNotGame;
173	        }
174	        if self.always.contains(&exe) || self.always.contains(&key) {
175	            return Verdict::UserGame;
176	        }
177	        if let Some(&is_game) = self.db_overrides.get(&key).or_else(|| self.db_overrides.get(&exe)) {
178	            return if is_game { Verdict::UserGame } else { Verdict::UserNotGame };
179	        }
180	        if key == "java:minecraft" || KNOWN_GAMES.iter().any(|(e, _)| *e == exe) {
181	            return Verdict::KnownGame;
182	        }
183	        if NON_GAMES.contains(&exe.as_str()) {
184	            return Verdict::KnownNonGame;
185	        }
186	        let path = info.exe_path.to_lowercase().replace('/', "\\");
187	        if !path.is_empty() {
188	            if self.library_folders.iter().any(|f| path.starts_with(f.as_str())) {
189	                return Verdict::GameFolder;
190	            }
191	            if GAME_PATH_MARKERS.iter().any(|m| path.contains(m)) && !is_launcher_like(&exe) {
192	                return Verdict::GameFolder;
193	            }
194	            if path.starts_with(r"c:\windows\") {
195	                return Verdict::NotGame;
196	            }
197	        }
198	        if self.fullscreen_is_game && info.fullscreen {
199	            return Verdict::Fullscreen;
200	        }
201	        Verdict::NotGame
202	    }
203	}
204	
205	fn is_launcher_like(exe: &str) -> bool {
206	    let stem = exe.trim_end_matches(".exe");
207	    ["launcher", "crashreport", "crashhandler", "updater", "setup", "unins", "helper", "bootstrap", "redist", "vc_redist", "dxsetup", "easyanticheat", "battleye", "cefprocess", "webhelper"]
208	        .iter()
209	        .any(|w| stem.contains(w))
210	}
211	
212	/// Built-in friendly name for well-known exes.
213	pub fn known_game_name(key: &str) -> Option<&'static str> {
214	    if key == "java:minecraft" {
215	        return Some("Minecraft");
216	    }
217	    KNOWN_GAMES.iter().find(|(e, _)| *e == key).map(|(_, n)| *n)
218	}
219	
220	/// Best-effort friendly name. Inputs in order of trust: Steam manifest name,
221	/// built-in table, exe version-info product name/description, then the exe stem.
222	pub fn friendly_name(
223	    key: &str,
224	    exe_path: &str,
225	    steam_name: Option<&str>,
226	    product_name: Option<&str>,
227	    file_description: Option<&str>,
228	) -> String {
229	    let clean = |s: &str| crate::naming::collapse_ws(&crate::naming::strip_invisible(s));
230	    if let Some(n) = steam_name.map(clean).filter(|s| !s.is_empty()) {
231	        return n;
232	    }
233	    if let Some(n) = known_game_name(key) {
234	        return n.to_string();
235	    }
236	    let generic = |s: &str| {
237	        let l = s.to_lowercase();
238	        l.is_empty()
239	            || l.contains("unreal engine")
240	            || l.contains("unity")
241	            || l == "game"
242	            || l.contains("bootstrap")
243	            || l.contains("launcher")
244	            || l.starts_with("microsoft")
245	            || l == "java(tm) platform se binary"
246	            || l == "openjdk platform binary"
247	    };
248	    for cand in [product_name, file_description].into_iter().flatten() {
249	        let c = clean(cand);
250	        if !generic(&c) && c.chars().any(|ch| ch.is_alphabetic()) && c.chars().count() <= 60 {
251	            return c;
252	        }
253	    }
254	    // Exe stem: strip common suffixes like "-Win64-Shipping".
255	    let stem = Path::new(exe_path)
256	        .file_stem()
257	        .map(|s| s.to_string_lossy().to_string())
258	        .unwrap_or_else(|| key.trim_end_matches(".exe").to_string());
259	    let mut stem = stem;
260	    for suf in ["-Win64-Shipping", "-WinGDK-Shipping", "_x64", "-Win64", "64", "_dx12", "_dx11", "_vulkan", "_BE", "_EAC"] {
261	        if stem.len() > suf.len() && stem.to_lowercase().ends_with(&suf.to_lowercase()) {
262	            stem.truncate(stem.len() - suf.len());
263	        }
264	    }
265	    let stem = stem.replace(['_', '-'], " ");
266	    let stem = crate::naming::collapse_ws(&stem);
267	    if stem.is_empty() {
268	        "Unknown".into()
269	    } else {
270	        // Capitalise the first letter of each word if the whole thing is lower case.
271	        if stem.chars().all(|c| !c.is_uppercase()) {
272	            stem.split(' ')
273	                .map(|w| {
274	                    let mut c = w.chars();
275	                    c.next().map(|f| f.to_uppercase().collect::<String>() + c.as_str()).unwrap_or_default()
276	                })
