pub const DEFAULT_VOICE_APPS: &[&str] = &["discord.exe", "discordptb.exe", "discordcanary.exe", "teamspeak.exe", "ts3client_win64.exe", "teams.exe", "ms-teams.exe", "zoom.exe", "skype.exe", "slack.exe", "mumble.exe", "guilded.exe"];
