458	    pub fn list_clips(&self, f: &ClipFilter) -> Result<Vec<Clip>> {
459	        let mut sql = format!("{} WHERE 1=1", Self::CLIP_SELECT);
460	        let mut args: Vec<rusqlite::types::Value> = Vec::new();
461	        if !f.include_missing {
462	            sql.push_str(" AND c.missing=0");
463	        }
464	        if let Some(g) = f.game_id {
465	            sql.push_str(" AND c.game_id=?");
466	            args.push(g.into());
467	        }
468	        if let Some(cat) = f.category_id {
469	            sql.push_str(" AND c.id IN (SELECT clip_id FROM clip_categories WHERE category_id=?)");
470	            args.push(cat.into());
471	        }
472	        if f.uncategorized {
473	            sql.push_str(" AND c.id NOT IN (SELECT clip_id FROM clip_categories)");
474	        }
475	        if f.favorites_only {
476	            sql.push_str(" AND c.favorite=1");
477	        }
478	        let search = f.search.trim();
479	        if !search.is_empty() {
480	            for word in search.split_whitespace() {
481	                sql.push_str(
482	                    " AND (c.title LIKE ? ESCAPE '\\' OR c.notes LIKE ? ESCAPE '\\' OR g.name LIKE ? ESCAPE '\\'
483	                      OR c.id IN (SELECT cc.clip_id FROM clip_categories cc JOIN categories k ON k.id=cc.category_id
484	                                  WHERE k.name LIKE ? ESCAPE '\\'))",
485	                );
486	                let pat = format!("%{}%", word.replace('\\', "\\\\").replace('%', "\\%").replace('_', "\\_"));
487	                for _ in 0..4 {
488	                    args.push(pat.clone().into());
489	                }
490	            }
491	        }
492	        sql.push_str(match f.sort {
493	            ClipSort::Newest => " ORDER BY c.created_at DESC, c.id DESC",
494	            ClipSort::Oldest => " ORDER BY c.created_at ASC, c.id ASC",
495	            ClipSort::Longest => " ORDER BY c.duration DESC",
496	            ClipSort::Largest => " ORDER BY c.size DESC",
497	            ClipSort::Title => " ORDER BY c.title COLLATE NOCASE ASC",
498	            ClipSort::Game => " ORDER BY g.name COLLATE NOCASE ASC, c.created_at DESC",
499	        });
500	        let mut st = self.conn.prepare(&sql)?;
501	        let mut clips = st
502	            .query_map(rusqlite::params_from_iter(args), Self::row_clip)?
503	            .collect::<rusqlite::Result<Vec<_>>>()?;
504	        // Attach categories in one query.
505	        let mut cats: HashMap<i64, Vec<i64>> = HashMap::new();
506	        let mut st2 = self.conn.prepare("SELECT clip_id, category_id FROM clip_categories")?;
507	        for row in st2.query_map([], |r| Ok((r.get::<_, i64>(0)?, r.get::<_, i64>(1)?)))? {
508	            let (c, k) = row?;
509	            cats.entry(c).or_default().push(k);
510	        }
511	        for c in &mut clips {
512	            if let Some(v) = cats.remove(&c.id) {
513	                c.category_ids = v;
514	            }
515	        }
516	        Ok(clips)
517	    }
