        assert_eq!(norm_path("I:/OBS/Recordings/a.mp4"), r"I:\OBS\Recordings\a.mp4");
        assert!(same_path("I:/OBS/a.mp4", r"i:\obs\A.MP4"));
        assert!(!same_path("I:/OBS/a.mp4", r"I:\OBS\b.mp4"));
    }
}

